  return w;
}
template <class T, class S>
vector<pair<T, S>> zip(vector<T> v, vector<S> w) {
  int n = min(sz(v), sz(w));
  vector<pair<T, S>> x(n);
  for (int i = 0; i < n; i++) x[i] = make_pair(v[i], w[i]);
  return x;
}
template <class T, class S>
pair<vector<T>, vector<S>> unzip(vector<pair<T, S>> v) {
  int n = sz(v);
  auto w = make_pair(vector<T>(n), vector<S>(n));
  for (int i = 0; i < n; i++) {
    w.first[i] = v[i].first;
    w.second[i] = v[i].second;
  }
  return w;
}
template <class T, class S>
vector<T> unzip_first(vector<pair<T, S>> v) {
  int n = sz(v);
  vector<T> w(n);
  for (int i = 0; i < n; i++) w[i] = v[i].first;
  return w;
}
template <class T, class S>
vector<S> unzip_second(vector<pair<T, S>> v) {
  int n = sz(v);
  vector<S> w(n);
  for (int i = 0; i < n; i++) w[i] = v[i].second;
  return w;
}

void solve(int N, vi x, vi y) {
  union_find uf(N);
  vp xi = zip_vi(x);
  SORT(xi);
  rep(i, N - 1)if(xi[i].first == xi[i + 1].first)
    uf.union_set(xi[i].second, xi[i + 1].second);
  vp yi = zip_vi(y);
  SORT(yi);
  rep(i, N - 1)if(yi[i].first == yi[i + 1].first)
    uf.union_set(yi[i].second, yi[i + 1].second);
  unordered_map<int, unordered_set<int>> xs, ys;
  rep(i, N) {
    int r = uf.root(i);
    xs[r].insert(x[i]);
    ys[r].insert(y[i]);
  }
  int ans = 0;
  each(p, xs) {
    int r = p.first;
    int xn = sz(p.second), yn = sz(ys[r]);
    if(xn == 1 || yn == 1)continue;
    ans += xn * yn - uf.size(r);
  }
  COUT(ans);
}


