template<unsigned long long SIZE> class unionFind{
    protected:
        long long uni[SIZE];
        long long diff_weight[SIZE];
    public:
        unionFind(){
            for(int i=0;i<SIZE;i++){
                uni[i]=-1;
                diff_weight[i]=0;
            }
        }
        unsigned long long root(unsigned long long a){
            if(a>=SIZE) throw std::range_error("与えられたインデックスが木の範囲外です");
            if(uni[a]<0) return a;
            else{
                unsigned long long r=root(uni[a]);
                diff_weight[a]+=diff_weight[uni[a]];
                return uni[a]=r;
            }
        }
        long long weight(unsigned long long a){
            root(a);
            return diff_weight[a];
        }
        long long diff(unsigned long long a, unsigned long long b){
            if(isSame(a,b)) return weight(b)-weight(a);
            else return INT64_MAX;
        }
        unsigned long long count(unsigned long long a){
            return -uni[root(a)];
        }
        bool merge(unsigned long long a, unsigned long long b, long long w=1){
            w+=weight(a);  w-=weight(b);
            a=root(a);  b=root(b);
            if(a==b) return false;
            if(uni[a]>uni[b]){
                swap(a, b);
                w=(-w);
            }
            uni[a]+=uni[b];
            uni[b]=a;
            diff_weight[b]=w;
            return true;
        }
        bool isSame(unsigned long long a,unsigned long long b){
            return root(a)==root(b);
        }
};

int64_t xy2id(int64_t x, int64_t y){
    return x*1000000 + y;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout.precision(12);
    cout.setf(ios_base::fixed, ios_base::floatfield);

    int n;
    cin >> n;
    static int group[100000];
    static vector<int> inx[100000], iny[100000];
    static vector<pair<int,int>> pts;
    static unordered_map<int64_t, int> coor2idx;
    for(int i=0;i<n;i++){
        int x, y;
        cin >> x >> y;
        x--;
        y--;
        pts.emplace_back(x,y);
        inx[x].push_back(y);
        iny[y].push_back(x);
        coor2idx[xy2id(x,y)]=i;
    }

    int g = 0;
    for(int i=0;i<n;i++){
        if(group[i] == 0){
            g++;
            queue<int> q;
            unordered_set<int> checked;
            checked.clear();
            q.push(i);
            checked.insert(i);
            group[i] = g;

            while(!q.empty()){
                int t = q.front();
                q.pop();
                int xx = pts[t].first;
                int yy = pts[t].second;
                for(int yyy : inx[xx]){
                    int idx = coor2idx[xy2id(xx,yyy)];
                    if(checked.count(idx) > 0) continue;
                    q.push(idx);
                    checked.insert(idx);
                    group[idx] = g;
                }
                for(int xxx : iny[yy]){
                    int idx = coor2idx[xy2id(xxx,yy)];
                    if(checked.count(idx) > 0) continue;
                    q.push(idx);
                    checked.insert(idx);
                    group[idx] = g;
                }                
            }
        }
    }

    static unordered_set<int> xs[100000], ys[100000];
    static int g_cnt[100000];
    for(int i=0;i<n;i++){
        xs[group[i]-1].insert(pts[i].first);
        ys[group[i]-1].insert(pts[i].second);
        g_cnt[group[i]-1]++;
