const int L = 1e5;

void dfs(const vec<int,2>& G, vector<int>& seen, int v, int& X, int& Y, int& M) {
  if (seen[v]) return;
  seen[v] = 1;
  M += G[v].size();
  if (v < L) {
    ++X;
  } else {
    ++Y;
  }
  for (int u : G[v]) {
    dfs(G, seen, u, X, Y, M);
  }
}

