    for (int i = 0; i < N; i++) {
      int X, Y;
      cin >> X >> Y;
      --X;
      --Y;
      G[X].push_back(Y + L);
      G[Y + L].push_back(X);
    }
    ll res = 0;
    vector<int> seen(2 * L, 0);
    for (int v = 0; v < 2 * L; v++) {
      if (seen[v]) continue;
      int X = 0, Y = 0, M = 0;
      dfs(G, seen, v, X, Y, M);
      res += 1ll * X * Y - M / 2;
    }
    cout << res << endl;
  }
  return 0;
}

