struct UnionFindTree{
  vector<int> par,rank,size;
  UnionFindTree(int N){
    par = rank = vector<int>(N,0);
    size = vector<int>(N,1);
    for(int i = 0; i < N; i++) par[i] = i;
  }
  int find(int x){
    if(par[x] == x) return x;
    else return par[x] = find(par[x]);
  }
  void unite(int x,int y){
    x = find(x);
    y = find(y);
    if(x == y)  return ;
    if(rank[x] < rank[y]){
      par[x] = y;
    }else{
      par[y] = x;
      if(rank[x] == rank[y]) ++rank[x];
    }
    size[x] = size[y] = size[x] + size[y];
  }
  bool same(int x,int y){
    return find(x) == find(y);
  }
};

ll part(vi& vec,vl& x,vl& y){
  bool ok = false;
  map<ll,ll> xs,ys;
  for(auto& i:vec){
    xs[x[i]]++;
    ys[y[i]]++;
  }
  for(auto& i:vec){
    if(xs[x[i]]>=2 && ys[y[i]]>=2) ok = true;
  }
  if(ok) return ll(xs.size())*ll(ys.size())-ll(vec.size());
  return 0LL;
}

void solve(long long N, std::vector<long long> x, std::vector<long long> y){
  UnionFindTree uft(N);
  map<ll,vector<int>> xmp,ymp;
  rep(i,N){
    xmp[x[i]].pb(i);
    ymp[y[i]].pb(i);
  }
  for(auto&& p:xmp){
    auto&& vec = p.second;
    rep(i,vec.size()-1){
      uft.unite(vec[i],vec[i+1]);
    }
  }
  for(auto&& p:ymp){
    auto&& vec = p.second;
    rep(i,vec.size()-1){
      uft.unite(vec[i],vec[i+1]);
    }
  }
  vvi g(N);
  rep(i,N) g[uft.find(i)].pb(i);
  ll ans = 0;
  rep(i,N){
    if(g[i].size()){
      ans += part(g[i],x,y);
    }
  }
  cout << ans << endl;
}

int main(){
  long long N;
  scanf("%lld",&N);
  std::vector<long long> x(N);
  std::vector<long long> y(N);
  for(int i = 0 ; i < N ; i++){
    scanf("%lld",&x[i]);
    scanf("%lld",&y[i]);
  }
  solve(N, std::move(x), std::move(y));
  return 0;
}

