        cnt[x[i]] = 0;
        cnt[y[i]] = 0;
    }
    int c = 0;
    for (auto &p : cnt)
        cnt[p.first] = c++;
    UnionFind uf(c);
    for (int i = 0; i < n; ++i) {
        uf.unite(cnt[x[i]], cnt[y[i]]);
    }
    map<int, pair<set<int>, set<int>>> rect;
    for (int i = 0; i < n; ++i) {
        rect[uf.root(cnt[x[i]])].first.insert(cnt[x[i]]);
        rect[uf.root(cnt[x[i]])].second.insert(cnt[y[i]]);
    }
    ll ret = -n;
    for (auto &p : rect) {
        ret += p.second.first.size() * p.second.second.size();
    }
    cout << ret << "\n";
    return 0;
}

