template<class F> int mgr(int ok, int ng, F f) {
    if (ok < ng)
        while (ng - ok > 1) {
            int mid = (ok + ng) / 2;
            if (f(mid))ok = mid; else ng = mid;
        }
    else
        while (ok - ng > 1) {
            int mid = (ok + ng) / 2;
            if (f(mid))ok = mid; else ng = mid;
        }
    return ok;
}
