    int addtop(int i, int k = 1) { return v += p10[keta(v) - i - 1] * k; }
    int dec(int i, int k = 1) { return v -= p10[i] * k; }
    int dectop(int i, int k = 1) { return v -= p10[keta(v) - i - 1] * k; }
