int N;
const int MAX_N = 100001;
int x[MAX_N], y[MAX_N];

// union-find O(α(n))
// 1. init(n) *** Notice that if 3 groupes, init(3 * n)
// 2. use unite(x, y) and same(x, y)

int par[MAX_N * 2];
int rk[MAX_N * 2];

void init(int n){
  REP(i,n){
    par[i] = i;
    rk[i] = 0;
  }
}

int find(int x){
  if(par[x] == x){
    return x;
  }else{
    return par[x] = find(par[x]);
  }
}

void unite(int x, int y){
  x = find(x);
  y = find(y);
  if(x==y) return;
  if(rk[x] < rk[y]){
    par[x] = y;
  }else{
    par[y] = x;
    if(rk[x] == rk[y]) rk[x]++;
  }
}

bool same(int x, int y){
  return find(x) == find(y);
}

int main(){
  cin >> N;
  REP(i, N) cin >> x[i] >> y[i];

  init(2 * MAX_N);
  vpi vx, vy;
  REP(i, N) {
    vx.pb(pi(x[i], y[i]));
    vy.pb(pi(y[i], x[i]));
  }

  sort(ALL(vx));
  sort(ALL(vy));

  REP(i, N - 1) {
    if(vx[i].F == vx[i + 1].F) {
      unite(vx[i].S + MAX_N, vx[i + 1].S + MAX_N);
    }
    if(vy[i].F == vy[i + 1].F) {
      unite(vy[i].S, vy[i + 1].S);
    }
  }

  set<pi> st;
