	}
	UnionFind uf(202020);
	rep(i,100001){
		if(y[i].size() > 1){
			rep(j,y[i].size()-1){
				uf.unite(y[i][j]*2,y[i][j+1]*2);
			}
		}
		if(x[i].size() > 1){
			rep(j,x[i].size()-1){
				uf.unite(x[i][j]*2+1, x[i][j+1]*2+1);
			}
		}
	}
	ll ans = 0;
	rep(i,100001){
		if(x[i].empty()) continue;
		for(auto j : x[i]){
			if(uf.same(i*2+1, j*2)) continue;
			ans += uf.size(i*2+1) * uf.size(j*2);
			uf.unite(i*2+1, j*2);
		}
	}
	cout << ans - n << endl;
}

