#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Forest_Uni {
	vector<UL> v;
	UL Sz;
	void init(UL n) {
		Sz = n;
		v.clear();
		rep(i, n) v.push_back(i);
	}
	void add() { v.push_back(v.size()); }
	UL root(UL p) {
		if (v[p] == p) return p;
		return v[p] = root(v[p]);
	}
	void unite(UL a, UL b) {
		UL A = root(a);
		UL B = root(b);
		if (A != B) {
			Sz--;
			v[A] = B;
		}
	}
};

struct Problem {

	void Solve(){
		UL N; cin >> N;
		vector<pair<UL, UL>> P(N);
		rep(i, N) cin >> P[i].first >> P[i].second;
		rep(i, N) { P[i].first--; P[i].second--; }
		Forest_Uni G;
		G.init(200000);
		rep(i, N) {
			G.unite(P[i].first, P[i].second + 100000);
		}
		vector<pair<ULL, ULL>> M(200000, { 0, 0 });
		rep(i, 100000) { M[G.root(i)].first++; }
		rep(i, 100000) { M[G.root(i + 100000)].second++; }
		ULL ans = 0;
		rep(i, M.size()) { ans += M[i].first * M[i].second; }
		ans -= N;
		cout << ans << endl;
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
