int find(int x) {
    return x == par[x] ? x : par[x] = find(par[x]);
}

void merge(int x, int y) {
     x = find(x);
     y = find(y);
     if (x == y) return;
     sz1[x] += sz1[y];
     sz2[x] += sz2[y];
     par[y] = x;
}

int main() {
