        for (int j = 1; j < (int)G[i].size(); j++) {
            merge(G[i][0], G[i][j]);
        }
        if (!G[i].empty()) sz1[find(G[i][0])]++;
    }
    LL ans = 0;
    for (int i = 0; i < MAXN; i++) {
        int tmp = find(i);
