const int N = 1e5 + 7;
struct UF {
    int tab[N], roz[N];

    UF() {
        FOR(i, 0, N) tab[i] = i, roz[i] = 1;
    }
    int Find(int a) {
        return (tab[a] == a ? a : tab[a] = Find(tab[a]));
    }
    void Union(int a, int b) {
        a = Find(a), b = Find(b);
        if(a == b) return;

        roz[b] += roz[a];
        tab[a] = b;
    }
};

UF uf;

vi id[N][2];
set<int> X[N], Y[N];

