ll cnt_x, cnt_y;

void dfs(int v) {
	if (v >= 100001) cnt_y++;
	else cnt_x++;
	used[v] = true;
	for (int c : g[v]) {
		if (used[c]) continue;
		dfs(c);
	}
	return;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> n;
	rep(i, n) {
		int a, b;
		cin >> a >> b;
		b += 100000;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	memset(used, 0, sizeof(used));
	ll ans = 0;
	rep(i, 100001) {
		if (g[i].size() && !used[i]) {
			cnt_x = 0, cnt_y = 0;
			dfs(i);
			ans += (cnt_x * cnt_y);
		}
	}
	ans -= n;
	printf("%d\n", ans);
	return 0;
}

