struct UnionFind {
  vector<int> parent;
  int __size;
  UnionFind(int size_) : parent(size_, -1), __size(size_) {}
  bool unite(int x,int y) {
    if ((x=find(x)) != (y=find(y))) {
      if (parent[y] < parent[x]) swap(x,y);
      parent[x] += parent[y];
      parent[y] = x;
      __size--;
      return true;
    }
    return false;
  }
  bool same(int x,int y){return find(x)==find(y);}
  int find(int x){return parent[x] < 0 ? x : parent[x] = find(parent[x]);}
  int size(int x){return -parent[find(x)];}
  int size(){return __size;}
};

const int MAX = 100100;

vector<pair<int, int>> AB;

signed main() {

    SS(int, N);

    UnionFind uf_x(MAX), uf_y(MAX);
    set<pair<int, int>> done;

    REP(i, N) {
        SS(int, A, B);
        AB.emplace_back(make_pair(A, B));
        uf_x.unite(uf_y.find(A), B);
        uf_y.unite(uf_x.find(B), A);
    }

    ll res = 0;
    EACH(ab, AB) {
        int a, b;
        tie(a, b) = ab;
        a = uf_x.find(a);
        b = uf_y.find(b);
        if (done.count(make_pair(a, b))) continue;
        done.insert(make_pair(a, b));
        res += uf_x.size(a) * uf_y.size(b);
    }
    cout << res - N << endl;

}

