// 0-indexed
class UnionFind {
private:
	std::vector<int> parent_, size_;
public:
	UnionFind(const int size)
		:parent_(size), size_(size, 1)
	{
		for (int i{}; i < size; i++) parent_[i] = i;
	}
	int calcRoot(const int index)
	{
		int &parent{parent_[index]};
		if (parent == index) return index;

		parent = calcRoot(parent);
		return parent;
	}
	bool areConnected(const int index1, const int index2)
	{
		return calcRoot(index1) == calcRoot(index2);
	}
	void unite(const int index1, const int index2)
	{
		const int root1{calcRoot(index1)}, root2{calcRoot(index2)};
		if (root1 == root2) return;
		if (size_[root1] <= size_[root2])
		{
			size_[root2] += size_[root1];
			parent_[root1] = root2;
		}
		else
		{
			size_[root1] += size_[root2];
			parent_[root2] = root1;
		}
		return;
	}
	int calcSize(const int index)
	{
		return size_[calcRoot(index)];
	}
};

int main()
{
	int N;
	scanf("%d", &N);
	std::vector<std::pair<int64_t, int64_t>> xy(N);
	for (auto& e: xy) scanf("%lld%lld", &e.first, &e.second);

	std::sort(xy.begin(), xy.end());
	int64_t pre{xy.front().first};
	std::vector<std::vector<int64_t>> x(1);
	for (auto& e: xy)
	{
		if (e.first != pre)
			x.push_back({});
		x.back().push_back(e.second);
		pre = e.first;
		e.first = x.size() - 1;
	}
	std::sort(xy.begin(), xy.end(), [](auto a, auto b) { return a.second < b.second; });
	UnionFind uf(x.size());
	for (int i{1}; i < N; i++)
		if (xy[i - 1].second == xy[i].second)
			uf.unite(xy[i - 1].first, xy[i].first);

	std::vector<std::set<int64_t>> connected(x.size());
	for (int i{}; i < (int)x.size(); i++)
		connected[uf.calcRoot(xy[i].first)].insert(xy[i].second);

	int64_t ans{};
	for (int i{}; i < (int)x.size(); i++)
		ans += (int64_t)uf.calcSize(i) * connected[i].size();
	ans -= N;
	printf("%lld\n", ans);
	return 0;
}

