#define MOD 1000000007
#define REP(i, N) for (int i = 0; i < N; ++i)
#define REP1(i, N) for (int i = 1; i <= N; ++i)
#define RREP(i, N) for (int i = N - 1; i >= 0; --i)
#define ALL(a) a.begin(), a.end()

struct UnionFind {
  vector<int> par;
  vector<int> sz;
  UnionFind(int n) { init(n); }

  void init(int n) {
    par.resize(n);
    sz.resize(n);
    REP(i, n) {
      par[i] = i;
      sz[i] = 1;
    }
  }

  int find(int x) {
    if (par[x] == x)
      return x;
    else
      return par[x] = find(par[x]);
  }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (sz[x] < sz[y]) {
      par[x] = y;
      sz[y] += sz[x];
    } else {
      par[y] = x;
      sz[x] += sz[y];
    }
  }

  bool same(int x, int y) { return find(x) == find(y); }

  int size(int x) { return sz[find(x)]; }
};

int main() {
  int n;
  cin >> n;
  UnionFind uf(200000);
  REP(i, n) {
    int x, y;
    cin >> x >> y;
    x--, y--;
    uf.unite(x, y + 100000);
  }
  map<int, int> mx, my;
  REP(i, 100000) {
    mx[uf.find(i)]++;
    my[uf.find(i + 100000)]++;
  }
  ll ans = 0;
  REP(i, 200000) ans += mx[i] * my[i];
  cout << ans - n << endl;
  return 0;
}

