ll N;
//Union Find
const ll MAX_V = 1000010;

ll par[MAX_V];//
ll Rank[MAX_V];
ll X[MAX_V];
ll Y[MAX_V];
ll edge[MAX_V];

void init_UF(){
  for(ll i = 0; i < MAX_V; i++){
    par[i] = i;
    Rank[i] = 1;
    if(i < 100000) X[i] = 1;
    else Y[i] = 1;
  }
}

ll find(ll x){
  if(par[x] == x) return x;
  else{
    return par[x] = find(par[x]);
  }
}

bool same(ll x, ll y){
  return find(x) == find(y);
}

void unite(ll x, ll y){
  ll rx = find(x), ry = find(y);
  if(rx != ry){
    if(Rank[rx] >= Rank[ry]){
      par[ry] = rx;
      if(Rank[rx] == Rank[ry]) Rank[rx]++;
      X[rx] += X[ry];
      Y[rx] += Y[ry];
      edge[rx]++;
    }else{
      par[rx] = ry;
      X[ry] += X[rx];
      Y[ry] += Y[rx];
      edge[ry]++;
    }
  }
}

void solve(){
  init_UF();
  cin >> N;
  vector<ll> x(N), y(N);
  rep(i, N) cin >> x[i] >> y[i];
  rep(i, N){
    unite(x[i]-1, y[i]-1+100000);
  }
  ll ans = 0;
  set<ll> used;
  rep(i, N){
    ll f = find(i);
    if(used.count(find(i))) continue;
    used.insert(f);
    ans += max(0LL, X[f] * Y[f] - edge[f]);
  }
  rep(i, N){
    ll f = find(i+100000);
    if(used.count(find(i))) continue;
    used.insert(f);
    ans += max(0LL, X[f] * Y[f] - edge[f]);
  }

  cout << ans << endl;
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

