int root(int n)
{
	while(par[n] != n)
		n = par[n];
	return n;
}

void merge(int a, int b)
{
	a = root(a);
	b = root(b);
	if(a == b)
		return;
	if(ht[a] >= ht[b])
	{
		ht[a] = max(ht[a], ht[b]+1);
		par[b] = a;
	}
	else
	{
		ht[b] = max(ht[b], ht[a]+1);
		par[a] = b;
	}
	return;
}

