void init(int num)
{
    elem = vector<int>(num, 0);
    elmrank = vector<int>(num, 0);

    for (int i = 0; i < num; ++i)
    {
        elem[i] = i;
    }
}

int dfs(int num)
{
    if (elem[num] == num)
    {
        return num;
    }
    else
    {
        elem[num] = dfs(elem[num]);
        return elem[num];
    }
}

void unite(int a, int b)
{
    a = dfs(a);
    b = dfs(b);

    if (a == b)
    {
        return;
    }
    else
    {
        if (elmrank[a] < elmrank[b])
        {
            elem[a] = b;
        }
        else
        {
            if (elmrank[a] == elmrank[b])
            {
                elmrank[a]++;
            }
            elem[b] = a;
        }
    }
}


