struct UnionFind{
    std::vector<int> parent, rank, cnt, wi;

    UnionFind(int n) : parent(n), rank(n, 0), cnt(n, 1), wi(n, 0) {
        std::iota(parent.begin(), parent.end(), 0);
    }

    int find(int v){
        if(v == parent[v]){return v;}
        return parent[v] = find(parent[v]);
    }

    bool same(int v, int w){
        return find(v) == find(w);
    }

    void unite(int v, int w){
        v = find(v);
        w = find(w);

        if(v == w){return;}

        if(rank[v] > rank[w]){
            parent[w] = v;
            cnt[v] += cnt[w];
            wi[v] += wi[w];
        }else{
            parent[v] = w;
            cnt[w] += cnt[v];
            wi[w] += wi[v];
            if(rank[v] == rank[w]){rank[w] += 1;}
        }
    }

    int count(int v){
        return cnt[find(v)];
    }

    int width(int v){
        return wi[find(v)];
    }
};

UnionFind uf(100100);
int N;
std::vector<P> ps;
std::vector<int> ys;

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N;

    for(int i=0;i<N;++i){
        int x, y;
        std::cin >> x >> y;

        ps.emplace_back(x, y);
        ys.emplace_back(y);
    }

    std::sort(ys.begin(), ys.end());
    ys.erase(std::unique(ys.begin(), ys.end()), ys.end());

    for(int i=0;i<N;++i){
        snd(ps[i]) = std::lower_bound(ys.begin(), ys.end(), snd(ps[i])) - ys.begin();
    }

    std::sort(ps.begin(), ps.end());

    for(int i=0,j=1;i<N;){
        while(j < N && fst(ps[j]) == fst(ps[i])){
            uf.unite(snd(ps[j]), snd(ps[i]));
            j += 1;
        }

        uf.wi[uf.find(snd(ps[i]))] += 1;

        i = j;
        j += 1;
    }

    ll res = 0;

    for(int i=0;i<ys.size();++i){
        if(i == uf.find(i)){
            // std::cout << ys[i] << ", " << uf.count(i) << ", " << uf.width(i) << std::endl;
            res += 1ll * uf.count(i) * uf.width(i);
        }
    }

    res -= N;

    std::cout << res << std::endl;
}

