typedef long long ll;
#define FOR(I,A,B) for(ll I = ll(A); I < ll(B); ++I)

class UnionFind{
public:
	vector<int> par;
	//0-indexed
	UnionFind(int n){init(n);}
	void init(int n = 1) {
		par.resize(n);
		for(int i=0;i<n;++i)par[i]=i;
	}
	int root(int x = 1){
		if(par[x]==x)return x;
		return par[x]=root(par[x]);
	}
	void unite(int x = 1,int y = 1){
		x = root(x);
		y = root(y);
		if(x==y)return;
		par[x] = y;
	}
};

int main(){
	ll N,xi,yi,ans=0;
	cin >> N;
	UnionFind uf(N);
	vector<ll> x(100001,-1),y(100001,-1),nx(N,0),ny(N,0);
	FOR(i,0,N){
		cin >> xi >> yi;
		if((x[xi]==-1)&&(y[yi]==-1)){
			x[xi] = y[yi] = i;
		}else if((x[xi]!=-1)&&(y[yi]==-1)){
			y[yi] = x[xi];
		}else if((x[xi]==-1)&&(y[yi]!=-1)){
			x[xi] = y[yi];
		}else{
			uf.unite(x[xi],y[yi]);
		}
	}
	FOR(i,0,100001){
		if(x[i]!=-1)nx[uf.root(x[i])]++;
		if(y[i]!=-1)ny[uf.root(y[i])]++;
	}
	FOR(i,0,N){
		ans += nx[i]*ny[i]-1;
	}
	cout << ans << endl;
}

