int lcm(int a,int b) { return a/gcd(a,b)*b; }

struct Point
{
	int x,y;
	vector<int> sameX,sameY;
	bool tag=false;
};

void dfs(set<int> &X,set<int> &Y,vector<Point> &pts,int now,int &cnt)
{
	cnt++;
	Point &p=pts[now];
	p.tag=true;
	X.insert(p.x);
	Y.insert(p.y);
	/*
	cout<<"\n"<<p.x<<" "<<p.y<<"\n";
	cout<<"x  "; for(auto i:p.sameX) cout<<i<<" "; cout<<"\n";
	cout<<"y  "; for(auto i:p.sameY) cout<<i<<" "; cout<<"\n";
	cout<<cnt<<"\n\n";
	*/
	for(auto &i:p.sameX)
	{
		if(pts[i].tag) continue;
		dfs(X,Y,pts,i,cnt);
	}
	for(auto &i:p.sameY)
	{
		if(pts[i].tag) continue;
		dfs(X,Y,pts,i,cnt);
	}
}

int32_t main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);

	int n; cin>>n;
	vector<Point> pts(n);
	map<int,int> mpX,mpY;
	For(i,0,n-1)
	{
		Point &p=pts[i];
		cin>>p.x>>p.y;
		if(mpX.count(p.x))
		{
			p.sameX.emplace_back(mpX[p.x]);
			pts[mpX[p.x]].sameX.emplace_back(i);
		}
		else mpX[p.x]=i;
		if(mpY.count(p.y))
		{
			p.sameY.emplace_back(mpY[p.y]);
			pts[mpY[p.y]].sameY.emplace_back(i);
		}
		else mpY[p.y]=i;
	}
	set<int> X,Y;
	int ans=0,cnt;
	For(id,0,n-1)
	{
		Point &i=pts[id];
		if(i.tag) continue;
		X.clear(); Y.clear(); cnt=0;
		dfs(X,Y,pts,id,cnt);
		ans+=sz(X)*sz(Y)-cnt;
		//cout<<sz(X)<<" "<<sz(Y)<<"\n";
	}
	cout<<ans<<"\n";
	return 0;
}

