	vector<int> data;
	vector<int> size;
	unionfind(int n){
		for(int i=0;i<n;i++){
			data.push_back(i);
			size.push_back(1);
		}
	}

	int find(int x){
		if(data[x]==x)return x;
		return data[x]=find(data[x]);
	}

	bool unite(int x,int y){
		x=find(x);y=find(y);
		if(x==y)return false;
		data[x]=y;
		size[y]+=size[x];
		return true;
	}

	bool check(int x,int y){
		return (find(x)==find(y));
	}

	int get_size(int x){
		int X = find(x);
		return size[X];
	}
};


