const ll MX = 100010;

struct UnionFind{
    vector<ll> par;
    vector<ll> sz;
    //type1, type2の数
    vector<ll> tp[2];

    UnionFind(ll n){
        par.resize(n);
        sz.resize(n);
        tp[0].resize(n);
        tp[1].resize(n);
        for (ll i = 0; i < n; i++){
            par[i] = i;
            sz[i] = 1;
            tp[i >= MX][i]++;
        }
    }

    ll find(ll x){
        if (par[x] == x){
            return x;
        }else{
            return par[x] = find(par[x]);
        }
    }

    void unite(ll x, ll y){
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (sz[x] > sz[y])
            swap(x, y);
        par[x] = y;
        sz[y] += sz[x];
        tp[0][y] += tp[0][x];
        tp[1][y] += tp[1][x];
    }

    bool same(ll x, ll y){
        return find(x) == find(y);
    }

    ll size(ll x){
        return sz[find(x)];
    }
};


signed main(){
    ios::sync_with_stdio(false);
