        x--,y--;
        y += MX;
        uni.unite(x,y);
    }
    for(int i=0;i<2*MX;i++){
        if(i == uni.find(i)){
            ans += uni.tp[0][i] * uni.tp[1][i];
        }
    }
    ans -= n;
    cout << ans << endl;


}

