      buf.push_back(ps[i].second);
    } else {
      int now = buf[0];
      for (int j = 1; j < buf.size(); j++) {
        u.connect(now, buf[j]);
      }
      buf.clear();
      buf.push_back(ps[i].second);
    }
  }
  int now = buf[0];
  for (int j = 1; j < buf.size(); j++) {
    u.connect(now, buf[j]);
  }
  ll ans = 0;
  vector<set<int>> q(101010);
