#include <bits/stdc++.h>

using namespace std;

using ll = long long;

struct UnionFind {
    //各要素が属する集合の代表(根)を管理する
    //もし、要素xが根であればdata[x]は負の値を取り、-data[x]はxが属する集合の大きさに等しい
    vector<int> data;
    vector<ll> cntx, cnty, cnte;

    UnionFind(int sz) : data(2 * sz, -1), cntx(2 * sz, 0), cnty(2 * sz, 0), cnte(2 * sz, 0) {
        for (int i = 0; i < sz; i++) cntx[i]++;
        for (int i = sz; i < sz * 2; i++) cnty[i]++;
    }

    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        bool is_union = (x != y);
        if (is_union) {
            if (data[x] > data[y]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
            cntx[x] += cntx[y];
            cnty[x] += cnty[y];
            cnte[x] += cnte[y];
            cnte[x]++;
            cntx[y] = 0;
            cnty[y] = 0;
            cnte[y] = 0;
        } else {
            cnte[x]++;
        }
        return is_union;
    }

    int find(int x) {
        if (data[x] < 0) { //要素xが根である
            return x;
        } else {
            data[x] = find(data[x]); //data[x]がxの属する集合の根でない場合、根になるよう更新される
            return data[x];
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return -data[find(x)];
    }

    ll calc() {
        ll res = 0;
        for (int i = 0; i < data.size(); i++) {
            if (i == find(i)) {
                res += cntx[i] * cnty[i] - cnte[i];
            }
        }
        return res;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<int> x(n), y(n);
    UnionFind uf(100000);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        uf.unite(x[i] - 1, 100000 + y[i] - 1);
    }

    cout << uf.calc() << endl;
    return 0;
}

