void solve() {
	vector<vector<int>> xy(1e5+1);
	vector<vector<int>> yx(1e5+1);
	int N; cin >> N;
	vector<pii> ps;
	REP(i, N){
		int x, y; cin >> x >> y;
		ps.emplace_back(x, y);
	}

	unordered_set<int> xss;
	unordered_set<int> yss;
	for (auto& p : ps) {
		xy[p.first].push_back(p.second);
		yx[p.second].push_back(p.first);
		xss.insert(p.first);
		yss.insert(p.second);
	}

	vector<int> xs, ys;
	for (auto& a : xss) {
		xs.push_back(a);
	}
	for (auto& a : yss) {
		ys.push_back(a);
	}

	UnionFind uf(1e5 + 1);

	REP(i, N) {
		for (auto& y : ys) {
			int old = -1;
			for (auto& x : yx[y]) {
				if (old != -1) {
					uf.unite(x, old);
				}
				old = x;
			}
		}
	}

	unordered_map<int, unordered_set<int>> memo;
	for (auto x : xs) {
		int root = uf.root(x);
		for (auto y : xy[x]) {
			memo[root].insert(y);
		}
	}

	int cnt = 0;
	for (auto& x : xs) {
		cnt += memo[uf.root(x)].size() - xy[x].size();
	}
	cout << cnt << endl;
}

