set<int> xValues[100001];
set<int> yValues[100001];
set<int> yConnections[100001];

set<int> depthFirstSearch(int current, set<int> cg) {
    for (int other: yConnections[current]) {
        if (cg.count(other)) continue;
        cg.insert(other);
        depthFirstSearch(other, cg);
    }
    return cg;
}

set<set<int>> findGroups() {
    set<int> used;
    set<set<int>> groups;
    set<int> currentGroup;
    for (int i = 1; i <= 100000; i++) {
        if (used.count(i)) continue;
        currentGroup.insert(i);
        currentGroup = depthFirstSearch(i, currentGroup);
        if (currentGroup.size() == 1) {
            currentGroup.clear();
            continue;
        }
        for (int u: currentGroup) used.insert(u);
        groups.insert(currentGroup);
        currentGroup.clear();
    }
}

ll sumPerGroup(set<int> ys) {
    set<int> xs;

    int points = 0;
    for (int y: ys) {
        for (int x: xValues[y]) {
            xs.insert(x);
        }
        points += xValues[y].size();
    }
    long long xSize = xs.size();
    long long ySize = ys.size();
    long long numPoints = points;

    return xSize*ySize-points;
}

void solve() {
    int n; cin >> n;

    fo(i, 100001) {
        set<int> xx;
        set<int> yy;
        set<int> yc;
        xValues[i] = xx;
        yValues[i] = yy;
        yConnections[i] = yc;
    }

    int x, y;
    fo(i, n) {
        scanf("%d %d", &x, &y);
        for(int yOther: yValues[x]) {
            yConnections[yOther].insert(y);
            yConnections[y].insert(yOther);
        }
        yValues[x].insert(y);
        xValues[y].insert(x);
    }
    set<set<int>> groups = findGroups();

    ll ans = 0;
    for (set<int> g: groups) ans += sumPerGroup(g);

    cout << ans;

}

