void solve() {
  int n;
  cin >> n;
  set<int> xset, yset;
  vector<pair<int, int>> xy;
  rep(i, n) {
    int x, y;
    cin >> x >> y;
    xset.insert(x);
    yset.insert(y);
    xy.emplace_back(x, y);
  }
  vi32 xs, ys;
  each(x, xset) xs.push_back(x);
  each(y, yset) ys.push_back(y);
  int m = sz(xs) + sz(ys);
  vector<vi32> g(m);
  rep(i, n) {
    int x, y;
    tie(x, y) = xy[i];
    int xi = lower_bound(all(xs), x) - xs.begin();
    int yi = lower_bound(all(ys), y) - ys.begin();
    yi += sz(xs);
    g[xi].emplace_back(yi);
    g[yi].emplace_back(xi);
  }
  i64 ans = 0;
  vi32 seen(m);
  int cnts;
  vi32 cnt(2);
  auto dfs = [&](auto dfs, int u, int mod) {
    if (seen[u]) return;
    seen[u] = 1;
    cnt[mod]++;
    cnts += sz(g[u]);
    each(v, g[u]) {
      dfs(dfs, v, 1 - mod);
    }
  };
  rep(i, m) {
    if (seen[i]) continue;
    cnt.assign(2, 0);
    cnts = 0;
    dfs(dfs, i, 0);
    ans += (i64) cnt[0] * cnt[1] - cnts / 2;
  }
  cout << ans << endl;
}

