struct UF {
    vi v;
    UF(int n) : v(n, -1) {}
    int root(int i) { return (v[i] < 0 ? i : v[i] = root(v[i])); }
    bool in(int i, int j) { return (root(i) == root(j)); }
    void merge(int i, int j) {
        if((i = root(i)) == (j = root(j))) return ;
        if(v[i] < v[j]) swap(i, j);
        v[i] += v[j];
        v[j] = i;

        return ;
    }
};

piii A[100000];
int B[100000];

int main() {
    int n; cin >> n;
    UF uf(n);
    int u, v;
    for(int i = 0; i < n; ++i) {
        cin >> u >> v;
        A[i] = piii(u, v, i); 
    }

    sort(A, A + n);
    for(int i = 1; i < n; ++i) {
        int l, g, f, k;
        tie(u, v, k) = A[i];
        tie(l, f, g) = A[i - 1];
        if(l == u) uf.merge(k, g);
    }

    sort(A, A + n, [](piii& r, piii& t) -> bool {
        int u, v, h, l, g, f;
        tie(u, v, h) = r;
        tie(l, g, f) = t;
        return v < g;
    });

    for(int i = 1; i < n; ++i) {
        int l, g, f, k;
        tie(u, v, k) = A[i];
        tie(l, f, g) = A[i - 1];
        if(v == f) uf.merge(k, g);
    }

    set <int> xA[20000], yA[20000];

    for(int i = 0; i < n; ++i) {
        int h;
        tie(u, v, h) = A[i];
        xA[uf.root(h)].insert(u);
        yA[uf.root(h)].insert(v);
        B[uf.root(h)] += 1;
    }

    ll mx = 0;
    for(int i = 0; i < n; ++i) {
      	ll nx = (ll) xA[i].size() * yA[i].size();
      	nx -= B[i];
        mx += max(nx, 0LL);
    }

    cout << mx;

    return 0;
}

