vpii y[100010]; // y[i] := x = i にあるy座標の列(sorted)
pii P[100010];
bool visited[100010];

int bfs(int idx)
{
	if (visited[idx]) return 0;
	queue<pair<pii, int>> q;
	q.emplace(P[idx], idx);

	set<int> SX, SY;
	SX.insert(P[idx].first);
	SY.insert(P[idx].second);
	visited[idx] = true;

	int sub = 1;

	while (q.size()) {
		auto cur = q.front(); q.pop();

		int curx = cur.first.first, cury = cur.first.second;
		int pid = cur.second;

		int xidx = lower_bound(all(x[cury]), pii(curx, pid)) - begin(x[cury]);
		int yidx = lower_bound(all(y[curx]), pii(cury, pid)) - begin(y[curx]);

		for (int i = -1; i <= 1; ++i) {
			if (0 <= xidx + i and xidx + i < x[cury].size()) {
				pii neix = x[cury][xidx + i];
				int nx = neix.first;
				int id = neix.second;

				if (visited[id]) continue;
				sub++;

				SX.insert(nx);
				q.emplace(pii(nx, cury), id);
				visited[id] = true;
			}
		}
		for (int i = -1; i <= 1; ++i) {
			if (0 <= yidx + i and yidx + i < y[curx].size()) {
				pii neiy = y[curx][yidx + i];
				int ny = neiy.first;
				int id = neiy.second;

				if (visited[id]) continue;
				sub++;
				SY.insert(ny);
				q.emplace(pii(curx, ny), id);
				visited[id] = true;
			}
		}
	}

	return SX.size() * SY.size() - sub;
}

