int BIG(vi & e, int x) {
	int l = 0, r = sz(e) - 1;
	while(l + 1 < r) {
		int mid = l + r >> 1;
		if(e[mid] <= x) l = mid;
		else r = mid;
	}
	if(e[l] > x) return sz(e) - l;
	if(e[r] > x) return sz(e) - r;
	return 0;
}
int SMALL(vi & e, int x) {
	int l = 0, r = sz(e) - 1;
	while(l + 1 < r) {
		int mid = l + r >> 1;
		if(e[mid] >= x) r = mid;
		else l = mid;
	}
	if(e[r] < x) return r + 1;
	if(e[l] < x) return l + 1;
	return 0;
}
