    }

    ll ans = -N;
    vi vis(MA);
    rep(i, N) {
        int x = uf[X[i]];
        if (vis[x]++)continue;
        ans += (ll)uf.getSize(X[i])*uf.getSize(MA+Y[i]);
    }
    cout << ans << endl;
}

