class DisjointSet {
    public:
        DisjointSet(int n) : N(n), pars(n, -1) {

        }

        int find(int x) {
            return pars[x] < 0 ? x : (pars[x] = find(pars[x]));
        }

        bool merge(int x, int y) {
            x = find(x), y = find(y);
            if (x == y) {
                return false;
            }

            if (pars[x] < pars[y]) {
                swap(x, y);
            }
            pars[y] += pars[x];
            pars[x] = y;
            return true;
        }

    private:
        int N;
        vector<int> pars;
};

class Solution {
public:
    long long solve(vector<pair<int,int>>& P) {
        int n = P.size();
        DisjointSet ds(n);

        map<int,int> xm;
        map<int,int> ym;

        for (int i = 0; i < n; ++i) {
            int x = P[i].first;
            int y = P[i].second;
            if (xm.count(x) == 0) {
                xm[x] = i;
            } else {
                ds.merge(i, xm[x]);
            }
            if (ym.count(y) == 0) {
                ym[y] = i;
            } else {
                ds.merge(i, ym[y]);
            }
        }

        vector<vector<int>> Xs(n);
        vector<vector<int>> Ys(n); 
        for (int i = 0; i < n; ++i) {
            int x = ds.find(i);
            Xs[x].push_back(P[i].first);
            Ys[x].push_back(P[i].second);
        } 

        long long res = 0;
        for (int i = 0; i < n; ++i) {
            sort(Xs[i].begin(), Xs[i].end());
            Xs[i].resize(unique(Xs[i].begin(), Xs[i].end()) - Xs[i].begin());
            sort(Ys[i].begin(), Ys[i].end());
            Ys[i].resize(unique(Ys[i].begin(), Ys[i].end()) - Ys[i].begin());

            res += Xs[i].size() * 1LL * Ys[i].size();
        }
        res -= n;
        return res;
    }
};

