    while (!que.empty()) {
      int u = que.front(); que.pop();
      for (auto v : G[u]) {
        if (seen[v]) continue;
        seen[v] = true;
        que.push(v);
        X.insert(x[v]);
        Y.insert(y[v]);
        ++cnt;
      }
    }

    ans += X.size() * Y.size() - cnt;
  }

  cout << ans << endl;
  return 0;
}

