int getRoot(int v){ return root[v] == -1 ? v : root[v] = getRoot(root[v]); }

int main(){
    int N;
    while(cin >> N){
        map<int, int> xDict;
        map<int, vector<int>> ySet;
        vector<set<int>> S(N);
        vector<int> ySize(N, 0);
        for(int i=0;i<N;i++){
            int x, y; cin >> x >> y;
            if(!xDict.count(x)){
                int idx = xDict.size();
                xDict[x] = idx;
            }
            S[xDict[x]].insert(y);
            ySize[xDict[x]]++;
            if(!ySet.count(y)) ySet[y] = vector<int>();
            ySet[y].push_back(xDict[x]);
        }
        fill(root, root+N, -1);
        fill(size, size+N, 1);
        for(auto& item : ySet){
            auto& v = item.second;
            for(int i=0;i+1<v.size();i++){
                int p = getRoot(v[i]);
                int q = getRoot(v[i+1]);
                if(p == q) continue;
                if(S[p].size() < S[q].size()) swap(p, q);
                for(auto t : S[q]) S[p].insert(t);
                root[q] = p;
                size[p] += size[q];
                ySize[p] += ySize[q];
            }
        }
        long long res = 0;
        for(int i=0;i<N;i++){
            int r = getRoot(i);
            if(r != i) continue;
            res += (long long)size[r] * S[r].size() - ySize[r];
        }
        cout << res << endl;
    }
}

