struct DSU {
  vector<int> par, rank;

  DSU(const size_t &_n) {
    par.resize(_n), rank.resize(_n);
    iota(par.begin(), par.end(), 0);
    fill(rank.begin(), rank.end(), 1);
  }

  int find(int x) {
    return par[x] == x ? x : par[x] = find(par[x]);
  }

  int unite(int u, int v) {
    u = find(u), v = find(v);
    if( u == v ) return u;
    int parent = u, child = v;
    if( rank[child] > rank[parent] ) swap(parent, child);
    // if( rank[parent] == rank[child] ) rank[parent]++;
    rank[parent] += rank[child];
    par[child] = parent;
    return parent;
  }

};

DSU dsu(N);

int main() {
  ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);

  cin >> n;

  fill(sz, sz+N, 0);

  for(int i=0; i<n; i++) {
    int x, y; cin >> x >> y;
    a[x].emplace_back(y);
  }

  ll ans = 0;
  for(int i=0; i<N; i++) {
    if( a[i].empty() ) continue;
    vi sets;
    for(int y: a[i]) {
      int s = dsu.find(y);
      sets.emplace_back(s);
    }
    sort(all(sets)); sets.erase(unique(all(sets)), sets.end());

    ll tot = 1;
    for(int sid: sets) tot += sz[sid];
    // pr(sets, tot);

    for(int sid: sets) {
      int p = dsu.find(sets.front()), q = sid;
      if( p == q ) continue;
      ll pcol = sz[p], qcol = sz[q];
      ll prow = dsu.rank[p], qrow = dsu.rank[q];
      // pr(p, q, prow, pcol, qrow, qcol);
      ans += (pcol * qrow + prow * qcol);
      dsu.unite(p, q);
    }

    int par = dsu.find(sets.front());

    sz[par] = tot;
    ans += dsu.rank[par] - a[i].size();
  }

  cout << ans << endl;

}
