#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MAX = 1e5;

struct UnionFind {
    vector<ll> par,rank,cnt; // par[i]:iの親の番号,rank[r]:rを根とする木の高さ,cnt[r]:rを根とする木の要素数

    UnionFind(ll N){ //全て根として初期化
        for(ll i = 0; i < N; i++) par.push_back(i);
        rank.assign(N,0);
        cnt.assign(N,1);
    }

    ll root(ll x){ // xの根を返す
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(ll x,ll y){ // xの木とyの木を併合
        ll rx = root(x); 
        ll ry = root(y);
        if (rx == ry) return;

        if(rank[rx] < rank[ry]){
            par[rx] = ry;
            cnt[ry] += cnt[rx]; 
        }else{
            par[ry] = rx;
            cnt[rx] += cnt[ry];
            if(rank[x] == rank[y]) rank[rx] ++;
        }
    }

    ll tsize(ll x){ //　xの木の要素数を返す
        ll rx = root(x);
        return cnt[rx];
    }

    bool same(ll x,ll y){ // xとyが同一の木に存在するかを返す
        ll rx = root(x);
        ll ry = root(y);
        return rx == ry;
    }
};

int main(){
    int n;
    ll ans = 0;
    cin >> n;
    vector<int> x(n),y(n);
    UnionFind tree(2*MAX+1);

    for(int i = 0;i < n;i ++){
        cin >> x[i] >> y[i];
        tree.unite(x[i],y[i]+MAX);
    }
    map<int,ll> mpx,mpy;

    for(int i = 1;i <= MAX;i ++){
        mpx[tree.root(i)] ++;
    }
    for(int i = MAX+1;i <= 2*MAX;i ++){
        mpy[tree.root(i)] ++;
    }

    for(int i = 1;i <= 2*MAX;i ++){
        ans += mpx[i]*mpy[i];
    }

    cout << ans - n << endl;
    return 0;
}

