		u[x].Union(u[y + 100000]);
	}
	long r = 0;
	for (int i = 0; i < 200000; i++)
		if (u[i + 1].p == nullptr)
			r += u[i + 1].a*long(u[i + 1].s - u[i + 1].a);
	cout << r - n << endl;
