    constexpr ll MAX = 1e5;

    vector<ll> x(N), y(N);
    for (ll i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
        y[i] += MAX + 1;
    }

    vector<vector<ll>> edges(2 * MAX + 2);

    for (ll i = 0; i < N; i++) {
        edges[x[i]].push_back(y[i]);
        edges[y[i]].push_back(x[i]);
    }

    ll ans = 0;

    vector<bool> visit(2 * MAX + 2, false);
    for (ll i = 0; i < 2 * MAX + 2; i++) {
        ll X_num = 0, Y_num = 0;
        stack<ll> st;
        st.push(i);
        while (!st.empty()) {
            ll t = st.top();
            st.pop();
            if (visit[t]) {
                continue;
            }

            visit[t] = true;
            (t <= MAX ? X_num++ : Y_num++);

            for (ll next : edges[t]) {
                if (!visit[next]) {
                    st.push(next);
                }
            }
        }

        ans += X_num * Y_num;
    }

    cout << ans - N << endl;
}

