    int find(int x){
        if (par[x] == x) return x;
        else return par[x] = find(par[x]);
    }
    UF(int n):par(_DSU::get(n+10)),rank(_DSU::get(n+10)){
	for(int i = 0;i<n;i++){
            par[i] = i,rank[i] = 0;
        }
    }
    bool unite(int x, int y){
    	x = find(x);y = find(y);
	if (x == y)return false;
	if (rank[x] < rank[y])swap(x,y);
    par[y] = x;
    if (rank[x] == rank[y])rank[x]++;
	return true;
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
};
