struct UnionFind {
    UnionFind(int n) : p(n, -1) {}
    int root(int u) {
        return p[u] < 0 ? u : p[u] = root(p[u]);
    }
    int size(int u) {
        return -p[root(u)];
    }
    bool same(int u, int v) {
        return root(u) == root(v);
    }
    void unite(int u, int v) {
        u = root(u);
        v = root(v);
        if (u == v) return;
        if (p[u] > p[v]) swap(u, v);
        p[u] += p[v];
        p[v] = u;
    }
    vector<int> p;
};

struct P {
    int x, y, i;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<P> p(n);
    for (int i = 0; i < n; i++) {
        cin >> p[i].x >> p[i].y;
        p[i].i = i;
    }

    UnionFind uf(n);

    sort(p.begin(), p.end(), [](const P &p1, const P &p2) {
        return p1.x < p2.x;
    });
    for (int i = 1; i < n; i++) {
        if (p[i].x == p[i - 1].x) uf.unite(p[i].i, p[i - 1].i);
    }

    sort(p.begin(), p.end(), [](const P &p1, const P &p2) {
        return p1.y < p2.y;
    });
    for (int i = 1; i < n; i++) {
        if (p[i].y == p[i - 1].y) uf.unite(p[i].i, p[i - 1].i);
    }

    for (int i = 0; i < n; i++) {
        p[i].i = uf.root(p[i].i);
    }
    sort(p.begin(), p.end(), [](const P &p1, const P &p2) {
        return p1.i < p2.i;
    });

    ll s = 0;
    int i0 = 0, i3 = p[0].i;
    for (int i1 = 0; i1 <= n; i1++) {
        if (i1 < n && p[i1].i == i3) continue;

        set<int> sx;
        for (int i = i0; i < i1; i++) {
            sx.insert(p[i].x);
        }
        set<int> sy;
        for (int i = i0; i < i1; i++) {
            sy.insert(p[i].y);
        }
        //cout << i0 << ' ' << i1 << ' ' << sx.size()  << ' ' << sy.size() << ' ' << (i1 - i0) << endl;
        s += sx.size() * sy.size() - (i1 - i0);
        if (i1 == n) break;
        i0 = i1;
        i3 = p[i1].i;
    }

    cout << s << endl;

    return 0;
}

