      cin >> x[i] >> y[i];
    }

    // x, yをソート
    vector<pair<int, int>> xy(N);
    for (int i = 0; i < N; ++i) {
        xy[i] = make_pair(x[i], y[i]);
    }
    sort(xy.begin(), xy.end());
    for (int i = 0; i < N; ++i) {
        x[i] = xy[i].first;
        y[i] = xy[i].second;
    }

    // mapで探索済みか管理
    map<pair<int, int>, int> mp;
    for (int i = 0; i < N; ++i) {
        mp[xy[i]] = 0;
    }

    ll ans = 0; // 操作後の点の数
    set<int> setX;
    set<int> setY;
    stack<pair<int, int>> st;
    stack<int> coY; // stの点とx座標が同じ点のy座標
    for (int i = 0; i < N; ++i) {
        if(mp[xy[i]] == 0){
            st.push(xy[i]);
            mp[xy[i]] = 1;
            while (! st.empty()){
                while (! st.empty()){
                    auto top = st.top();
                    st.pop();
                    if(setX.count(top.first) == 0){
                        setX.insert(top.first);
                        auto iter1 = lower_bound(x.begin(), x.end(), top.first);
                        auto iter2 = upper_bound(x.begin(), x.end(), top.first);
                        for (int j = iter1 - x.begin(); j < iter2 - x.begin(); ++j) {
                            if(mp[xy[j]] == 0){
                                mp[xy[j]] = 1;
                                coY.push(y[j]);
                            }
                        }
                    }
                }
                while (! coY.empty()){
                    int top = coY.top();
                    coY.pop();
                    if(setY.count(top) == 0){
                        setY.insert(top);
                        auto iter1 = lower_bound(y.begin(), y.end(), top);
                        auto iter2 = upper_bound(y.begin(), y.end(), top);
                        for (int j = iter1 - y.begin(); j < iter2 - y.begin(); ++j) {
                            if(mp[xy[j]] == 0){
                                mp[xy[j]] = 1;
                                st.push(xy[j]);
                            }
                        }
                    }
                }
            }

            ll temp = setX.size();
            temp *= setY.size();
            ans += temp;
            setX.clear();
            setY.clear();
        }
    }

    ans -= N;
    cout << ans;
    return 0;
}

