struct UnionFind
{
   vector<int> A, S;

   UnionFind(int n){
      A.resize(n+1);
      S.resize(n+1);
      for (int i = 1; i <= n; ++i)
      {
         A[i] = i;
         S[i] = 1;         
      }
   }

   int find(int x){
      while(x != A[x]){
         A[x] = A[A[x]];
         x = A[x];
      }
      return x;
   }

   bool unite(int x, int y){
      x = find(x), y = find(y);
      if(x == y)
         return false;
      if(S[x] < S[y])swap(x, y);
      S[x] += S[y];
      A[y] = x;
      return true;
   } 

   int getSize(int x){
      x = find(x);
      return S[x];
   }
};

