struct Dsu {
  struct node_struct {
    int par, size, len[2];
    node_struct(int p, int s, int b) : par(p), size(s) { 
      for (int c: {0, 1}) len[c] = b == c; 
    }
    void merge(node_struct &b) {
      b.par = par;
      size += b.size;
      len[0] += b.len[0];
      len[1] += b.len[1];
    }
  };
  vector<node_struct> nodes;
  Dsu(int n) {
    nodes.reserve(n);
    for (int i = 0; i < n / 2; ++i) nodes.emplace_back(i, 1, 0);
    for (int i = 0; i < n / 2; ++i) nodes.emplace_back(i + n / 2, 1, 1);
  }
  int anc(int x) {
    while (x != nodes[x].par) x = nodes[x].par;
    return x;
  }
  bool unite(int x, int y) {
    int a = anc(x);
    int b = anc(y);
    if (a == b) return false;
    if (nodes[a].size < nodes[b].size) swap(a, b);
    nodes[a].merge(nodes[b]);
    return true;
  }
};

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
  int n, x, y; cin >> n;
  const int MAXN = 1e5 + 10;
  Dsu djs(MAXN * 2);
  for (int i = 0; i < n; ++i) {
    cin >> x >> y;
    djs.unite(x, y + MAXN);
  }
  vector<bool> vis(MAXN * 2, false);
  LL ans = 0;
  for (int i = 0; i < MAXN * 2; ++i) if (not vis[djs.anc(i)]) {
    int j = djs.anc(i);
    ans += 1ll * djs.nodes[j].len[0] * djs.nodes[j].len[1];
    vis[j] = 1;
  }
  cout << ans - n << '\n';
}

