struct UnionFindTree {
  vector<int> par;
  int n;

  UnionFindTree(int _n) : n(_n) {
    par.resize(_n);
    for (int i = 0; i < _n; i++) {
      par[i] = i;
    }
  }

  int findParent(int v) {
    if (par[v] == v) return v;
    return par[v] = findParent(par[v]);
  }

  void merge(int x, int y) {
    x = findParent(x);
    y = findParent(y);
    if (x == y) return;
    else {
      par[y] = x;
    }
  }
};

int main()
{
  int N;
  vector< pair<int, int> > p;
  map<int, int> x_map, y_map;

  scanf("%d", &N);
  p.resize(N);
  vector<int> xs[N], ys[N];

  for (int i = 0; i < N; i++) {
    scanf("%d %d", &p[i].first, &p[i].second);
    int x_id = (x_map.find(p[i].first) != x_map.end() ? x_map[p[i].first] : x_map.size());
    int y_id = (y_map.find(p[i].second) != y_map.end() ? y_map[p[i].second] : y_map.size());
    x_map[p[i].first] = x_id;
    y_map[p[i].second] = y_id;
    xs[x_id].push_back(i);
    ys[y_id].push_back(i);
  }

  UnionFindTree uf(N);

  for (int i = 0; i < x_map.size(); i++) {
    if (xs[i].size() >= 2) {
      for (int j = 1; j < xs[i].size(); j++) {
        uf.merge(xs[i][0], xs[i][j]);
      }
    }
  }

  for (int i = 0; i < y_map.size(); i++) {
    if (ys[i].size() >= 2) {
      for (int j = 1; j < ys[i].size(); j++) {
        uf.merge(ys[i][0], ys[i][j]);
      }
    }
  }

  set<int> gr_x[N], gr_y[N];
  for (int i = 0; i < N; i++) {
    gr_x[uf.findParent(i)].insert(p[i].first);
    gr_y[uf.findParent(i)].insert(p[i].second);
  }
  long long ans = 0;
  for (int i = 0; i < N; i++) {
    ans += (long long)gr_x[i].size() * gr_y[i].size();
  }

  printf("%lld\n", ans - N);

  return 0;
}

