vector<int> e[2][100001];
bool used[2][100001];

pair<int, int> dfs(int a, int b) {
    used[a][b] = true;
    pair<int, int> ret = {0, 0};
    (a == 0 ? ret.first : ret.second)++;
    for(const auto &x : e[a][b]) {
        if(!used[!a][x]) {
            pair<int, int> p = dfs(!a, x);
            ret.first += p.first;
            ret.second += p.second;
        }
    }
    return ret;
}

