const int MAX = 1e5+10;

int parent[MAX*2];
int rankb[MAX*2];

void init(int x) {
    for(int i = 0; i <= x; i++) {
        parent[i] = i;
        rankb[i] = 0;
    }
}

int root(int x) {
    return (parent[x]==x) ? x : parent[x]=root(parent[x]);
}

bool same(int x, int y) {
    return root(x) == root(y);
}

void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;

    if (rankb[x] < rankb[y])
        parent[x] = y;
    else {
        parent[y] = x;
        if (rankb[x] == rankb[y]) rankb[x]++;
    }
}

int N;
map<int, ll> ver, hor;

