typedef long long ll;
class UF
{
  public:
  int s;//木の頂点数
  vector<int> par;//親
  vector<int> rank;//木の深さ
  vector<int> size;//木の直径
  //コンストラクタ
  //n要素で初期化
  UF(int n)
  {
    s=n;
    par.resize(s);
    rank.resize(s);
    size.resize(s);
    for(int i=0;i<n;i++)
    {
      par[i]=i;
      rank[i]=0;
      size[i]=1;
    }
  }
  //木の根を求める
  int find(int x)
  {
    if(par[x]==x)
      return x;
    else
      return par[x]=find(par[x]);
  }
  //xとyの属する集合を併合
  void unite(int x,int y)
  {
    x=find(x);
    y=find(y);
    if(x==y)
      return;

    if(rank[x]<rank[y])
    {
      par[x]=y;
      size[y]+=size[x];
    }else{
      par[y]=x;
      size[x]+=size[y];
      if(rank[x]==rank[y])
        rank[x]++;
    }
  }
  //xとyが同じ集合に属するか否か
  bool same(int x,int y)
  {
    return find(x)==find(y);
  }
  //xが属する集合の大きさを求める
  int getsize(int x)
  {
    return size[par[x]];
  }
};
class Edge
{
	public:
	int to,cost;

	Edge(int t,int c)
	{
		to=t;cost=c;
	}
};
vector<Edge> g[200000];
bool used[200000];
int vecx=0; //連結成分中のx側の個数
//連結成分の深さを判定する
int saiki(int now,int dep)
{
	int ret=dep;
	used[now]=true;
	if(now<100000)
		vecx++;
	for(int i=0;i<g[now].size();i++)
	{
		Edge e=g[now][i];
		if(!used[e.to])
			ret=max(ret,saiki(e.to,dep+1));
	}
	return ret;
}

int main()
{
	int n;
	ll ans=0;
	cin>>n;
	UF u=UF(200000);
	for(int i=0;i<n;i++)
	{
		int x,y;
		cin>>x>>y;
		x--;y--;
		y+=100000;
		g[x].push_back(Edge(y,1));
		g[y].push_back(Edge(x,1));
		u.unite(x,y);
	}
	fill(used,used+200000,false);
	//全要素について深さを判定する
	//2以上なら条件を満たしているので求める
	for(int i=0;i<200000;i++)
	{
		if(!used[i])
		{
			vecx=0;
			if(saiki(i,0)>=2)
				ans+=vecx*(u.getsize(i)-vecx);
		}
	}
	cout<<max(0LL,ans-n)<<endl;
	return 0;
}

