int main() {
	int n; std::cin >> n;
	std::vector<std::vector<int>> nodes(200000);
	for (auto i = 0; i < n; ++i) {
		int x, y; std::cin >> x >> y; --x; --y;
		nodes[x * 2].push_back(y * 2 + 1);
		nodes[y * 2 + 1].push_back(x * 2);
	}
	std::stack<int> stack;
	std::vector<bool> is_visit(200000, false);
	long long int result = -n;
	for (auto i = 0; i < nodes.size(); ++i) if (!is_visit[i]) {
		long long int odd = 0, even = 0;
		stack.push(i);
		is_visit[i] = true;
		while (!stack.empty()) {
			const auto top = stack.top(); stack.pop();
			if (top % 2 == 1) ++odd;
			else ++even;
			for (const auto next : nodes[top]) if (!is_visit[next]) {
				is_visit[next] = true;
				stack.push(next);
			}
		}
		result += odd * even;
	}
	std::cout << result << std::endl;
}

