        cin >> a[i] >> b[i];
    }

    vector<list<pair<ll,ll>>> x(100001),y(100001);

    for(int i = 0; i < n; i++){
        x[a[i]].push_back(make_pair(a[i],b[i]));
        y[b[i]].push_back(make_pair(a[i],b[i]));
    }

    unordered_set<ll> usedp;
    vector<bool> usedx(100001,false),usedy(100001,false);

    ll ans = 0;

    for(int i = 1; i < 100001; i++){
        if(x[i].size() > 0 && usedp.find(ptoInd(x[i].front().first,x[i].front().second)) == usedp.end()){
            queue<pair<ll,ll>> q;
            for(auto itr = x[i].begin(); itr != x[i].end(); itr++){
                q.push(*itr);
            }
            ll xsize = 0;
            ll ysize = 0;
            ll count = 0;
            while(!q.empty()){
                auto tmp = q.front();
                q.pop();
                if(usedp.find(ptoInd(tmp.first,tmp.second)) != usedp.end()){
                    continue;
                }
                count++;
                usedp.insert(ptoInd(tmp.first,tmp.second));
                if(!usedx[tmp.first]){
                    xsize++;
                    usedx[tmp.first] = true;
                }
                if(!usedy[tmp.second]){
                    ysize++;
                    usedy[tmp.second] = true;
                }
                if(!usedx[tmp.first]){
                    for(auto itr = x[tmp.first].begin(); itr != x[tmp.first].end(); itr++){
                        if(usedp.find(ptoInd((*itr).first,(*itr).second)) == usedp.end()){
                            q.push(*itr);
                        }
                    }
                }
                if(!usedy[tmp.second]){
                    for(auto itr = y[tmp.second].begin(); itr != y[tmp.second].end(); itr++){
                        if(usedp.find(ptoInd((*itr).first,(*itr).second)) == usedp.end()){
                            q.push(*itr);
                        }
                    }
                }
            }
            ans += (xsize * ysize) - count;
        }
    }

    cout << ans << endl;

    return 0;
}

