struct UnionFind{
    vector<int> parent;
    vector<int> rank;
    UnionFind(int n){ parent = vector<int>(n, -1); rank = vector<int>(n, 0); }
    int find(int x){
        if(parent[x] == -1) return x;
        else return (parent[x] = find(parent[x]));
    }
    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(rank[x] < rank[y])
            parent[x] = y;
        else
            parent[y] = x;
        if(rank[x] == rank[y])
            ++rank[x];
        return true;
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
};

const int MAX_M = 100010;

void solve(long long N, std::vector<long long> x, std::vector<long long> y){
    UnionFind uf(MAX_M * 2 + 10);

    for(int i = 0; i < N; ++i) {
        uf.unite(x[i], y[i] + MAX_M);
    }

    vector<int> a(MAX_M * 2 + 10), b(MAX_M * 2 + 10);

    for(int i = 1; i <= 100000; ++i) {
        a[uf.find(i)]++;
        b[uf.find(i + MAX_M)]++;
    }

    int res = 0;
    for(int i = 1; i < MAX_M * 2 + 10; ++i) {
        res += a[i] * b[i];
    }

    cout << res - N << endl;
}

