using namespace std;

struct Point {
	int x;
	int y;
	int i;
};

pair<int64_t, int64_t> search(vector<Point>& ps, vector<Point>& psx, vector<Point>& psy, vector<bool>& used, int i) {
	assert(!used[i]);

	multiset<int64_t> xused;
	multiset<int64_t> yused;

	queue<Point> search;
	search.push(ps[i]);
	used[i] = true;

	int  count = 1;

	while (!search.empty()) {
		Point cur = search.front();
		search.pop();

		if (xused.find(cur.x) == xused.end()) {
			auto it = lower_bound(psx.begin(), psx.end(), cur, [](const Point & lhs, const Point & rhs) {
				return lhs.x < rhs.x;
				});
			while (it != psx.end() && it->x == cur.x) {
				if (it->y != cur.y && !used[it->i]) {
					used[it->i] = true;
					search.push(*it);
					count++;
				}
				it++;
			}
			xused.insert(cur.x);
		}
		if (yused.find(cur.y) == yused.end()) {
			auto it = lower_bound(psy.begin(), psy.end(), cur, [](const Point & lhs, const Point & rhs) {
				return lhs.y < rhs.y;
				});
			while (it != psy.end() && it->y == cur.y) {
				if (it->x != cur.x && !used[it->i]) {
					used[it->i] = true;
					search.push(*it);
					count++;
				}
				it++;
			}
			yused.insert(cur.y);
		}
	}

	if (xused.size() == 1 && yused.size() == 1) {
		return make_pair(count, 0);
	}
	return make_pair(count, (xused.size() * yused.size()) - count);
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n; cin >> n;

	vector<Point> ps(n);
	FOR_LT(i, 0, n) {
		cin >> ps[i].x >> ps[i].y;
		ps[i].i = i;
	}

	vector<Point> psx = ps;
	vector<Point> psy = ps;
	sort(psx.begin(), psx.end(), [](const Point & lhs, const Point & rhs) {
		return lhs.x < rhs.x;
		});
	sort(psy.begin(), psy.end(), [](const Point & lhs, const Point & rhs) {
		return lhs.y < rhs.y;
		});

	vector<bool> used(n, false);

	int64_t sum = 0;
	int64_t ans = 0;
	int i = 0;
	while (sum != n) {
		pair<int64_t, int64_t> cur = search(ps, psx, psy, used, i);

		sum += cur.first;
		ans += cur.second;

		while (i != n && used[i]) i++;
	}

	cout << ans << endl;

	return 0;
}

