namespace adaptor = boost::adaptors;
template<class T>using p_queue = std::priority_queue<T, std::vector<T>, std::greater<>>;


void Main()
{
	std::size_t N;
	std::cin >> N;
	std::map<int, std::map<int, std::size_t>> xs;
	std::map<int, std::map<int, std::size_t>> ys;
	std::vector<std::pair<int, int>> points(N);
	for (auto i : boost::irange<std::size_t>(0, N))
	{
		int x, y;
		std::cin >> x >> y;
		xs[x].emplace(y, i);
		ys[y].emplace(x, i);
		points[i] = std::make_pair(x, y);
	}
	boost::dynamic_bitset<> flag(N);
	std::size_t count = 0;
	for (auto i : boost::irange<std::size_t>(0, N))
	{
		if (flag[i])
		{
			continue;
		}
		auto x = points[i].first;
		auto y = points[i].second;
		if (xs[x].size() == 1 || ys[y].size() == 1)
		{
			continue;
		}
		std::set<int> xp, yp;
		std::stack<int> stack;
		stack.emplace(i);
		while (stack.size())
		{
			auto index = stack.top();
			stack.pop();
			if (flag[index])
			{
				continue;
			}
			flag[index] = true;
			auto tx = points[index].first;
			auto ty = points[index].second;
			for (auto x : xs[tx])
			{
				yp.emplace(x.first);
				stack.emplace(x.second);
			}
			for (auto y : ys[ty])
			{
				xp.emplace(y.first);
				stack.emplace(y.second);
			}
		}
		count += xp.size() * yp.size();
	}
	std::cout << count - flag.count() << std::endl;
}

int main()
{
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);
	std::cout << std::fixed << std::setprecision(15);
	Main();
}

