class UnionFind{
private:
  vector<int> node;
public:
  UnionFind(int n){
    node=vector<int>(n,-1);
  }
  int root(int x){
    if(node[x]<0) return x;
    return node[x]=root(node[x]);
  }
  int size(int x){
