		link[i] = i, d[i] = 1;
}
int root(int x) {
	if (link[x] == x)
		return x;
	else
		return (link[x] = root(link[x]));
}
ll merge(int a, int b) {
	a = root(a), b = root(b);
	if (a == b)
		return 0;
	ll a_size = c[a].size(), b_size = c[b].size(), dv = d[a];
	if (a > b)
		swap(a, b);
	if (c[a].size() < c[b].size())
