	for (int v : c[b])
		same += c[a].find(v) != c[a].end();
	ll count = (a_size - same) + (b_size - same) * dv;
	c[a].insert(c[b].begin(), c[b].end());
	c[b].clear();
	link[b] = a;
	d[a] = max(d[a], d[b]) + 1;
	return count;
}
