  map<int, set<int> > xy;
  map<int, set<int> > yx;
  IdGenerator<int> id;

  REP(i,n){
    const int x = getInt();
    const int y = getInt();

    xy[x].insert(y);
    yx[y].insert(x);
    id.getId(y);
  }

  UnionFind uf(id.size());

  for(const auto &a : xy){
    bool ok = false;
    for(const int y : a.second){
      if(yx[y].size() >= 2) ok = true;
    }
    if(!ok) continue;
    const int first = id.getId(*a.second.begin());
    for(const int y : a.second){
      const int second = id.getId(y);
      uf.unite(first, second);
    }
  }

  map<int, set<int> > m;
  map<int, int> cnt;

  for(const auto &a : yx){
    const int y = a.first;
    const int i = uf[id.getId(y)];
    m[i].insert(a.second.begin(), a.second.end());
    cnt[i]++;
  }

  ll ans = 0;
  for(const auto a : m){
    ans += (ll)cnt[a.first] * (ll)a.second.size();
  }
  ans -= n;
  printf("%lld\n", ans);

