void solve()
{
    int n;
    cin >> n;
    akari<int> xs(n), ys(n);
    akari<pair<int, int>> xp(n), yp(n);
    for (int i = 0; i < n; i++)
    {
        cin >> xs[i] >> ys[i];
        xp[i] = make_pair(xs[i], i);
        yp[i] = make_pair(ys[i], i);
    }
    sort(xp.begin(), xp.end());
    sort(yp.begin(), yp.end());
    UnionFind uf(n);
    for (int i = 0; i < n - 1; i++)
    {
        if (xp[i].first == xp[i + 1].first)
        {
            uf.merge(xp[i].second, xp[i + 1].second);
        }
        if (yp[i].first == yp[i + 1].first)
        {
            uf.merge(yp[i].second, yp[i + 1].second);
        }
    }
    int group = 0;
    akari<int> used(n, -1);
    map<int, int> cnt[n];
    set<int> s[n];
    for (int i = 0; i < n; i++)
    {
        int p = uf.root(i);
        if (used[p] == -1)
        {
            used[p] = group++;
        }
        p = used[p];
        cnt[p][ys[i]]++;
        s[p].insert(xs[i]);
    }
    i64 ans = 0;
    for (int i = 0; i < group; i++)
    {
        i64 m = s[i].size();
        for (auto &p : cnt[i])
        {
            ans += m - (i64)p.second;
        }
    }
    cout << ans << endl;
}

