using namespace std;

struct UnionFind{
    vector <int> par;
    vector <int> height;
    vector <int> card;

    UnionFind(int N){
        par.assign(N, 0);
        height.assign(N, 0);
        card.assign(N, 1);
        for(int i = 0; i < N; i++){
            par[i] = i;
        }
    }
    int set_size(int x){
        return card[root(x)];
    }
    int root(int x){
        if(x == par[x]){
            return x;
        }
        par[x] = root(par[x]);
        return par[x];
    }

    int same(int x, int y){
        return root(x) == root(y);
    }

    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y){
            return;
        }
        if(height[x] >= height[y]){
            par[y] = x;
            if(height[x] == height[y]){
                height[x] ++;
            }
            card[x] += card[y];
        } else {
            par[x] = y;
            card[y] += card[x];
        }
    }
};

vector <int> x_ids[100000];
vector <int> y_ids[100000];
