int main(){
    int N;
    cin >> N;
    int x_max = 0;
    int y_max = 0;
    for(int i = 0; i < N; i++){
        cin >> x[i] >> y[i];
        x_max = max(x_max, x[i]);
        y_max = max(y_max, y[i]);
        x_ids[x[i] - 1].push_back(i);
        y_ids[y[i] - 1].push_back(i);
    }

    UnionFind uf(N);
    for(int i = 0; i < x_max; i++){
        for(int j = 1; j < x_ids[i].size(); j++){
            uf.unite(x_ids[i][0], x_ids[i][j]);
        }
    }

    for(int i = 0; i < y_max; i++){
        for(int j = 1; j < y_ids[i].size(); j++){
            uf.unite(y_ids[i][0], y_ids[i][j]);
        }
    }

    map <int, int> group_to_x_num;
    map <int, int> group_to_y_num;
    for(int i = 0; i < N; i++){
        int rt = uf.root(i);
        if(group_to_x_num.find(rt) == group_to_x_num.end()){
            group_to_x_num[rt] = uf.set_size(rt);
        }
        if(group_to_y_num.find(rt) == group_to_y_num.end()){
            group_to_y_num[rt] = uf.set_size(rt);
        }
    }

    for(int i = 0; i < x_max; i++){
        if(x_ids[i].size() > 0){
            int rt = uf.root(x_ids[i][0]);
            group_to_x_num[rt] -= ((x_ids[i].size()) - 1);
        }
    }

    for(int i = 0; i < y_max; i++){
        if(y_ids[i].size() > 0){
            int rt = uf.root(y_ids[i][0]);
            group_to_y_num[rt] -= ((y_ids[i].size()) - 1);
        }
    }

    long long ans = 0;
