    for(int i=0;i<2*N_MAX;++i) {
        int p = uf.find(i);
        if(p != i) continue;
        int s = uf.size[p];
        if(s <= 3) continue;
        ans += (s/2) * (s/2);
    }
    ans -= n;

    cout << max(0LL, ans) << endl;
}

