    forn(i, n) cin >> p.fi >> p.se, M[p.se].push_back(p.fi);

    ll ans = 0;
    DSU dsu(1e5 + 10);
    DSU dsu2(1e5 + 10);
    Arr Y(1e5 + 10, -1);
    fori(y, 1, 1e5 + 5)
    {
        ll prev = -1;
        for (ll x : M[y])
        {
            if (Y[x] != -1)
            {
                dsu.merge(y, Y[x]);
                dsu2.merge(M[y].front(), M[Y[x]].front());
            }
            if (prev != -1)
                dsu2.merge(x, prev);
            prev = x;
            Y[x] = y;
        }
    }

    fori(y, 1, 1e5 + 5)
    {
        if (dsu.count(y) > 1 && dsu.get(y) == y)
        {
            ll x = M[y].front();
            ans += dsu.count(y) * dsu2.count(x);
        }
        if (dsu.count(y) == 1 && M[y].size() > 0)
            ans += M[y].size();
    }
    cout << (ans - n);
    return 0;
}

