//UnionFind
class UnionFind {
private:
    vector<int> par;
    vector<pair<int, int>> siz;
public:
    UnionFind(int n,int m) {
        par.resize(n+m, -1);
        siz.resize(n+m);
        fill(siz.begin(), siz.begin() + n, pair<int, int>(1, 0));
        fill(siz.begin()+n, siz.end(), pair<int, int>(0, 1));
    }

    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }

    bool unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return false;
        if (size(rx) < size(ry)) swap(rx, ry);
        par[rx] += par[ry];
        siz[rx].first += siz[ry].first;
        siz[rx].second += siz[ry].second;
        par[ry] = rx;
        return true;
    }

    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int size(int x) {
        return -par[root(x)];
    }

    int xsize(int x) {
        return siz[root(x)].first;
    }

    int ysize(int x) {
        return siz[root(x)].second;
    }
};

