struct UnionFind {
    int n;
    vector<int> rank;
    vector<int> parent;

    UnionFind(int n = 0) : n(n) {
        rank = vector<int>(n);
        parent = vector<int>(n);
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        return (parent[x] == x ? x : parent[x] = find(parent[x]));
    }

    void unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y)  return;

        if(rank[x] < rank[y])  swap(x, y);
        parent[y] = x;
        rank[x] += (rank[x] == rank[y]);
    }

    int count() {
        set<int> s;
        for(int i = 0; i < n; i++)  s.insert(find(i));
        return s.size();
    }
};

int main() {
