    UnionFind vertex(4e5); // 0 <= x < 2e5, 2e5 <= y < 4e5
    for(lint i=0; i<n; i++)  vertex.unite(x[i], y[i]);

    map<lint, lint> vx, vy;
    for(lint i=0; i<4e5; i++) {
        lint root = vertex.find(i);
        (i < 2e5 ? vx[root] : vy[root])++;
    }

    set<lint> roots;
    for(auto e : x)  roots.insert(vertex.find(e));

    lint ans = 0;
    for(auto root : roots) {
        ans += vx[root] * vy[root];
    }

    cout << ans - n << endl;
}

