void dfs(int v) {
    if (visited[v]) {
        return;
    }
    visited[v] = true;

    if (v < MAX_XY) {
        cx++;
    } else {
        cy++;
    }
    ce += g[v].size();

    for (int to : g[v]) {
        dfs(to);
    }
}

ll solve() {
    for (int i = 0; i < N; i++) {
        g[x[i]].push_back(y[i] + MAX_XY);
