struct Pos {
    int x, y;

    Pos(int posX, int posY)
    {
        x = posX;
        y = posY;
    }

    bool operator<(const Pos &another) const
    {
        return (y == another.y)?(x<another.x):(y<another.y);
    }
};

int main(int argc, char *argv[])
{
    int n;
    int ans;

    std::vector<int> vecX, vecY;
    std::vector<Pos> pos;

    std::cin >> n;

    vecX.resize(n);
    vecY.resize(n);
    pos.reserve(n);

    for (int i = 0; i < n; i++) {
        int x, y;
        std::cin >> x >> y;

        pos.push_back(Pos(x, y));

        vecX[i] = x;
        vecY[i] = y;
    }

    // 行列の圧縮
    std::sort(vecX.begin(), vecX.end());
    std::sort(vecY.begin(), vecY.end());

    vecX.erase(std::unique(vecX.begin(), vecX.end()), vecX.end());
    vecY.erase(std::unique(vecY.begin(), vecY.end()), vecY.end());

    if (vecX.size() < vecY.size()) {
        // swap
        std::swap(vecX, vecY);
        std::vector<Pos> posSwap;
        posSwap.reserve(n);
        for(int i = 0; i < n; i++) {
            posSwap.push_back(Pos(pos[i].y, pos[i].x));
        }
        std::swap(pos, posSwap);
    }

    std::sort(pos.begin(), pos.end());

    const int bitsX = vecX.size();
    const int lenX = std::ceil((double) bitsX / 64);
    int lenY = vecY.size();

    std::vector<std::uint64_t> bitsArray(lenX * lenY, 0);
    bitsArray.resize(lenX * lenY);

    // 色付け
    int ptrX = 0, ptrY = 0;
    for (int i = 0; i < n; i++) {
        int x = pos[i].x, y = pos[i].y;
        while(vecY[ptrY] != y) {
            ptrX = 0;
            ptrY++;
        }
        while(vecX[ptrX] != x) {
            ptrX++;
        }
        bitsArray[ptrY * lenX + (ptrX / 64)] |= ((std::uint64_t) 1)<<(ptrX % 64);
    }

    // 拡散
    std::vector<int> mul(lenY, 1);
    for (int i = 0; i < lenY; i++) {
        for (int j = 0; j < lenY; j++) {
            if (i == j) {continue;}
            if (mul[j] == 0) {continue;}
            std::uint64_t hasDouble = 0;
            for (int k = 0; k < lenX; k++) {
                hasDouble |= (bitsArray[i * lenX + k] & bitsArray[j * lenX + k]);
                if (hasDouble) {break;}
            }
            if (!hasDouble) {continue;}
            for (int k = 0; k < lenX; k++) {
                const std::uint64_t bitsOr = bitsArray[i * lenX + k] | bitsArray[j * lenX + k];
                bitsArray[i * lenX + k] = bitsOr;
            }
            mul[i] += mul[j];
            mul[j] = 0;
        }
    }

    std::uint64_t count = 0;
    for (int i = 0; i < lenY; i++) {
        if (mul[i] == 0) {continue;}
        for (int j = 0; j < lenX; j++) {
            count += _popcnt64(bitsArray[i * lenX + j]) * mul[i];
        }
    }

    ans = count - n;

    std::cout << ans << std::endl;

    return 0;
}

