    if(i < 100000) X[i] = 1;
    else Y[i] = 1;
  }
}

ll find(ll x){
  if(par[x] == x) return x;
  else{
    return par[x] = find(par[x]);
  }
}

bool same(ll x, ll y){
  return find(x) == find(y);
}

void unite(ll x, ll y){
  ll rx = find(x), ry = find(y);
  if(rx != ry){
    if(Rank[rx] >= Rank[ry]){
      par[ry] = rx;
      if(Rank[rx] == Rank[ry]) Rank[rx]++;
      X[rx] += X[ry];
      Y[rx] += Y[ry];
      edge[rx]++;
    }else{
      par[rx] = ry;
      X[ry] += X[rx];
      Y[ry] += Y[rx];
      edge[ry]++;
    }
  }else{
    edge[rx]++;
  }
}

