    this->sz = sz;
    par.clear();
    par.resize(2 * sz);
    cnt.clear();
    cnt.resize(2 * sz);
    for(int i=0;i<sz;++i) {
      par[i] = i;
      par[sz+i] = sz+i;
      cnt[i] = {1, 0};
      cnt[sz+i] = {0, 1};
    }
  }
  int root(int x) {
    return par[x] == x ? x : par[x] = root(par[x]);
  }
  void unite(int x, int y) {
    int rootx = root(x), rooty = root(y);
    if(rootx == rooty) return;
    ll cntxf = cnt[rootx].first, cntxs = cnt[rootx].second, cntyf = cnt[rooty].first, cntys = cnt[rooty].second;
    cnt[rootx] = {cntxf + cntyf, cntxs + cntys};
    par[rooty] = rootx;
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int sizex(int x) {
    return cnt[root(x)].first;
  }
  int sizey(int x) {
    return cnt[root(x)].second;
  }
};
