int sz[2*MAXN];
set<int> xCoords[2*MAXN], yCoords[2*MAXN];

int parent (int a) {
    return par[a] = par[a] == a ? a : parent(par[a]);
}
bool same (int a, int b) {
    return parent(a) == parent(b);
}
void unite (int a, int b) {
    a = parent(a), b = parent(b);
    if (a==b) return;
    if (sz[b] > sz[a]) swap(a,b);
    par[b] = a;
    sz[a] += sz[b];
    for (int x : xCoords[b]) xCoords[a].insert(x);
    for (int y : yCoords[b]) yCoords[a].insert(y);
}

set<int> pars;
