vector<bool> visited(2 * 100000, false);
vector<vector<int>> g(2 * 100000);

PII dfs(int v) {
    if (visited[v]) return {0,0};
    visited[v] = true;
    PII p(0,0);
    for (int u : g[v]) {
        PII x = dfs(u);
        p.first += x.first;
        p.second += x.second;
    }
    if (v < 100000) p.first++;
    else p.second++;
    return p;
}

