int main()
{
    int n;

    std::cin >> n;

    std::set<P> nvis, dat;

    std::vector<P> in(n);
    std::vector<int> xs, ys;

    rep(i, n)
    {
        int x, y;
        std::cin >> x >> y;
        in[i] = P(x, y);
        xs.push_back(x);
        ys.push_back(y);
    }

    std::sort(rag(xs));
    std::sort(rag(ys));
    xs.erase(std::unique(rag(xs)), std::end(xs));
    ys.erase(std::unique(rag(ys)), std::end(ys));

    rep(i, n)
    {
        int x = std::lower_bound(rag(xs), in[i].first) - std::begin(xs);
        int y = std::lower_bound(rag(ys), in[i].second) - std::begin(ys);
        dat.emplace(x, y);
        nvis.emplace(x, y);
    }

    std::queue<P> que;
    std::set<P> vis;

    while (!nvis.empty())
    {
        vis.clear();

        while (!que.empty())
            que.pop();

        que.push(*nvis.begin());
        vis.insert(que.front());

        while (!que.empty())
        {
