    vector<bool> visit(2 * MAX + 2, false);
    for (ll i = 0; i < 2 * MAX + 2; i++) {
        ll num = 0, X_num = 0, Y_num = 0;
        stack<ll> st;
        st.push(i);
        while (!st.empty()) {
            ll t = st.top();
            st.pop();

            num++;
            visit[t] = true;
            (t <= MAX ? X_num++ : Y_num++);

            for (ll next : edges[t]) {
                if (visit[next]) {
                    continue;
                }

                st.push(next);
            }
        }

        if (X_num == 0 || Y_num == 0) {
            continue;
        }

        ans += X_num * Y_num - num + 1;
    }

