ll count(const vii& g) {
  si sx;
  si sy;
  for (auto p : g) {
    sx.insert(p.first);
    sy.insert(p.second);
  }

  return sx.size()*sy.size() - g.size();
}

void dfs(vector<bool>& visited, vii& g, int u) {
  if (u<=X_MAX) {
    for (int v : all[u]) {
      g.emplace_back(u,v);
    }
  }

  for (int v : all[u]) {
    if (visited[v]){
      continue;
    }

    visited[v] = true;
    dfs(visited, g, v);
  }

}

