        }
    }
    for(auto itr=mpy.begin();itr!=mpy.end();++itr) {
        vector<int> v = itr->second;
        for(int i=0;i<v.size()-1;++i) {
            uf.unite(v[i], v[i+1]);
        }
    }

    map<int, int> cnt;
