template<class Type>
Type solve(Type res = Type()){
    ll N; cin >> N;
    map<int,vector<int>> X,Y;
    for(int i = 0; i < N;i++){
        int x,y; cin >> x >> y;
        X[x].push_back(y);
        Y[y].push_back(x);
    }

    ll M1 = 0;
    for(auto iter_xp = X.begin(); iter_xp != X.end(); iter_xp++){
        int x; vector<int> xs;
        tie(x,xs) = *iter_xp;
        for(auto y:xs){
            ll it = upper_bound(Y[y].begin(),Y[y].end(),x) - Y[y].begin();
            M1 += (xs.size()-1)*(Y[y].size()-it);
        }
    }
    ll M2 = 0;
    for(auto iter_xp = X.rbegin(); iter_xp != X.rend(); iter_xp++){
        int x; vector<int> xs;
        tie(x,xs) = *iter_xp;
        for(auto y:xs){
            ll it = lower_bound(Y[y].begin(),Y[y].end(),x) - Y[y].begin();
            M2 += (xs.size()-1)*it;
        }
    }

    ll M3 = 0;
    for(auto iter_xp = X.begin(); iter_xp != X.end(); iter_xp++){
        int x; vector<int> xs;
        tie(x,xs) = *iter_xp;
        for(auto y:xs){
            M3 += (xs.size()-1)*(Y[y].size()-1);
        }
    }
    res = M3 - min(M1,M2);
    return res;
}
