long long MAX = 100005;


class UnionFind{
    public:
    vector<int> parent;

    UnionFind(int N) {
        parent = vector<int>(N, -1);
    }

    int root(int A) {
        if (parent[A] < 0) return A;
        return parent[A] = root(parent[A]);
    }

    int size(int A) {
        return - parent[root(A)];
    }

    bool unite(int A, int B) {
        A = root(A);
        B = root(B);
        if (A == B) return false; 

        if (size(A) < size(B)) swap(A,B);

        parent[A] += parent[B];
        parent[B] = A;
        t[A][0] += t[B][0];
        t[A][1] += t[B][1];
        return true;
    }

    bool same(int A, int B) {
        return root(A) == root(B);
    } 
};


int main() {
    long long n; cin >> n;
    UnionFind uni(200050);
    for (int i = 0; i < MAX; i++) {
        t[i][0] = 1;
    }
    for (int i = MAX; i < MAX+MAX; i++) {
        t[i][1] = 1;
    }
    for (int i = 0; i < n; i++) {
        long long x, y; cin >> x >> y;
        uni.unite(x, y + MAX);
    }

    long long ans = 0;
    for (int i = 0; i < MAX + MAX; i++) {
        if (uni.root(i) == i && t[i][0] && t[i][1]) {
            long long ret = t[i][0] * t[i][1];
            ans += ret;
        }
    }

    ans -= n;
    cout << ans << endl;
    return 0;
}

