#define int long
class Trees{
  vector<int> par;
  vector<int> rank;
  public:
  int root(int i){
    int rt;
    if(par[i]==i){rt=i;rank[i]=1;}
    else{rt=root(par[i]);par[i]=rt;rank[i]=2;}
    return rt;
  }
  void unite(int i,int j){
    int rki=rank[i];int rkj=rank[j];
    if(rki<rkj){par[root(i)]=root(j);rank[i]++;}
    else{par[root(j)]=root(i);rank[j]++;}
  }
  bool same(int i,int j){
    return root(i)==root(j);
  }
  Trees(int n){
    for(int i=0;i<n;i++) {par.push_back(i);rank.push_back(1);};
  }
};
struct Point{
  int x,y;
  int id; 
};
bool cmpx(const Point& left, const Point& right){
  return left.x<right.x;
}
bool cmpy(const Point& left, const Point& right){
  return left.y<right.y;
}
bool cmpid(const Point& left, const Point& right){
  return left.id<right.id;
}
struct Group{
  int num;
  set<int>X,Y;
  Group(){
    num=0; 
  }
};
#define long int
int main(){
  #define int long
  int N;cin>>N;
  Trees trees(N);
  vector<Point>points(N);
  for(int i=0;i<N;i++){cin>>points[i].x>>points[i].y;points[i].id=i;}
  //xでまとめる
  sort(points.begin(),points.end(),cmpx);
  int last=0;
  for(int i=0;i<N;i++){
    if(points[i].x!=points[last].x)last=i;
    else trees.unite(points[i].id,points[last].id);
  }
  //yでまとめる
  sort(points.begin(),points.end(),cmpy);
  last=0;
  for(int i=0;i<N;i++){
    if(points[i].y!=points[last].y)last=i;
    else trees.unite(points[i].id,points[last].id);
  }
  //配列順序をもとに戻す
  sort(points.begin(),points.end(),cmpid);

  vector<Group> group(N);//root基準でやる
  for(int i=0;i<N;i++){
    group[trees.root(i)].num++;
    group[trees.root(i)].X.insert(points[i].x);
    group[trees.root(i)].Y.insert(points[i].y);
  }
  int ans=0;
  for(int i=0;i<N;i++){
    ans+=group[i].X.size()*group[i].Y.size()-group[i].num;
  }
  while(ans<0);
  cout<<ans;
}

