};

void dfs(int pos, vector<Node>& nodes, lint& num_x, lint& num_y, lint& num_edge) {
    nodes[pos].visited = true;
    if (pos < m) num_x++; else num_y++;

    for (int nex: nodes[pos].tos) {
        if (nodes[nex].visited == false) {
            num_edge++;
            dfs(nex, nodes, num_x, num_y, num_edge);
        }
    }
}

