    }
    int root(int x) {
        if (parent[x] == x) return x;
        parent[x] = root(parent[x]);
        return parent[x];
    }

    bool same(int x, int y){
        return root(x) == root(y);
    }

    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (rank[x] > rank[y]) {
            parent[y] = x;
            sizeb[x] += sizeb[y];
            sizew[x] += sizew[y];
        }
        else {
            parent[x] = y;
            sizeb[y] += sizeb[x];
            sizew[y] += sizew[x];
            if (rank[x] == rank[y]) rank[y] += 1;
        }
    }
};

int main(){
    int N;
    cin >> N;
    unionfind uf(200002);
    for (int i = 1; i <= 100000; i++) {
        uf.sizeb[i] = 1;
        uf.sizew[i+100000] = 1;
    }
    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        uf.unite(x, 100000+y);
    }
    ll ans = 0;
    for (int i = 1; i <= 200000; i++) {
        if (uf.root(i) == i) {
            ans += (ll)uf.sizeb[i] * uf.sizew[i];
        }
    }
    cout << ans-N << endl;
    return 0;
}

