/**
 *	UnionFind木を構成する
 *	nodeの深さ，木のサイズを取得可能
 */
class UnionFind {
	std::vector<ll> m_root;
	std::vector<ll> m_depth;
	std::vector<ll> m_size;
public:
	UnionFind(ll size_) : m_root(size_), m_depth(size_, 0), m_size(size_, 1) {
		std::iota(m_root.begin(), m_root.end(), 0);
	}
	void unite(ll x, ll y) {
		x = root(x);
		y = root(y);
		if (x == y) return;
		ll t = size(x) + size(y);
		m_size[x] = m_size[y] = t;
		if (m_depth[x] < m_depth[y]) m_root[x] = y;
		else m_root[y] = x;
		if (m_depth[x] == m_depth[y]) ++m_depth[x];
	}
	bool isSame(ll x, ll y) {
		return root(x) == root(y);
	}
	ll root(ll x) {
		if (m_root[x] == x) return x;
		return m_root[x] = root(m_root[x]);
	}
	ll size(ll x) {
		if (m_root[x] == x) return m_size[x];
		return size(m_root[x] = root(m_root[x]));
	}
};
signed main() {
	ll n;
	cin >> n;

	vector<PAIR> v;
	v.reserve(n);
	REP(_, n) {
		ll a, b;
		cin >> a >> b;
		--a; --b;
		v.emplace_back(a, b);
	}


	//dump(v);
	constexpr ll size = 1e5 + 1;
	//constexpr ll size = 5;
	auto tree = UnionFind(size);
	sort(ALL(v), [](cauto a, cauto b) {
		return a.second < b.second;
	});
	ll now = -1;
	ll nows = -1;
	REPC(x, v) {
		if (x.second != now) {
			now = x.second;
			nows = x.first;
			continue;
		}
		tree.unite(nows, x.first);
	}
	//dump(v);
	sort(ALL(v), [](cauto a, cauto b) {
		return a.first < b.first;
	});

	unordered_map<ll, unordered_set<ll>> mp;
	REPC(x, v) {
		mp[tree.root(x.first)].emplace(x.second);
	}

	ll ans = -n;
	REP(i, size) {
		//dump(tree.root(i));
		ans += mp[tree.root(i)].size();
	}
	cout << ans << endl;
}

