struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {//xの親を求める
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {//xとyが連結しているか判定
        return root(x) == root(y);
    }

    bool merge(int x, int y) {//xとyを連結
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {//xを含む木のサイズを求める
        return -par[root(x)];
    }
};

int main() {
    int N;
    cin>>N;
    UnionFind uf(N);
    vector<P> points(N);
    vector<P> X(N),Y(N);
    rep(i,N){
        cin>>points.at(i).first>>points.at(i).second;
        X.at(i).first=points.at(i).first;
        X.at(i).second=i;
        Y.at(i).first=points.at(i).second;
        Y.at(i).second=i;
    }
    sort(X.begin(),X.end());
    sort(Y.begin(),Y.end());
    rep(i,N-1){
        if(X.at(i).first==X.at(i+1).first){
            uf.merge(X.at(i).second,X.at(i+1).second);
        }
    }
    rep(i,N-1){
        if(Y.at(i).first==Y.at(i+1).first){
            uf.merge(Y.at(i).second,Y.at(i+1).second);
        }
    }
    vector<set<int>> x(N),y(N);
    rep(i,N){
        int p=uf.root(i);
        x.at(p).insert(points.at(i).first);
        y.at(p).insert(points.at(i).second);
    }
    ll ans=-N;
    rep(i,N){
        ll now=x.at(i).size()*y.at(i).size();
        ans+=now;
    }
    cout<<ans<<endl;
}

