int main() {
    int n, result = 0;
    cin >> n;
    map<pair<int, bool>, set<pair<int, bool>>> graph;
    for (int x, y; cin >> x >> y; ) {
        graph[{x, true}].emplace(y, false);
        graph[{y, false}].emplace(x, true);
    }
    set<pair<int, bool>> visited;
    for (auto& p : graph) {
        if (visited.count(p.first) == 0) {
            queue<pair<int, bool>> queue;
            queue.emplace(p.first);
            visited.emplace(p.first);
            int count[2] = {}, edges = 0;
            do {
                auto& front = queue.front();
                count[front.second]++;
                auto it = graph.find(front);
                edges += it->second.size();
                for (auto& i : it->second) {
                    if (visited.count(i) == 0) {
                        visited.emplace(i);
                        queue.emplace(i);
                    }
                }
                queue.pop();
            } while (!queue.empty());
            if (count[0] + count[1] >= 3) {
                result += count[0] * count[1] - edges / 2;
            }
        }
    }
    cout << result;
    return 0;
}

