// クラスカル法
// 連結グラフの最小全域木を求める
class Kruskal {
private:
  Graph graph;
  vector<Edge> MinimumSpanningTree;
  ll minimumCost;
  void searchMinimumSpanningTree() {
    UnionFindTree uf(graph.nodes);
    sort(all(graph.edges));
    itrep(edge, graph.edges) {
      if (!uf.same(edge->from, edge->to)) {
        uf.unite(edge->from, edge->to);
        MinimumSpanningTree.push_back(*edge);
      }
    }
  }

public:
  Kruskal(Graph graph) { this->graph = graph; }
  ll getMinimumSpanningTreeCost() {
    searchMinimumSpanningTree();
    ll cost = 0;
    itrep(it, MinimumSpanningTree) { cost += it->cost; }
    return cost;
  }
};

// ダイクストラ法 O((E+V)logV)
// 最小経路問題を解くためのアルゴリズム。辺の重みに負数を含む場合は利用不可
class Dijkstra {
private:
  Graph graph;
  map<ll, vector<Edge>> fromPaths;
  vl distances;
  vl srcs;

public:
  Dijkstra(Graph graph) {
    this->graph = graph;
    itrep(edge, graph.edges) {
      fromPaths[edge->from].push_back(*edge);
      fromPaths[edge->to].push_back(Edge(edge->to, edge->from, edge->cost));
    }
  }
  void searchMinimumPathFrom(ll src) {
    // 複数回呼ばれる度に計算する
    this->distances = vl(graph.nodes + 1, INF);
    this->srcs = vl(graph.nodes + 1, INF);

    priority_queue<ll> pq;
    distances[src] = 0;
    srcs[src] = -1;

    pq.push(src);
    while (!pq.empty()) {
      int u = pq.top();
      pq.pop();

      itrep(edge, fromPaths[u]) {
        int v = edge->to;
        int w = edge->cost;
        if (distances[v] > distances[u] + w) {
          distances[v] = distances[u] + w;
          srcs[v] = u;
          pq.push(v);
        }
      }
    }
  };
  ll getDistance(ll n) { return this->distances[n]; }
  ll getFrom(ll n) { return this->srcs[n]; }
};

// ベルマンフォード O(|V||E|)
// 非負コストが含まれていても最短経路問題を解くためのアルゴリズム。閉路の検出も可能
class BellmanFord {
private:
  Graph graph;
  // 閉路が含まれるかは個々のノードごとに管理する必要あり
  vector<bool> hasNegativeCycles;
  vector<ll> distances;

public:
  BellmanFord(Graph graph) {
    this->graph = graph;
    this->distances = vector<ll>(this->graph.nodes + 1, INF);
    this->hasNegativeCycles = vector<bool>(this->graph.nodes + 1, false);
  }
  void searchMinimumPathFrom(ll src) {
    this->distances[src] = 0;

    for (ll i = 0; i < graph.nodes - 1; i++) {
      itrep(edge, graph.edges) {
        ll u = edge->from;
        ll v = edge->to;
        ll w = edge->cost;
        if (this->distances[u] + w < this->distances[v]) {
          this->distances[v] = this->distances[u] + w;
        }
      }
    }

    itrep(edge, graph.edges) {
      ll u = edge->from;
      ll v = edge->to;
      ll w = edge->cost;
      if (this->distances[u] + w < this->distances[v]) {
        this->hasNegativeCycles[v] = true;
      }
      if (this->hasNegativeCycles[u] == true) {
        this->hasNegativeCycles[v] = true;
      }
    }
  }
  ll getDistance(ll n) { return this->distances[n]; }
  bool hasNegativeCycle(ll n) { return this->hasNegativeCycles[n]; }
};

void solve(long long N, std::vector<long long> x, std::vector<long long> y) {
  map<ll, set<pll>> sameX;
  map<ll, set<pll>> sameY;
  queue<pll> allPoints;
  rep(i, 0, N) {
    sameX[x[i]].insert(mp(y[i], x[i]));
    sameY[y[i]].insert(mp(x[i], y[i]));
    allPoints.push(mp(x[i], y[i]));
  }

  map<pll, vector<pll>> edges;
  itrep(it, sameX) {
    set<pll> xys = it->second;
    itrep(xy, xys) {
      pll from = mp(xy->second, xy->first);

      xy++;
      if (xy != xys.end()) {
        pll to = mp(xy->second, xy->first);
        edges[from].push_back(to);
        edges[to].push_back(from);
      }
      xy--;
    }
  }
  itrep(it, sameY) {
    set<pll> xys = it->second;
    itrep(xy, xys) {
      pll from = mp(xy->first, xy->second);

      xy++;
      if (xy != xys.end()) {
        pll to = mp(xy->first, xy->second);
        edges[from].push_back(to);
        edges[to].push_back(from);
      }
      xy--;
    }
  }

  set<pll> checked;
  ll ans = 0;
  while (!allPoints.empty()) {
    pll p = allPoints.front();
    allPoints.pop();

    if (checked.find(p) != checked.end()) {
      continue;
    }

    queue<pll> que;
    que.push(p);
    set<ll> xSet;
    set<ll> ySet;
    ll xyCnt = 0;
    while (!que.empty()) {
      pll p2 = que.front();
      que.pop();

      if (checked.find(p2) != checked.end()) {
        continue;
      }
      checked.insert(p2);

      xyCnt++;
      xSet.insert(p2.first);
      ySet.insert(p2.second);
      itrep(edge, edges[p2]) { que.push(*edge); }
    }
    ans += xSet.size() * ySet.size() - xyCnt;
  }
  print(ans);
}

