        uft.unite(x, y+max);
    }
    unordered_map<int, long> xm, ym;
    for (int i=1; i<=2*max; i++) {
        int r = uft.root(i);
        if (i <= max)
            xm[r]++;
        else 
            ym[r]++;
    }
    long cnt = 0;
    for (auto xmi:xm) 
        cnt += xmi.second * ym[xmi.first];
    cout << cnt - n << '\n';
    return 0;
}

