struct UnionFind {
  vector<int> par;
  vector<int> sizes;

  UnionFind(int N) : par(N), sizes(N, 1) {
    for(int i = 0; i < N; i++) par.at(i) = i;
  }

  int find(int x) { 
    if (par.at(x) == x) return x;
    return par.at(x) = find(par.at(x));
  }

  void unite(int x, int y) {
    int rx = find(x); 
    int ry = find(y); 
    if (rx == ry) return; 
    if (sizes.at(rx) < sizes.at(ry)) swap(rx,ry);
    par.at(ry) = rx;
    sizes.at(rx) += sizes.at(ry);    
  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }

  int size(int x){
    return sizes.at(find(x));
  }

  int num_of_connected_components(){
    int ret = 0;
    for(int i = 0; i < par.size(); i++){
      if(find(i) == i) ret++;
    }
    return ret;
  }
};

int main(){
  ll n; cin >> n;
  const ll M = 1e5;
  UnionFind uft(2*M);
  REP(i,n){
    ll x,y; cin >> x >> y;
    x--; y--;
    uft.unite(x,y+M);
  }
  vector<ll> cntx(2*M,0), cnty(2*M,0);
  REP(i,2*M){
    ll k = uft.find(i);
    if(i<M) cntx[k]++;
    else cnty[k]++;
  }
  ll ans = 0;
  REP(i,2*M) ans += cntx[i] * cnty[i];
  ans -= n;
  cout << ans << endl;
}

