class DisjointSet {
public:
  vint v;
  DisjointSet(int n) : v(n, -1) {}

  int root(int n) { return v[n] < 0 ? n : (v[n] = root(v[n])); }
  bool unite(int a, int b) {
    int ra = root(a), rb = root(b);
    if (ra == rb) return false;
    if (-ra > -rb) swap(ra, rb);
    v[rb] += v[ra];
    v[ra] = rb;
    return true;
  }
  int size() { return count_if(ALL(v), [](int x){ return x < 0; }); }
};


const int N = 100001;

int main() {
  int n;
  while (cin >> n) {
    vint x(n), y(n);
    REP(i,n) cin >> x[i] >> y[i];

    auto vx = [](int x) { return x; };
    auto vy = [](int y) { return N + y; };

    DisjointSet ds(N + N);
    REP(i,n) ds.unite(vx(x[i]), vy(y[i]));
    vint cx(N + N), cy(N + N);
    REP(i,N) {
      cx[ds.root(vx(i))]++;
      cy[ds.root(vy(i))]++;
    }

    ll result = 0;
    REP(i,N+N) result += (ll)cx[i] * cy[i];
    cout << result - n << endl;
  }
}

