#define N 100000
int visited[2*N];

pair<int, int> dfs(int cur, vector<vector<int>> edge, int x, int y){
  if (visited[cur] == 1)
    return pair<int, int>(0, 0);


  visited[cur] = 1;

  int xs = 0, ys = 0;
  for (int i = 0; i < edge[cur].size(); i++){
    pair<int, int> a = dfs(cur, edge, 0, 0);
    xs += a.first;
    ys += a.second;
  }

  cout << cur << endl;
  if (cur > N)
    return pair<int, int>(xs, ys + 1);
  else
    return pair<int, int>(xs + 1, ys);
}

int main(void){
  ll n;
  cin >> n;
  vector<vector<int>> edge(2*N, vector<int>(0));

  int x, y;
  for (int i = 0; i < n; i++){
    cin >> x >> y;
    x--; y--;
    edge[x].push_back(N + y);
    edge[N + y].push_back(x);
  }


  ll sum = 0;
  for (int i = 0; i < 2*N; i++){
    pair<int, int> p = dfs(i, edge, 0, 0);
    sum += p.first * p.second;
  }

  cout << sum << endl;

  return 0;
}


ll power(ll n, ll k){
  ll res = 1;
  while(k > 0){
    if (k & 1) 
      res = res * n % MOD;
    n = n * n % MOD;
    k >>= 1;
  }
  return res;
}

ll genfact(ll n, ll k){

  ll res = 1;
  while (k >= 0){
    res = (res * (n - k)) % MOD;
    k--;
  }

  return res;
}

ll inv(ll n){
  return power(n, MOD - 2);
}

ll fact(ll n){
  return genfact(n, n - 1);
}

ll nck(ll n, ll k){
  if (k == 0)
    return 1;

  return ((genfact(n, k) % MOD) * inv(fact(k))) % MOD;
}

