int n, ans;

int getPar(int v) {
	return (par[v] == v ? v : par[v] = getPar(par[v]));
}

void merge (int v, int u) {
    v = getPar(v);
    u = getPar(u);
	par[u] = v;
}

int32_t main() {
	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> y[i];
		X[x[i]].push_back(i);
		Y[y[i]].push_back(i);
		par[i] = i;
	}
	for (int i = 1; i < N; i++) {
		for (auto v : X[i])
			merge(X[i][0], v);
		for (auto v : Y[i])
			merge(Y[i][0], v);
	}
	for (int i = 0; i < n; i++)
		s[getPar(i)].insert(i);
	for (int i = 0; i < n; i++) {
		if (!s[i].size()) continue;
