		cin >> X[i] >> Y[i];
	}
	vector<int> gx = X, gy = Y;
	sort(gx.begin(), gx.end());
	gx.erase(unique(gx.begin(), gx.end()), gx.end());
	sort(gy.begin(), gy.end());
	gy.erase(unique(gy.begin(), gy.end()), gy.end());
	int sx = gx.size(), sy = gy.size();
	vector<vector<int> > G(sx + sy);
	for (int i = 0; i < N; ++i) {
		int px = lower_bound(gx.begin(), gx.end(), X[i]) - gx.begin();
		int py = lower_bound(gy.begin(), gy.end(), Y[i]) - gy.begin();
		G[px].push_back(py + sx);
		G[py + sx].push_back(px);
	}
	vector<bool> vis(sx + sy, false);
	int cx = 0, cy = 0;
	function<void(int) > dfs = [&](int pos) {
		vis[pos] = true;
		if (pos < sx) ++cx;
		else ++cy;
		for (int i : G[pos]) {
			if (vis[i]) continue;
			dfs(i);
		}
	};
	long long ans = 0;
	for (int i = 0; i < sx + sy; ++i) {
		if (!vis[i]) {
			cx = 0, cy = 0;
			dfs(i);
			ans += 1LL * cx * cy;
		}
	}
	cout << ans - N << endl;
	return 0;
}

