    int x, y;
    cin >> x >> y;
    P.emplace_back(x,y);
    uf.unite(x,y+M);
    XX.insert(x);
    YY.insert(y);
  }

  vector<int> X(2*M,0), Y(2*M,0);

  for(auto x : XX)
    ++X[uf.find(x)];

  for(auto y : YY)
    ++Y[uf.find(y+M)];

  long long ans = -N;
  for(int i = 0; i < 2*M; ++i){
    ans += (long long)X[i]*Y[i];
  }
  cout << ans << endl;
}

