      uf.merge(Y[i].second,Y[i+1].second);
    }
  }
  for(int i=0;i<N;i++){
    mp[uf.root(i)].first.insert(X[i].first);
    mp[uf.root(i)].second.insert(Y[i].first);
  }
  ll ans=0ll;
  for(auto e : mp){
    ans+=e.second.first.size()*e.second.second.size();
  }
  cout<<ans-N<<endl;
}

