double comd(int n, int r) {
    static vd fac;
    if (sz(fac) < n + 1) {
        if (sz(fac) == 0)fac.push_back(1);
        rep(i, sz(fac) - 1, n) { fac.push_back(fac.back() * (i + 1)); }
    }
    if (n < r || n <= 0)return 0;
    return fac[n] / fac[n - r] / fac[r];
}
