vector<string> split(const string a, const char deli) {
    string b = a + deli;
    int l = 0, r = 0, n = b.size();
    vector<string> res;
    rep(i, n) {
        if (b[i] == deli) {
            r = i;
            if (l < r)res.push_back(b.substr(l, r - l));
            l = i + 1;
        }
    }
    return res;
}
vector<string> split(const string a, const string deli) {
    vector<string> res;
    int kn = sz(deli);
    std::string::size_type Pos(a.find(deli));
    int l = 0;
    while (Pos != std::string::npos) {
        if (Pos - l)res.push_back(a.substr(l, Pos - l));
        l = Pos + kn;
        Pos = a.find(deli, Pos + kn);
    }
    if (sz(a) - l)res.push_back(a.substr(l, sz(a) - l));
    return res;
}
