class UF{
  vector<ll> par,rank,size_x,size_y,size_edge;
public:
  UF(ll size){
    for (ll i = 0; i < size; i++) {
      par.push_back(i);
      rank.push_back(0);
      if(i<100000){size_x.push_back(1);size_y.push_back(0);}
      else {size_y.push_back(1);size_x.push_back(0);}
      size_edge.push_back(0);
    }
  }
  ll find(ll x){
    if(par[x]==x)return x;
    return par[x]=find(par[x]);
  }
  void unite(ll x,ll y){
    x=find(x);
    y=find(y);
    if(x==y){++size_edge[x];return;}
    if(rank[x]<rank[y]){
      par[x]=y;
      size_x[y]+=size_x[x];
      size_y[y]+=size_y[x];
      size_edge[y]+=size_edge[x]+1;
    }
    else{
      par[y]=x;
      size_x[x]+=size_x[y];
      size_y[x]+=size_y[y];
      size_edge[x]+=size_edge[y]+1;
      if(rank[x]==rank[y])rank[x]++;
    }
  }
  bool same(ll x,ll y){
    return find(x)==find(y);
  }
  ll operator [](ll x){
    return this->find(x);
  }
  ll sizeX(ll x){
    x=find(x);
    return size_x[x];
  }
  ll sizeY(ll y){
    y=find(y);
    return size_y[y];
  }
  ll sizeE(ll x){
    x=find(x);
    return size_edge[x];
  }
};

void solve(long long N, std::vector<long long> x, std::vector<long long> y){
  UF uf(200000);
  REP(N){
    uf.unite(x[i],y[i]+100000);
  }
  set<ll> used;
  ll ans=0;
  REP(200000){
    ll tmp=uf.find(i);
    if(used.find(tmp)==used.end()){
      used.insert(tmp);
      ans+=uf.sizeX(tmp)*uf.sizeY(tmp)-uf.sizeE(tmp);
    }
  }
  cout<<ans<<endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    std::vector<long long> x(N);
    std::vector<long long> y(N);
    for(ll i = 0 ; i < N ; i++){
        scanf("%lld",&x[i]);
        scanf("%lld",&y[i]);
        --x[i];
        --y[i];
    }
    solve(N, std::move(x), std::move(y));
    return 0;
}

