void dfs(const auto& G, auto& visited, int v, LL& xcnt, LL& ycnt) {
    if (visited[v]) return;
    visited[v] = true;
    if (v < G.size()/2) ++xcnt;
    else                ++ycnt;
    for (auto u : G[v]) {
        dfs(G, visited, u, xcnt, ycnt);
    }
}

