    cin >> raw_xs[i];
    cin >> raw_ys[i];
  }
  vector<int> xs, to_raw_xs, ys, to_raw_ys;
  tie(xs, to_raw_xs) = Compress(raw_xs);
  tie(ys, to_raw_ys) = Compress(raw_ys);

  int x_size = to_raw_xs.size();
  int y_size = to_raw_ys.size();
  vector<vector<Edge>> graph(x_size + y_size);
  for (int i = 0; i < n; i++) {
    int v1 = xs[i];
    int v2 = ys[i] + x_size;
    graph[v1].push_back(Edge({v1, v2}));
    graph[v2].push_back(Edge({v2, v1}));
  }
  // cout << "HOGE 1" << endl;
  vector<vector<int>> components = ConnectedComponents(graph);
  // cout << "HOGE 2" << endl;
  int64 count = 0;
  for (const auto& component : components) {
    int64 left_count = count_if(
        component.begin(), component.end(),
        [x_size] (int i) { return i < x_size; });
    int64 right_count = component.size() - left_count;
    count += left_count * right_count;
  }
  int64 answer = count - n;
  cout << answer << endl;
}

