class disjoint_set {
  int n;
  vector<int> prt;
  public:
    vector<int> hor;
    vector<int> ver;
    disjoint_set (int n)
      : n(n), prt(n, -1), hor(n, 0), ver(n, 0)
      {
        for (int i = 0; i < n; i++) {
          for (int i = 0; i < mx; i++) {
            hor[i] = 1;
            ver[mx + i] = 1;
          }
        }
      }
      inline bool is_root (int x) const {
        return prt[x] < 0;
      }
      inline int size (int x) {
        return -prt[find(x)];
      }
      inline bool equiv (int x, int y) {
        return find(x) == find(y);
      }
      int find (int x) {
        return (is_root(x) ? x : (prt[x] = find(prt[x])));
      }
      inline bool unite (int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return false;
        if (size(x) < size(y)) swap(x, y);
        prt[x] += prt[y];
        hor[x] += hor[y];
        ver[x] += ver[y];
        prt[y] = x;
        return true;
      }
};
