int p[100010];
set<int> idx[100010];
int root(int x){
	if(p[x] == x) return x;
	return p[x] = root(p[x]);
}
void merge(int a, int b){
	a = root(a);
	b = root(b);
	if(a == b) return;
	if(idx[a].size() < idx[b].size()) swap(a, b);
	for(int i : idx[b]) idx[a].insert(i);
	p[b] = a;
}

