int a, b;
bool used[200005];
const int offset = 1e5;
void dfs(int s){
    if(s < offset)a++;
    else b++;
    used[s] = true;
    for(int x : g[s]){
        if(!used[x]){
            dfs(x);
        }
    }
}
int main(){
