        cin >> x >> y;
        x--, y--;
        g[x].push_back(y + offset);
        g[y + offset].push_back(x);
    }
    ll ans = -n;
    for(int i = 0; i < offset; i++){
        if(!used[i]){
            a = b = 0;
            dfs(i);
            ans += (long long) a * b;
        }
    }
    cout << ans << endl;
}

