constexpr int N_MAX = 100000;

class UnionFind {
    public:
    int n;
    vector<int> par, rank, size;  //親, 深さ, その木の要素数

    UnionFind(int n): n(n) {
        for(int i=0;i<n;++i){
            par.push_back(i);
            rank.push_back(0);
            size.push_back(1);
        }
    }

    //根を求める
    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            int p = find(par[x]);
            size[x] = size[p];
            return par[x] = p;
        }
    }

    //xとyの属する集合の併合
    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        size[x] += size[y];
        size[y] = size[x];
        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
    }

    //同じ集合に属するか否か
    bool is_same(int x, int y){
        return find(x) == find(y);
    }
};

int main() {
    std::ios::sync_with_stdio(0); cin.tie(0);
    int n;
    cin >> n;
    UnionFind uf = UnionFind(2*N_MAX);
    int x, y;
    for(int i=0;i<n;++i){
        cin >> x >> y;
        --x; --y;
        uf.unite(x, N_MAX+y);
    }

    ll ans = 0LL;
    for(int i=0;i<2*N_MAX;++i) {
        int p = uf.find(i);
        if(p != i) continue;
        ll s = uf.size[p];
        if(s <= 3LL) continue;
        ans += (s/2) * (s/2);
    }
    ans -= n;

    cout << max(0LL, ans) << endl;
}

