        REP(i, n) { par[i] = i; }
    }

    ll root(ll v) {
        if(par[v] == v) return v;
        return par[v] = root(par[v]);
    }

    void unite(ll x, ll y) {
        x = root(x);
        y = root(y);
        if(x == y) return;

        if(rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if(rank[x] == rank[y]) { rank[x]++; }
        }
    }

    bool is_same(ll x, ll y) { return root(x) == root(y); }
};

