        xmp[x].push_back(y);
        ymp[y].push_back(x);
    }
    UnionFind uf = UnionFind(int(1e5)+5);

    for(auto itr = ymp.begin();itr != ymp.end();itr++){
        vector<ll> vec = itr->second;
