typedef pair<int,int> P;
typedef pair<ll,ll> Pll;

struct Unionfind{
    vector<int> data;
    Unionfind(int size):data(size, -1) {}
    bool unite(int x, int y){
        x=root(x);
        y=root(y);
        if(x!=y){
            if(data[y] < data[x]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return x!=y;
    }
    bool same(int x, int y){
        return root(x) == root(y);
    }
    int root(int x){
        return (data[x] < 0) ? x : data[x]=root(data[x]);
    }
    int size(int x){
        return -data[root(x)];
    }
};

signed main(){
    int n; cin >> n;
    int x[n],y[n];
    int X[100100],Y[100100];
    rep(i,100100) X[i]=Y[i]=-1;
    Unionfind uni(n);
    rep(i,n){
        cin >> x[i] >> y[i];
        if(X[x[i]]==-1) X[x[i]]=i;
        if(Y[y[i]]==-1) Y[y[i]]=i;
        if(i!=X[x[i]]) uni.unite(i,X[x[i]]);
        if(i!=Y[y[i]]) uni.unite(i,Y[y[i]]);
    }
    map<P,int> mp_x; map<P,int> mp_y;
    map<int,Pll> mp_num;
    rep(i,n){
        int rt=uni.root(i);
        //cout << rt << endl;
        if(mp_x[{rt,x[i]}]==0){
            mp_x[{rt,x[i]}]=1;
            mp_num[rt].fi++;
        }
        if(mp_y[{rt,y[i]}]==0){
            mp_y[{rt,y[i]}]=1;
            mp_num[rt].se++;
        }
    }
    ll ans=0;
    for(auto u:mp_num){
        //cout << u.se.fi << " " << u.se.se << endl;
        ans+=u.se.fi*u.se.se;
    }
