void init(int n){
	for(int i=0; i<n; i++){
		par[i] = i;
		Rank[i] = 0;
		size[i] = 1;
	}
}

int find(int x){
	if(par[x] == x){
		return x;
	}else{
		return par[x] = find(par[x]);
	}
}

void unite(int x, int y){
	x = find(x);
	y = find(y);
	if(x == y) return;
	if(Rank[x] < Rank[y]){
		par[x] = y;
		size[y] += size[x];
		set<int> st;
		for(int i=0; i<Y[x].size(); i++){
			st.insert(Y[x][i]);
		}
		for(int i=0; i<Y[y].size(); i++){
			st.insert(Y[y][i]);
		}
		si[x] = st.size();
		si[y] = si[x];
	}else{
		par[y] = x;
		size[x] += size[y];
		set<int> st;
		for(int i=0; i<Y[x].size(); i++){
			st.insert(Y[x][i]);
		}
		for(int i=0; i<Y[y].size(); i++){
			st.insert(Y[y][i]);
		}
		si[x] = st.size();
		si[y] = si[x];
		if(Rank[x] == Rank[y]) Rank[x]++;
	}
}

