    yxs[y].insert(x);
  }

  UnionFind uf(1e5 + 1);
  for (auto s : yxs) {
    for (auto e : s) {
      uf.Unite(*begin(s), e);
    }
  }

  ll r = 0;
  for (int i = 0; i < xys.size(); i++) {
    int f = uf.Find(i);
