int N; 
int X[100010]; int Y[100010]; bool seen[100010]; 
vector<int> A[100010]; vector<int> B[100010]; vector<int> P[100010]; 
void dfs(int i, int &index){
	if(seen[i]) return; 
	P[index].push_back(i); 
	seen[i] = true; 
	bool finished = true; 
	for(int j = 0; j < A[X[i]].size(); j++){
		if(!seen[A[X[i]].at(j)]) {finished = false; break;} 
	}
	for(int j = 0; j < B[Y[i]].size(); j++){
		if(!seen[B[Y[i]].at(j)]) {finished = false; break; }
	}
	if(finished) return; 
	for(int j = 0; j < A[X[i]].size(); j++){
		dfs(A[X[i]].at(j), index); 
	}
	for(int j = 0; j < B[Y[i]].size(); j++){
		dfs(B[Y[i]].at(j), index); 
	}
}
int main(){
	cin >> N; 
	for(int i = 0; i < N; i++){
		cin >> X[i] >> Y[i]; 
		A[X[i]].push_back(i); B[Y[i]].push_back(i); 
	}
	int index = 0; 
	for(int i = 0; i < N; i++){
		if(seen[i]) continue; 
		dfs(i, index); 
		index ++; 
	}
	long long int ans = 0; 
	for(int i = 0; i <= index; i++){
		set<int> x, y; 
		for(int j = 0; j < P[i].size(); j++){
			x.insert(X[P[i].at(j)]); 
			y.insert(Y[P[i].at(j)]); 
		}
		long long int tmp = (long long) x.size() * y.size(); 
		ans += tmp; 
	}
	cout << ans - (long long) N << endl; 	
}

