typedef long long ll;

const int N = 1e5 + 5;

int fa[N];
int n1[N], n2[N];

vector<int> edge[N];

int Find(int v)
{
  return v == fa[v] ? v : fa[v] == Find(fa[v]);
}

int main()
{
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n, m = 0;
  cin >> n;
  for (int i = 0; i < n; ++ i) {
    int u, v;
    cin >> u >> v;
    m = max(m, max(u, v));
    edge[u].push_back(v);
  }
  for (int i = 1; i <= m; ++ i) {
    fa[i] = i;
    n1[i] = 0;
    n2[i] = 1;
  }
  for (int i = 1; i <= m; ++ i) {
    int len = edge[i].size();
    if (len == 0) continue;
    int pa = Find(edge[i][0]);
    n1[pa] ++;
    for (int j = 1; j < len; ++ j) {
      int v = edge[i][j];
      int pa2 = Find(v);
      if (pa != pa2) {
        fa[pa2] = pa;
        n1[pa] += n1[pa2];
        n2[pa] += n2[pa2];
      }
    }
  }
  ll ans = 0;
  for (int i = 1; i <= m; ++ i) {
    if (fa[i] == i) {
      ans += 1ll * n1[i] * n2[i];
    }
  }
  cout << ans - 1ll * n << endl;
  return 0;
}

