struct Node {
    bool visited;
    vector<int> tos;
};

void dfs(int pos, vector<Node>& nodes, lint& num_x, lint& num_y, lint& num_edge) {
    nodes[pos].visited = true;
    if (pos < m) {
        num_x++;
        num_edge += nodes[pos].tos.size();
    } else {
        num_y++;
    }

    for (int nex: nodes[pos].tos) {
        if (nodes[nex].visited == false) {
            dfs(nex, nodes, num_x, num_y, num_edge);
        }
    }
}

int main() {
    int n;
    cin >> n;
    vector<Node> nodes(2 * m);
    for (int i = 0; i < 2 * m; i++) {
        nodes[i].visited = false;
    }
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        nodes[x].tos.push_back(m + y);
        nodes[m + y].tos.push_back(x);
    }

    lint ans = 0;
    for (int i = 0; i < 2 * m; i++) {
        if (nodes[i].visited == false) {
            lint num_x = 0, num_y = 0, num_edge = 0;
            dfs(i, nodes, num_x, num_y, num_edge);
            ans += num_x * num_y - num_edge;
        }
    }

    cout << ans << endl;
    return 0;
}

