class UnionFind {
private:
	vector<ll> par;
public:
	vector<set<int>> X;
	vector<set<int>> Y;
	UnionFind(int N) {par = vector<int>(N, -1); X = vector<set<int>>(N); Y = vector<set<int>>(N);}
	int find(int x);
	ll size(int x);
	void unite(int x, int y);
	bool same(int x, int y);
	void setX(int n,int x);
	void setY(int n,int y);
};

int UnionFind::find(int x) {
	if (par[x] < 0) return x;
	else return par[x] = find(par[x]);
}

ll UnionFind::size(int x) {
	return -par[find(x)];
}

void UnionFind::unite(int x, int y) {
	x = find(x);
	y = find(y);
 	if (x == y) return;
	//大きい方に小さい方をくっ付ける
	// if (size(x) < size(y)) swap(x, y);
	par[x] += par[y];
	par[y] = x;
}

bool UnionFind::same(int x, int y) {
	x = find(x);
	y = find(y);
	return x == y;
}

void UnionFind::setX(int n,int x) {
	X[find(n)].insert(x);
}

void UnionFind::setY(int n,int y) {
	Y[find(n)].insert(y);
}

bool solve() {
	int n;cin >> n;
	map<int,set<int>> X;
	map<int,set<int>> Y;
	UnionFind uf(n);
	REP (i,n) {
		//その点は必ず初出
		int x,y;cin>>x>>y;
		X[x].insert(i);
		Y[y].insert(i);
		uf.X[i]={x};
		uf.Y[i]={y};
		bool al = false;
		if (X[x].size() > 1) {
			for (auto a : X[x]) {
				if (a != i) {uf.unite(a,i);uf.setX(a,x);uf.setY(a,y);al = true;break;}
			}
		}
		if (!al && Y[y].size() > 1) {
			for (auto a : Y[y]) {
				if (a != i) {uf.unite(a,i);uf.setX(a,x);uf.setY(a,y);break;}
			}
		}
	}
	int ans = 0;
	REP (i,n) {
		if (uf.find(i) == i) {
			ans += (ll)uf.X[i].size() * (ll)uf.Y[i].size();
		}
	}
	ans -= n;
	cout << ans << endl;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	solve();
}

