    for(int p : xset)   xcnt[uf.parent(p)]++;
    for(int p : yset)   ycnt[uf.parent(p+base)]++;
    ll ans = 0;
    for(auto p : xcnt){
        ans += p.second * ycnt[p.first];
    }
