struct UnionFind {
    const int N;
    std::vector<int> p, sz;

    explicit UnionFind(int N) : N(N), p(N), sz(N, 1) {
        std::iota(p.begin(), p.end(), 0);
    }

    int find(int u) {
        if (p[u] == u) return u;
        return p[u] = find(p[u]);
    }

    std::pair<int, bool> unite(int u, int v) {
        u = find(u), v = find(v);
        if (u == v) return {u, false};
        if (sz[u] < sz[v]) std::swap(u, v);
        p[v] = u;
        sz[u] += sz[v];
        return {u, true};
    }

    int size(int u) {
        return sz[find(u)];
    }
};

int solve(const ll N, const vector<Pt<>>& xs) {
    map<int, int> x2i, y2i;
    for (const auto& p : xs) {
        int x = p.real(), y = p.imag();
        x2i[x] = 0, y2i[y] = 0;
    }
    int nx = 0;
    for (auto& xi : x2i) xi.second = nx++;
    int ny = 0;
    for (auto& yi : y2i) yi.second = ny++;
    static UnionFind uf(nx + ny);
    for (const auto& p : xs) {
        int i = x2i[p.real()], j = y2i[p.imag()];
        uf.unite(i, nx + j);
    }
    vector<ll> ct(nx + ny);
    for (const auto& p : xs) {
        int i = x2i[p.real()];
        ++ct[uf.find(i)];
    }
    vector<pair<ll, ll>> ct2(nx + ny);
    REP(i, nx) ++ct2[uf.find(i)].first;
    FOR(j, nx, nx + ny) ++ct2[uf.find(j)].second;
    ll ans = 0;
    REP(i, nx + ny) {
        ans += ct2[i].first * ct2[i].second - ct[i];
    }
    assert(ans < nx*ny);
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll N; cin >> N;
    vector<Pt<>> xs(N);
    REP(i, N) {
        int x, y; cin >> x >> y;
        xs[i] = {x, y};
    }
    cout << solve(N, xs) << '\n';

    return 0;
}

