#include <bits/stdc++.h>
using namespace std;
using ll = long long;

class UnionFind {
public:
    // parent node index if not root index
    // minus size of the tree if root index
    std::vector<int> data;

    UnionFind( int n ) {
        data.resize( n, -1 );
    }

    int find( int x ) {
        if ( data[x] < 0 ) {
            return x;
        } else {
            int r = find( data[x] );
            data[x] = r;
            return r;
        }
    }

    void unite( int x, int y ) {
        int r = find( x );
        int s = find( y );
        if ( r != s ) {
            data[r] += data[s];
            data[s] = r;
        }
    }

    int count( int x ) {
        return -data[find(x)];
    }
};

int main() {
    int NMAX = 1e5;
    int N;
    cin >> N;
    UnionFind uf(2 * NMAX);
    int x,y;
    for ( int i = 0; i < N; i++ ) {
        cin >> x >> y;
        x--, y--;
        uf.unite(x,y+NMAX);
    }

    map<int, int> nx, ny;
    for ( int i = 0; i < 2 * NMAX; i++ ) {
        int r = uf.find(i);
        int c = uf.count(r);
        if ( c <= 1 ) continue;
        if ( i < NMAX ) {
            nx[r]++;
        } else {
            ny[r]++;
        }
    }

    ll dots = 0;
    for( auto q : nx ) {
        dots += q.second * ny[q.first];
    }
    ll ans = dots - N;
    cout << ans << '\n';
    return 0;
}

