  map<int,ll> mx, my;
  rep(i, M) mx[ uf.find(i) ]++;
  rep(i, M) my[ uf.find(i + M) ]++;

  ll res = 0;
  rep(i, 2*M) res += mx[i]*my[i];
  cout << res - n << "\n";

  return 0;
}

