class UnionFindS{
private:
    vector<int> par;
    vector<int> xc;
    vector<int> yc;
public:
    UnionFindS(int n){
        par=vector<int>(n,-1);
        xc=vector<int>(n,1);
        yc=vector<int>(n,1);
    }
    int find(int x){
        if(par.at(x)<0) return x;
        else return par.at(x)=find(par.at(x));
    }
    int size(int x){
        return -par.at(find(x));
    }
    void unite(int x, int xx, int y, int yy){
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(size(x)<size(y)) swap(x,y);
        par.at(x)+=par.at(y);
        par.at(y)=x;
        if(xx/200000==yy/200000){
            xc[x]++;
        }else{
            yc[x]++;
        }
    }
    bool same(int x, int y){
        return find(x)==find(y);
    }
    int get(int x){
        return xc[find(x)]*yc[find(x)]-size(x);
    }
};

