        in[i] = P(x, y);
        xs.push_back(x);
        ys.push_back(y);
    }

    std::sort(rag(xs));
    std::sort(rag(ys));
    xs.erase(std::unique(rag(xs)), std::end(xs));
    ys.erase(std::unique(rag(ys)), std::end(ys));

    std::set<P> fs;

    rep(i, n)
    {
        int x = std::lower_bound(rag(xs), in[i].first) - std::begin(xs);
        int y = std::lower_bound(rag(ys), in[i].second) - std::begin(ys);
        dat.emplace(x, y);
        nvis.emplace(x, y);
        fs.emplace(x, y);
    }

    while (!fs.empty())
    {
        std::queue<P> que;

        que.push(*fs.begin());

        fs.erase(que.front());

