    for (int i = 0; i < n; ++i) v[i] = i;
  }
  int root(int i) {
    if (v[i] == i) return i;
    return v[i] = root(v[i]);
  }
  void unite(int i, int j) {
    int ri = root(i);
    int rj = root(j);
    if (ri == rj) return;
    v[ri] = rj;
  }
  map<int, vector<int>> get() {
    map<int, vector<int>> mp;
    for (int i = 0; i < n; ++i) {
      mp[root(i)].push_back(i);
    }
    return mp;
  }
};

