using namespace std;

class UF{
public:
    int n;
    vector<int> parent;
    vector<int> size;

    UF(int n){
        parent.resize(n);
        size.resize(n);
        for(int i = 0; i < n; i++){
            parent[i] = i;
            size[i] = 1;
        }
    }

    bool unite(int a, int b){
        int parentA = find(a);
        int parentB = find(b);

        if(parentA == parentB){
            return false;
        }
        else{
            int sizeA = size[parentA];
            int sizeB = size[parentB];
            if(sizeA < sizeB){
                parent[parentA] = parentB;
                size[parentB] += sizeA;
            }
            else{
                parent[parentB] = parentA;
                size[parentA] += sizeB;
            }
            return true;
        }
    }

    int find(int node){
        int p = parent[node];
        if(p == node){
            return p;
        }
        else{
            int newP = find(p);
            parent[node] = newP;
            return newP;
        }
    }
};

int main(){

    int N;
    cin >> N;

    map<int, int> xMap;
    map<int, int> yMap;
    vector<pair<int, int>> xy(N);
    UF uf(N);

    int x, y;
    for(int i = 0; i < N; i++){
        cin >> x >> y;
        xy[i] = make_pair(x, y);

        auto tempX = xMap.find(x);
        if(tempX == xMap.end()){
            xMap[x] = i;
        }
        else{
            uf.unite(i, tempX->second);
        }

        auto tempY = yMap.find(y);
        if(tempY == yMap.end()){
            yMap[y] = i;
        }
        else{
            uf.unite(i, tempY->second);
        }
    }

    vector<set<int>> xSet(N);
    vector<set<int>> ySet(N);

    for(int i = 0; i < N; i++){
        auto tempXY = xy[i];
        int p = uf.find(i);
        xSet[p].insert(tempXY.first);
        ySet[p].insert(tempXY.second);
    }

    long long ans = 0;
    for(int i = 0; i < N; i++){
        if(uf.parent[i] == i){
            ans += ((long long)xSet[i].size() * ySet[i].size() - uf.size[i]);
        }
    }

    cout << ans << endl;

    return 0;
}

