	sort(ALL(v), [](cauto a, cauto b) {
		return a.second < b.second;
	});
	ll now = 0;
	ll nows = 0;
	REPC(x, v) {
		if (x.second != now) {
			now = x.second;
			nows = x.first;
			continue;
		}
		tree.unite(nows, x.first);
	}
	//dump(v);
	sort(ALL(v), [](cauto a, cauto b) {
		return a.first < b.first;
	});

	unordered_map<ll, unordered_set<ll>> mp;
	REPC(x, v) {
		mp[tree.root(x.first)].emplace(x.second);
	}

	ll ans = -n;
	REP(i, size) {
		//dump(tree.root(i));
		ans += mp[tree.root(i)].size();
	}
	cout << ans << endl;
}

