ll modx(ll Base, ll exponent)
{
	ll ans = 1;
	if(Base == 1)
		return Base;
	while(exponent)
	{
		if(exponent & 1)
			ans = (ans * Base)%mod;
		Base = (Base * Base)%mod;
		exponent = exponent >> 1;
	}
	return ans;
}

ll inmodx(ll num)
{
	return (modx(num, mod-2LL));
}

bool cmp(pii a, pii b)//true for a before b
{
	if(a.S < b.S)
		return 1;
	if(a.S > b.S)
		return 0;
	if(a.F <= b.F)
		return 1;
	return 0;
}

const int N = (1e5) + 9;
const int M = (672*672) + 9;
const int LOGN = ((int)log2(N)) + 3;
const int LOGM = ((int)log2(M)) + 3;
const int BUCK = 900;

int par[N], ht[N];
vi vx[N], vy[N];
set < int > st[N];

int root(int n)
{
	while(par[n] != n)
		n = par[n];
	return n;
}

void merge(int a, int b)
{
	a = root(a);
	b = root(b);
	if(a == b)
		return;
	if(ht[a] >= ht[b])
	{
		ht[a] = max(ht[a], ht[b]+1);
		par[b] = a;
	}
	else
	{
		ht[b] = max(ht[b], ht[a]+1);
		par[a] = b;
	}
	return;
}

void solve()
{
	int n, i, j, x, y, a;
	ll ans = 0;
	cin >> n;
	fo(i,1,N)
	{
		ht[i] = 1;
		par[i] = i;
	}
	fo(i,1,n+1)
	{
		cin >> x >> y;
		vx[x].pb(y);
		vy[y].pb(x);
	}
	fo(i,1,N)
		fo(j,1,sz(vy[i]))
			merge(vy[i][0],vy[i][j]);
	fo(i,1,N)
	{
		a = root(i);
		for(auto x : vx[i])
			st[a].insert(x);
	}
	fo(i,1,N)
	{
		a = root(i);
		ans += sz(st[a]);
	}
	ans -= n;
	cout << ans << '\n';
	return;
}

