bool visited[maxN];
set<int> distinX, distinY;
vector<int> g[maxN];

void dfs(int u){
	visited[u] = true;
	distinX.insert(x[u]);
	distinY.insert(y[u]);

	for(int i = 0, L = g[u].size(); i < L; i++){
		int v = g[u][i];
		if(visited[v]){
			continue;
		}

		dfs(v);
	}
}

void solv(){
	for(int i = 1; i < maxN; i++){
		for(int j = 0, L = vvX[i].size(); j + 1 < L; j++){
			int u = vvX[i][j], v = vvX[i][j + 1];
			g[u].push_back(v);
			g[v].push_back(u);
		}

		for(int j = 0, L = vvY[i].size(); j + 1 < L; j++){
			int u = vvY[i][j], v = vvY[i][j + 1];
			g[u].push_back(v);
			g[v].push_back(u);
		}
	}

	ll ans = -n;
	for(int i = 0; i < n; i++){
		if(!visited[i]){
			distinX.clear();
			distinY.clear();
			dfs(i);
			ans += (ll)(distinX.size()) * (ll)(distinY.size());
			//cerr << " * " << (ll)(distinX.size()) * (ll)(distinY.size()) << '\n';
		}
	}

	cout << ans << '\n';
}

