class UnionFind{
    private:
        vector<ll> par;
        vector<ll> siz;
        vector<vector<ll>> nodes;
    public:
        UnionFind(ll sz){
            par.resize(sz);
            siz.assign(sz,1LL);
            nodes.resize(sz);
            rep(i,sz){
                par[i] = i;
                nodes[i].push_back(i);
            }
        }

        ll find(ll x){
            if (par[x] == x) return x;
            else return par[x] = find(par[x]);
        }

        void unite(ll x,ll y){
            x = find(x);
            y = find(y);
            if (x == y) return;
            if (siz[x] < siz[y]) swap(x,y);
            rep(i,siz[y]){
                nodes[x].push_back(nodes[y][i]);
            }
            siz[x] += siz[y];
            par[y] = x;
        }

        bool same(ll x,ll y){
            return find(x) == find(y);
        }

        ll size(ll x){
            return siz[find(x)];
        }

        vector<vector<ll>> give(){
            return nodes;
        }
};
