	for (int i = 0; i < 100000; i++) {
		for (int j = 1; j < h[i].size(); j++)uf.Unite(h[i][j] + 100000, h[i][j - 1] + 100000);
		for (int j = 1; j < w[i].size(); j++)uf.Unite(w[i][j], w[i][j - 1]);
	}
	vector<int>hnum(200000);
	vector<int>wnum(200000);
	for (int i = 0; i < 100000; i++) {
		hnum[uf.Find(i)]++;
		wnum[uf.Find(i + 100000)]++;
	}
	long long int ans = 0;
	for (int i = 0; i < 200000; i++)ans += hnum[i] * wnum[i];
