void init(int n){
    for(int i=0;i<n;i++){
        par[i]=i;
        cnt[i]=1;
    }
}

int root(int a){
    if(par[a]==a) return a;
    else return par[a]=root(par[a]);
}

void unite1(int a,int b){
    if(root(a)!=root(b)) {
        for(auto it=cntx[root(b)].begin();it != cntx[root(b)].end();it++){
            int z=*it;
            cntx[root(a)].insert(z);
        }
        for(auto it=cnty[root(b)].begin();it != cnty[root(b)].end();it++){
            int z=*it;
            cnty[root(a)].insert(z);
        }
        cnt[root(a)]+=cnt[root(b)];
        par[root(b)]=root(a);
    }
}

void unite2(int a,int b){
    if(root(a)!=root(b)) {
        for(auto it=cntx[root(b)].begin();it != cntx[root(b)].end();it++){
            int z=*it;
            cntx[root(a)].insert(z);
        }
        for(auto it=cnty[root(b)].begin();it != cnty[root(b)].end();it++){
            int z=*it;
            cnty[a].insert(z);
        }
        cnt[root(a)]+=cnt[root(b)];
        par[root(b)]=root(a);
    }
}

