struct UnionFind {
    vector<int> par;
    UnionFind(int n) : par(n, -1) {}

    int find(int x) {
        if (par[x] < 0)
            return x;
        else
            return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (par[x] > par[y])
            swap(x, y);
        par[x] += par[y];
        par[y] = x;
    }

    int size(int x) {
        return -par[find(x)];
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    int mx = 100005;

    UnionFind uf(210200);

    rep(i, 0, n) {
        int x, y;
        cin >> x >> y;
        uf.unite(x, y + mx);
    }
    map<int, ll> mpx, mpy;

    rep(i, 1, mx) {
        mpx[uf.find(i)]++;
        mpy[uf.find(i + mx)]++;
    }
    ll ans = -n;

    rep(i, 1, 2 * mx) ans += mpx[i] * mpy[i];
    cout << ans << endl;

    return 0;
}

