using namespace std;
typedef int64_t ll;
typedef vector<ll> llv;
typedef vector<llv> llvv;

ll gcd(ll a, ll b)
{
    return (a < b) ? gcd(b, a) : ((a % b) ? gcd(b, a % b) : b);
}

ll lcm(ll a, ll b)
{
    return a * b / gcd(a, b);
}

ll N;
llvv PTS;
llv UF;
llvv CONNECTED;

ll find(ll a)
{
    if (UF[a] == -1)
    {
        return -1;
    }

    if (UF[a] == a)
    {
        return a;
    }
    return UF[a] = find(UF[a]);
}

void unite(ll a, ll b)
{
    if (UF[a] == -1)
        UF[a] = a;
    if (UF[b] == -1)
        UF[b] = b;
    UF[b] = find(a);
}

void dfs(ll pts)
{
    foreach (child, PTS[pts])
    {
        if (UF[child] == -1)
        {
            unite(pts, child);
            dfs(child);
        }
    }
}

constexpr ll M = 100000;

int main()
{
    cin >> N;
    PTS = llvv(M * 2);
    UF = llv(M * 2, -1);
    rep(i, N)
    {
        ll x, y;
        cin >> x >> y;
        PTS[2 * (x - 1) + 0].push_back(2 * (y - 1) + 1);
        PTS[2 * (y - 1) + 1].push_back(2 * (x - 1) + 0);
    }
    ll m = -1;
    rep(i, M)
    {
        if (PTS[i * 2].size() != 0)
        {
            m = i * 2;
            dfs(i * 2);
        }
    }

    CONNECTED = llvv(m + 1);
    rep(i, M)
    {
        if (UF[i] != -1)
            CONNECTED[UF[i]].push_back(i);
    }

    ll ans = 0;
    rep(i, m + 1)
    {
        if (CONNECTED[i].size() == 0)
            continue;
        ll cnt = 0;
        foreach (e, CONNECTED[i])
        {
            cnt += e & 1;
        }
        foreach (e, CONNECTED[i])
        {
            if (e & 1)
            {
                ans += cnt - PTS[e].size();
            }
        }
    }

    cout << ans << endl;
    return 0;
}

