    static vector<pair<int,int>> pts;
    for(int i=0;i<n;i++){
        int x, y;
        cin >> x >> y;
        x--;
        y--;
        pts.emplace_back(x,y);
        inx[x].emplace_back(y,i);
        iny[y].emplace_back(x,i);
    }

    int g = 0;
    for(int i=0;i<n;i++){
        if(group[i] == 0){
            g++;
            queue<int> q;
            unordered_set<int> checked;
            checked.clear();
            q.push(i);
            checked.insert(i);
            group[i] = g;

            while(!q.empty()){
                int t = q.front();
                q.pop();
                int xx = pts[t].first;
                int yy = pts[t].second;
                for(auto p : inx[xx]){
                    int yyy = p.first;
                    int idx = p.second;
                    if(checked.count(idx) > 0 || yyy==yy) continue;
                    q.push(idx);
                    checked.insert(idx);
                    group[idx] = g;
                }
                for(auto p : iny[yy]){
                    int xxx = p.first;
                    int idx = p.second;
                    if(checked.count(idx) > 0 || xxx==xx) continue;
                    q.push(idx);
                    checked.insert(idx);
                    group[idx] = g;
                }                
            }
        }
    }

    static unordered_set<int> xs[100000], ys[100000];
    static int g_cnt[100000];
    for(int i=0;i<n;i++){
        xs[group[i]-1].insert(pts[i].first);
        ys[group[i]-1].insert(pts[i].second);
        g_cnt[group[i]-1]++;
    }

    int64_t ans = 0;
    for(int i=0;i<g;i++){
        if(xs[i].size()<=1 || ys[i].size()<=1) continue;
        ans += xs[i].size() * ys[i].size() - g_cnt[i];
    }

    cout << ans << endl;

    return 0;
}

#include<bits/stdc++.h>
