	queue<pii> que;
	for(int x = 1; x <= MAX; x++) {
		if(v[X][x].size() == 0 || l[X][x] != 0) {
			continue;
		}
		l[X][x] = label;
		que.push(pii(x, X));
		while(!que.empty()) {
			pii p = que.front();
			que.pop();
			for(auto i : v[p.second][p.first]) {
				if(l[1 - p.second][i] == 0) {
					l[1 - p.second][i] = label;
					que.push(pii(i, 1 - p.second));
				}
			}
		}
		label++;
	}

	map<int, ll> count_x, count_y;
	for(int i = 0; i < label; i++) {
		count_x[i] = 0;
		count_y[i] = 0;
	}
	for(int i = 1; i <= MAX; i++) {
		count_x[l[X][i]]++;
		count_y[l[Y][i]]++;
	}
	ll count_p = 0;
	for(int i = 1; i < label; i++) {
		count_p += count_x[i] * count_y[i];
	}
	cout << count_p - n << endl;
}

