void za(int* x) {
  static int z[N];
  for (int i = 0; i < n; ++i) {
    z[i] = x[i];
  }
  sort(z, z + n);
  map<int, int> m;
  for (int i = 0, v = 0; i < n; ++i) {
    if (m.find(z[i]) == m.end()) {
      m[z[i]] = v++;
    }
  }
  for (int i = 0; i < n; ++i) {
    x[i] = m[x[i]];
  }
}

