int cntx[N + 5], cnty[N + 5];
map < int , bool > visx[N + 5], visy[N + 5];

int find(int x){
	if(par[x] == x) return x;
	return par[x] = find(par[x]);
}

void reset(){
	FOR(i,N+2){
		par[i] = i;
	}
}

bool cmp(point a, point b){
	return a.x < b.x;
}

bool cmp2(point a, point b){
	return a.y < b.y;
}

void getSet(){
	sort(pp+1,pp+n+1,cmp);
	REP(i,1,n-1){
		int u = pp[i].id;
		int v = pp[i+1].id;
		if(p[u].x != p[v].x) continue;
		int pu = find(u);
		int pv = find(v);
		if(pu != pv) par[pu] = pv;
	}
	sort(pp+1,pp+n+1,cmp2);
	REP(i,1,n-1){
		int u = pp[i].id;
		int v = pp[i+1].id;
		if(p[u].y != p[v].y) continue;
		int pu = find(u);
		int pv = find(v);
		if(pu != pv) par[pu] = pv;
	}
}

ll solve(){
	getSet();
	REP(i,1,n){
		int idd = find(i);
		if(!visx[idd][p[i].x]){
			visx[idd][p[i].x] = true;
			cntx[idd]++;
		}
		if(!visy[idd][p[i].y]){
			visy[idd][p[i].y] = true;
			cnty[idd]++;
		}

	}
	ll ret = 0;
	REP(i,1,n){
		int idd = find(i);
		if(idd = i){
			ret += (ll)cntx[i] * (ll)cnty[i];
		}
	}
	return ret - n;
}

