/*
頂点Xi とYiをもつ二部グラフを考える
点(x, y)　が存在するとき、XxとYyの間に辺を張ると

辺a-b a-d c-b c-dのうちちょうど3辺が存在するようなとき、
もう一つを追加するという操作を何回行えるか

異なる連結成分間では辺が結ばれないことが分かり、
また連結成分では二部グラフの両側に必ず辺が結ばれる
*/

void _dfs(int* x, int* y, int i) {
    visited[i] = true;
    for (int k = 0; k < G[i].size(); k++) {
        int next = G[i][k];
        if (!visited[next]) {
            if (next <= BOUND - 1) {
                (*x)++;
                _dfs(x,y,next);
            } else {
                (*y)++;
                _dfs(x,y,next);
            }
        }
    }
}

int dfs(int i) {
    int x=0,y=0;
    if (i <= BOUND-1) x++;
    else y++;
    _dfs(&x,&y,i);
    return x * y;
}

//連結成分内の二部グラフ組み合わせ数を返す
int solve() {
    int res = 0;
    for (int i = 0; i < 2 * BOUND; i++) {
        if (!visited[i]) {
            res += dfs(i);
        }
    }
    return res;
}

int main() {
    cin >> N; 
    int x,y;
    for (int i = 0; i < N; i++) {
        cin >> x >> y;
        G[x-1].push_back(y - 1 + BOUND);
        G[y-1+BOUND].push_back(x - 1);
    }
    int res = solve();
    //既にある辺は除いて考える
    cout << res - N << "\n";
}

