// Does coordinate compression.
// Arguments:
// - raw_xs: Values to compress.
// Returns:
// - xs: Compressed values.
// - to_raw: A mapping from a compressed value to a raw value.
// Verified: CF573Div1D
tuple<vector<int>, vector<int>> Compress(const vector<int>& raw_xs) {
  unordered_set<int> raw_x_set(raw_xs.begin(), raw_xs.end());
  vector<int> to_raw(raw_x_set.begin(), raw_x_set.end());
  sort(to_raw.begin(), to_raw.end());
  unordered_map<int, int> to_index;
  for (int i = 0; i < to_raw.size(); i++) {
    to_index[to_raw[i]] = i;
  }
  vector<int> xs;
  for (int raw_x : raw_xs) {
    xs.push_back(to_index[raw_x]);
  }
  return make_tuple(xs, to_raw);
}

struct Edge {
  int from, to;
};

vector<vector<int>> ConnectedComponents(const vector<vector<Edge>>& graph) {
  int n = graph.size();
  vector<vector<int>> components;
  vector<int> visited(n);

  function<void(int)> dfs = function<void(int)>([&] (int v) {
    if (visited[v]) return;
    visited[v] = true;
    components[components.size() - 1].push_back(v);
    for (auto e : graph[v]) {
      if (visited[e.to]) continue;
      dfs(e.to);
    }
  });

  for (int s = 0; s < n; s++) {
    if (visited[s]) continue;
    components.push_back(vector<int>());
    dfs(s);
  }
  return components;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<int> raw_xs(n), raw_ys(n);
  for (int i = 0; i < n; i++) {
    cin >> raw_xs[i];
    cin >> raw_ys[i];
  }
  vector<int> xs, to_raw_xs, ys, to_raw_ys;
  tie(xs, to_raw_xs) = Compress(raw_xs);
  tie(ys, to_raw_ys) = Compress(raw_ys);

  int x_size = to_raw_xs.size();
  int y_size = to_raw_ys.size();
  vector<vector<Edge>> graph(x_size + y_size);
  for (int i = 0; i < n; i++) {
    int v1 = xs[i];
    int v2 = ys[i] + x_size;
    graph[v1].push_back(Edge({v1, v2}));
    graph[v2].push_back(Edge({v2, v1}));
  }
  // cout << "HOGE 1" << endl;
  vector<vector<int>> components = ConnectedComponents(graph);
  // cout << "HOGE 2" << endl;
  int64 count = 0;
  for (const auto& component : components) {
    int64 left_count = count_if(
        component.begin(), component.end(),
        [x_size] (int i) { return i < x_size; });
    int64 right_count = component.size() - left_count;
    count += left_count * right_count;
  }
  int64 answer = count - n;
  cout << answer << endl;
}

