struct uf {
private:
	vector<int> par, ran;
public:
	void init(int n) {
		par.resize(n, 0);
		ran.resize(n, 0);
		rep(i, n) {
			par[i] = i;
		}
	}
	int find(int x) {
		if (par[x] == x)return x;
		else return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y)return;
		if (ran[x] < ran[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (ran[x] == ran[y])ran[x]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

vector<int> vx[1 << 17], vy[1 << 17];
vector<int> G[1 << 17];
void solve() {
	int n; cin >> n;
	uf u; u.init(n);
	vector<P> v;
	rep(i, n) {
		int x, y; cin >> x >> y;
		vx[x].push_back(i);
		vy[y].push_back(i);
		v.push_back({ x,y });
	}
	rep(i, (1 << 17)) {
		rep(j, (int)vx[i].size()-1) {
			int le = vx[i][j], ri = vx[i][j + 1];
			u.unite(le, ri);
			G[le].push_back(ri);
			G[ri].push_back(le);
		}
		rep(j, (int)vy[i].size() - 1) {
			int le = vy[i][j], ri = vy[i][j + 1];
			u.unite(le, ri);
			G[le].push_back(ri);
			G[ri].push_back(le);
		}
	}
	vector<bool> used(n, false);
	ll ans = 0;
	rep(i, n) {
		if (used[i])continue;
		queue<int> q; q.push(i); used[i] = true;
		vector<int> cx, cy;
		while (!q.empty()) {
			int id = q.front(); q.pop();
			cx.push_back(v[id].first);
			cy.push_back(v[id].second);
			rep(j, G[id].size()) {
				int to = G[id][j];
				if (used[to])continue;
				used[to] = true;
				q.push(to);
			}
		}
		sort(cx.begin(), cx.end());
		sort(cy.begin(), cy.end());
		ll lx = unique(cx.begin(), cx.end()) - cx.begin();
		ll ly = unique(cy.begin(), cy.end()) - cy.begin();
		ans += lx * ly;
	}
	ans -= n;
	cout << ans << endl;
}

