  for(auto x : m) {
    rep(i,x.second.size()-1) uf.unite(x.second[i],x.second[i+1]);
  }
  vector<set<int>> s(MAX);
  rep(i,n) s[uf.find(x[i])].insert(y[i]);
  ll ans = 0;
  rep(i,MAX) ans += s[uf.find(i)].size() - v[i];
