class UnionFind { public: std::vector<size_t> P; std::vector<size_t> S; size_t find(size_t x) { return P[x] == x ? x : P[x] = find(P[x]); } public: UnionFind(size_t n) { P.resize(n); iota(P.begin(), P.end(), 0); S.resize(n); fill(S.begin(), S.end(), 1); } void unite(size_t x, size_t y) { x = find(x); y = find(y); if (x == y) return; if (S[x] < S[y]) { P[x] = y; S[y] += S[x]; } else { P[y] = x; S[x] += S[y]; } } bool same(size_t x, size_t y) { return find(x) == find(y); } size_t size(size_t x) { return S[find(x)]; } };

using P = pair<i64, i64>;
signed main() {
  i64 n;
  cin >> n;
  vector<P> ps(n);
  vector<vector<i64>> cx(100010);
  vector<vector<i64>> cy(100010);
  UnionFind uf(n);
  vector<i64> Y;
  REP(i, n){
    i64 x, y;
    cin >> x >> y;
    ps[i] = {x, y};
    cx[x].push_back(i);
    cy[y].push_back(i);
    if (cx[x].size() > 1) {
      uf.unite(cx[x][0], i);
    }
    if (cy[y].size() > 1) {
      uf.unite(cy[y][0], i);
    }
  }
  vector<set<i64>> kx(100010);
  vector<set<i64>> ky(100010);
  REP(i, n) {
    kx[uf.find(i)].insert(ps[i].first);
    ky[uf.find(i)].insert(ps[i].second);
  }
  i64 ans = 0;
  REP(i, 100010) {
    ans += kx[i].size() * ky[i].size();
  }
  ans -= n;
  cout << ans << endl;
}

