bool mark[M];
int L,R,E;
void dfs(int x) {
	E++;
	if(mark[x])return;
	mark[x]=1;
	if(x<=tx)L++;
	else R++;
	for(int i=0; i<edge[x].size(); i++)
		dfs(edge[x][i]);
}
int main() {
	int n;
	cin>>n;
	for(int i=1; i<=n; i++) {
		scanf("%d %d",&x[i],&y[i]);
		if(!mkx[x[i]])mkx[x[i]]=++tx;
		if(!mky[y[i]])mky[y[i]]=++ty;
	}
	for(int i=1; i<=n; i++) {
		int a=mkx[x[i]];
		int b=mky[y[i]]+tx;
		edge[a].push_back(b);
		edge[b].push_back(a);
	}
	for(int i=1; i<=tx+ty; i++) {
		if(!mark[i]) {
			L=0,R=0,E=0;
			dfs(i);
			if(L<2||R<2)continue;
			E/=2;
			ans+=1LL*L*R-E;
		}
	}
	cout<<ans<<endl;
	return 0;
}

