        return;
    }

/* xの属する集合を返す */
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }

/* yにxを統合する */
    void unite(int x, int y) {
        p[find(x)] = p[find(y)];
    }

/* xとyが属する集合が同じかを判定する */
    bool same(int x, int y) {
        return find(x) == find(y);
    }

};

class Solve {
public:
    int N;
    vector<pair<int, int>> xy;
    vector<vector<int>> x, y;

    void input() {
        cin >> N;
        x.resize(100001);
        y.resize(100001);
        xy.resize(N);
        rep(i, 0, N) {
            cin >> xy[i].first >> xy[i].second;
            x[xy[i].first].push_back(i);
            y[xy[i].second].push_back(i);
        }
    }

    void solve() {
        input();
        UnionFind uf(N);
        for (auto e : x) {
            if (e.size() > 1) {
                for (auto ee : e) {
                    if (!uf.same(e[0], ee)) {
                        uf.unite(e[0], ee);
                    }
                }
            }
        }

        for (auto e : y) {
            if (e.size() > 1) {
                for (auto ee : e) {
                    if (!uf.same(e[0], ee)) {
                        uf.unite(e[0], ee);
                    }
                }
            }
        }

        vector<vector<int>> gr(N);
        vector<set<int>> grsx(N);
        vector<set<int>> grsy(N);
        for (int i = 0; i < N; ++i) {
            int e = uf.find(i);
            gr[e].push_back(i);
            grsx[e].insert(xy[i].first);
            grsy[e].insert(xy[i].second);
        }

        ll ans = 0;
        for (int i = 0; i < N; ++i) {
            if (gr[i].size() > 0) {
                ll w = grsx[i].size();
                ll h = grsy[i].size();
                ll tmp = w * h - (ll) gr[i].size();
                ans += tmp;
            }
        }

        cout << ans << endl;


    }
};


