#include <bits/stdc++.h>

using namespace std;

typedef long long LL;
typedef pair<int, int> PII;

class UnionFind {
 public:
  vector<int> parent;
  vector<LL> cnt;
  vector<set<int>> xs, ys;
  UnionFind(int n, vector<int> x, vector<int> y) {
    parent = vector<int>(n);
    cnt = vector<LL>(n, 1);
    for (int i = 0; i < n; i++) parent[i] = i;
    xs.resize(n);
    ys.resize(n);
    for (int i = 0; i < n; i++) {
      xs[i].insert(x[i]);
      ys[i].insert(y[i]);
    }
  }
  int find(int v) {
    if (v == parent[v]) return v;
    return parent[v] = find(parent[v]);
  }

  int uni(int u, int v) {
    u = find(u);
    v = find(v);
    if (u == v) return false;
    if (cnt[v] < cnt[u]) swap(v, u);
    for (auto val : xs[u]) xs[v].insert(val);
    for (auto val : ys[u]) ys[v].insert(val);

    parent[u] = v;
    cnt[v] += cnt[u];
    return true;
  }
};

int main() {
  int N;
  cin >> N;
  vector<int> xs, ys;
  vector<vector<int>> revx(100100), revy(100100);
  for (int i = 0; i < N; i++) {
    int x, y;
    cin >> x >> y;
    xs.push_back(x);
    ys.push_back(y);
    revx[x].push_back(i);
    revy[y].push_back(i);
  }

  UnionFind uf(N, xs, ys);

  for (auto vec : revx) {
    for (int i = 1; i < vec.size(); i++) uf.uni(vec[0], vec[i]);
  }
  for (auto vec : revy) {
    for (int i = 1; i < vec.size(); i++) uf.uni(vec[0], vec[i]);
  }
  LL ans = 0;
  for (int i = 0; i < N; i++) {
    if (uf.parent[i] != i) continue;
    ans += (LL)uf.xs[i].size() * (LL)uf.ys[i].size();
  }
  cout << ans - N << endl;

  return 0;
}

