UnionFind uf;
set<ll> group_val_x[MAX_N]; // グループ i で出てくる x 座標のバリエーション
set<ll> group_val_y[MAX_N]; // グループ i で出てくる y 座標のバリエーション


// x 座標もしくは y 座標が同じものを同じグループにする
void dfs(ll id) {
    if(isChecked[id]) { return; }
