vvll xedges(100000), yedges(100000);
V<bool> xvisited(100000, false), yvisited(100000, false);

vll dfs(ll i, ll xy) {
  if (xy == 0) xvisited[i] = true;
  else yvisited[i] = true;
  ll xc=(xy+1)%2, yc=xy%2, ec=0;
  if (xy == 0){  // x
    ec += xedges[i].size();
    REP(to, xedges[i].size()) {
      if (!yvisited[xedges[i][to]]) {
        auto p = dfs(xedges[i][to], (xy+1)%2);
        xc += p[0], yc += p[1], ec += p[2];
      }
    }
  } else {
    ec += yedges[i].size();
    REP(to, yedges[i].size()) {
      if (!xvisited[yedges[i][to]]) {
        auto p = dfs(yedges[i][to], (xy+1)%2);
        xc += p[0], yc += p[1], ec += p[2];
      }
    }
  }
  vll ans(3); ans[0] = xc; ans[1] = yc; ans[2] = ec;
  return ans;
}

int main() {
  ll n; cin >> n;
  REP(i, n) {
    ll x, y; cin >> x >> y;
    xedges[x-1].push_back(y-1);
    yedges[y-1].push_back(x-1);
  }
  ll ans = 0;
  REP(i, n) {
    if(!xvisited[i] && xedges[i].size()!=0) {
      auto p = dfs(i, 0);
      ans += p[0] * p[1] - p[2]/2;
    }
  }
  cout << ans << endl;
  return 0;
}

