// T (typename) : グラフの頂点を表す型, (int)parent を持つ必要あり
template <typename T>
struct UnionFind {
    vector<T> &u;
    UnionFind(vector<T> &u) : u(u) {
        for (int i = 0; i < u.size(); i++) {
            u[i].parent = i;
            u[i].edge_num = 0;
        }
    }
    int root(int x) {
        if (x < 0 || u.size() <= x) return -1;
        else if (x == u[x].parent) return x;
        else return u[x].parent = root(u[x].parent);
    }
    bool connect(int a, int b) {
        a = root(a), b = root(b);
        bool retval = a != b;
        if (retval) {
            u[a].X += u[b].X;
            u[a].Y += u[b].Y;
            u[a].edge_num += u[b].edge_num;
        }
        u[a].edge_num++;
        u[b].parent = a;
        return retval;
    }
};

struct Node {
    int parent;
    int X, Y;
    int edge_num;
};

int main() {
    int N;
    cin >> N;
    const int V = 2e5;
    vector<Node> uf(V);
    for(int i = 0; i < V; i++) {
        uf[i].X = i < V / 2 ? 1 : 0;
        uf[i].Y = i < V / 2 ? 0 : 1;
    }
    UnionFind<Node> uf_tree(uf);
    for(int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        x--, y--;
        y += 1e5;
        uf_tree.connect(x, y);
    }
    i64 ans = 0;
    for(int i = 0; i < V; i++) {
        if(uf_tree.root(i) == i) {
            i64 x = uf[i].X, y = uf[i].Y, e = uf[i].edge_num;
            ans += x * y - e;
        }
    }
    cout << ans << endl;
    return 0;
}

