using Segment = pair<int,int>;


class IntervalTree {
public:
    vector<vector<Segment> > stock;
    int N, l, r;

public:
    IntervalTree(int l, int r) {
        this->l = l;
        this->r = r;
        this->N = ceil2(r - l + 1);
        stock.assign(N*2, vector<Segment>());
    }
    ~IntervalTree() {}

public:
    void insert(Segment seg) {
        int sl = seg.first - this->l, sr = seg.second - this->l;
        queue<ii> q;
        q.push(ii(0, N));
        while (!q.empty()) {
            int b = q.front().first, w = q.front().second;
            q.pop();
            if (sl <= b && b+w-1 <= sr) {
                int L = N/w, i = b/w;
                stock[L+i].push_back(seg);
                continue;
            }
            if (w == 1) continue;
            int m = w/2;
            if (sl < b+m) {
                q.push(ii(b, m));
            }
            if (b+m <= sr) {
                q.push(ii(b+m, m));
            }
        }
    }

    vector<Segment> search(int p) {
        vector<Segment> res;

        if (p < l || r < p) return res;
        p -= l;

        int cnt = 0;
        for (int w=1,i=0,m=N; m>=1; w*=2,m/=2,i*=2) {
            int x = N/w;
            if (p & m) {
                ++i;
                p -= m;
            }
            res.insert(res.end(), ALL(stock[w+i]));
            /*
            for (int j=0; j<stock[w+i].size(); ++j) {

            }
            */
        }
        return res;
    }
    void dump() {
#if 0
        printf("[%d..%d, N=%d]", l, r, N);
        for (int w=1; w<=N; w*=2) {
            for (int i=0; i<w; ++i) {
                int x = N/w;
                printf("%d %d [%d..%d] ", w, i, x*i, x*(i+1)-1);
                cout << stock[w+i] << endl;
            }
        }
#endif
    }
};



ll solve(int N, vi& x, vi& y) {
    set<int> xe, ye;
    rep(i,N){
        xe.insert(x[i]);
        ye.insert(y[i]);
    }
    int xN = xe.size(), yN = ye.size();
    map<int,int> xZ, yZ;
    int xi=0, yi=0;
    for (int x: xe) xZ[x] = xi++;
    for (int y: ye) yZ[y] = yi++;
    rep(i,N){
        x[i] = xZ[ x[i] ];
        y[i] = yZ[ y[i] ];
    }

    using P = pair<int, ii>;
    vector<P> vert, horiz;

    IntervalTree it(0, xN);

    {
        vvi po(xN);
        rep(i,N) po[x[i]].pb(y[i]);
        rep(x,xN){
            sort(ALL(po[x]));
            int last = -2, from = -2, to = -2;
            for(int y: po[x]){
                if (y == last+1){
                    to = y;
                } else {
                    if (from < to) {
                        vert.emplace_back(x, ii(from, to));
                    }
                    from = to = y;
                }
                last = y;
            }
            if (from < to) {
                vert.emplace_back(x, ii(from, to));
            }
        }
    }

    {
        vvi po(yN);
        rep(i,N) po[y[i]].pb(x[i]);
        rep(y,yN){
            sort(ALL(po[y]));
            int last = -2, from = -2, to = -2;
            for(int x: po[y]){
                if (x == last+1){
                    to = x;
                } else {
                    if (from < to) horiz.emplace_back(y, ii(from, to));
                    from = to = x;
                }
                last = x;
            }
            if (from < to) horiz.emplace_back(y, ii(from, to));
        }
    }




    ll ans = 0;
    for(auto &v: vert) {
        int x = v.first;
        int vw = (v.second.second - v.second.first) + 1;
        for(auto &h: horiz) {
            int y = h.first;
            if (!IN(y, v.second.first, v.second.second)) continue;
            if (!IN(x, h.second.first, h.second.second)) continue;
            int hw = (h.second.second - h.second.first) + 1;
            ll area = (ll)vw * hw;
            ans += (area - vw - hw + 1);
        }
    }
    return ans;
}

