const int L=100000;

class union_find{
	vector<int> a;
public:
	union_find(int n):a(n,-1){}
	int find(int x){
		if(a[x]<0) return x;
		return a[x]=find(a[x]);
	}
	void unite(int x,int y){
		x=find(x),y=find(y);
		if(x!=y){ a[x]+=a[y]; a[y]=x; }
	}
	int size(int x){ return -a[find(x)]; }
};

int main(){
	int n; scanf("%d",&n);
	vector<pair<int,int>> p(n);
	rep(i,n){
		scanf("%d%d",&p[i].first,&p[i].second);
		p[i].first--;
		p[i].second--;
	}

	vector<vector<int>> xtoy(L),ytox(L);
	rep(i,n){
		xtoy[p[i].first].emplace_back(p[i].second);
		ytox[p[i].second].emplace_back(p[i].first);
	}

	rep(x,L) sort(xtoy[x].begin(),xtoy[x].end());
	rep(y,L) sort(ytox[y].begin(),ytox[y].end());

	union_find U(2*L);
	vector<bool> used(L);
	rep(x,L){
		if(xtoy[x].size()<=1) continue;

		bool ok=false;
		for(int y:xtoy[x]) if(!used[y]) {
			for(int x2:ytox[y]) if(x2!=x) {
				U.unite(x2,x);
				ok=true;
			}
			used[y]=true;
		}
		if(!ok) continue;

		for(int y:xtoy[x]) U.unite(y+L,x);
	}

	fill(used.begin(),used.end(),false);
	rep(y,L){
		if(ytox[y].size()<=1) continue;

		bool ok=false;
		for(int x:ytox[y]) if(!used[x]) {
			for(int y2:xtoy[x]) if(y2!=y) {
				U.unite(y2+L,y+L);
				ok=true;
			}
			used[x]=true;
		}
		if(!ok) continue;

		for(int x:ytox[y]) U.unite(x,y+L);
	}

	int m=0;
	map<int,int> f; // representative of U -> index in [0, m)
	rep(i,2*L){
		int u=U.find(i);
		if(U.size(u)>1 && f.count(u)==0) f[u]=m++;
	}
	vector<pair<int,int>> cnt(m);
	rep(i,2*L){
		int u=U.find(i);
		if(U.size(u)<=1) continue;
		if(i<L) cnt[f[u]].first ++; // x-coordinate
		else    cnt[f[u]].second++; // y-coordinate
	}

	long long ans=0;
	rep(i,m){
		ans+=1LL*cnt[i].first*cnt[i].second;
	}
	rep(i,n){
		if(U.size(p[i].first)>1) ans--;
	}
	printf("%lld\n",ans);

	return 0;
}

