struct UnionFindTree {
  std::vector<int> data;

  UnionFindTree(int size) : data(size, -1) { }
  bool Unite(int x, int y) {
    x = Root(x); y = Root(y);
    if (x != y) {
      if (data[y] < data[x]) std::swap(x, y);
      data[x] += data[y];
      data[y] = x;
    }
    return x != y;
  }
  bool IsSameRoot(int x, int y) {
    return Root(x) == Root(y);
  }
  int Root(int x) {
    return data[x] < 0 ? x : data[x] = Root(data[x]);
  }
  int Size(int x) { return -data[Root(x)]; }
};

int main() {
  int N; cin >> N;
  constexpr int offset = 1e5 + 1;
  UnionFindTree tree((offset + 1)*2);
  for (int i = 0; i < N; ++i) {
    int x, y; cin >> x >> y;
    tree.Unite(x, y + offset);
  }

  map<int, LL> mx, my;
  for (int i = 1; i <= offset; ++i) {
    mx[tree.Root(i)]++;
    my[tree.Root(i + offset)]++;
  }

  LL total = 0;
  for (int i = 1; i <= offset; ++i) {
    total += mx[i] * my[i];
  }
  cout << max(0LL, total - N) << endl;
}

