using namespace std;

vector<int> _parent, _rank;

void set_init(int n)
{
	_parent.assign(n, -1);
	_rank.assign(n, 0);
}

int set_find(int x)
{
	return _parent[x] < 0 ? x : _parent[x] = set_find(_parent[x]);
}

bool set_join(int x, int y)
{
	x = set_find(x), y = set_find(y);
	if (x == y) return false;
	if (_rank[y] > _rank[x]) swap(x, y);
	else if (_rank[x] == _rank[y]) _rank[x]++;
	_parent[y] = x;
	return true;
}

