    for(int i=0; i<N; i++) cin >> p[i].first >> p[i].second;
    sort(p.begin(), p.end());

    const int M = 1e6+1;
    UnionFind uf(M);
    for(int i=0; i<N-1; i++){
        if(p[i].first == p[i+1].first) uf.unite(p[i].second, p[i+1].second);
    }

    vector<int> szx(M);
    for(int i=0; i<N; i++){
        if(i != N-1 && p[i].first != p[i+1].first) szx[uf.root(p[i].second)]++;
        else if(i == N-1) szx[uf.root(p[i].second)]++;
    }

    ll ans = 0;
    for(int i=0; i<M; i++) ans += (ll)uf.get_size(i) * szx[i];
    cout << ans - N << endl;
}

