using namespace std;

struct DSU {
    int n;
    vector<int> ps;
    DSU(int n): n(n), ps(n) {
        for (int i = 0; i < n; ++i) {
            ps[i] = i;
        }
    }
    int get_parent(int i) {
        if (ps[i] == i) return i;
        return ps[i] = get_parent(ps[i]);
    }
    void merge(int i, int j) {
        i = get_parent(i);
        j = get_parent(j);
        ps[i] = j;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<pair<int, int>> points(n);
    for (auto& point : points) {
        int x, y;
        cin >> x >> y;
        point.first = x;
        point.second = y;
    }
    int max_y = max_element(points.begin(), points.end(), [](auto p1, auto p2) { return p1.second < p2.second; })->second;
    DSU lines(max_y+1);
    sort(points.begin(), points.end());
    for (int i = 1; i < n; ++i) {
        if (points[i].first == points[i-1].first) {
            lines.merge(points[i].second, points[i-1].second);
        }
    }
    vector<int> line_count(max_y+1);
    vector<set<int>> parent_lines(max_y+1);
    for (auto point : points) {
        lines.get_parent(point.second);
        ++line_count[point.second];
        parent_lines[lines.get_parent(point.second)].insert(point.first);
    }
    long long sum = 0;
    for (int i = 0; i <= max_y; ++i) {
        sum += (int) parent_lines[lines.get_parent(i)].size() - line_count[i];
    }
    cout << sum << endl;
    return 0;
}

