		int nErase = 0;
		while (true) {
			bool erased = false;
			for (auto oneX : xs) {
				auto itr = X.find(oneX);
				if (itr != X.end()) {
					auto id = X.begin()->second;
					xs.insert(x[id]);
					ys.insert(y[id]);
					X.erase(itr);
					++nErase;
					erased = true;
				}
			}
			for (auto oneY : ys) {
				auto itr = Y.find(oneY);
				if (itr != Y.end()) {
					auto id = Y.begin()->second;
					xs.insert(x[id]);
					ys.insert(y[id]);
					Y.erase(itr);
					++nErase;
					erased = true;
				}
			}
			if (!erased)break;
		}
		res += xs.size() * ys.size() - nErase / 2;
		assert(X.size() == Y.size());
	}
