struct UnionFind{
private:
    vector<int> par;
    vector<int> rank;
    vector<int> xsz, ysz;

public:
    //n要素で親を初期化、par[x]はxの親を表す
    UnionFind(int n, ll base){
        par.resize(n,0);
        rank.resize(n,0);
        xsz.resize(n,0);
        ysz.resize(n,1);
        fill(xsz.begin(), xsz.begin() + base, 1);
        fill(ysz.begin(), ysz.begin() + base, 0);

        rep(i,n){
            par[i] = i;
        }
    }

    //木の根を求める
    int root(int x){
        if(par[x] == x) return x;
        else return par[x] = root(par[x]);
    }

    //xとyの属する集合を併合
    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y) return;

        if(rank[x] < rank[y]){
            swap(x,y);
        }

        par[y] = x;
        xsz[x] += xsz[y];
        ysz[x] += ysz[y];
        if(rank[x] == rank[y]) rank[x]++; 
    }

    //xとyが同じ集合に属するか否か
    bool same(int x, int y){
        return root(x) == root(y);
    }

    //xが属する集合のサイズを返す
    pair<int, int> size(int x){
        return {xsz[root(x)], ysz[root(x)]};
    }

    // 集合の数を返す
    int num_of_s(){
        set<int> st;
        rep(i,par.size()) st.insert(root(i));
        return st.size();
    }
};


