void solve(){
    ps = points(n);
    rep(i, n){
        ll x, y; in2(x, y);
        xs[x].pb(y);
        ys[y].pb(x);
        ps[i] = {x, y};
    }

    ll nx = xs.size(), ny = ys.size();

    answer = 0;
    rep(i, n){
        ll x = ps[i].x, y = ps[i].y;
