            answer--; continue;
        }else if (visited[0][x] || visited[1][y] || 
                  xs[x].size() == 1 || ys[y].size() == 1)
            continue;

        visited[0][x] = visited[1][y] = true;
        answer += (xs[x].size() - 1) * (ys[y].size() - 1);

    }

    prl(answer);
}

