using namespace std;

typedef long long int ll;

set < int > sx, sy;

int up (int y) {
  auto it = sy.upper_bound (y);
  return (it == sy.end() ? -1 : *it);
}

int down (int y) {
  auto it = sy.lower_bound (y);
  return (it == sy.begin() ? -1 : *(--it));
}

int right (int x) {
  auto it = sx.upper_bound (x);
  return (it == sx.end() ? -1 : *it);
}

int left (int x) {
  auto it = sx.lower_bound (x);
  return (it == sx.begin() ? -1 : *(--it));
}

int main () {
  ios_base::sync_with_stdio(false);
  cin.tie(0);cout.tie(0);

  int n;
  cin >> n;
  vector < pair < int, int > > v (n);
  for (auto &i : v) cin >> i.first >> i.second;

  set < pair < int, int > > s (v.begin(), v.end());

  for (auto i : v) {
    sx.insert (i.first);
    sy.insert (i.second);
  }

  for (int i = 0; i < v.size(); i++) {
    int x = v[i].first, y = v[i].second;
    int u = up (y), d = down (y), l = left (x), r = right (x);
    vector < int > p = {u, d}, q = {l, r};
    for (int j = 0; j < 2; j++) {
      for (int k = 0; k < 2; k++) {
        if (q[j] == -1 || p[k] == -1) continue;
        if (!s.count ({q[j], p[k]})) {
          s.insert ({q[j], p[k]});
          v.push_back ({q[j], p[k]});
          sx.insert (q[j]);
          sy.insert (p[k]);
        }
      }
    }
  }

  cout << (int)v.size() - n << '\n';
}

