map<P, int> mp;
int ans = 0;

set<int> stX, stY;
set<P> st;
void search(int x, int y) {
    if (visited[mp[{x, y}]]) return;
    stX.insert(x);
    stY.insert(y);
    st.insert({x, y});
    visited[mp[{x, y}]] = true;
    for(auto to: Y[x]) {
        auto itr = mp.find({x, to});
        if (itr == mp.end()) continue; 
        search(x, to);
    }
    for(auto to: X[y]){
        auto itr = mp.find({x, to});
        if (itr == mp.end()) continue; 
        search(to, y);
    }

}

