			ans[0] += Y.first;
			ans[1] += Y.second;
		}
		if (f && !markx[u]){
			auto Y = dfs(!f, u);
			ans[0] += Y.first;
			ans[1] += Y.second;
		}
	}
	else
	for (auto u: adjy[v]){
		if (!f && !marky[u]){
			auto Y = dfs(!f, u);
			ans[0] += Y.first;
			ans[1] += Y.second;
