const int N = 100005;
vector<int> parent;
vector<int> sizeNode;
vector<int> height;
vector<int> row;

void make_set(int v, int heightColumn){
    parent[v] = v;
    height[v] = heightColumn;
    sizeNode[v] = 1;
}

int find_set(int v){
    if(v == parent[v]){
        return v;
    }
    return parent[v] = find_set(parent[v]);
}

void union_sets(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if(a != b){
        if(sizeNode[a] < sizeNode[b]){
            swap(a, b);
        }
        parent[b] = a;
        sizeNode[a] += sizeNode[b];
        height[a] += height[b];
    }
}

