    vector<int> check(N + 1, 0);
    for(int i = 0; i < N;i ++){
        if(parent[i] != -1){
            int p = find_set(i);
            if(check[p] == 0){
                ans += (1LL * sizeNode[p] * height[p]);
                check[p] = 1;
            }
        }
    }
    cout << ans - n;
}

