class UnionFind{
  private:
    vector<int> data;

  public:
    UnionFind(int n) : data(n,-1) {}
    int root(int i) { return data[i] < 0 ? i : data[i] = root(data[i]); }
    int size(int i) { return -data[root(i)]; }
    bool same(int x, int y) {return root(x) == root(y); }
    bool connected() {return size(0) == (int)data.size(); }

    bool unit(int i,int j){
        i = root(i);
        j = root(j);
        if(i != j){
            data[i] += data[j];
            data[j] = i;
        }
        return i != j;
    }
};

const int MAX = 1e5;

int main()
{
    int n;
    cin >> n;

    vector<vector<int>> ver(MAX);
    for(int i = 0; i < n; i++) {
        int x, y; cin >> x >> y; x--;
        y--;
        ver[x].push_back(y);
    }

    UnionFind tree(MAX);

    for(int i = 0; i < MAX; i++) {
        int m = ver[i].size();
        for(int j = 1; j < m; j++) {
            tree.unit(ver[i][j - 1], ver[i][j]);
        }
    }

    ll sum = 0;

    for(int i = 0; i < MAX; i++) {
        if(!ver[i].size())continue;
        int cur = tree.size(ver[i].front()) - ver[i].size();
        sum += cur;
    }
    cout << sum << endl;

}

