    sort(xp, xp+N, cmpx);
    sort(yp, yp+N, cmpy);
    for (int i = 1, last = 0, nowx = xp[0].x; i <= N; i++) {
        if (xp[i].x != nowx) {
            if (i > last + 1) {
                xaxis.insert(nowx);
                while (last < i) yaxis.insert(xp[last++].y);
            } else last = i;
            nowx = xp[i].x;
