struct uf{
    int N;
    vector<int> p;
    vector<int> s;

    uf(int n){
        N = n+1;
        p.assign(N,0);
        s.assign(N,1);
        Rep(i,N) p[i] = i;
    }

    int root(int x ){
        while( p[x] != x ){
            x = p[x] = p[p[x]];
        }
        return x;
    }

    void unite( int a, int b ){
        a = root(a);
        b = root(b);
        if( s[a] < s[b] ) swap(a,b);
        s[a] += s[b];
        p[b] = a;
    }

    bool same(int a, int b ){
        return root(a) == root(b);
    }

    ll size( int x ){
        return (ll)s[root(x)];
    }

};

