struct DSU {
	ll res;
	vector<int> r;
	vector<set<int>> s;
	DSU(int n):r(n,-1),s(n) {}
	int get(int x) {
		return r[x]<0 ? x : r[x]=get(r[x]);
	}
	int size(int x) {
		return -r[get(x)];
	}
	void add(int x,int y) {
		x=get(x);
		s[x].insert(y);
		res-=r[x];
	}
	bool join(int x,int y) {
		x=get(x);
		y=get(y);
		if (x==y) return false;
		if (r[x]>r[y]) swap(x,y);
		res+=ll(r[x])*sz(s[x]);
		res+=ll(r[y])*sz(s[y]);
		r[x]+=r[y];
		s[x].insert(begin(s[y]),end(s[y]));
		r[y]=x;
		s[y].clear();
		res-=ll(r[x])*sz(s[x]);
		return true;
	}
};

