struct UnionFind {
    UnionFind() {}
    UnionFind(int n) {
        resize(n);
    }

    void resize(int n) {
        par.resize(n, -1);
    }

    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }

    bool merge(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return false;
        if (par[rx] > par[ry]) swap(rx, ry);
        par[rx] += par[ry];
        par[ry] = rx;
        return true;
    }

    bool is_same(int x, int y) {
        return (root(x) == root(y));
    }

    int size(int x) {
        return -par[root(x)];
    }

private:
    vector<int> par;
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    // std::ifstream in("input.txt");
    // std::cin.rdbuf(in.rdbuf());
    const ll MAX = 101000;
    ll n;
    cin >> n;
    vector<pair<ll, ll>> xy(n);
    rep(i, n) cin >> xy[i].first >> xy[i].second;
    UnionFind uf(MAX * 2);
    rep(i, n) {
        uf.merge(xy[i].first, xy[i].second + MAX);
    }
    map<ll, ll> mx, my;
    reps(i, 0, MAX) mx[uf.root(i)]++;
    reps(i, MAX, MAX * 2) my[uf.root(i)]++;
    ll res = 0;
    rep(i, MAX * 2) res += mx[i] * my[i];
    cout << (res - n) << endl;
    return 0;
}

