struct UnionFind{
    vector<int> p;

    UnionFind(int n) : p(n,-1) { }

    int root(int x){
        if(p[x] < 0) return x;
        else return p[x] = root(p[x]);
    }

    bool merge(int x,int y){
        x = root(x);
        y = root(y);
        if(x == y) return false;
        if(p[x] > p[y]) swap(x,y);
        p[x] += p[y];
        p[y] = x;
        return true;
    }

    int size(int x){
        return -p[root(x)];
    }
};

