class UnionFind{
private:
  vector<int> node;
public:
  UnionFind(int n){
    node=vector<int>(n);
    iota(all(node),0);
  }
  int root(int x){
    if(node[x]==x) return x;
    return node[x]=root(node[x]);
  }
  void uni(int x, int y){
    x=root(x);
    y=root(y);
    node[y]=x;
  }
};

