	for(i = 0; i < N; i++){
		scanf("%lld%lld", &x[i], &y[i]);
		x[i]--;
		y[i]--;
		esx[x[i]].push_back(y[i]);
		esy[y[i]].push_back(x[i]);
	}
	union_find ufx(M), ufy(M);
	for(i = 0; i < M; i++){
		for(j = 0; j < esx[i].size(); j++){
			ufy.merge(esx[i][0], esx[i][j]);
		}
	}
	for(i = 0; i < M; i++){
		for(j = 0; j < esy[i].size(); j++){
			ufx.merge(esy[i][0], esy[i][j]);
		}
	}
	set<pair<int, int>> st;
	int sum = 0;
	for(i = 0; i < N; i++){
		int rx = ufx.root(x[i]);
		int ry = ufy.root(y[i]);
