struct UnionFind {
    vector<long long> data;

    UnionFind(long long N) : data(vector<long long>(N, -1)) {
    }

    long long root(long long x) {
        if (data[x] < 0)
            return x;
        else
            return data[x] = root(data[x]);
    }

    bool same(long long x, long long y) {
        return root(x) == root(y);
    }

    void unite(long long x, long long y) {
        if (!same(x, y)) {
            x = root(x);
            y = root(y);
            if (data[x] < data[y]) {
                data[x] += data[y];
                data[y] = x;
            } else {
                data[y] += data[x];
                data[x] = y;
            }
        }
        return;
    }

    long long getsize(long long x) {
        return -data[root(x)];
    }

    vector<long long> parents() {
        set<long long> s;
        vector<long long> ans;
        for (int i = 0; i < data.size(); i++) {
            s.insert(root(i));
        }
        for (set<long long>::iterator itr = s.begin(); itr != s.end(); itr++) {
            ans.push_back(*itr);
        }
        return ans;
    }
};

