// size用
struct UnionFind {
    vector<ll> par;
    vector<ll> sizes;

    UnionFind(ll n) : par(n), sizes(n, 1) { REP(i, n) par[i] = i; }

    ll find(ll x) {
        if(x == par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(ll x, ll y) {
        x = find(x);
        y = find(y);

        if(x == y) return;

        if(sizes[x] < sizes[y]) swap(x, y);

        par[y] = x;
        sizes[x] += sizes[y];
        sizes[y] = 0;
    }

    bool same(ll x, ll y) { return find(x) == find(y); }

    ll size(ll x) { return sizes[find(x)]; }
};

signed main() {
    LCIN(N);
    VL x(N), y(N);
    REP(i, N) cin >> x[i] >> y[i];
    VL cx(x), cy(y);
    sort(All(cx)), sort(All(cy));
    cx.erase(unique(All(cx)), cx.end());
    cy.erase(unique(All(cy)), cy.end());
    ll n = cx.size(), nn = cy.size();
    UnionFind uf(n + nn);
    REP(i, N) {
        ll xdx = lower_bound(All(cx), x[i]) - cx.begin();
        ll ydx = lower_bound(All(cy), y[i]) - cy.begin();
        uf.unite(xdx, n + ydx);
    }
    VPL memo(n + nn);
    REP(i, n) memo[uf.find(i)].fi++;
    REP(i, nn) memo[uf.find(n + i)].se++;
    ll ans = 0;
    FOREACH(m, memo) { ans += m.fi * m.se; }
    cout << ans - N << "\n";
}

