class UnionFind{
private:
  vector<int> par, rank;
public:
  UnionFind(int n){
	par.assign(n, 0);
	rank.assign(n, 0);
	for(int i=0;i<n;++i)
	  par[i] = i;
  }

  //find root of x
  int find(int x){
		if(par[x] == x)
			return x;
		return (par[x] = find(par[x]));
  }

  void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;

		if(rank[x] < rank[y]){
			par[x] = y;
		}
		else{
			par[y] = x;
			if(rank[x] == rank[y])
			++rank[x];
		}
  }

  bool same(int x, int y){
		return find(x) == find(y);
  }
};


