int n;
vector<int> graph[N*2+1];
int seen[N*2+1];

void dfs(int cur, int& l, int& r) {
    seen[cur] = true;
    if(cur <= N) l++;
    else r++;
    for(auto child : graph[cur]) {
        if(!seen[child]) {
            dfs(child, l, r);
        }
    }
}

