    }

    int ans = 0;
    for(int i = 1; i <= N; ++i) {
        if(!seen[i]) {
            int l = 0, r = 0;
            dfs(i, l, r);
            ans += l*r;
        }
    }
    ans -= n;

    cout << ans << endl;

