ll dfs(int z, bool isX, vector<int> &usedX, vector<int> &usedY, vector<vector<int>> &XtoY, vector<vector<int>> &YtoX){
    if(isX&&usedX[z]==1){
        return 0;
    }else if(isX==false&&usedY[z]==1){
        return 0;
    }
    if(isX){
        usedX[z]=1;
    }else{
        usedY[z]=1;
    }
    cnt[isX]++;

    vector<int> tmp;
    ll c=0;
    if(isX){
        tmp=XtoY[z];
    }else{
        tmp=YtoX[z];
    }
    for(auto &e:tmp){
        if(isX){
            if(m.count({z,e})){
                continue;
            }else{
                m[{z,e}]=1;
                c++;
            }
        }else{
            if(m.count({e,z})){
                continue;
            }else{
                m[{e,z}]=1;
                c++;
            }
        }
        c+=dfs(e,!(isX),usedX,usedY,XtoY,YtoX);
    }
    return c;
}

