struct UnionFind{
  vector<int> par; //親
  vector<int> size; //集合の大きさ

  UnionFind(int n){
    par.resize(n);
    size.resize(n);
    for(int i = 0; i < n; i++){
      par[i] = i;
      size[i] = 1;
    }
  }

  //木の根を求める
  int root(int x){
    if(par[x] == x){
      return x;
    }
    else {
      return par[x] = root(par[x]);
    }
  }

  //xとyの属する集合を併合
  void unite(int x,int y){
    x = root(x);
    y = root(y);
    if(x == y) return;

    if(size[x] < size[y]) swap(x,y);
    par[y] = x;
    size[x] += size[y];
  }
};

const int N = 1e5;

signed main(){

  int n; cin >> n;
  UnionFind uf(N*2);
  for(int i = 0; i < n; i++){
    int a, b; cin >> a >> b;
    a--, b--;
    uf.unite(a, b + N);
  }

  vector<int> x(N*2), y(N*2);
  for(int i = 0; i < N; i++){
    x[uf.root(i)]++;
    y[uf.root(i + N)]++;
  }

  int cnt = 0;
  for(int i = 0; i < N*2; i++){
    cnt += x[i] * y[i];
  }
  cout << cnt - n << endl;

  return 0;
}

