constexpr int C{200010};
using Info = tuple<ll, ll>;

Info &operator+=(Info &left, Info const &right)
{
  get<0>(left) += get<0>(right);
  get<1>(left) += get<1>(right);
  return left;
}

class Solve
{
  ll N;
  vector<vector<int>> V;
  ll cnt;
  vector<int> visited;

public:
  Solve(ll N, vector<vector<int>> V) : N{N}, V{V}, cnt{-N}, visited(C, -1) {}

  void flush()
  {
    for (auto i = 0; i < C; ++i)
    {
      if (visited[i] == -1)
      {
        Info X{dfs(i)};
        cnt += get<0>(X) * get<1>(X);
      }
    }
    cout << cnt << endl;
  }

private:
  Info dfs(int v, int c = 0)
  {
    assert(visited[v] == -1);
    visited[v] = c;
    Info ans{0, 0};
    if (c == 0)
    {
      get<0>(ans) = 1;
    }
    else
    {
      get<1>(ans) = 1;
    }
    for (auto u : V[v])
    {
      if (visited[u] == -1)
      {
        ans += dfs(u, 1 - c);
      }
    }
    return ans;
  }
};

int main()
{
  ll N;
  cin >> N;
  vector<vector<int>> V(C);
  for (auto i = 0; i < N; ++i)
  {
    int x, y;
    cin >> x >> y;
    V[x].push_back(y + C / 2);
    V[y + C / 2].push_back(x);
  }
  Solve solve(N, V);
  solve.flush();
}

