int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);

    const long Size = 100000;
    int N; cin>>N;
    map<long, set<long>> graph;
    for (size_t i = 0; i < N; i++) {
        long x,y; cin>>x>>y;
        x--;y--;
        graph[x].insert(Size+y);
        graph[Size+y].insert(x);
    }

    vector<bool> visited(Size*2, false);
    set<long> xx,yy;
    function<size_t(long,size_t)> find = [&](long p, size_t cnt) {
        if (visited[p])
            return cnt;
        visited[p] = true;
        cnt++;
        if (p < Size)
            xx.insert(p);
        else
            yy.insert(p);
        for (auto n : graph[p])
            cnt = find(n, cnt);
        return cnt;
    };

    long ans = 0;
    for (size_t i = 0; i < Size*2; i++) {
        if (visited[i])
            continue;
        long cnt = find(i, -1);
        auto nx = xx.size();
        auto ny = yy.size();
        if (nx < 2 or ny < 2)
            continue;
        ans += nx*ny-cnt;
        xx = {};
        yy = {};
    }
    cout << ans << endl;


    return 0;
}

