struct UnionFind {
    vector<int> par;
    UnionFind(int n) : par(n, -1) {}
    int root(int x) {
        if (par[x] < 0)
            return x;
        else
            return (par[x] = root(par[x]));
    }
    bool issame(int x, int y) {
        if (root(x) == root(y)) return true;
    }
    bool merge(int x, int y) {
        int rx = root(x), ry = root(y);
        if (rx == ry) return false;
        par[rx] += par[ry];
        par[ry] = rx;
        return true;
    }
};

const int MAXN = 100100;

