	{
		d[i] = i;
	}
}
void unite(int *d,ll *lev,int x, int y) {
	int px = parent(d,x);
	int py = parent(d,y);

	if (px == py) return;
	if (lev[px] < lev[py]) {
		d[px] = py;
		lev[py] += lev[px];		
	}
	else {
		d[py] = px;
		lev[px] += lev[py];
	}
}
