		if (parent(d2, y) == y && lev2[y] == 0) {
			lev2[y]++;
		}

		if (es2[y].size() > 0) {
			ll py = parent(d1,es2[y][0]);
			ll px = parent(d1, x);
			unite(d1,lev1,x, es2[y][0]);
			if(py != px)
				edg[px] = edg[py] = (edg[py] + edg[px]);
		}

		if (es1[x].size() > 0) {
			unite(d2, lev2, y, es1[x][0]);
		}

		es1[x].push_back(y);
		es2[y].push_back(x);

		edg[parent(d1, x)]++;
	}

	bool use[100010];
	memset(use, 0, sizeof(use));
