const int L = 1e5;

void dfs(const vec<int,2>& G, vector<int>& seen, int v, int& X, int& Y, int& M) {
  for (int u : G[v]) {
    if (seen[u]) continue;
    seen[u] = 1;
    ++M;
    if (u < L) {
      ++X;
    } else {
      ++Y;
    }
    dfs(G, seen, u, X, Y, M);
  }
}

