int par[100010];  //親
int _rank[100010]; //木の深さ

// n要素で初期化
void init(int n){
      REP(i, n){
		par[i] = i;
          _rank[i] = 0;
	}
}
//木の根を求める
int find(int x){
	if(par[x] == x) return x;
	else return par[x] = find(par[x]);
}
//xとyの属する集合を結合
void unite(int x, int y){
	x = find(x);
	y = find(y);
	if(x == y) return;
	if(_rank[x] < _rank[y]) par[x] = y;
	else{
		par[y] = x;
		if(_rank[x] == _rank[y]) _rank[x]++;
	}
}

int n, x[100010], y[100010];
VI idxs[100010];

map<int, int> x_to_idx;
map<int, int> y_to_idx;

void solve() {
  cin >> n;
  init(n+1);
  REP(i, n) {
    cin >> x[i] >> y[i];
    if (x_to_idx[x[i]] == 0 && y_to_idx[y[i]] == 0) {
      x_to_idx[x[i]] = i+1;
      y_to_idx[y[i]] = i+1;
      continue;
    }
    if (x_to_idx[x[i]] > 0 && y_to_idx[y[i]] > 0) {
      unite(x_to_idx[x[i]], i+1);
      unite(y_to_idx[y[i]], i+1);
      continue;
    }
    if (x_to_idx[x[i]] > 0) {
      unite(x_to_idx[x[i]], i+1);
      y_to_idx[y[i]] = i+1;
      continue;
    }
    if (y_to_idx[y[i]] > 0) {
      unite(y_to_idx[y[i]], i+1);
      x_to_idx[x[i]] = i+1;
      continue;
    }
  }
  REP(i, n) {
    idxs[find(i+1)-1].push_back(i);
  }
  LL res = 0;
  REP(i, n) {
    set<int> xs, ys;
    for(auto j : idxs[i]) {
      xs.insert(x[j]);
      ys.insert(y[j]);
    }
    res += (LL)SZ(xs) * SZ(ys) - SZ(idxs[i]);
  }
  cout << res << endl;
}

int main() {
	solve();
	return 0;
}

