struct uf {
private:
	vector<int> par, ran, siz;
public:
	void init(int n) {
		par.resize(n, 0);
		ran.resize(n, 0);
		siz.resize(n, 1);
		rep(i, n) {
			par[i] = i;
		}
	}
	int find(int x) {
		if (par[x] == x)return x;
		else return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y)return;
		if (ran[x] < ran[y]) {
			par[x] = y;
			siz[y] += siz[x];
		}
		else {
			par[y] = x;
			siz[x] += siz[y];
			if (ran[x] == ran[y])ran[x]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

