  sort(ALL(dot));
  rep(i,0,n) swap(get<0>(dot[i]),get<2>(dot[i]));
  rep(i,0,n) swap(get<0>(dot[i]),get<1>(dot[i]));  

  VVi vil(n);

  rep(i,0,n){
    vil[tree.root(i)].pb(i);
  }

  //VVerr(vil);

  set<int> x,y;
  int ans = 0;

  rep(i,0,n){
    if(vil[i].size() <= 2) continue;
    x = {};
    y = {};

    rep(j,0,vil.size()){
      x.insert(get<0>(dot[j]));
      y.insert(get<1>(dot[j]));
    }

    ans += (x.size())*(y.size()) - vil[i].size();

  }
  cout << ans << endl;
  return 0;
}

