using namespace std;

struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main() {
    int N;
    // for removing duplication
    set<int> x_set, y_set;

    cin >> N;
    vector<int> x(N), y(N);

    int M = 2e5;
    auto uf = UnionFind(M+1);

    for(int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
        x_set.insert(x[i]);
        y_set.insert(y[i]);
    }

    for(int i = 0; i < N; i++) {
        int x_idx = *x_set.lower_bound(x[i]);
        int y_idx = *y_set.lower_bound(y[i]);
        uf.unite(x_idx, 1e5+y_idx);
    }
    vector<set<int>> xs(M+1), ys(M+1);
    for(int i = 0; i < N; i++) {
        int x_idx = *x_set.lower_bound(x[i]);
        int y_idx = *y_set.lower_bound(y[i]);
        int root = uf.root(x_idx);
        xs[root].insert(x_idx);
        ys[root].insert(y_idx);
    }

    set<int> s;
    for(int i = 0; i < M; i++) {
        s.insert(uf.root(i));
    }

    long long ans = 0;
    for(auto& i : s) {
        ans += (long long)xs[i].size() * ys[i].size();
    }

    cout << ans - N << endl;
}

