class UnionFind{
public://par,rank,init,uf,uf,root,same,unite
	int par[MAXN],rank[MAXN],sum[MAXN];
	set<int>tate[MAXN],yoko[MAXN];
	void init(int n){
		rep(i,n)par[i]=i,rank[i]=0,sum[i]=1;
	}
	UnionFind(int n){
		init(n);
	}UnionFind(){}
	int root(int x){
		return x==par[x]?x:par[x]=root(par[x]);
	}
	bool same(int x,int y){
		return root(x)==root(y);
	}
	void unite(int x,int y){
		x=root(x);
		y=root(y);
		if(x==y)return;
		if(rank[x]<rank[y]){
			par[x]=y;
			sum[y]+=sum[x];
			//tate[y]にtate[x]を追加
			for(auto i:tate[x])tate[y].insert(i);
			for(auto i:yoko[x])yoko[y].insert(i);
		} else{
			par[y]=x;
			sum[x]+=sum[y];
			if(rank[x]==rank[y])++rank[x];
			for(auto i:tate[y])tate[x].insert(i);
			for(auto i:yoko[y])yoko[x].insert(i);
		}
	}
};
