int getfa(int x, vector<int> &fa) {
	return fa[x] == x ? x : (fa[x] = getfa(fa[x], fa));
}

int main() {
	int n, m = 0, x, y;
	scanf("%d", &n);
	vector<pair<int, int>> p;
	for (int i = 0; i < n; i++) {
		scanf("%d %d", &x, &y);
		m = max(m, max(x, y));
		p.push_back(make_pair(x, y));
	}
	sort(p.begin(), p.end());
	vector<int> fa(m + 1, 0);
	vector<int> li(m + 1, 0);
	vector<int> po(m + 1, 0);
	for (int i = 1; i <= m; i++) {
		fa[i] = i;
		li[i] = 0;
		po[i] = 1;
	}
	ll ans = 0;
	for (int i = 0, j = 0; i < n; i = j) {
		while (j < n && p[i].first == p[j].first) j++;
		// cout << i << " " << j << endl;
		int f1 = getfa(p[i].second, fa), f2;
		ll tt = 1LL * li[f1] * po[f1];
		// cout << "=" << li[f1] << " " << po[f1] << " " << tt << endl;
		for (int k = i + 1; k < j; k++) {
			f2 = getfa(p[k].second, fa);
			if (f2 != f1) {
				fa[f2] = f1;
				li[f1] += li[f2];
				po[f1] += po[f2];
				tt += 1LL * li[f2] * po[f2];
			}
		}
