struct UnionFind {
    vector<i64> ps_;

    explicit UnionFind(i64 n) : ps_(n,-1) {}

    i64 size() const { return SIZE(ps_); }

    i64 root(i64 x) {
        i64 p = ps_[x];
        if(p < 0) return x;
        return ps_[x] = root(p);
    }

    void unite(i64 x, i64 y) {
        i64 rx = root(x);
        i64 ry = root(y);
        if(rx == ry) return;

        i64 kx = -ps_[rx];
        i64 ky = -ps_[ry];
        if(kx < ky) swap(rx,ry);
        ps_[ry] = rx;
        ps_[rx] = -(kx+ky);
    }
};

void solve() {
    i64 N = RD();
    vector<i64> X(N);
    vector<i64> Y(N);
    REP(i, N) {
        X[i] = RD();
        Y[i] = RD();
    }

    auto vert_x = [](i64 x) { return x; };
    auto vert_y = [](i64 y) { return 100000+y; };

    UnionFind uf(200001);
    REP(i, N) {
        uf.unite(vert_x(X[i]), vert_y(Y[i]));
    }

    HashMap<i64,i64> mx;
    HashMap<i64,i64> my;
    FOR(x, 1, 100001) {
        i64 r = uf.root(vert_x(x));
        ++mx[r];
    }
    FOR(y, 1, 100001) {
        i64 r = uf.root(vert_y(y));
        ++my[r];
    }

    i64 ans = 0;
    REP(r, SIZE(uf)) {
        ans += mx[r] * my[r];
    }
    ans -= N;

    PRINTLN(ans);
}

signed main() {


