class UnionFindTree{
private:
	vll par;
	vll rank;
public:
	UnionFindTree(ll num): par(num), rank(num) { REP(i, num) par[i] = i; }
	bool same(ll x, ll y) { return root(x) == root(y); }
	ll root(ll x) { return (par[x] == x) ? x : par[x]=root(par[x]); }
	void unite(ll x, ll y){
		x = root(x);
		y = root(y);
		if (x == y) return;
		if (rank[x] < rank[y]) par[x] = y;
		else                   par[y] = x;
		if (rank[x] == rank[y]) rank[x]++;
	}
};

vector<pair<ll, ll>> xy;

int main()
{
	ll N;
	cin>>N;
	vector<pair<ll, ll>> xy = cinv2(N);

	vector<tuple<ll, ll, ll>> xyidx;
	REP(i, N){
		xyidx.emplace_back(xy[i].first, xy[i].second, i);
	}
	auto xyidx_xsort = xyidx;
	auto xyidx_ysort = xyidx;

	std::sort(xyidx_xsort.begin(), xyidx_xsort.end(),
		[](auto &a, auto &b) { return get<0>(a) < get<0>(b); }
	);
	std::sort(xyidx_ysort.begin(), xyidx_ysort.end(),
		[](auto &a, auto &b) { return get<1>(a) < get<1>(b); }
	);

	UnionFindTree uft(N);
	REP(i, N-1){
		auto &enow = xyidx_xsort[i];
		auto &enxt = xyidx_xsort[i+1];
		if (get<0>(enow) == get<0>(enxt)){
			uft.unite(get<2>(enow), get<2>(enxt));
		}
	}
	REP(i, N-1){
		auto &enow = xyidx_ysort[i];
		auto &enxt = xyidx_ysort[i+1];
		if (get<1>(enow) == get<1>(enxt)){
			uft.unite(get<2>(enow), get<2>(enxt));
		}
	}

	unordered_map<ll, vll> grps;
	REP(i, N){
		ll r = uft.root(i);
		grps[r].push_back(i);
	}

	ll ans = 0;
	EACH(e, grps){
		auto grp = e.second;
		if (grp.size() <= 2) continue;

		std::unordered_set<ll> xpos;
		std::unordered_set<ll> ypos;
		xpos.reserve(grp.size());
		ypos.reserve(grp.size());
		EACH(idx, grp){
			auto x = xy[idx].first;
			auto y = xy[idx].second;
			xpos.insert(x);
			ypos.insert(y);
		}
		ans += xpos.size() * ypos.size() - grp.size();
	}

	cout << ans << '\n';

	return 0;
}

