		vertices = move(r.vertices);
		edges = move(r.edges);
	}
	Graph& operator=(Graph&& r)
	{
		for (auto &p_vertex : vertices) {
			delete p_vertex;
		}
		for (auto &p_edge : edges) {
			delete p_edge;
		}
		vertices = move(r.vertices);
		edges = move(r.edges);
		return *this;
	}
	void add_edge(Edge *p_edge);
	void add_edge(int edge_src, int edge_dst, Weight w);
	void add_edge(int edge_src, int edge_dst);
};

