    vector<int> root, siz;

    void init(int n)
    {
        root.resize(n);
        siz.resize(n);
        for(int i=0;i<n;i++)
            root[i] = i, siz[i] = 1;
    }

    int find(int x)
    {
        return root[x] = (root[x] == x ? x : find(root[x]));
    }

    int merge(int x, int y)
    {
        x = find(x);
        y = find(y);
        if(x == y) return 0;
        siz[x] += siz[y];
        root[y] = x;
        return 1;
    }

    ll get_size(int x)
    {
        return siz[find(x)];
    }
};
