struct union_find{
    vector<int> par;
    vector<int> rank;
    vector<int> size;
    vector<int> count;
    vector<int> pcount;
    union_find(int n) : par(n), rank(n), size(n), count(n), pcount(n){
        for(int i = 0; i < n; i++){
            par[i] = i; rank[i] = 0; size[i] = 1; count[i] = 0; pcount[i] = 0;
        }
    }
    int root (int x){
        if(par[x] == x) return x;
        par[x] = root(par[x]);
        return par[x];
    }
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) { return; }
        if (rank[rx] < rank[ry]){
            par[rx] = ry;
            size[ry] += size[rx];
            count[ry] += count[rx];
            pcount[ry] += pcount[rx];
        }
        else{
            par[ry] = rx;
            size[rx] += size[ry];
            count[rx] += count[ry];
            pcount[rx] += pcount[ry];
            if (rank[rx] == rank[ry]) rank[rx]++;
        }
    }
    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
    int get_size(int x){
        int rx = root(x);
        return size[rx];
    }
    int get_count(int x){
        int rx = root(x);
        return count[rx];
    }
    void add_count(int x){
        int rx = root(x);
        count[rx]++;
    }
    void add_pcount(int x){
        int rx = root(x);
        pcount[rx]++;
    }
};


const int MAX_P = 100001;

int main(){
    union_find uf(MAX_P);
    int n; cin>>n;
    vector<int> P[MAX_P];
    rep(i, n){
        int x, y; cin>>x>>y; x--; y--;
        P[x].push_back(y);
    }

    rep(x, MAX_P){
        vector<int> Y = P[x];
        if(Y.empty()) continue;
        uf.add_count(Y[0]);
        uf.add_pcount(Y[0]);
        if(Y.size() == 1) continue;
        rep(i, Y.size()-1) {uf.add_pcount(Y[0]); uf.unite(Y[i], Y[i+1]) ;}
    }

    long all = 0;
    rep(x, MAX_P){
        int rx = uf.root(x);
        if (x != rx || uf.size[rx] == 1 || uf.count[rx] == 1) continue;
        all += (long)uf.size[rx] * (long)uf.count[rx] - (long)uf.pcount[rx];
    }

    cout<<all<<endl;
}

