struct UnionFind
{
    vector<int> par, sz;
    UnionFind(int n) {
        par.resize(n);
        sz.resize(n, 1);
        for (int i = 0; i < n; ++i) par[i] = i;
    }
    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }
    bool merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (sz[x] < sz[y]) swap(x, y);
        par[y] = x;
        sz[x] += sz[y];
        sz[y] = 0;
    }
    bool issame(int x, int y) {
        return root(x) == root(y);
    }
    int size(int x) {
        return sz[root(x)];
    }
};

void dfs(const auto& G, auto& visited, int v, int p, int& xcnt, int& ycnt, int& ecnt) {
    if (visited[v]) return;
    visited[v] = true;
    if (v < G.size()/2) ++xcnt;
    else       ++ycnt;
    for (auto u : G[v]) {
        if (u == p) continue;
        ++ecnt;
        dfs(G, visited, u, v, xcnt, ycnt, ecnt);
    }
}

