//cur=0:x,cur=1:y
//vertex:頂点
ll dfs(int cur,int vertex){
  if(used[cur][vertex]) return 0;
  used[cur][vertex] = true;
  num[cur]++;
  ll n_edge = 0;
  rep(i,G[cur][vertex].to.size()){
    PII p;
    if(cur == 0) p = PII(vertex,G[cur][vertex].to[i]);
    else p = PII(G[cur][vertex].to[i],vertex);
    if(st.count(p)) continue;
    st.insert(p);
    n_edge++;
    n_edge += dfs(cur^1,G[cur][vertex].to[i]);
  }
  return n_edge;
}

