    i64 a = xm[x];
    i64 b = ym[y];
    a = uf.root(a);
    b = uf.root(b);
    if(a == 0 && b == 0) {
      xm[x] = t;
      ym[y] = t;
      tag[i] = t;
      t++;
    }
    else if(a == 0) {
      xm[x] = b;
      tag[i] = b;
    }
    else if(b == 0) {
      ym[y] = a;
      tag[i] = a;
    }
    else {
      uf.unite(a, b);
      tag[i] = a;
    }
  }

  vector<i64> ss(t, 0);
