class UnionFind {
public:
    vector<int> par;
    vector<int> rnk;
    vector<int> sze;

    UnionFind(ll n): par(n), rnk(n, 0), sze(n, 1) {
        for (ll i = 0; i < n; ++i) par[i] = i;
    }

    void init(int n) {
        for (int i = 0; i < n; i++) {
            par.resize(n);
            rnk.assign(n, 0);
            sze.assign(n, 1);
        }
    }

    int find(int x) {
        if (par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return 0;
        if (rnk[x] < rnk[y]) {
            sze[y] = sze[x] + sze[y];
            par[x] = y;
        }
        else {
            sze[x] = sze[x] + sze[y];
            par[y] = x;
            if (rnk[x] == rnk[y]) rnk[x]++;
        }
        return 1;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    bool size(int x) {
        return sze[find(x)];
    }
};

int main() {
    int n;
    cin >> n;
    vector<int> x(n), y(n);
    UnionFind uf = UnionFind(200000);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        x[i]--;  y[i]--;
        uf.unite(x[i], y[i] + 100000);
    }

    vector<Pll> v(200000, Pll(0, 0));
    for (int i = 0; i < 200000; i++) {
        if (i < 100000) v[uf.find(i)].first++;
        else v[uf.find(i)].second++;
    }

    ll ans = 0;
    bool f[200000] = {};
    for (int i = 0; i < 200000; i++) {
        if (v[i].first >= 2 && v[i].second >= 2) {
            ans += v[i].first * v[i].second;
            f[i] = 1;
        }
    }

    for (int i = 0; i < n; i++) {
        if (uf.same(x[i], y[i] + 100000) && f[uf.find(x[i])]) {
            ans--;
        }
    }
    cout << ans << endl;
}

