int _par[MAX_N];//親                                                       
int _rank[MAX_N];//木の深さ                                                

//n要素で初期化 parは親の要素の番号                                        
void init(int n){
  for(int i=0; i<n; i++){
    _par[i] = i;
    _rank[i]=0;
  }
}

//木の根を求める                                                           
int find(int x){
  if(_par[x]==x){
    return x;
  }
  else{
    return _par[x] = find(_par[x]);
  }
}

//xとyの属する集合の併合                                                   
void unite(int x, int y){
  x=find(x);
  y=find(y);
  if(x==y) return;

  if (_rank[x] < _rank[y]){
    _par[x] = y;
  }else{
    _par[y]=x;
    if(_rank[x] == _rank[y])_rank[x]++;
  }
}

//xとyが同じ集合に属するか否か                                             
bool same(int x, int y){
  return find(x) == find(y);
}


