class UnionFind {
private:
    vector<int> par, sizes;

public:

    UnionFind(int n = 100010) : par(n), sizes(n, 1) {
        rep(i, n) par[i] = i;
    }

    int root(int x) {
        if (x == par[x]) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (sizes[x] < sizes[y]) swap(x, y);
        par[y] = x;
        sizes[x] += sizes[y];
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return sizes[root(x)];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    UnionFind uf(100010);
    vector<pair<pii, int> > v(n);

    rep(i, n) {
        cin >> v[i].first.first >> v[i].first.second;
        v[i].second = i;
    }
    sort(all(v));

    rep(i, n - 1) {
        if (v[i].first.first == v[i + 1].first.first) uf.unite(v[i].second, v[i + 1].second);
    }

    rep(i, n) swap(v[i].first.first, v[i].first.second);
    sort(all(v)); 

    rep(i, n - 1) {
        if (v[i].first.first == v[i + 1].first.first) uf.unite(v[i].second, v[i + 1].second);
    }

    vector<int> num[100010];
    rep(i, n) num[uf.root(v[i].second)].push_back(i);
    ll ans = 0;

    rep(i, 100010) {
        if (num[i].empty()) continue;
        set<int> x, y;
        for (auto t : num[i]) {
            x.insert(v[t].first.first);
            y.insert(v[t].first.second);
        }
        if (x.size() == 1 || y.size() == 1) continue;
        ans += (ll) x.size() * (ll) y.size() - (ll) num[i].size();
    }

    cout << ans << endl;

    return 0;
}

