int bfs(int idx)
{
	queue<pair<pii, int>> q;
	q.emplace(P[idx], idx);

	set<int> SX, SY;
	SX.insert(P[idx].first);
	SY.insert(P[idx].second);
	visited[idx] = true;

	int sz = 1;

	while (q.size()) {
		auto cur = q.front(); q.pop();

		int curx = cur.first.first, cury = cur.first.second;
		int id = cur.second;

		int xidx = lower_bound(all(x[cury]), pii(curx, id)) - begin(x[cury]);
		int yidx = lower_bound(all(y[curx]), pii(cury, id)) - begin(y[curx]);

		for (int i = -1; i <= 1; ++i) {
			if (0 <= xidx + i and xidx + i < x[cury].size()) {
				pii neix = x[cury][xidx + i];
				int nx = neix.first;
				int nid = neix.second;

				if (visited[id]) continue;
				sz++;

				SX.insert(nx);
				q.emplace(pii(nx, cury), nid);
				visited[id] = true;
			}
		}
		for (int i = -1; i <= 1; ++i) {
			if (0 <= yidx + i and yidx + i < y[curx].size()) {
				pii neiy = y[curx][yidx + i];
				int ny = neiy.first;
				int nid = neiy.second;

				if (visited[id]) continue;
				sz++;
				SY.insert(ny);
				q.emplace(pii(curx, ny), nid);
				visited[id] = true;
			}
		}
	}

	return SX.size() * SY.size() - sz;
}

