struct uftree{
	int par[100005];
	int rank[100005];
	int sz[100005];
	uftree(){
	}
	void init(int n){
		for(int i=0;i<n;i++){
			par[i]=i;
			rank[i]=0;
			sz[i]=1;
		}
	}
	int find(int x){
		if(par[x]==x)return x;
		return par[x]=find(par[x]);
	}

	void unite(int x,int y){
		x=find(x);
		y=find(y);
		if(x==y)return;
		if(rank[x]<rank[y]){
			par[x]=y;
			sz[y]+=sz[x];
		}else{
			if(rank[x]==rank[y])rank[x]++;
			par[y]=x;
			sz[x]+=sz[y];
		}
	}

	bool same(int x,int y){
		return find(x)==find(y);
	}
};


