#include <bits/stdc++.h>

using namespace std;
using ll = long long;
using P = pair<int, int>;

// [ _UnionFind ]
// Union-Find木 /* union by size */
// 宣言は UnionFind uf(N); のようにする
// find(x) : xの根を求める
// same(x, y) : xとyが同じ集合に属するかどうか
// size(x) : xの属する集合の要素数
// size() : 集合がいくつあるか
// unite(x, y) : xとyの属する集合を併合する
struct UnionFind {
private:
	vector<int> uf;
	size_t sz;

public:
	UnionFind(size_t Size) {
		uf.assign(Size, -1);
		sz = Size;
	}

	int find(int x) { return (uf[x] < 0) ? x : uf[x] = find(uf[x]); }
	bool same(int x, int y) { return find(x) == find(y); }
	int size(int x) { return -uf[find(x)]; }
	int size() { return sz; }

	void unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y) { return; }
		--sz;

		if (uf[y] < uf[x]) { swap(x, y); }
		uf[x] += uf[y];
		uf[y] = x;
	}
};

int main() {
	const int sz = 1e5;
	int N;
	cin >> N;
	vector<int> x(N), y(N);
	vector<vector<int>> vx(sz), vy(sz);
	map<P, int> mp;
	for (int i = 0; i < N; ++i) {
		cin >> x[i] >> y[i];
		--x[i];
		--y[i];
		vx[x[i]].push_back(y[i]);
		vy[y[i]].push_back(x[i]);
		mp[P(x[i], y[i])] = i;
	}

	UnionFind uf(N);
	for (int i = 0; i < sz; ++i) {
		if (vx[i].size() < 2) { continue; }
		int idx = mp[P(i, vx[i][0])];
		for (int j = 1; j < vx[i].size(); ++j) {
			uf.unite(idx, mp[P(i, vx[i][j])]);
		}
	}
	for (int i = 0; i < sz; ++i) {
		if (vy[i].size() < 2) { continue; }
		int idx = mp[P(vy[i][0], i)];
		for (int j = 1; j < vy[i].size(); ++j) {
			uf.unite(idx, mp[P(vy[i][j], i)]);
		}
	}

	map<int, vector<P>> mp2;
	for (int i = 0; i < N; ++i) {
		P p = P(x[i], y[i]);
		mp2[uf.find(mp[p])].push_back(p);
	}

	ll sum = 0;
	for (auto it = mp2.begin(); it != mp2.end(); ++it) {
		set<int> X, Y;
		for (auto p : it->second) {
			X.insert(p.first);
			Y.insert(p.second);
		}
		sum += ((ll)X.size() * (ll)Y.size());
	}
	cout << sum - N << endl;

	return 0;
}

