int compress(vector< int > &x) {
	vector< int > xs = x;
	int N = x.size();
	sort(xs.begin(), xs.end());
	xs.erase(unique(xs.begin(), xs.end()), xs.end());
	for (int i = 0; i < N; i++) {
		x[i] = lower_bound(xs.begin(), xs.end(), x[i]) - xs.begin();
	}
	return xs.size();
}
int N, M, K, T, Q;
pii dfs(vector< vector< int > > &G, vector< int > &done, int x) {
	pii ret = pii(1, done[x]);
	rep(i, G[x].size()) {
		int j = G[x][i];
		if (done[j] != -1)
			continue;
		done[j] = 1 - done[x];
		pii p = dfs(G, done, j);
		ret.first += p.first;
		ret.second += p.second;
	}
	return ret;
}
signed main() {
