	vector< int > x(N), y(N);
	rep(i, N) cin >> x[i] >> y[i];
	int W = compress(x);
	int H = compress(y);
	vector< vector< int > > G(H + W);
	rep(i, N) {
		G[x[i]].push_back(y[i] + W);
		G[y[i] + W].push_back(x[i]);
	}
	vector< int > done(H + W, -1);
	int ans = 0;
	rep(i, H + W) if (done[i] == -1) {
		done[i] = 0;
		pii p = dfs(G, done, i);
		ans += p.second * (p.first - p.second);
	}
	ans -= N;
	cout << ans << endl;
	return 0;
}

