    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

const ll MAX = 110000;
ll N;
vector<ll> x, y;

ll solve() {
    UnionFind uf(MAX * 2);
    x.resize(N); y.resize(N);
    rep (i, N) cin >> x[i] >> y[i], uf.merge(x[i], y[i] + MAX);

    map<int, ll> mx, my;
    for (int i = 0; i < MAX; i++) mx[uf.root(i)]++;
    for (int i = MAX; i < MAX*2; i++) my[uf.root(i)]++;
    ll res = 0;
    for (int r = 0; r < MAX*2; r++) res += mx[r] * my[r];
    return res - N;
}

int main() {
    cin >> N; cout << solve() << endl;
}

