struct UnionFind {
private:
	vector<int> uf;
	size_t sz;

public:
	UnionFind(size_t Size) {
		uf.assign(Size, -1);
		sz = Size;
	}

	int find(int x) { return (uf[x] < 0) ? x : uf[x] = find(uf[x]); }
	bool same(int x, int y) { return find(x) == find(y); }
	int size(int x) { return -uf[find(x)]; }
	int size() { return sz; }

	void unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y) { return; }
		--sz;

		if (uf[y] < uf[x]) { swap(x, y); }
		uf[x] += uf[y];
		uf[y] = x;
	}
};

int main() {
	const int sz = 1e5;
	int N;
	cin >> N;
	vector<int> x(N), y(N);
	UnionFind uf(sz * 2);
	for (int i = 0; i < N; ++i) {
		cin >> x[i] >> y[i];
		--x[i];
		--y[i];
		uf.unite(x[i], y[i] + sz);
	}

	vector<ll> cx(sz * 2, 0), cy(sz * 2, 0);
	for (int i = 0; i < sz * 2; ++i) {
		if (i < sz) { cx[uf.find(i)] += 1; }
		else { cy[uf.find(i)] += 1; }
	}

	ll sum = 0;
	for (int i = 0; i < sz * 2; ++i) {
		sum += cx[i] * cy[i];
	}
	cout << sum - N << endl;

	return 0;
}

