pair<int, int> dfs(int u, int b, vector<vector<int>> &graph, vector<bool> &visit){
	if(visit[u]) return {0, 0};
	visit[u] = true;
	pair<int, int> x = {0, 0};
	for(int v: graph[u]){
		auto p = dfs(v, 1-b, graph, visit);
		x.first += p.first;
		x.second += p.second;
	}
	if(b) x.second++;
	else x.first++;
	return x;
}

