struct DSU {
    DSU(int N) {
        m_weight.resize(N, 1);
        m_color.resize(N);
        iota(m_color.begin(), m_color.end(), 0);
    }

    int get(int x) {
        while (x != m_color[x])
            x = m_color[x];
        return x;
    }

    void merge(int x, int y) {
        x = get(x);
        y = get(y);

        if (x == y)
            return;

        if (m_weight[x] > m_weight[y])
            std::swap(x, y);

        m_weight[y] += m_weight[x];
        m_color[x] = m_color[y];
    }

    vector<int> m_weight, m_color;
};

int main(int argc, char * argv[]) {
    int N;
    cin >> N;
    vector<pair<int, int>> X(N);
    for (auto & x : X)
        cin >> x.first >> x.second;

    map<int, vector<int>> h; // give x find all y
    map<int, int> y_to_rowid;
    for (auto & pt : X) {
        h[pt.first].push_back(pt.second);
        y_to_rowid[pt.second] = -1;
    }

    int rows = 0;
    for (auto & x : y_to_rowid) {
        x.second = rows;
        ++rows;
    }

    DSU dsu(rows);
    for (auto & x : h) {
        int y0 = x.second[0];
        for (int y1 : x.second) {
            dsu.merge(y_to_rowid[y0], y_to_rowid[y1]);
        }
    }

    map<int, set<int>> row_points, merged_row_points;
    for (auto & pt : X) {
        merged_row_points[dsu.get(y_to_rowid[pt.second])].insert(pt.first);
        row_points[y_to_rowid[pt.second]].insert(pt.first);
    }
    int64_t ops = 0;
    for (int i = 0; i < rows; ++i) {
        ops += merged_row_points[dsu.get(i)].size() - row_points[i].size();
