using namespace std;

#define MAX_N (100000L)
#define MAX_XY (100000L)

struct UnionFind {
  vector<int> par;  // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

  UnionFind(int N) : par(N) {  //最初は全てが根であるとして初期化
    for (int i = 0; i < N; i++) par[i] = i;
  }

  int root(int x) {  // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  void unite(int x, int y) {  // xとyの木を併合
    int rx = root(x);         // xの根をrx
    int ry = root(y);         // yの根をry
    if (rx == ry) return;  // xとyの根が同じ(=同じ木にある)時はそのまま
    par[rx] =
        ry;  // xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
  }

  bool same(int x, int y) {  // 2つのデータx, yが属する木が同じならtrueを返す
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }
};

int main(int argc, char *argv[]) {
  // read inputs
  long N, xs[MAX_N], ys[MAX_N];
  scanf("%ld", &N);
  for (long i = 0; i < N; i++) {
    scanf("%ld %ld", &xs[i], &ys[i]);
  }

  // cnt
  UnionFind uf(N);
  vector<set<long>> is_with_xs(MAX_XY + 1, set<long>()),
      is_with_ys(MAX_XY + 1, set<long>());
  for (long i = 0; i < N; i++) {
    const long x = xs[i], y = ys[i];
    if (is_with_xs[x].size() > 0) {
      uf.unite(i, *is_with_xs[x].begin());
    }
    if (is_with_ys[y].size() > 0) {
      uf.unite(i, *is_with_ys[y].begin());
    }
    is_with_xs[x].insert(i);
    is_with_ys[y].insert(i);
  }

  vector<set<long>> grp_to_is(MAX_N + 1, set<long>()),
      grp_to_xs(MAX_N + 1, set<long>()), grp_to_ys(MAX_N + 1, set<long>());
  for (long i = 0; i < N; i++) {
    const long root = uf.root(i);
    grp_to_is[root].insert(i);
    grp_to_xs[root].insert(xs[i]);
    grp_to_ys[root].insert(ys[i]);
  }

  // count for each group
  long ans = 0;
  for (long i = 0; i < N; i++) {
    ans += grp_to_xs[i].size() * grp_to_ys[i].size() - grp_to_is[i].size();
  }

  // print answer
  printf("%ld\n", ans);

  return 0;
}

