int main()
{
    int N;
    cin >> N;
    set<pair<int, int>> points;
    map<int, set<int>> cols, rows;
    for (int i = 0; i < N; ++i)
    {
        int xi, yi;
        cin >> xi >> yi;
        points.insert({ xi, yi });
        cols[xi].insert(yi);
        rows[yi].insert(xi);
    }
    map<pair<int, int>, vector<set<int>>> friends;
    deque<pair<int, int>> queue;
    for (const auto &point : points)
    {
        friends[point] = vector<set<int>> { cols[point.first], rows[point.second] };
        friends[point][0].erase(point.second);
        friends[point][1].erase(point.first);
        queue.push_back(point);
    }

    int count = 0;
    for (;;)
    {
        if (queue.empty())
        {
            break;
        }
        const auto point = queue.front();
        queue.pop_front();
        for (const int x : friends[point][1])
        {
            for (const int y : friends[point][0])
            {
                const pair<int, int> p{ x, y };
                if (friends.find(p) == friends.end())
                {
                    ++count;
                    friends[p] = vector<set<int>>{
                        { point.second }, { point.first }};
                    queue.push_back(p);
                    friends[{x, point.second}][0].insert(y);
                    queue.push_back({ x, point.second });
                    friends[{point.first, y}][1].insert(x);
                    queue.push_back({ point.first, y });
                }
            }
        }
    }
    cout << count << endl;
}

