using namespace std;

struct UnionFind {
    vector<int> parent;

    UnionFind(int n) : parent(n, -1) {}
    void Init(int n) { parent.assign(n, -1); }

    int Root(int x) {
        if (parent[x] < 0) return x;
        else return parent[x] = Root(parent[x]);
    }

    bool IsSame(int x, int y) {
        return Root(x) == Root(y);
    }

    bool Merge(int x, int y) {
        x = Root(x); y = Root(y);
        if (x == y) return false;
        if (parent[x] > parent[y]) swap(x, y);
        parent[x] += parent[y];
        parent[y] = x;
        return true;
    }

    int Size(int x) {
        return -parent[Root(x)];
    }
};

void Compress(vector<long long>& x, map<long long, long long>& zip, vector<long long>& unzip) {
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());

    unzip.resize(x.size());
    for(long long i = 0; i < x.size(); ++i) {
        zip[x[i]] = i;
        unzip[i] = x[i];
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout.setf(ios::fixed);

    Int N; cin >> N;
    vector<Int> x(N), y(N), orgX(N), orgY(N);
    rep(i, 0, N) cin >> x[i] >> y[i];
    orgX = x; orgY = y;

    map<long long, long long> zipx;
    vector<long long> unzipx;
    Compress(x, zipx, unzipx);
    map<long long, long long> zipy;
    vector<long long> unzipy;
    Compress(y, zipy, unzipy);

    Int nx = x.size(), ny = y.size();
    UnionFind uf(nx+ny);

    rep(i, 0, N) {
        uf.Merge(zipx[orgX[i]], zipy[orgY[i]]+nx);
    }

    map<Int, Int> mx, my;
    rep(i, 0, nx) {
        mx[uf.Root(i)]++;
    }
    rep(i, nx, nx+ny) {
        my[uf.Root(i)]++;
    }

    Int res = 0;
    rep(i, 0, nx+ny) {
        res += mx[i] * my[i];
    }

    cout << res - N << endl;
}

