class UnionFind{
public://par,rank,init,uf,uf,root,same,unite
	int par[MAXN],rank[MAXN],sum[MAXN];
	set<int> sx[MAXN],sy[MAXN];
	void init(int n){
		rep(i,n)par[i]=i,rank[i]=0,sum[i]=1;
	}
	UnionFind(int n){
		init(n);
	}UnionFind(){}
	int root(int x){
		return x==par[x]?x:par[x]=root(par[x]);
	}
	bool same(int x,int y){
		return root(x)==root(y);
	}
	void unite(int x,int y){
		x=root(x);
		y=root(y);
		if(x==y)return;
		if(rank[x]<rank[y]){
			par[x]=y;
			sum[y]+=sum[x];
			each(sx[x])sx[y].insert(e);
			each(sy[x])sy[y].insert(e);
		} else{
			par[y]=x;
			sum[x]+=sum[y];
			each(sx[y])sx[x].insert(e);
			each(sy[y])sy[x].insert(e);
			if(rank[x]==rank[y])++rank[x];
		}
	}
};

int main(){
	lint n,x,y,ans=0;in(n);
	UnionFind t(n);
	vector<vector<int>> v(100000),h(100000);
	rep(n){
		in(x,y);--x,--y;
		t.sx[i].insert(x),t.sy[i].insert(y);
		v[y].pb(i),h[x].pb(i);
	}
	rep(100000)if(v[i].size()>1)each(v[i])t.unite(v[i][0],e);
	rep(100000)if(h[i].size()>1)each(h[i])t.unite(h[i][0],e);
	rep(n)if(t.par[i]==i){
		ans+=t.sx[i].size()*t.sy[i].size()-t.sum[i];
	}
	out(ans);
}
