struct UF{
  vector<int> par; //親
  vector<int> size; //集合の大きさ

  UF(int n){
    par.resize(n);
    size.resize(n);
    for(int i = 0; i < n; i++){
      par[i] = i;
      size[i] = 1;
    }
  }

  //木の根を求める
  int root(int x){
    if(par[x] == x){
      return x;
    }
    else {
      return par[x] = root(par[x]);
    }
  }

  //xとyの属する集合を併合
  void unite(int x,int y){
    x = root(x);
    y = root(y);
    if(x == y) return;

    if(size[x] < size[y]) swap(x,y);
    par[y] = x;
    size[x] += size[y];
  }

};

const int MAX = 1e5 + 10;

signed main(){

  int n; cin >> n;
  UF uf(MAX*2);
  for(int i = 0; i < n; i++){
    int x,y; cin >> x >> y;
    uf.unite(x,y + MAX);
  }

  vector<int> x(MAX*2,0),y(MAX*2,0);
  for(int i = 0; i < MAX; i++){
    x[uf.root(i)]++;
    y[uf.root(i + MAX)]++;
  }

  int ans = 0;
  for(int i = 0; i < MAX*2; i++){
    ans += x[i] * y[i];
  }
  cout << ans - n << endl;

  return 0;
}

