#include<bits/stdc++.h>

using namespace std;

typedef long long int ll;

const int N = 1e5 + 5;

vector < int > x (N), y (N), p (N), sz (N);
vector < vector < int > > adj (N);

int find (int u) {
  if (u == p[u]) return u;
  return p[u] = find (p[u]);
}

void merge (int u, int v) {
  u = find (u);
  v = find (v);
  if (u != v) {
    if (sz[u] > sz[v]) swap (u, v);
    p[u] = v;
    sz[v] += sz[u];
  }
}

