struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

int main()
{
	int N;
	cin >> N;
	using point = tuple<int, int, int>;
	vector<point> p;
	for (int i = 0; i < N; ++i) {
		int x, y;
		cin >> x >> y;
		p.emplace_back(i, x, y);
	}

	auto geti = [](auto &p) { return get<0>(p); };
	auto getx = [](auto &p) { return get<1>(p); };
	auto gety = [](auto &p) { return get<2>(p); };

	UnionFind s(N);
	sort(p.begin(), p.end(), [&](auto &a, auto &b) {
		return make_tuple(getx(a), gety(a)) < make_tuple(getx(b), gety(b));
	});
	for (int i = 0; i + 1 < N; ++i) {
		if (getx(p[i]) == getx(p[i + 1])) {
			s.unionSet(geti(p[i]), geti(p[i + 1]));
		}
	}

	sort(p.begin(), p.end(), [&](auto &a, auto &b) {
		return make_tuple(gety(a), getx(a)) < make_tuple(gety(b), getx(b));
	});
	for (int i = 0; i + 1 < N; ++i) {
		if (gety(p[i]) == gety(p[i + 1])) {
			s.unionSet(geti(p[i]), geti(p[i + 1]));
		}
	}

	map<int, vector<point>> g;

	sort(p.begin(), p.end());
	for (int i = 0; i < N; ++i) {
		g[s.root(i)].push_back(p[i]);
	}

	long long ans = 0;
	for (const auto &e : g) {
		set<int> x, y;
		for (auto &p : e.second) {
			x.insert(getx(p));
			y.insert(gety(p));
		}
		ans += 1LL * x.size()*  y.size() - e.second.size();
	}
	cout << ans << endl;
}

