//連結成分の深さを判定する
int saiki(int now,int dep)
{
	//cerr<<dep<<endl;
	int ret=dep;
	used[now]=true;
	if(now<1e5)
		vecx++;
	else
		vecy++;
	for(int i=0;i<g[now].size();i++)
	{
		Edge e=g[now][i];
		if(!used[e.to])
			ret=max(ret,saiki(e.to,dep+1));
	}
	return ret;
}

