class UnionFind{
public:
	vector<int> par;
	//0-indexed
	UnionFind(int n){init(n);}
	void init(int n = 1) {
		par.resize(n);
		for (int i = 0; i < n; ++i) par[i] = i;
	}
	int root(int x = 1){
		if(par[x]==x)return x;
		else{
			return par[x] = root(par[x]);
		}
	}
	void unite(int x = 1,int y = 1){
		x = root(x);
		y = root(y);
		if(x==y)return;
		else par[x] = y;
	}
	int setsize(){
		set<int> se;
		for(auto x:par){
			se.insert(root(x));
		}
		return se.size();
	}
};

int main(){
	ll N;
	cin >> N;
	vector<ll> x(N),y(N);
	FOR(i,0,N)cin>>x[i]>>y[i];
	UnionFind uf(N+1);
	map<ll,ll> ux,uy;
	FOR(i,0,N){
		if(ux[x[i]]!=0){
			uf.unite(ux[x[i]],i+1);
		}else{
			ux[x[i]] = i+1;
		}
		if(uy[y[i]]!=0){
			uf.unite(uy[y[i]],i+1);
		}else{
			uy[y[i]] = i+1;
		}
	}

	set<ll> lx[N+1],ly[N+1];
	FOR(i,0,N){
		lx[uf.root(i+1)].insert(x[i]);
		ly[uf.root(i+1)].insert(y[i]);
	}
	ll ans = 0;
	FOR(i,0,N+1){
		ans += lx[i].size()*ly[i].size();
	}
	cout << ans - N << endl;
}

