using namespace std;

using ll = long long;

struct DSU {
    vector<int> parent;
    vector<vector<int> > set_size;
    set<int> roots;
    int len;

    DSU() {}

    DSU(const int n, const int m) : len(n + m) { assign(n, m); }

    void assign(const int n, const int m) {
        parent.resize(len);
        set_size.assign(2, vector<int>(len, 0));
        // debug();
        fill(set_size[0].begin(), set_size[0].end() - m, 1);
        // debug();
        fill(set_size[1].begin() + n, set_size[1].end(), 1);
        // debug();
        iota(parent.begin(), parent.end(), 0);
        roots.insert(parent.begin(), parent.end());
    }

    bool check(const int a, const int b) { return root(a) == root(b); }

    int root(int x) {
        while (x != parent[x]) {
            x = parent[x] = parent[parent[x]];
        }
        return x;
    }

    int size() { return roots.size(); }

    ll size(const int i) { 
        const int r = root(i);
        return ll(set_size[0][r]) * set_size[1][r]; 
    }

    bool join(int a, int b) {
        a = root(a), b = root(b);

        if (a == b) {
            return false;
        }
        const int net_size_a = set_size[0][a] + set_size[1][a],
            net_size_b = set_size[0][b] + set_size[1][b];
        if (net_size_a < net_size_b) {
            swap(a, b);
        }

        roots.erase(b);
        set_size[0][a] += set_size[0][b];
        set_size[1][a] += set_size[1][b];
        parent[b] = a;
        return true;
    }

    void debug() {
        cerr << "Roots: ";
        for (int r : roots) {
            cerr << r << ' ';
        }
        cerr << '\n';

        cerr << "Sizes:\n";
        for (int i = 0; i < len; i++) {
            cerr << '(' << set_size[0][i] << ", " << set_size[1][i] << ")\n";
        }
    }
};

int main() {
    cin.tie(0);
    ios_base::sync_with_stdio(0);

    int n = 1e5, m = 1e5, q;
    cin >> q;
    DSU d(n, m);
    // d.debug();
    for (int i = 0; i < q; i++) {
        int x, y;
        cin >> x >> y;
        d.join(x - 1, n + y - 1);
        // d.debug();
    }
    ll res = 0;
    for (int r : d.roots) {
        res += d.size(r);
    }
    res -= q;
    cout << res << '\n';
}

