    xy[i].first--; xy[i].second--;
    xu[xy[i].first].push_back(i);
    yu[xy[i].second].push_back(i);
  }

  UnionFind uf(n);
  rep (i, M) {
    for (int j = 1; j < xu[i].size(); j++) {
      uf.unite(xu[i][j - 1], xu[i][j]);
    }
    for (int j = 1; j < yu[i].size(); j++) {
      uf.unite(yu[i][j - 1], yu[i][j]);
    }
  }

  vector<set<int> > x_st(uf.g), y_st(uf.g);
  rep (i, n) {
    int r = uf.find(i);
    x_st[r].insert(xy[i].first);
