struct UnionFind {
    int H, W;
    vector<int> par, rnk;
    vector<pii> cnt;

    UnionFind(int H, int W) : H(H), W(W) {
        int N = H + W;
        par.resize(N);
        rnk.resize(N);
        cnt.resize(N);
        for (int i = 0; i < N; ++i) {
            par[i] = i;
            if (i < H)
                cnt[i].first = 1;
            else
                cnt[i].second = 1;
        }
    }

    int root(int x) {
        return par[x] == x ? x : par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    void unite(int x, int y) {
        x = root(x), y = root(y);
        if (x == y)
            return;
        if (rnk[x] < rnk[y])
            swap(x, y);
        if (rnk[x] == rnk[y])
            rnk[x]++;
        par[y] = x;
        cnt[x] += cnt[y];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    cin >> N;
    UnionFind uf(100000, 100000);
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        x--, y--;
        x += 100000;
        uf.unite(x, y);
    }

    ll ans = 0;
    static bool seen[200000];
    for (int i = 0; i < 200000; ++i) {
        int rt = uf.root(i);
        if (!seen[rt]) {
            ans += (ll)uf.cnt[rt].first * uf.cnt[rt].second;
            seen[rt] = true;
        }
    }

    cout << ans - N << endl;

    return 0;
}

