	ios_base::sync_with_stdio(false);

	int N; cin >> N;
	VI x(N), y(N);
	map<int, int>xp;
	map<int, int>yp;
	UnionFind uf(N);
	FOR(i, 0, N) {
		cin >> x[i] >> y[i];
		if (xp.find(x[i]) == xp.end()) {
			xp[x[i]] = i;
		}
		else {
			uf.unionSet(i, xp[x[i]]);
		}
		if (yp.find(y[i]) == yp.end()) {
			yp[y[i]] = i;
		}
		else {
			uf.unionSet(i, yp[y[i]]);
		}
	}

	VVI comp(uf.allsz());
	map<LL, int>smap;
	map<LL, int>umap;
	int idpoint = 0;
	FOR(i, 0, N) {
		int r = uf.root(i);
		if (umap.find(r) == umap.end()) {
			umap[r] = idpoint++;
		}
	}
	FOR(i, 0, N) {
		smap[i] = umap[uf.root(i)];
	}
	FOR(i, 0, N) {
		comp[smap[i]].push_back(i);
	}
	auto solve = [&](vector<int> &a) {
