const int SIZE = 1e6+10;
struct Union_Find{
    int d[SIZE],num[SIZE],ll[SIZE],rr[SIZE];
    void init(int n){
        REP(i,n){
            d[i]=i,num[i]=1;
            if(i<=100000)ll[i]=1,rr[i]=0;
            else rr[i]=1,ll[i]=0;
        }
    }
    int find(int x){return (x!=d[x])?(d[x]=find(d[x])):x;}
    bool is_root(int x){return d[x]==x;}
    bool uu(int x,int y){
        x=find(x);
        y=find(y);
        if(x==y)return 0;
        if(num[x]>num[y])swap(x,y);
        ll[y]+=ll[x];
        rr[y]+=rr[x];
        num[y]+=num[x];
        d[x]=y;
        return 1;
    }
}U;
