typedef long long i64;

int main()
{
	const int MAX = 1e5;
	vector<vector<int>> g(2 * MAX);
	int n;

	scanf("%d", &n);
	for(int i = 0; i < n; i++) {
		int x, y;
		scanf("%d%d", &x, &y);
		x -= 1;
		y -= 1;
		g[x].push_back(MAX + y);
		g[MAX + y].push_back(x);
	}

	i64 ans = 0;
	vector<bool> visited(2 * MAX);

	for(int s = 0; s < 2 * MAX; s++) {

		if(visited[s]) {
			continue;
		}

		queue<int> q;
		int edges = 0;
		int x_vertices = 0, y_vertices = 0;

		q.push(s);

		while(!q.empty()) {

			int v = q.front();
			q.pop();

			if(visited[v]) {
				continue;
			}
			visited[v] = true;
			if(v < MAX) {
				x_vertices += 1;
			} else {
				y_vertices += 1;
			}

			for(auto& w : g[v]) {
				if(!visited[w]) {
					edges += 1;
				}
				q.push(w);
			}
		}

		ans += x_vertices * (i64)y_vertices - edges;
	}

	printf("%lld\n", ans);

	return 0;
}

