int uf_find(vector<int>& v, int a)
{
    if(v[a]==a) return a;
    return v[a]=uf_find(v,v[a]);
}

void uf_union(vector<int>& v, int a, int b)
{
    int ap=uf_find(v,a),bp=uf_find(v,b);
    if(ap==bp) return;
    v[max(ap,bp)]=min(ap,bp);
}

