struct UnionFind {
private :
    vector<int> data; int sz;
public :
    UnionFind(int sz) : data(sz, -1), sz(sz) { }

    bool unite(int x, int y) {
        if ((x = root(x)) == (y = root(y))) return false;
        if (data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        sz--;
        return true;
    }

    bool is_same(int x, int y) { return root(x) == root(y); }

    int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }

    size_t size(int x) { return (size_t)-data[root(x)]; }

    size_t size() { return (size_t)sz; }

};

constexpr int MAX = 100100;

int main() {
    int n;
    cin >> n;
    UnionFind uf(n);
    vector<int> x(n), y(n);
    vector<int> idx(MAX, -1), idy(MAX, -1);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        if (idx[x[i]] == -1) {
            idx[x[i]] = i;
        } else {
            uf.unite(i, idx[x[i]]);
        }
        if (idy[y[i]] == -1) {
            idy[y[i]] = i;
        } else {
            uf.unite(i, idy[y[i]]);
        }
    }

    vector<vector<int>> dx(n), dy(n);
    for (int i = 0; i < n; i++) {
        const int r = uf.root(i);
        dx[r].emplace_back(x[i]);
        dy[r].emplace_back(y[i]);
