int const inf = 1e9;

set<int> row[100010], col[100010];

struct Container {
    set<int> xx;
    set<int> yy;

    void update(int x, int y) {
        xx.insert(x);
        yy.insert(y);
    }
};

map<pair<int, int>, int> visited;

void dfs(int x, int y, Container &cont, int &counter) {
    if (abs(x) == inf || abs(y) == inf) return;
    if (visited.count({x, y})) return;
    cont.update(x, y);
    visited[{x, y}] = true;
    counter++;
    dfs(*row[y].upper_bound(x), y, cont, counter);
    dfs(*--row[y].lower_bound(x), y, cont, counter);
    dfs(x, *col[x].upper_bound(y), cont, counter);
    dfs(x, *--col[x].lower_bound(y), cont, counter);
}

void solve(long long N, std::vector<long long> x, std::vector<long long> y) {
    for (int i = 0; i < 100010; i++) {
        row[i].insert(-inf);
        row[i].insert(+inf);
        col[i].insert(-inf);
        col[i].insert(+inf);
    }
    for (int i = 0; i < N; i++) {
        row[y[i]].insert(x[i]);
        col[x[i]].insert(y[i]);
    }
    ll ans = 0;
    for (int i = 0; i < N; i++) {
        if (!visited.count({x[i], y[i]})) {
            auto c = Container();
            int counter = 0;

            dfs(x[i], y[i], c, counter);
            ans += 1ll * (c.xx.size()) * (c.yy.size()) - counter;
        }
    }
    cout << ans << endl;

}

