int root(ll i){
    while(par[i] != i){
        par[i] = par[par[i]];
        i = par[i];
    }
    return i;
}
void Union(int a , int b){
    int r_a = root(a);
    int r_b = root(b);
    if(X[r_a]+Y[r_a] > X[r_b] + Y[r_b])
        swap(r_a , r_b);
    par[r_a] = r_b;
    X[r_b] += X[r_a];
    Y[r_b] += Y[r_a];
}
