// size用
struct UnionFind {
    vector<ll> par;
    vector<ll> sizes;

    UnionFind(ll n) : par(n), sizes(n, 1) { REP(i, n) par[i] = i; }

    ll find(ll x) {
        if(x == par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(ll x, ll y) {
        x = find(x);
        y = find(y);

        if(x == y) return;

        if(sizes[x] < sizes[y]) swap(x, y);

        par[y] = x;
        sizes[x] += sizes[y];
        sizes[y] = 0;
    }

    bool same(ll x, ll y) { return find(x) == find(y); }

    ll size(ll x) { return sizes[find(x)]; }
};

signed main() {
    LCIN(N);
    VL x(N), y(N);
    REP(i, N) {
        cin >> x[i] >> y[i];
        x[i]--, y[i]--;
    }
    VL cx(x), cy(y);
    sort(All(cx)), sort(All(cy));
    cx.erase(unique(All(cx)), cx.end()), cy.erase(unique(All(cy)), cy.end());
    REP(i, N) {
        ll idx = lower_bound(All(cx), x[i]) - cx.begin();
        x[i] = idx;
        idx = lower_bound(All(cy), y[i]) - cy.begin();
        y[i] = idx;
    }
    ll sz = cx.size() + cy.size();
    UnionFind uf(sz);
    REP(i, N) uf.unite(x[i], y[i] + cx.size());
    VL xcnt(sz), ycnt(sz);
    REP(i, cx.size()) xcnt[uf.find(i)]++;
    REP(i, cy.size()) ycnt[uf.find(i + cx.size())]++;
    ll cnt = 0;
    REP(i, sz) { cnt += xcnt[i] * ycnt[i]; }
    cout << cnt - N << "\n";
}

