struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unite(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool same(int x, int y) { return root(x) == root(y); }
	int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
	int size(int x) { return -data[root(x)]; }
};

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll N;
	while(cin>>N) {
		ll MX = 100001;
		VI X(N), Y(N);
		VI LX(MX), LY(MX);
		UnionFind ux(MX), uy(MX);
		REP(i, N) cin>>X[i]>>Y[i];
		REP(i, N) {
			if(LX[X[i]]) {
				uy.unite(LX[X[i]], Y[i]);
//				cout<<"UNITE Y "<<LX[X[i]]<<" "<<Y[i]<<endl;
			}
			LX[X[i]]=Y[i];
			if(LY[Y[i]]) {
				ux.unite(LY[Y[i]], X[i]);
//				cout<<"UNITE X "<<LY[Y[i]]<<" "<<X[i]<<endl;
			}
			LY[Y[i]]=X[i];
		}
		VI visX(MX), visY(MX);
		ll ans = 0;
		REP(i, N) {
			if(!visX[ux.root(X[i])] || !visY[uy.root(Y[i])]) {
				visX[ux.root(X[i])]=1;
				visY[uy.root(Y[i])]=1;
//				cout<<"ADD "<<ux.size(X[i])<<" "<<uy.size(Y[i])<<endl;
				ans += ux.size(X[i]) * uy.size(Y[i]);
			}
		}
		ans -= N;

		cout<<ans<<endl;
//		break;
	}

	return 0;
}

