  vector<ll> x(n), y(n);
  // vector<vector<ll>> ys(100000 + 1);

  int inf = 100000 + 1;
  vector<ll> xc(inf * 2), yc(inf * 2);

  UF uf(inf * 2);

  for(int i = 0; i < n; i++) {
    cin >> x[i] >> y[i];
    // ys[x[i]].push_back(y[i]);
    uf.unite(x[i], inf + y[i]);
  }

  for(int i = 0; i < inf; i++) {
    xc[uf.find(i)]++;
  }

  for(int i = 0; i < inf; i++) {
    yc[uf.find(inf + i)]++;
  }

  for(int i = 0; i < inf + inf; i++) {
    if(uf.find(i) == i) {
      ans += xc[i] * yc[i];
    }
  }

  ans -= n;
  cout << ans << endl;

  return 0;
}

