struct UnionFind
{
   vector<int> parent, size;

   void init(int n){
      parent.resize(n+1);
      size.resize(n+1);

      for (int i = 1; i <= n; ++i)
      {
         parent[i] = i;
         size[i] = 1;
      }

   }

   int find(int x){

      while(x != parent[x]){
         parent[x] = parent[parent[x]];
         x = parent[x];
      }

      return x;
   }

   bool unite(int x, int y){
      x = find(x);
      y = find(y);
      if(x == y)
         return false;
      parent[y] = x;
      size[x] += size[y];
      return true;
   }

   int getSize(int x){
      x = find(x);
      return size[x];
   }

};

