// template

class UnionFind{
	vector<int> to;
	vector<int> cnt;
	vector<int> rank;

public:
	UnionFind(int N) {
		to = vector<int>(N); REP(i, N) to[i] = i;
		cnt = vector<int>(N, 1);
		rank = vector<int>(N, 1);
	}

	size_t size() {
		return to.size();
	}

	int root(int node) {
		if (node == to[node]) {
			return node;
		}
		to[node] = root(to[node]);
		return to[node];
	}

	int count(int node) {
		return cnt[root(node)];
	}

	int same(int a, int b) {
		return root(a) == root(b);
	}


	void unite(int a,int b){
		if (rank[a] < rank[b]) swap(a, b);
		int rootb = root(b), roota = root(a);
		to[rootb] = roota;
		cnt[roota] += cnt[rootb];
		if (rank[a] == rank[b]) ++rank[a];
	}
};

void DFS(int node, vector<vector<int> >& G, vector<bool>& check, vector<int>& res) {
	if (check[node]) {
		return;
	}
	check[node] = true;
	res.push_back(node);
	for (auto& to : G[node]) {
		DFS(to, G, check, res);
	}
}

void solve() {
	vector<vector<int>> xy(1e5+1);
	vector<vector<int>> yx(1e5+1);
	int N; cin >> N;
	vector<pii> ps;
	REP(i, N){
		int x, y; cin >> x >> y;
		ps.emplace_back(x, y);
	}

	unordered_set<int> xss;
	unordered_set<int> yss;
	for (auto& p : ps) {
		xy[p.first].push_back(p.second);
		yx[p.second].push_back(p.first);
		xss.insert(p.first);
		yss.insert(p.second);
	}

	vector<int> xs, ys;
	for (auto& a : xss) {
		xs.push_back(a);
	}
	for (auto& a : yss) {
		ys.push_back(a);
	}

	unordered_map<int, unordered_set<int> > GG(1e5+1);

	REP(i, N) {
		for (auto& y : ys) {
			int old = -1;
			for (auto& x : yx[y]) {
				if (old != -1) {
					GG[old].emplace(x);
					GG[x].emplace(old);
				}
				old = x;
			}
		}
	}

	vector<vector<int> > G(1e5+1);
	for (auto& gg : GG) {
		int from = gg.first;
		for (auto& to : gg.second) {
			G[from].emplace_back(to);
			G[to].emplace_back(from);
		}
	}

	vector<bool> check(1e5+1);
	int cnt = 0;
	for (auto& x : xs) if(not check[x]) {
		vector<int> res;
		DFS(x, G, check, res);

		unordered_set<int> se;
		for (auto& xx : res) {
			for (auto y : xy[xx]) {
				se.emplace(y);
			}
		}

		for (auto& xx : res) {
			cnt += se.size() - xy[xx].size();
		}
	}
	cout << cnt << endl;
}

