void dfs(int x){
    if(used[x] == 0){
        used[x] = 1;
        if(x < MXN){
            cnt1++;
        }else{
            cnt2++;
        }
        for(int i = 0; i < q[x].size(); i++){
            dfs(q[x][i]);
        }
    }
}

