    }
    LL ans = 0;
    for(int i = 0; i < 2*MAX_N; i++){
        ans += mx[i] * my[i];
    }
    cout << ans - N << endl;


}

#include <bits/stdc++.h>
using namespace std;

struct UnionFind {
    vector<int> par;
    vector<int> sz;

    UnionFind(int n=0){
        if(n>0) initialize(n);
    }

    void initialize(int n){
        par.resize(n);
        sz.resize(n);
        for(int i=0; i<n; i++){
            par[i] = i;
            sz[i] = 1;
        }
    }

    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            return par[x] = find(par[x]);
        }
    }

    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(sz[x] > sz[y]) swap(x, y);
        par[x] = y;
        sz[y] += sz[x];
        return true;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    int size(int x){
        return sz[find(x)];
    }
};

int main(){
    int N;
    cin >> N;
    vector<int> X(N), Y(N);
    map<int, vector<int>> xs, ys;
    for(int i=0; i<N; i++){
        cin >> X[i] >> Y[i];
        xs[X[i]].push_back(i);
        ys[Y[i]].push_back(i);
    }
    UnionFind uf(N);
    for(auto& p : xs){
        auto& v = p.second;
        for(int a : v) uf.unite(a, v[0]);
    }
    for(auto& p : ys){
        auto& v = p.second;
        for(int a : v) uf.unite(a, v[0]);
    }
    vector<set<int>> xst(N), yst(N);
    for(int i=0; i<N; i++){
        xst[uf.find(i)].insert(X[i]);
        yst[uf.find(i)].insert(Y[i]);
    }

    int64_t ans = -N;
    for(int i=0; i<N; i++){
        int64_t xsz = xst[i].size(), ysz = yst[i].size();
        ans += xsz * ysz;
    }
    cout << ans << endl;
}

