using namespace std;
using ll = long long;

class UnionFind {
public:
    // parent node index if not root index
    // minus size of the tree if root index
    std::vector<int> data;

    UnionFind( int n ) {
        data.resize( n, -1 );
    }

    int find( int x ) {
        if ( data[x] < 0 ) {
            return x;
        } else {
            int r = find( data[x] );
            data[x] = r;
            return r;
        }
    }

    void unite( int x, int y ) {
        int r = find( x );
        int s = find( y );
        if ( r != s ) {
            data[r] += data[s];
            data[s] = r;
        }
    }

    int count( int x ) {
        return -data[find(x)];
    }
};

template<typename T> int compress(vector<T>& x) {
    int n = x.size();
    vector<T> xs(n);
    for ( int i = 0; i < n; i++ ) xs[i] = x[i];
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    for ( int i = 0; i < n; i++ ) {
        x[i] = find(xs.begin(), xs.end(), x[i]) - xs.begin();
    }
    return xs.size();
}

int main() {
    int N;
    cin >> N;
    vector<int> X(N), Y(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> X[i] >> Y[i];
        X[i]--, Y[i]--;
    }
    compress(X);
    compress(Y);
    UnionFind uf(2 * N);
    for ( int i = 0; i < N; i++ ) {
        uf.unite(X[i], Y[i] + N);
    }

    map<int, int> nx, ny;
    for ( int i = 0; i < 2 * N; i++ ) {
        int r = uf.find(i);
        int c = uf.count(r);
        if ( c <= 1 ) continue;
        if ( i < N ) {
            nx[r]++;
        } else {
            ny[r]++;
        }
    }

    ll dots = 0;
    for( auto q : nx ) {
        dots += (ll)q.second * ny[q.first];
    }
    ll ans = dots - N;
    cout << ans << '\n';
    return 0;
}

