class unionFind {
public:
  vector<ll> data;

  unionFind(ll size) {
    data.assign(size, -1);
  }

  bool same(ll x, ll y) {
    return find(x)==find(y);
  }

  void unite(ll x, ll y) {
    x=find(x);
    y=find(y);
    if(x==y) return;
    if(data[x]>data[y]) swap(x, y);
    data[x]+=data[y];
    data[y]=x;
  }

  ll find(ll k) {
    if(data[k]<0) return k;
    return data[k]=find(data[k]);
  }

  ll size(ll k) {
    return -data[find(k)];
  }

};

int main(void) {
  ll i, j, k;
  ll N;
  cin >> N;

  unionFind uf=unionFind(MAX*2);

  for(i=0; i<N; i++) {
    ll x, y;
    cin >> x >> y;
    uf.unite(x, y+MAX);
  }

  map<ll, ll> mx, my;
  for(i=0; i<MAX; i++) mx[uf.find(i)]++;
  for(i=MAX; i<MAX*2; i++) my[uf.find(i)]++;

  ll ans=0;
  for(i=0; i<MAX*2; i++) ans+=mx[i]*my[i];
  ans-=N;
  pt(ans);

}

