int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);

    const long Size = 100000;
    int N; cin>>N;
    map<long, set<long>> graph;
    for (long i = 0; i < N; i++) {
        long x,y; cin>>x>>y;
        x--;y--;
        graph[x].insert(Size+y);
        graph[Size+y].insert(x);
    }

    set<long> node;
    long nx = 0, ny = 0;
    function<void(long)> find = [&](long p) {
        if (node.find(p) != node.end())
            return;
        node.insert(p);
        if (p < Size)
            nx++;
        else
            ny++;
        for (auto n : graph[p])
            find(n);
        return;
    };

    long ans = 0;
    for (size_t i = 0; i < Size*2; i++) {
        if (graph[i].empty() or node.find(i) != node.end())
            continue;
        find(i);
        ans += nx*ny-(nx+ny-1);
    }
    cout << ans << endl;


    return 0;
}

