struct UFS {
    vector<ll> data;
    UFS(ll N) : data(N) { rep(i, N) data[i] = -1; }
    def root(ll x) {
        if (data[x] < 0)
            return x;
        else
            return data[x] = root(data[x]);
    }
    def unite(ll x, ll y) {
        ll root_x = root(x), root_y = root(y);
        if (root_x != root_y) {
            if (data[root_x] > data[root_y]) swap(root_x, root_y);
            data[root_x] += data[root_y];
            data[root_y] = root_x;
            return true;
        }
        return false;
    }
    def same(ll x, ll y) { return root(x) == root(y); }
    def size(ll x) { return -data[root(x)]; }
};

signed main() {
    ll N;
    cin >> N;
    UFS uf(200001);
    ll X[N], Y[N], x[200001], y[200001], xi[100001], yi[100001], res = 0;
    rep(i, N) {
        cin >> X[i] >> Y[i];
        uf.unite(X[i], Y[i] + 100000);
        xi[X[i]]++, yi[Y[i]]++;
    }
    rep(i, 100000) {
        if (xi[i + 1]) x[uf.root(i + 1)]++;
        if (yi[i + 1]) y[uf.root(i + 1 + 100000)]++;
    }
    rep(i, 200001) res += x[i] * y[i];
    cout << res - N << endl;
}

