vi Gx[200010];
vi Gy[100010];
bool xb[100010];
bool yb[100010];

int edge, xnodes, ynodes;

void dfs(int i, bool ekkusu) {
    if (ekkusu) {
        rep(j, Gx[i].size()) {
            int y = Gx[i][j];
            if (yb[y])
                continue;
            edge++;
            ynodes++;
            yb[y] = true;
            dfs(y, false);
        }
    } else {
        rep(j, Gy[i].size()) {
            int x = Gy[i][j];
            if (xb[x])
                continue;
            edge++;
            xnodes++;
            xb[x] = true;
            dfs(x, true);
        }
    }
}

signed main() {
    int n;
    scanf("%lld", &n);
    rep(i, n) {
        int x, y;
        scanf("%lld%lld", &x, &y);
        Gx[x].pb(y);
        Gy[y].pb(x);
    }
    rep1(i, 100000) {
        xb[i] = false;
        yb[i] = false;
    }

    int ret = 0;
    rep1(i, 10000) {
        if (xb[i])
            continue;

        edge = 0;
        xnodes = 0;
        ynodes = 0;

        xnodes++;
        xb[i] = true;
        dfs(i, true);

        ret += xnodes * ynodes - edge;
    }

    printf("%lld\n", ret);

    /* --------------------------------- */
    return 0;
};

