using namespace std;


class UnionFind {
    vector<int> parents;

public:
    UnionFind(int N) : parents(N, -1) {}

    int find(int x) {
        if (this->parents[x] < 0)
            return x;
        return this->parents[x] = this->find(this->parents[x]);
    }

    int size(int x) {
        return -this->parents[this->find(x)];
    }

    void marge(int x, int y){
        x = this->find(x);
        y = this->find(y);
        if (x == y)
            return;
        if (this->parents[x] > this->parents[y])
            swap(this->parents[x], this->parents[y]);
        this->parents[x] += this->parents[y];
        this->parents[y] = x;
    }

    bool is_same(int x, int y) {
        return this->find(x) == this->find(y);
    }
};


int main(){
  int N;
  cin >> N;
  map<int, set<int>> A;
  for(int ii=0; ii<N; ii++){
    int x, y;
    cin >> x >> y;
    A[x].insert(y);
  }

  vector<set<int>> B;
  for(auto& a : A){
    B.push_back(a.second);
  }

  int num_B = B.size();
  UnionFind uf(num_B);
  long long int ans = 0;
  bool flg = true;
  while(flg){
    flg = false;
    for(int ii=0; ii<num_B; ii++){
      for(int jj=ii+1; jj<num_B; jj++){
        if(uf.is_same(ii, jj)){
          continue;
        }
        set<int> result1;
        set<int> result2;
        int p_ii = uf.find(ii);
        int p_jj = uf.find(jj);
        set_difference(
          B[p_ii].begin(), B[p_ii].end(),
          B[p_jj].begin(), B[p_jj].end(),
          inserter(result1, result1.end()));
        set_difference(
          B[p_jj].begin(), B[p_jj].end(),
          B[p_ii].begin(), B[p_ii].end(),
          inserter(result2, result2.end()));
        if(result1.size()==0 && result2.size()==0){
          uf.marge(p_ii, p_jj);
          continue;
        }
        if(B[p_ii].size() + B[p_jj].size() == result1.size() + result2.size()){
          continue;
        }
        flg=true;
        ans += result1.size() * uf.size(p_jj) + result2.size() * uf.size(p_ii);
        uf.marge(p_ii, p_jj);
        for(auto& c : result1){
          B[p_jj].insert(c);
        }
        B[p_ii] = B[p_jj];
      }
    }
  }
  cout << ans << endl;
  return 0;
}

