void Graph_func::read_edge()
{
	cin >> N_edge;
	N = 100000;
	edgelist.resize(N_edge);
	adjnumX.resize(N);
	adjnumY.resize(N);
	adjlistX.resize(N);
	adjlistY.resize(N);
	xE.resize(N);
	yE.resize(N);
	for (int i = 0; i < N; i++)
	{
		xE[i] = 0;
		yE[i] = 0;
	}
	for (int i = 0; i < N_edge; i++)
	{
		cin >> edgelist[i].first >> edgelist[i].second;
		if (graph_from1)
		{
			edgelist[i].first--;
			edgelist[i].second--;
		}
		xE[edgelist[i].first] = 1;
		yE[edgelist[i].second] = 1;
	}
	return;
}

void Graph_func::adjini()
{
	for (int i = 0; i < N; i++)
	{
		adjnumX[i] = 0;
	}
	for (int i = 0; i < N; i++)
	{
		adjnumY[i] = 0;
	}
	for (int i = 0; i < N_edge; i++)
	{
		int x = edgelist[i].first;
		int y = edgelist[i].second;
		adjlistX[x].push_back(y);
		adjlistY[y].push_back(x);
		adjnumX[x]++;
		adjnumY[y]++;
	}
	return;
}

void Graph_func::graph_num_sbrtX(int x) // ex. graph_num_sbrt(i, filled);
{
	for (int i = 0; i < adjnumX[x]; i++)
	{
		int x_new = adjlistX[x][i];
		if (!yE[x_new])
		{
			yE[x_new] = true;
			graph_num_sbrtY(x_new);
			ytmp++;
		}
	}
	return;
}

void Graph_func::graph_num_sbrtY(int x) // ex. graph_num_sbrt(i, filled);
{
	for (int i = 0; i < adjnumY[x]; i++)
	{
		int x_new = adjlistY[x][i];
		if (!xE[x_new])
		{
			xE[x_new] = true;
			graph_num_sbrtX(x_new);
			xtmp++;
		}
	}
	return;
}

int Graph_func::graph_num()
{
	int anstmp = 0;
	int i = 0;
	bool end = false;
	while (!end)
	{
		if (i >= N)
			break;
		while (1)
		{
			if (!xE[i])
				break;
			i++;
			if (i >= N)
			{
				end = true;
				break;
			}
		}
		if (end)
			break;
		xE[i] = true;
		xtmp = 1;
		ytmp = 0;
		graph_num_sbrtX(i);
		anstmp += xtmp * ytmp;
	}
	return anstmp;
}

