struct union_find {
  std::vector<int> par, rank;

  explicit union_find(int n): par(n), rank(n,0) {
    std::iota(par.begin(), par.end(), 0);
  }

  int find(int x) {
    if(par[x] == x) return x;
    return par[x] = find(par[x]);
  }

  void unite(int x, int y) {
    x = find(x); y = find(y);
    if(x == y) return;
    if(rank[x] < rank[y]) par[x] = y;
    else {
      par[y] = x;
      if(rank[x] == rank[y]) ++rank[x];
    }
  }
};


int main() {
