  for(auto &v: m) {
    std::sort(v.second.begin(), v.second.end());
    vv.emplace_back(std::move(v.second));
  }
  union_find uf(vv.size());
  for(int y: sy) {
    int iy = -1;
    for(int i = 0; i < vv.size(); ++i) {
      if(!std::binary_search(vv[i].begin(), vv[i].end(), y)) continue;
