ll search_x(const ll, ll&, ll&);
ll search_y(const ll, ll&, ll&);

vvll xPath(L_MAX), yPath(L_MAX);
vb x_flag(L_MAX, true), y_flag(L_MAX, true);

ll search_x(const ll y, ll& x_kind, ll& y_kind){
  ll ans = 0;
  if(!y_flag[y]) return ans;
  y_flag[y] = false;
  y_kind++;
  ans++;

  REP(i,yPath[y].size()){
    ans += search_y(yPath[y][i], x_kind, y_kind);
  }
  return ans;
}

ll search_y(const ll x, ll& x_kind, ll& y_kind){
  ll ans = 0;
  if(!x_flag[x]) return ans;
  x_flag[x] = false;
  x_kind++;
  ans++;

  REP(i,xPath[x].size()){
    ans += search_x(xPath[x][i], x_kind, y_kind);
  }
  return ans;
}

