class UnionFind
{
public:
  vector<long long> par;

  UnionFind(int n) : par(n, -1) {}
  void init(int n)
  {
    par.assign(n, -1);
  }

  int root(int x)
  {
    if (par[x] < 0)
    {
      return x;
    }
    return par[x] = root(par[x]);
  }

  bool is_same(int x, int y)
  {
    return root(x) == root(y);
  }

  bool merge(int x, int y)
  {
    x = root(x);
    y = root(y);
    if (x == y)
    {
      return false;
    }
    if (par[x] > par[y])
    {
      swap(x, y);
    }
    par[x] += par[y];
    par[y] = x;
    return true;
  }

  long long size(int x)
  {
    return -par[root(x)];
  }
};

int N;
int x[100010];
int y[100010];
bool visited[100010];

vector<int> X[100010];
vector<int> Y[100010];

set<int> used_x;
set<int> used_y;

void add_point(int P, UnionFind &uf, int k)
{
  visited[P] = true;
  used_x.insert(x[P]);
  used_y.insert(y[P]);
  if (k == 0)
  {
    for (auto e : X[x[P]])
    {
      if (!visited[e])
      {
        uf.merge(P, e);
        add_point(e, uf, 1);
      }
    }
  }
  else if (k == 1)
  {
    for (auto e : Y[y[P]])
    {
      if (!visited[e])
      {
        uf.merge(P, e);
        add_point(e, uf, 0);
      }
    }
  }
}

ll solve(int P)
{
#if DEBUG == 1
  cerr << "solve(" << P << ")" << endl;
#endif
  used_x.clear();
  used_y.clear();
  UnionFind uf(N);
  add_point(P, uf, 0);
  add_point(P, uf, 1);
  ll s = uf.size(P);
  ll a = 0, b = 0;
  a = used_x.size();
  b = used_y.size();
#if DEBUG == 1
  cerr << "a = " << a << ", b = " << b << ", s = " << s << endl;
#endif
  return a * b - s;
}

