struct vu_t
{
	int n;
	int p;
	vi c;
	vu_t(int idx=-1) : n(1),p(idx) {}
};


void vu_cat(vector<vu_t>&vu, int a, int b)
{
	int ap=vu[a].p;
	int bp=vu[b].p;

	if(ap==bp) return;
	if(vu[ap].n<vu[bp].n) swap(ap, bp);
	vu[ap].n+=vu[bp].n;
	vu[ap].c.push_back(bp);
	for(auto mb:vu[bp].c)
	{
		vu[mb].p=ap;
		vu[ap].c.push_back(mb);
	}
	vu[bp].n=0;
	vu[bp].p=ap;
	vu[bp].c.clear();
}


ll vu_calc(vpii&xy, vector<vu_t>&vu, int idx)
{
	set<int> sx, sy;
	int p=vu[idx].p;

	sx.insert(xy[p].first);
	sy.insert(xy[p].second);
	for(auto&mc:vu[p].c)
	{
		sx.insert(xy[mc].first);
		sy.insert(xy[mc].second);
	}
	return sx.size()*sy.size()-vu[p].n;
}


