	if (itrY1->first == itrY2->first)
	  continue;

	set<uint32_t> union_set;
	set_union(itrY1->second.begin(), itrY1->second.end(),
		  itrY2->second.begin(), itrY2->second.end(),
		  inserter(union_set, union_set.end()));
	set<uint32_t> intersection_set;
	set_intersection(itrY1->second.begin(), itrY1->second.end(),
			 itrY2->second.begin(), itrY2->second.end(),
			 inserter(intersection_set, intersection_set.end()));
	if (intersection_set.size() == 0)
	  continue;

	itrY1->second = union_set;
	itrY2->second = union_set;
	for (uint32_t x : union_set) {
	  pointsX[x].insert(itrY1->first);
	  pointsX[x].insert(itrY2->first);
	}
      }
    }

    uint64_t new_count = 0;
    for (auto X : pointsX)
      new_count += X.second.size();

    if (count == new_count)
      break;
    count = new_count;
  }

  cout << count-N << endl;

  return 0;
}

