class Solution {
private:
    vector<int> fa;
    int find(int x) {
        return fa[x] == x ? x : fa[x] = find(fa[x]);
    }
    void merge(int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx != ry) {
            fa[rx] = ry;
        }
    }
    void init(int len) {
        for (int i = 0; i < len; ++i) {
            fa.push_back(i);
        }
    }
public:
    ll solve() {
        int N;
        cin >> N;
        int K = 100000;
        int len = 2 * K + 2;
        init(len);

        for (int i = 0; i < N; ++i) {
            int x, y;
            cin >> x >> y;
            merge(x, y + K);
        }
        ll sum = 0;
        vector<int> resx(len);
        vector<int> resy(len);
        for (int i = 1; i <= K; ++i) {
            int r = find(i);
            resx[r]++;
        }
        for (int i = K+1; i < len; ++i) {
            int r = find(i);
            resy[r]++;
        }
        for (int i = 1; i < len; ++i) sum += resx[i] * resy[i];
        return sum - N;
    }
};

int main(int argc, const char * argv[]) {
    Solution obj;
    cout << obj.solve() << endl;
    return 0;
}

