int64 dfs(int64 x, int64 y) {
  if (visited[PLL(x, y)]) return 0;
  visited[PLL(x, y)] = 1;
  int64 cnt = 1;
  if (!vx[x]) {
    cx_v++;
    vx[x] = 1;
  }
  if (!vy[y]) {
    cy_v++;
    vy[y] = 1;
  }
  int64 yy = *cx[x].begin();
  while (1) {
    auto itr = cx[x].lower_bound(yy);
    if (itr == cx[x].end()) break;
    yy = *itr;
    cx[x].erase(yy);
    cnt += dfs(x, yy);
  }
  int64 xx = *cy[y].begin();
  while (1) {
    auto itr = cy[y].lower_bound(xx);
    if (itr == cy[y].end()) break;
    xx = *itr;
    cy[y].erase(xx);
    cnt += dfs(xx, y);
  }
  return cnt;
}

