struct UnionFind {
    private:
    vector<ll> par,rank;
    vector<ll> Size;
    public:
    UnionFind(ll n){
        par.resize(n);
        rank.resize(n,0);
        Size.resize(n,1);
        rep(i,n){
            par[i]=i;
        }
    }
    ll root(ll x){
        if (par[x]==x){
            return x;
        }
        return par[x]=root(par[x]);
    }
    bool merge(ll x, ll y){
        x=root(x);
        y=root(y);
        if (x==y){
            return false;
        }
        if (rank[x]<rank[y]){
            swap(x,y);
        }
        if (rank[x]==rank[y]){
            ++rank[x];
        }
        par[y]=x;
        Size[x]+=Size[y];
        return true;
    }
    bool same(ll x, ll y){
        return root(x)==root(y);
    }
    ll size(ll x){
        return Size[root(x)];
    }
};

