//UnionFind
class UnionFind {
private:
    vector<int> par;
    vector<pair<int, int>> siz;
public:
    UnionFind(int n, int m) {
        par.resize(n + m, -1);
        siz.resize(n + m);
        fill(siz.begin(), siz.begin() + n, pair<int, int>(1, 0));
        fill(siz.begin() + n, siz.end(), pair<int, int>(0, 1));
    }

    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }

    bool unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return false;
        if (size(rx) < size(ry)) swap(rx, ry);
        par[rx] += par[ry];
        siz[rx].first += siz[ry].first;
        siz[rx].second += siz[ry].second;
        par[ry] = rx;
        return true;
    }

    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int size(int x) {
        return -par[root(x)];
    }

    int xsize(int x) {
        return siz[root(x)].first;
    }

    int ysize(int x) {
        return siz[root(x)].second;
    }
};

int main() {
    int N; input(N);
    UnionFind uni(1e5, 1e5);
    vector<bool> visited(2 * 1e5, false);
    REP(i, N) {
        int x, y; input(x, y);
        x--; y--;
        uni.unite(x, y + 1e5);
    }
    ll cnt = 0;
    REP(i, 2 * 1e5) {
        if (visited[uni.root(i)]) continue;
        visited[uni.root(i)] = true;
        cnt += (ll)uni.xsize(uni.root(i)) * uni.ysize(uni.root(i));
    }
    cout << cnt - N << endl;
    getchar(); getchar();
}

