struct uf{
    int N;
    vector<int> p;
    vector<int> s;

    uf(int n){
        N = n+1;
        p.assign(N,0);
        s.assign(N,1);
        Rep(i,N) p[i] = i;
    }

    int root(int x ){
        while( p[x] != x ){
            x = p[x] = p[p[x]];
        }
        return x;
    }

    void unite( int a, int b ){
        a = root(a);
        b = root(b);
        if( s[a] < s[b] ) swap(a,b);
        s[a] += s[b];
        p[b] = a;
    }

    bool same(int a, int b ){
        return root(a) == root(b);
    }

    ll size( int x ){
        return (ll)s[root(x)];
    }

};

int main() {

    int N;
    Scd(N);
    using pii = pair<int,int>;
    vector<pii> a(N);

    int x,y;
    map<int,int> zipx;
    map<int,int> zipy;
    Rep(i,N){
        Scd2(x,y);
        a[i] = pii(x,y);
        zipx[x] = 0;
        zipy[y] = 0;
    }

    uf u(N);

    int ind = 0;
    for( auto it = zipx.begin(); it != zipx.end(); it++ ){
        it->second = ind++;
    }
    ind = 0;
    for( auto it = zipy.begin(); it != zipy.end(); it++ ){
        it->second = ind++;
    }

    sort(a.begin(),a.end());

    int tx = -1;
    int ty = -1;
    Rep(i,N){
        int ttx = zipx[a[i].first];
        int tty = zipy[a[i].second];
        if( tx == ttx ) u.unite(ty, tty);
        tx = ttx;
        ty = tty;
    }

    ll ans = 0;
    Rep(i,N){
        int ttx = zipx[a[i].first];
        int tty = zipy[a[i].second];
        if( tx != ttx ) ans += u.size(tty);
        tx = ttx;
    }

    ans -= N;
    printf ("%llu\n", ans );

    return 0;
}

