  for (int i = 0; i < n; i++) {
    int u, v;
    cin >> u >> v;
    u--;
    v--;
    v += 1e5;
    G[u].emplace_back(v);
    G[v].emplace_back(u); // 有向グラフではコメントアウト
  }

  for (int i = 0; i < 1e5; i++) {
    if (color[i] == 0) {
      set<pair<int, int>> s;
      ll x = 0, y = 0;
      dfs(G, s, i, x, y);
    }
  }

  cout << ans << '\n';
}

