struct UnionFind {
  int sz;
  vector<int> par;
  vector<pair<int, int>> cnt;
  UnionFind(int sz) {
    this->sz = sz;
    par.clear();
    par.resize(2 * sz);
    cnt.clear();
    cnt.resize(2 * sz);
    for(int i=0;i<sz;++i) {
      par[i] = i;
      par[sz+i] = sz+i;
      cnt[i] = {1, 0};
      cnt[sz+i] = {0, 1};
    }
  }
  int root(int x) {
    return par[x] == x ? x : par[x] = root(par[x]);
  }
  void unite(int x, int y) {
    int rootx = root(x), rooty = root(y);
    int cntxf = cnt[rootx].first, cntxs = cnt[rootx].second, cntyf = cnt[rooty].first, cntys = cnt[rooty].second;
    if(cntxf + cntxs < cntyf + cntys) {
      swap(rootx, rooty);
    }
    cnt[rootx] = {cntxf + cntyf, cntxs + cntys};
    par[rooty] = rootx;
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int sizex(int x) {
    return cnt[root(x)].first;
  }
  int sizey(int x) {
    return cnt[root(x)].second;
  }
};
int main() {
  cin.tie(0);
  cout << fixed << setprecision(10);
  int n; cin >> n;
  int sz = 100000;
  UnionFind uf(sz);
  for(int i=0;i<n;++i) {
    int x, y; cin >> x >> y;
    x--; y--;
    uf.unite(x, y + sz);
  }
  vector<bool> sel(2 * sz);
  ll ans = 0;
  for(int i=0;i<sz;++i) {
    int root = uf.root(i);
    if(!sel[root]) {
      sel[root] = true;
      ll szx = uf.sizex(root), szy = uf.sizey(root);
      ans += szx * szy;
    }
  }
  cout << ans - n << endl;
}

