        }
    }
    bool used[maxn] = {};
    ll res = 0;
    for(int i = 0; i < n; i++){
        if(used[fset(i)])
            continue;
        res += X[fset(i)].size() * Y[fset(i)].size();
        used[fset(i)] = 1;
    }
    cout << res - n;
}

