        if(l == u) uf.merge(k, g);
    }

    sort(A, A + n, [](piii& r, piii& t) -> bool {
        int u, v, h, l, g, f;
        tie(u, v, h) = r;
        tie(l, g, f) = t;
        return v < g;
    });

    for(int i = 1; i < n; ++i) {
        int l, g, f, k;
        tie(u, v, k) = A[i];
        tie(l, f, g) = A[i - 1];
        if(v == f) uf.merge(k, g);
    }

    set <int> xA[20000], yA[20000];

    for(int i = 0; i < n; ++i) {
        int h;
        tie(u, v, h) = A[i];
        xA[uf.root(h)].insert(u);
        yA[uf.root(h)].insert(v);
        B[uf.root(h)] += 1;
    }

    ll mx = 0;
    for(int i = 0; i < n; ++i) {
      	ll nx = (ll) xA[i].size() * yA[i].size();
      	nx -= B[i];
        mx += max(nx, 0LL);
    }

    cout << mx;

    return 0;
}

