class UnionFind {
private:
	Vec< int > data;
	int num_of_g;

public:
	UnionFind(int n) : data(n, -1), num_of_g(n) {}

	bool unionSet(int x, int y) {
		x = root(x); y = root(y);

		if (x == y) return 0;

		if (data[y] < data[x]) swap(x, y);
		data[x] += data[y]; data[y] = x;
		--num_of_g;

		return 1;
	}

	bool sameSet(int x, int y) { return root(x) == root(y); }
	int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
	int size(int x) { return -data[root(x)]; }
	int getNumOfG() { return num_of_g; }
};

const int MAX_X = 100005;

int main() {
	int N;
	cin >> N;

	Vec< int > x(N), y(N);
	Vec< Vec< int > > px(MAX_X, Vec< int >());
	Vec< Vec< int > > py(MAX_X, Vec< int >());

	for_(i,0,N) {
		cin >> x[i] >> y[i];
		px[x[i]].push_back(i);
		py[y[i]].push_back(i);
	}

	UnionFind uf(N);
	for (int i=0; i<MAX_X; ++i) {
		int m = px[i].size();
		for (int j=0; j<m-1; ++j) uf.unionSet(px[i][j], px[i][j+1]);
		m = py[i].size();
		for (int j=0; j<m-1; ++j) uf.unionSet(py[i][j], py[i][j+1]);
	}

	Vec< Vec< int > > group(N, Vec< int >());
	for (int i=0; i<N; ++i) group[uf.root(i)].push_back(i);

	lint ans = 0;
	for (int g=0; g<N; ++g) {
		if (group[g].empty()) continue;
		bool flag = false;
		for (int i : group[g]) flag |= (px[x[i]].size() > 1 && py[y[i]].size() > 1);
		if (flag) {
			set< int > x_set, y_set;
			for (int i : group[g]) {
				x_set.insert(x[i]);
				y_set.insert(y[i]);
			}
			ans += (x_set.size() * y_set.size()) - group[g].size();
		}
	}
	cout << ans << endl;
}
