int main() {
    int n;
    cin >> n;
    unordered_map<int, vector<int> > es;
    unordered_set<int> rem;
    for (int j = 0; j < n; j++) {
        int x, y;
        cin >> x >> y;
        x--;
        y += B - 1;
        es[x].push_back(y);
        es[y].push_back(x);
        rem.insert(x);
        rem.insert(y);
    }
    long ans = -n;
    for (auto p: es) {
        if (rem.empty())
            break;
        if (rem.find(p.first) == rem.end())
            continue;
        long x_count = 0, y_count = 0;
        stack<int> dfs;
        dfs.push(p.first);
        while (!dfs.empty()) {
            int t = dfs.top();
            dfs.pop();
            if (rem.find(t) == rem.end())
                continue;
            rem.erase(t);
            if (t < B) {
                x_count++;
            } else {
                y_count++;
            }
            for (int v: es[t]) {
                dfs.push(v);
            }
        }
        ans += x_count * y_count;
    }
    cout << ans << endl;
    return 0;
}

