        edges[x].push_back(MAXN + y);
        edges[MAXN + y].push_back(x);
    }

    int ret = 0;
    vector<bool> used(2 * MAXN, false);
    for (int i = 0; i < 2 * MAXN; i++) {
        if (used[i])
            continue;

        vector<int> here;
        dfs(i, edges, used, here);

        int x = 0;
        int y = 0;
        int e = 0;
        for (int i : here) {
            if (i < MAXN)
                x++;
            else
                y++;
            e += edges[i].size();
        }

        e /= 2;

        ret += (x * y) - e;
    }

    cout << ret << endl;

    return 0;
}





