			int u = yid[i][j];
			int v = yid[i][j + 1];
			et[u].push_back(v);
			et[v].push_back(u);
		}
	}

	rep(i, n) { label[i] = -1; }

	int lcnt = 0;
	rep(i, n) {
		if (label[i] != -1) continue;
		label[i] = lcnt;

		queue<int> que;
		que.push(i);
		while (!que.empty()) {
			int v = que.front(); que.pop();
			rep(j, et[v].size()) {
				int nv = et[v][j];
				if (label[nv] == -1) {
					label[nv] = lcnt;
					que.push(nv);
				}
			}
		}
		lcnt++;
	}

	ids.resize(lcnt);
	rep(i, n) {
		ids[label[i]].push_back(i);
	}

	int sumCnt = 0;
	rep(i, ids.size()) {
		sumCnt += calc(ids[i]);
	}
	cout << sumCnt - n << endl;
	return 0;
}

