const ll M=2*N+2;
ll id[M];
ll sz[M];
vector<pll>pt;


void ini()
{
    for(ll i=0;i<M;i++)
    {
        id[i]=i;
        sz[i]=1;
    }
    return;
}

ll rt(ll x)
{
    while(x!=id[x])
    {
        id[x]=id[id[x]];
        x=id[x];
    }
    return x;
}

void merg(ll x,ll y)
{
    ll rtx=rt(x);
    ll rty=rt(y);
    if(rtx==rty)return;
    if(sz[rtx]>sz[rty])
		swap(rtx, rty);

	sz[rty]+=sz[rtx];
	sz[rtx]=0;
	id[rtx]=id[rty];
	return ;
}

int main()
{
    IOS
    ini();
    ll n;
    cin>>n;
    for(ll i=0;i<n;i++)
    {
        ll x,y;
        cin>>x>>y;
        pt.pb({x,y});
        merg(x,y+N);
    }
    map<ll,set<ll> >X;
    map<ll,set<ll> >Y;
    for(ll i=0;i<n;i++)
    {
        X[rt(pt[i].first)].insert(pt[i].first);
        Y[rt(pt[i].first)].insert(pt[i].second);
    }
    ll ans=0;
    for(auto it=X.begin();it!=X.end();it++)
    {
        ll fnl=(*it).first;
        ll rows=(*it).second.size();
        ll cols=(*Y.find(fnl)).second.size();
        ans+=(rows*cols);
    }
    cout<<ans-n<<endl;
    return 0;
}

