const int V_MAX = 1e5;

vector<int> G[V_MAX];

void add_edge(int u, int v) {
  G[u].push_back(v);
  G[v].push_back(u);
}

//------------------------------------------------------------------------------
const int N_MAX = 1e5;
const int X_I_MAX = 1e5;
const int Y_I_MAX = 1e5;

struct P { int id, x, y; };
int N;
P ps[N_MAX];

bool used[V_MAX];
ll cnt;
set<int> xst;
set<int> yst;

bool compare_x_asc_y_asc(const P& p1, const P& p2) {
  if (p1.x != p2.x) return p1.x < p2.x;
  return p1.y < p2.y;
}

bool compare_y_asc_x_asc(const P& p1, const P& p2) {
  if (p1.y != p2.y) return p1.y < p2.y;
  return p1.x < p2.x;
}

bool compare_id_asc(const P& p1, const P& p2) {
  return p1.id < p2.id;
}

void dfs2(int p, int v) {
  used[v] = true;
  cnt++;
  xst.insert(ps[v].x);
  yst.insert(ps[v].y);
  for (int u : G[v]) {
    if (u == p) continue;
    if (used[u]) continue;
    dfs2(v, u);
  }
}

ll dfs(int v) {
  cnt = 0;
  xst.clear();
  yst.clear();
  dfs2(-1, v);
  if (xst.size() > 1 && yst.size() > 1) {
    return (ll) xst.size() * (ll) yst.size() - cnt;
  } else {
    return 0;
  }
}

void solve() {
  sort(ps, ps + N, compare_x_asc_y_asc);
  REP(i, N - 1) if (ps[i].x == ps[i + 1].x) add_edge(ps[i].id, ps[i + 1].id);
  sort(ps, ps + N, compare_y_asc_x_asc);
  REP(i, N - 1) if (ps[i].y == ps[i + 1].y) add_edge(ps[i].id, ps[i + 1].id);
  sort(ps, ps + N, compare_id_asc);

  ll ans = 0;
  REP(v, N) {
    if (used[v]) continue;
    ans += dfs(v);
  }
  printf("%lld\n", ans);
}

void input() {
  scanf("%d", &N);
  REP(i, N) {
    int x, y;
    scanf("%d%d", &x, &y);
    ps[i] = { i, x, y };
  }
}

int main() {
  input();
  solve();
  return 0;
}

