    // combine a <- b
    if(sa < sb)swap(pa, pb);
    for(int x : sx[pb]){
        sx[pa].insert(x);
    }
    for(int x : sy[pb]){
        sy[pa].insert(x);
    }
    sz[pa] += sz[pb];
    p[pb] = pa;
}

