        if(i > 0 && x[id] == pts[i-1].F){ // combine x
            combine(id, pts[i-1].S);
        }
    }

    ll ans = 0;
    REP(i,1,n){
        if(i == cek(i)){
            // printf("lead %d, sx %d, sy %d, size %d\n",i, sx[i].size(), sy[i].size(), sz[i]);
            ans += (ll)sx[i].size() * sy[i].size() - sz[i];
        }
    }
