	scanf("%d%d", X+i, Y+i);
	vx[X[i]].push_back(i);
	vy[Y[i]].push_back(i);

	U.link(X[i], SIZE + Y[i]);
    }

    REP (i, SIZE) {
	EACH (e, vx[i]) U.link(SIZE+Y[vx[i][0]], SIZE+Y[*e]);
	EACH (e, vy[i]) U.link(X[vy[i][0]], X[*e]);
    }

    REP (i, N) {
	cnt[U.root(X[i])]++;
    }
    REP (i, SIZE) {
	if (vx[i].size()) xc[U.root(X[vx[i][0]])]++;
	if (vy[i].size()) yc[U.root(X[vy[i][0]])]++;
    }

