/*
 * Given a set of points on x,y plane. If there are 3 points form 3
 * corners of a rectangle, and the 4-th corner is missing a point, we
 * add a point at the 4-th corner position. The newly add point becomes
 * available for further operation, Ask how many points we can by doing
 * this repeatedly.
 */
/*
 *   |              There are 4 points initially. We can add 2 more
 * 3[x]-[ ]-[1]     points.
 *   |   |   |
 * 2[2]-[ ]-[x]     Create a bipartite G w/ x as left and y as right.
 *   |   |   |      1-1,1-3, 3-1,3-2
 * 1[x]-[ ]-[x]-
 *   1   2   3      Let x be the times we visit the left side, and y
 *                  be times we visit the right side. The total number
 * points can be created is x*y. The number of points we can add is
 * x-n where n is the number of initial points.
 *
 * R3-L1-R1-L3-R2 <=> (1,3)-(1,1)-(3,1)-(3,2)
 * left count x = 2; right count y = 3; n = 4; 2*3-4 = 2
 */

const int maxv = 1e5+5;
int vis[2*maxv], cnt[2]; VI G[2*maxv];

void dfs(const int u)
{
    vis[u]++; cnt[u/maxv]++;
    FOR_ALL(v,G[u]) if (!vis[*v])
        dfs(*v);
}

int main()
{
#ifdef foo_
    freopen("foo", "rt", stdin);
#endif
    ios::sync_with_stdio(false);
    int n;
    while (cin >> n) {
        FOR(i,0,SZ(G))
            G[i].clear();
        memset(vis,0,sizeof(vis));
        FOR(i,0,n) {
            int x,y; cin >> x >> y;
            y += maxv;
            G[x].push_back(y);
            G[y].push_back(x);
        }
        LL ans = 0;
        FOR(i,0,2*maxv) if (!vis[i]) {
            memset(cnt,0,sizeof(cnt));
            dfs(i);
            ans += 1LL*cnt[0]*cnt[1];
        }
        ans -= n;
        cout << ans << endl;
    }
    return 0;
}

