ll fp(ll x)
{
       while(par[x]!=x)
       {
              par[x]=par[par[x]];
              x=par[x];
       }
       return x;
}

void union1(ll x, ll y)
{
       ll parx=fp(x); // parx = root node of the component in which x is located
       ll pary=fp(y);
       if(parx==pary) return;
       if(urank[parx] <= urank[par[y]])
       {
              par[parx]=pary;
              urank[pary] += urank[parx];
       }
       else
       {
              par[pary]=parx;
              urank[parx] +=  urank[pary];
       }
}

