void solve()
{
       ll n;
       cin>>n;
       rep(i,1,N) create(i); // all points have rank 1 and root set to themselves
       rep(i,1,n+1)
       {
              ll x,y; cin>>x>>y;
              s1[y].insert(x); // x co-ordinates of points lying at y-coordinate = y
              s2[x].insert(y); // y                                 x              x
       }
