       {
              if(s1[i].size() <= 1) continue; // single isolated point, no other point in x or y dirn, or point not even there
              auto it1 = s1[i].begin();       // s1[i] - set of x coordinates of points having same y coordinate
              auto it2 = s1[i].begin();       // it1 - beginning, it2 - next point
              it2++;
              while(it2 != s1[i].end())
              {
                     union1(*it2, *it1);  // merge them .... setting root of the points to a single point in the y level and rank of that level ...
                     it1++;
                     it2++;
              }
       }
       rep(i,1,N)
