//! graphは基本クラス！使うときはundirected_graphかdirected_graphを使う。
template <class Info>
class graph {
   protected:
    using edge_type = edge<Info>;
    ::std::size_t N;
    ::std::vector<::std::vector<edge_type>> edges;

   public:
    graph(::std::size_t N_) : N(N_), edges(N_) {}
    virtual void add_edge(int x, int y, Info info = static_cast<Info>(1)) = 0;
    const ::std::vector<edge_type> &delta(int v) const {
        assert(v < N);
        return edges[v];
    }
    const ::std::vector<edge_type> &operator[](int v) const {
        return this->delta(v);
    }
    ::std::size_t size() const { return N; }
};

template <class Info>
class undirected_graph : public graph<Info> {
   public:
    undirected_graph(::std::size_t N) : graph<Info>(N) {}
    void add_edge(int x, int y, Info info = static_cast<Info>(1)) {
        this->edges[x].push_back(edge<Info>(x, y, info));
        this->edges[y].push_back(edge<Info>(y, x, info));
    }
};

template <class Info>
class directed_graph : public graph<Info> {
   public:
    directed_graph(::std::size_t N) : graph<Info>(N) {}
    void add_edge(int x, int y, Info info = static_cast<Info>(1)) {
        this->edges[x].push_back(edge<Info>(x, y, info));
    }
};

template <class Info>
struct bipartite_graph : public undirected_graph<Info> {
    ::std::size_t A;
    ::std::size_t B;

    /* UnionFind */
    template <typename T>
    struct UnionFind {
        vector<T> data;
        stack<pair<int, T>> history;

        UnionFind() = default;
        UnionFind(int sz) { data.assign(sz, -1); }

        bool unite(int x, int y) {
            x = root(x), y = root(y);
            history.emplace(x, data[x]);
            history.emplace(y, data[y]);
            if(x == y) return (false);
            if(data[x] > data[y]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
            return (true);
        }

        int root(int k) {
            if(data[k] < 0) return (k);
            return (root(data[k]));
        }

        bool same(int x, int y) { return root(x) == root(y); }

        int size(int k) { return (-data[root(k)]); }

        void undo() {
            data[history.top().first] = history.top().second;
            history.pop();
            data[history.top().first] = history.top().second;
            history.pop();
        }

        void snapshot() {
            while(history.size()) history.pop();
        }

        void rollback() {
            while(history.size()) undo();
        }
    };

    UnionFind<Info> uf;

    bipartite_graph(::std::size_t A_, ::std::size_t B_)
        : A(A_), B(B_), undirected_graph<Info>(A_ + B_), uf(A_ + B_) {}
    void add_edge(int x, int y, Info info = static_cast<Info>(1)) {
        undirected_graph<Info>::add_edge(x, y + A, info);
        this->uf.unite(x, y + A);
    }
    int size(int x, bool is_left = true) {
        return (is_left ? uf.size(x) : uf.size(x + A));
    };
    inline bool same(int left, int right) { return uf.same(left, right + A); };
    inline int root(int x, bool is_left = true) {
        return (is_left ? uf.root(x) : uf.root(x + A));
    }
};

