struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main() {
  int N;
  cin >> N;

  vector<tuple<int,int,int>> xy(N);
  UnionFind tree(N);

  long long ans = 0;

  for (int i=0; i<N; i++) {
    cin >> get<0>(xy[i]) >> get<1>(xy[i]);
    get<2>(xy[i]) = i;
  }

  sort(xy.begin(),xy.end());

  for (int i=0; i<N-1; i++) {
    if (get<0>(xy[i]) == get<0>(xy[i+1])) {
      tree.unite(get<2>(xy[i]),get<2>(xy[i+1]));
    }
  }
  for (int i=0; i<N; i++) {
    swap(get<0>(xy[i]),get<1>(xy[i]));
  }

  sort(xy.begin(),xy.end());

  for (int i=0; i<N-1; i++) {
    if (get<0>(xy[i]) == get<0>(xy[i+1])) {
      tree.unite(get<2>(xy[i]),get<2>(xy[i+1]));
    }
  }

  int p;
  for (int i=0; i<N; i++) {
    p = get<2>(xy[i]);
    get<2>(xy[i]) = tree.root(p);
    swap(get<0>(xy[i]),get<2>(xy[i]));
  }

  sort(xy.begin(),xy.end());

  long long num = 0;
  vector<pair<int,int>> can(N);
  vector<int> ansn1(N,1);
  vector<int> ansn2(N,1);
  vector<int> ansn3(N,0);

  for (int i=0; i<N; i++) {
    ansn3[get<0>(xy[i])]++;
    if (i == N-1) {
      break;
    }
    if (get<0>(xy[i]) == get<0>(xy[i+1])) {
      if (get<1>(xy[i]) != get<1>(xy[i+1])) {
        ansn1[get<0>(xy[i])]++;
      }
    }
  }

  for (int i=0; i<N; i++) {
    swap(get<2>(xy[i]),get<1>(xy[i]));
  }
  sort(xy.begin(),xy.end());

  for (int i=0; i<N; i++) {
    if (i == N-1) {
      break;
    }
    if (get<0>(xy[i]) == get<0>(xy[i+1])) {
      if (get<1>(xy[i]) != get<1>(xy[i+1])) {
        ansn2[get<0>(xy[i])]++;
      }
    }
  }

  for (int i=0; i<N; i++) {
    if (ansn1[i] != 1 && ansn2[i] != 1) {
      ans += ansn1[i] * ansn2[i] - ansn3[i];
    }
  }

  cout << ans << endl;

  return 0;
}

