//UnionFind木(サイズ有り)
struct UnionFind{
private:
	vector<int> par;
	vector<int> siz;
public:
	void init(int N){ //初期化する O(N)
		par.clear();
		siz.clear();
		for(int i=0; i<N; i++) par.push_back(i);
		for(int i=0; i<N; i++) siz.push_back(1);
	}
	int root(int a){ //親を返す O(α(N))
		if(par[a] == a) return a;
		return par[a] = root(par[a]);
	}
	void unite(int a, int b){ //木を併合する O(α(N))
		int rootA = root(a);
		int rootB = root(b);
		if(rootA == rootB) return;
		if(siz[rootA] < siz[rootB]) swap(rootA, rootB);
		par[rootB] = rootA;
		siz[rootA] += siz[rootB];
	}
	bool same(int a, int b){ //属する木が同じかを返す O(α(N))
		return root(a) == root(b);
	}
	int size(int a){ //その素集合の要素数を返す O(α(N))
		return siz[root(a)];
	}
};

