typedef long long ll;
typedef pair<ll, ll> P;

#define fs first
#define sc second

vector<int> x[101000], y[101000];
bool x_list[101000];
bool xc[101000], yc[101000];

P dfs(int xx, int yy){
    if(xc[xx] && yc[yy]){
        return P(0, 0);
    }
    P res = P(0, 0);
    if(!xc[xx]){
        xc[xx] = true;
        for(auto y2: x[xx]){
            P ret = dfs(xx, y2);
            res.fs += ret.fs;
            res.sc += ret.sc;
        }
        res.fs += 1;
    }
    if(!yc[yy]){
        yc[yy] = true;
        for(auto x2: y[yy]){
            P ret = dfs(x2, yy);
            res.fs += ret.fs;
            res.sc += ret.sc;
        }
        res.sc += 1;
    }
    return res;
}


int main(){
    int N;
    cin >> N;
    for(int i = 0; i < N; i++){
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        x[a].push_back(b);
        y[b].push_back(a);
    }

    ll res = 0;
    fill(xc, xc+101000, false);
    fill(yc, yc+101000, false);
    fill(x_list, x_list+101000, false);
    for(int i = 0; i < 101000; i++){
        if(!x[i].empty() && !yc[x[i][0]]){
            P ret = dfs(i, x[i][0]);
            res += ret.fs * ret.sc;
        }
    }

    cout << max(res - N, 0LL) << endl;

    return 0;
}

