#include <bits/stdc++.h>

#define reint register int
#define coint const int

using namespace std;

typedef long long ll;

coint SIZE = 100000 + 5;

bitset<SIZE> bit[SIZE], tmp;
int fa[SIZE], cnt;

int getfa(coint u) { return u == fa[u] ? u : fa[u] = getfa(fa[u]); }

struct Node { int x, y, bel; };

Node li[SIZE];

inline bool cmp1(const Node &x, const Node &y) { return x.x < y.x; }
inline bool cmp2(const Node &x, const Node &y) { return x.y < y.y; }

inline int getint(void) {
    reint x = 0, ch = getchar();
    for (; ch < '0' || ch > '9'; ch = getchar());
    for (; ch >= '0' && ch <= '9';
            x = (x << 1) + (x << 3) + ch - '0', ch = getchar());
    return x;
}

ll ans;

inline void union_(coint x, coint y) {
    coint xfa = getfa(x), yfa = getfa(y);
    if (xfa == yfa) return;

    tmp = bit[xfa] | bit[yfa];
    ans += (tmp.count() << 1) - bit[xfa].count() - bit[yfa].count();
    bit[yfa] = tmp;
    fa[xfa] = yfa;

    return;
}

int main(void) {
    coint n = getint();
    for (reint i = 1; i <= n; ++i) li[i].x = getint(), li[i].y = getint();
    sort(li + 1, li + n + 1, cmp1);

    int ind = 0;
    for (reint i = 1; i <= n; i = ind + 1) {
        ++cnt, fa[cnt] = cnt;
        for (; ind < n && li[ind + 1].x == li[i].x; ++ind)
            bit[cnt][li[ind + 1].y] = 1, li[i].bel = cnt;
    }

    sort(li + 1, li + n + 1, cmp2), ind = 0;
    for (reint i = 1; i <= n; i = ind + 1) {
        for (; ind < n && li[ind + 1].y == li[i].y; ++ind);
        for (reint j = i; j < ind; ++j)
            union_(li[j].bel, li[j + 1].bel);
    }

    printf("%lld\n", ans);

    return 0;
}

