        }
        prev[y[i]] = x[i];
    }
    std::map<int, std::set<int>> s;
    for (int i = 0; i < n; i++) {
        s[uf.find_root(x[i])].insert(y[i]);
    }
    long long ans = -n;
    for (const auto &p : s) {
        ans += uf.size(p.first) * p.second.size();
    }
    std::cout << ans << std::endl;
    return 0;
}

