  return Par[x] = find(Par[x]);
}
void merge(ll x, ll x2) {
  x = find(x);
  x2 = find(x2);
  if (Rank[x] > Rank[x2]) {
    Par[x2] = x;
  } else {
    Par[x] = x2;
    if (Rank[x] == Rank[x2]) ++Rank[x2];
  }
}
