struct uf
{
	vector<lint> p;
	vector<lint> s;

	uf(lint n) : p(n), s(n)
	{
		rep(i, n)
		{
			p[i] = i;
			s[i] = 1;
		}
	}

	lint rt(lint n)
	{
		return p[n] == n ? n : p[n] = rt(p[n]);
	}

	void un(lint n, lint m)
	{
		if (rt(n) != rt(m))
		{
			s[rt(m)] += s[rt(n)];
			p[rt(n)] = rt(m);
		}
	}

	bool eq(lint n, lint m)
	{
		return rt(n) == rt(m);
	}

	lint sz(lint n)
	{
		return s[rt(n)];
	}
};

int main()
{
	lint n;
	cin >> n;

	uf t(200020);

	rep(i, n)
	{
		lint x, y;
		cin >> x >> y;

		t.un(x, y + 100010);
	}

	vec xn(200020), yn(200020);

	rep(i, 200020)
	{
		if (i < 100005)
		{
			xn[t.rt(i)]++;
		}
		else
		{
			yn[t.rt(i)]++;
		}
	}

	lint s = 0;

	rep(i, 200020)
	{
		s += xn[i] * yn[i];
	}

	cout << s - n << endl;

	return 0;
}

