class DSU
{
    vector<ll> par;
    vector<ll> rank;

public:
    ll Find(ll v)
    {
        if (par[v] != v)
            par[v] = Find(par[v]);
        return par[v];
    }
    void Union(ll v, ll u)
    {
        ll vroot = Find(v);
        ll uroot = Find(u);
        if (rank[vroot] < rank[uroot])
        {
            par[vroot] = uroot;
        }
        else if (rank[uroot] < rank[vroot])
        {
            par[uroot] = vroot;
        }
        else
        {
            par[uroot] = vroot;
            rank[vroot]++;
        }
    }
    DSU(ll n)
    {
        for (ll i = 0; i <= n; i++)
        {
            par.push_back(i);
            rank.push_back(1);
        }
    }
};
void solve()
{
    ll n, m, q;
    cin >> q;
    n = 100000, m = 100000;
    DSU d(n + m);
    //vector<ll> arr(n);
    for (ll i = 0; i < q; i++)
    {
        ll x, y;
        cin >> x >> y;
        d.Union(x - 1, n + y - 1);
    }
    map<ll, ll> st1, st2;
    for (ll i = 0; i < n; i++)
    {
        st1[d.Find(i)]++;
    }
    for (ll i = n; i <= n + m - 1; i++)
    {
        st2[d.Find(i)]++;
    }
    ll ans = 0;
    for (auto it : st1)
    {
        if (st2.find(it.first) != st2.end())
        {
            ans += it.second * st2[it.first];
        }
    }
    if (ans > 0)
        cout << ans - q;
    else
    {
        cout << ans;
    }
}
