// code starts
#define max_n 200005//changable
vector<int> par(max_n);
vector<int> ranks(max_n);
vector<int> sizes(max_n);

void init(int n)
{
  int i;
  for(i=0;i<n;i++)
  {
    par[i]=i;
    ranks[i]=0;
    sizes[i]=1;
  }
}

int find(int x)
{
  if(par[x]==x)
  {
    return x;
  }
  else
  {
    return par[x] = find(par[x]);
  } 
}

void unite(int x, int y)
{
  x = find(x);
  y = find(y);
  if(x==y)return;
  if(ranks[x]<ranks[y])
  {
    par[x] = y;
    sizes.at(y)+=sizes.at(x);
  }
  else
  {
    par[y] = x;
    sizes.at(x)+=sizes.at(y);
    if(ranks[x]==ranks[y])ranks[x]++;
  }
}

int sizing(int x)
{
  return sizes.at(find(x));
}

bool same(int x,int y)
{
  return find(x) == find(y);
}

