long long solve() {
  long long ans = 0;
  uf = Unionfind(n + 1);
  for(int i = 0; i <= 100000; ++i)
    for(int j = 0; j < 2; ++j) memo[i][j] = -1;
  for(int i = 0; i < n; ++i) {
    if(memo[v[i].fi][0] == -1)
      memo[v[i].fi][0] = i;
    else
      uf.uni(i, memo[v[i].fi][0]);
    if(memo[v[i].se][1] == -1)
      memo[v[i].se][1] = i;
    else
      uf.uni(i, memo[v[i].se][1]);
  }
  for(int i = 0; i < n; ++i) {
    s[uf.root(i)][0].insert(v[i].fi);
    s[uf.root(i)][1].insert(v[i].se);
  }
  for(int i = 0; i < n; ++i)
    if(uf.root(i) == i)
      ans += s[i][0].size() * s[i][1].size();

  return ans - n;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef unsigned long long ull;

typedef array<ll,2> XY;

class UnionFind{
public:
    UnionFind(size_t n){
        m_parent.resize(n);
        iota(m_parent.begin(), m_parent.end(), 0);

        m_rank.resize(n);
        fill(m_rank.begin(), m_rank.end(), 0);
    }

    int Find(int x){
        if(m_parent[x] == x){
            return x;
        }else{
            m_parent[x] = Find(m_parent[x]);
            return m_parent[x];
        }
    }

    void Union(int x, int y){
        auto xroot = Find(x);
        auto yroot = Find(y);
        if(m_rank[xroot] > m_rank[yroot]){
            m_parent[yroot] = xroot;
        }else if(m_rank[xroot] < m_rank[yroot]){
            m_parent[xroot] = yroot;
        }else if(xroot != yroot){
            m_parent[yroot] = xroot;
            m_rank[xroot] = m_rank[xroot] + 1;
        }
    }
    std::vector<int> m_parent;
    std::vector<int> m_rank;
};

int main()
{
    ll N;
    cin >> N;
    ll xi, yi;
    vector<XY> xy;
    UnionFind uf(200000);
    for(int i=0;i<N;i++){
        cin >> xi >> yi;
        uf.Union(xi-1, 100000+yi-1);
        xy.push_back(array<ll,2>{xi, yi});
    }
    map<ll, set<ll>> Gx;
    map<ll, set<ll>> Gy;
    map<ll, ll> Ge;
    for(auto v : xy){
        auto root = uf.Find(v[0]-1);
        if(Gx.count(root)==0) Gx[root]=set<ll>();
        if(Gy.count(root)==0) Gy[root]=set<ll>();
        if(Ge.count(root)==0) Ge[root]=0;
        Gx[root].insert(v[0]);
        Gy[root].insert(v[1]);
        Ge[root]++;
    }
    ll res=0;
    for(auto m : Ge){
        auto ig = m.first;
        if(Gx[ig].size() >= 2 && Gy[ig].size() >= 2){
            res += Gx[ig].size() * Gy[ig].size() - Ge[ig];
        }
    }
    cout<<res<<endl;

    return 0;
}

