void fin(T const& t){ std::cout << t << std::endl; exit(0); }

struct union_find {
  std::vector<int> par, rank;

  explicit union_find(int n): par(n), rank(n,0) {
    std::iota(par.begin(), par.end(), 0);
  }

  int find(int x) {
    if(par[x] == x) return x;
    return par[x] = find(par[x]);
  }

  void unite(int x, int y) {
    x = find(x); y = find(y);
    if(x == y) return;
    if(rank[x] < rank[y]) par[x] = y;
    else {
      par[y] = x;
      if(rank[x] == rank[y]) ++rank[x];
    }
  }
};

int main() {
  int N; std::cin >> N;
  union_find uf(2e5);
  for(int i = 0; i < N; ++i) {
    int x, y; std::cin >> x >> y; --x; --y; y += 1e5;
    uf.unite(x, y);
  }

  std::map<int,int> cmpx, cmpy;
  for(int i = 0; i < 1e5; ++i) ++cmpx[uf.find(i)];
  for(int i = 1e5; i < 2e5; ++i) ++cmpy[uf.find(i)];
  int64_t ans = -N;
  for(auto const& p: cmpx) ans += (int64_t)p.second * cmpy[p.first];
  fin(ans);
  return 0;
}

