class UnionFind {
 public:
  vector<int> data;
  int count;
 public:
  UnionFind(int size) : data(size, -1), count(size) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
      --count;
    }
    return x != y;
  }
  bool findSet(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

ll solve(int N, vi& x, vi& y) {
    set<int> xe, ye;
    rep(i,N){
        xe.insert(x[i]);
        ye.insert(y[i]);
    }
    int xN = xe.size(), yN = ye.size();
    map<int,int> xZ, yZ;
    int xi=0, yi=0;
    for (int x: xe) xZ[x] = xi++;
    for (int y: ye) yZ[y] = yi++;
    rep(i,N){
        x[i] = xZ[ x[i] ];
        y[i] = yZ[ y[i] ];
    }

    using P = pair<int, ii>;
    vector<P> vert, horiz;


    {
        vvi po(xN);
        rep(i,N) po[x[i]].pb(y[i]);
        rep(x,xN){
            sort(ALL(po[x]));
            int last = -2, from = -2, to = -2;
            for(int y: po[x]){
                if (y == last+1){
                    to = y;
                } else {
                    if (from < to) {
                        vert.emplace_back(x, ii(from, to));
                    }
                    from = to = y;
                }
                last = y;
            }
            if (from < to) {
                vert.emplace_back(x, ii(from, to));
            }
        }
    }

    {
        vvi po(yN);
        rep(i,N) po[y[i]].pb(x[i]);
        rep(y,yN){
            sort(ALL(po[y]));
            int last = -2, from = -2, to = -2;
            for(int x: po[y]){
                if (x == last+1){
                    to = x;
                } else {
                    if (from < to) horiz.emplace_back(y, ii(from, to));
                    from = to = x;
                }
                last = x;
            }
            if (from < to) horiz.emplace_back(y, ii(from, to));
        }
    }



    int V = vert.size(), H = horiz.size();
    UnionFind uf(V + H);

    vi cross(V, 0);

    rep(i,V) {
        P v = vert[i];
        int x = v.first;
        rep(j,H) {
            P h = horiz[j];
            int y = h.first;
            if (!IN(y, v.second.first, v.second.second)) continue;
            if (!IN(x, h.second.first, h.second.second)) continue;
            uf.unionSet(i, V+j);
            cross[i]++;
        }
    }

    map<int,int> xmin, xmax, ymin, ymax, cnt, crosscnt;
    set<int> roots;

    rep(i,V){
        P v = vert[i];
        int x = v.first;
        int y0 = v.second.first, y1 = v.second.second;

        int r = uf.root(i);
        if (!found(roots, r)) {
            xmin[r] = xmax[r] = x;
            ymin[r] = y0;
            ymax[r] = y1;
            cnt[r] = y1 - y0 + 1;
            crosscnt[r] = cross[i];
            roots.insert(r);
        } else {
            amin(xmin[r], x);
            amax(xmax[r], x);
            amin(ymin[r], y0);
            amax(ymax[r], y1);
            cnt[r] += y1 - y0 + 1;
            crosscnt[r] += cross[i];
        }
    }
    rep(i,H){
        P h = horiz[i];
        int y = h.first;
        int x0 = h.second.first, x1 = h.second.second;

        int r = uf.root(V+i);
        if (!found(roots, r)) {
            ymin[r] = ymax[r] = y;
            xmin[r] = x0;
            xmax[r] = x1;
            cnt[r] = x1 - x0 + 1;
            roots.insert(r);
        } else {
            amin(xmin[r], x0);
            amax(xmax[r], x1);
            amin(ymin[r], y);
            amax(ymax[r], y);
            cnt[r] += x1 - x0 + 1;
        }
    }

    ll ans = 0;

    for (int r: roots) {
        int dx = xmax[r] - xmin[r] + 1;
        int dy = ymax[r] - ymin[r] + 1;
        ll area = (ll)dx * dy;
        area -= cnt[r] - crosscnt[r];
        ans += area;
    }

    return ans;
}

