class UnionFind {
  vector<int> par;
  vector<int> sizes;
  public:
  UnionFind(int n) : par(n), sizes(n, 1) {
    for (int i = 0; i < n; i++) {
      par[i] = i;
    }
  }
  int find(int x) {
    if (x == par[x]) return x;
    return par[x] = find(par[x]);
  }
  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (sizes[x] < sizes[y]) swap(x, y);
    par[y] = x;
    sizes[x] += sizes[y];
  }
  bool same(int x, int y) {
    return find(x) == find(y);
  }
  int size(int x) {
    return sizes[find(x)];
  }
};

void solve(long long N, std::vector<long long> x, std::vector<long long> y){
  map<long long, int> xmap;
  map<long long, int> ymap;
  UnionFind uf(N);

  for (int i = 0; i < N; i++) {
    if (!xmap.count(x[i])) {
      xmap[x[i]] = i;
    } else {
      uf.unite(i, xmap[x[i]]);
    }
    if (!ymap.count(y[i])) {
      ymap[y[i]] = i;
    } else {
      uf.unite(i, ymap[y[i]]);
    }
  }

  vector<set<int>> xlines(N);
  vector<set<int>> ylines(N);
  vector<int> usize(N, 0);

  for (int i = 0; i < N; i++) {
    xlines[uf.find(i)].insert(x[i]);
    ylines[uf.find(i)].insert(y[i]);
    usize[uf.find(i)]++;
  }

  long long ans = 0;

  for (int i = 0; i < N; i++) {
    ans += xlines[i].size() * ylines[i].size() - usize[i];
  }

  std::cout << ans << std::endl;
}

