class UnionFind{
public:
    UnionFind(ll n){
        size = n;
        parent = vector<ll>(size,-1);
    }
    ll getSize(){return size;}
    ll getParentElement(ll index){return parent[index];}
    ll getGroupSize(ll index){return abs(getParentElement(find(index)));}
    bool isSame(ll x, ll y){return find(x)==find(y);}
    void printParent(){
        for(auto v: parent) {cout << v << " ";}
        cout << endl;
    }
    ll find(ll x){
        ll a = x;
        vector<ll> children;
        while(parent[a]>=0){
            children.push_back(a);
            a = parent[a];
        }
        for(auto child: children){parent[child] = a;}
        return a;
    }
    ll Union(ll x, ll y){
        ll root_x = find(x);
        ll root_y = find(y);
        if(root_x != root_y){
            if(parent[root_x]>=parent[root_y]){
                parent[root_x] += parent[root_y];
                parent[root_y] = root_x;
            }else{
                parent[root_y] += parent[root_x];
                parent[root_x] = root_y;
            }
        }
        return parent[root_x];
    }
private:
    ll size;
    vector<ll> parent;
};

int main(){
    ll n;
    cin >> n;
    UnionFind uf(MAXSIZE*2);
    ll x, y;
    for(int i = 0; i < n; i++){
