const int MAX_N = (int)4e5 + 5, C = (int)2e5;
int parent[MAX_N], r[MAX_N], X[MAX_N], Y[MAX_N];
int M[MAX_N], used[MAX_N];
unordered_set<int> CX[MAX_N], CY[MAX_N];

void init(int n){
    for(int i=0;i<n;i++){
        parent[i] = i;
        r[i] = 0;
    }
}

int find(int x){
    if(parent[x] == x) return x;
    else return parent[x] = find(parent[x]);
}

void unite(int x, int y){
    x = find(x); y = find(y);
    if(x == y) return;
    if(r[x]<r[y]) parent[x] = y;
    else{
        parent[y] = x;
        if(r[x] == r[y]) r[x]++;
    }
}


