        unite(X[i], C+Y[i]);
    }
    for(int i=0;i<N;i++){
        CX[find(X[i])].emplace(X[i]);
        CY[find(C+Y[i])].emplace(Y[i]);
        M[find(X[i])]++;
    }
    lint ans = 0;
    for(int i=0;i<N;i++){
        int p = find(X[i]);
        if(used[p]) continue;
        used[p] = 1;
        ans += 1LL * CX[p].size() * CY[p].size() - M[p];
