struct UnionFind {
    vector<int> par;

    UnionFind(int n): par(n, -1) {}
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }

    int issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);

        if (x == y) return false;

        // merge by size
        // y must be bigger than x
        if (par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;

        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

int NMAX = 100100;

int main(){
    cin.tie(0);
    ios_base::sync_with_stdio(false);
    cout << fixed << setprecision(20);

    int N;
    cin >> N;

    UnionFind uf(NMAX * 2);
    vi X(N), Y(N);
    REP(i, N) cin >> X[i] >> Y[i], uf.merge(X[i], Y[i] + NMAX);

    map<ll, ll> mx, my;
    REP(i, NMAX) mx[uf.root(i)]++;
    REP(i, NMAX) my[uf.root(i + NMAX)]++;

    ll res = 0;
    REP(i, 2 * NMAX) res += mx[i] * my[i];

    print(res - N);
}

