long long par[200010],sz[200010] = {},sz2[200010] = {},e[200010],ans = 0;
int init(int n){
	for(int i=0;i<n;i++){
		par[i] = i; sz[i] = 1;
	}
	for(int i=n;i<2*n;i++){
		par[i] = i; sz[i] = 1; sz2[i] = 1;
	}
}

int find(int x){
	if(par[x]==x) return x;
	return par[x] = find(par[x]);
}

void unite(int x, int y){
	x = find(x); y = find(y);
	if(x==y){
		e[x]++; return;
	}
	if(sz[x]<sz[y]) swap(x,y);
	sz[x] += sz[y]; sz2[x] += sz2[y]; par[y] = x; e[x] += e[y] + 1;
}

bool same(int x, int y){
	return find(x)==find(y);
}
int main(){
