	init(100000);
	for(i=0;i<n;i++){
		int x,y; cin >> x >> y;
		unite(x,y + 100000);
	}
	for(i=0;i<=200000;i++){
		if(par[i]==i){
			if(sz[i]==1) continue;
			ans += (sz[i] - sz2[i])*sz2[i] - e[i];
		}
	}
	cout << ans << endl;
}

