using namespace std;

class UnionFind
{
  public:
    UnionFind(int n);
    int find(int x);
    bool same(int x, int y);
    int size(int x);
    void unite(int xp, int yp);

  private:
    vector<int> par;
    vector<int> sze;
};

UnionFind::UnionFind(int n)
    : par(vector<int>(n)), sze(vector<int>(n, 1))
{
    iota(begin(par), end(par), 0);
}

int UnionFind::find(int x)
{
    if (x != par[x])
        par[x] = find(par[x]);
    return par[x];
}

bool UnionFind::same(int x, int y)
{
    return find(x) == find(y);
}

int UnionFind::size(int x)
{
    return sze[find(x)];
}

void UnionFind::unite(int xp, int yp)
{
    int x = find(xp);
    int y = find(yp);
    if (x == y)
        return;
    if (size(x) > size(y))
    {
        sze[x] += size(y);
        par[y] = x;
    }
    else
    {
        sze[y] += size(x);
        par[x] = y;
    }
}

