class UFT{
public:
    vector<int> par;
    vector<int> siz;
    vector<int> mar;


    UFT(int n) :
        par(vector<int>(n)),
        siz(vector<int>(n, 1)),
        mar(vector<int>(n, 0)){ For(i, n) par[i] = i; }

    bool same(int x, int y){ return find(x) == find(y); }
    int find(int x){ return (par[x] == x) ? x : (par[x] = find(par[x])); }
    void unite(int x, int y){
        if(!same(x = find(x), y = find(y))){
            par[x] = y;
            siz[y] += siz[x];
            mar[y] += mar[x];
        }
    }
    int size(int x){ return siz[find(x)]; }
    void add(int x){ mar[find(x)] ++; }
    int count(int x){ return mar[find(x)]; }
    void print() const{ Couts(par); }
};

