    vector<long> X(100005,-1),Y(100005,-1);
    for(int i=0;i<N;i++){
        if(X.at(x.at(i))>=0) uf.marge(X.at(x.at(i)),i);
        if(Y.at(y.at(i))>=0) uf.marge(Y.at(y.at(i)),i);

        X.at(x.at(i))=i;
        Y.at(y.at(i))=i;
    }


    vector<set<long>> setX(N),setY(N);
    for(int i=0;i<N;i++){
        long root=uf.find(i);
        setX.at(root).insert(x.at(i));
        setY.at(root).insert(y.at(i));
    }

    long ans=-N;
    for(int i=0;i<N;i++){
        ans+=setX.at(i).size()*setY.at(i).size();
    }
