class DSU
{
public:
    vector<int> f;
    vector<int> cnt;
    DSU(int sz)
    {
        f = vector<int>(sz);
        cnt = vector<int>(sz, 1);
        forn(i, sz) f[i] = i;
    }
    int get(int x)
    {
        return f[x] == x ? x : (f[x] = get(f[x]));
    }
    void merge(int x, int y)
    {
        x = get(x);
        y = get(y);
        if (x != y)
            f[x] = y, cnt[y] += cnt[x];
    }
    bool same(int x, int y)
    {
        return get(x) == get(y);
    }
    int count(int x)
    {
        return cnt[get(x)];
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    ll n;
    cin >> n;
    pair<ll, ll> p;
    Mat M(1e5 + 10);
    forn(i, n) cin >> p.fi >> p.se, M[p.se].push_back(p.fi);

    ll ans = 0;
    DSU dsu(1e5 + 10);
    DSU dsu2(1e5 + 10);
    Arr Y(1e5 + 10, -1);
    fori(y, 1, 1e5 + 5)
    {
        ll prev = -1;
        for (ll x : M[y])
        {
            if (Y[x] != -1)
            {
                dsu.merge(y, Y[x]);
                dsu2.merge(M[y].front(), M[Y[x]].front());
            }
            if (prev != -1)
                dsu2.merge(x, prev);
            prev = x;
            Y[x] = y;
        }
    }

    fori(y, 1, 1e5 + 5)
    {
        if (dsu.count(y) > 1 && dsu.get(y) == y)
        {
            ll x = M[y].front();
            ans += 1LL * dsu.count(y) * dsu2.count(x);
        }
        if (dsu.count(y) == 1 && M[y].size() > 0)
            ans += M[y].size();
    }
    cout << (ans - n);
    return 0;
}

