#include <bits/stdc++.h>
using namespace std;
#define REP(i,n) for (int i=0;i<(n);i++)
#define REP2(i,m,n) for (int i=m;i<(n);i++)
typedef long long ll;

int N;
int X[101010];
int Y[101010];
vector<pair<int, int>> R[101010];
vector<pair<int, int>> C[101010];

class UnionFind {
    public:
    vector<int> table;
    vector<vector<int>> data;
    UnionFind(int n) {
        table = vector<int> (n, -1);
        data = vector<vector<int>> (n);
        REP(i, n) data[i].push_back(i);
    }

    ~UnionFind(){};

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (table[x] >= table[y]) {
            for (auto i: data[x]) data[y].push_back(i);
            data[x].clear();
            table[y] += table[x];
            table[x] = y;
        } else {
            for (auto i: data[y]) data[x].push_back(i);
            data[y].clear();
            table[x] += table[y];
            table[y] = x;
        }
    }

    int find(int x) {
        if (table[x] < 0) return x;
        return table[x] = find(table[x]);
    }
};

void solve() {
    cin >> N;
    REP(i, N) cin >> X[i] >> Y[i];
    REP(i, N) R[X[i]].push_back({Y[i], i});
    REP(i, N) C[Y[i]].push_back({X[i], i});

    UnionFind uf = UnionFind(N);
    REP(i, 101010) REP2(j, 1, (int)R[i].size()) {
        uf.unite(R[i][j].second, R[i][0].second);
    }
    REP(i, 101010) REP2(j, 1, (int)C[i].size()) {
        uf.unite(C[i][j].second, C[i][0].second);
    }

    ll ans = 0;
    set<int> sx;
    set<int> sy;

    REP(i, N) if (uf.table[i] < 0) {
        sx.clear();
        sy.clear();
        for (auto j: uf.data[i]) {
            sx.insert(X[j]);
            sy.insert(Y[j]);
        }
        ans += 1LL * sx.size() * sy.size() - (ll)uf.data[i].size();
    }

    cout << ans << endl;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

