const ll INF = 1e9+7;


struct UnionFind{

	std::vector<int> data;
	// dataの各要素について
	// 負の値:その集合のルートであること示す。また、その絶対値は集合の要素数となっている。
	// 正の値:親ノードの番号(dataのインデックス)。root()を呼び出すたびに集合のルートを指すように書きなおされるので木はそんなに深くならない

	//初期化 size:最大要素数
	UnionFind(int size): data(size, -1) {}

	// 集合を併合する
	// すでに同じ集合だった場合は、falseが返る
	bool unite(int x, int y){
		x=root(x);
		y=root(y);
		if( x != y ){
			// 要素数の大きな方へ合併するためのswap
			if( data[y] < data[x] ) std::swap(x, y);
			// 要素数を加算する
			data[x] += data[y];
			// yの属する集合のルートをxに変更
			data[y] = x;
		}
		return x!=y;
	}

	// 同じ集合かどうか判定
	bool find(int x, int y){
		return root(x) == root(y);
	}

	// 集合の識別番号を返す
	int root(int x){
		// 負の値を持つものがその集合のルート
		// 正の値は同じ集合に属するものを指す(辿ればいずれルートへ着く)
		return (data[x] < 0)? x : data[x]=root(data[x]);
	}

	// 集合の要素数を返す
	int size(int x){
		return -data[ root(x) ];
	}
};

int main(){
	ios_base::sync_with_stdio(false);
	ll N, ans=0;
	map<int,vector<int>> mp;

	cin >> N;
	rep(i,N){
		int x, y;
		cin >> x >> y;
		mp[x].push_back(y);
	}

	UnionFind uf(200005);
	for(auto p: mp){
		auto ys = p.Y;
		for(int y: ys) uf.unite(ys[0], y);
	}

	for(auto p: mp){
		auto ys = p.Y;
		ans += uf.size(ys[0]) - ys.size();
	}

	cout << ans << endl;

	return 0;
}

