// x, y 最小最大を探す
void dfs(ll x, ll y) {
    if( isUsed[ val_to_id[make_pair(x, y)] ]) { return; }
    isUsed[ val_to_id[make_pair(x, y)] ] = true;

    x_min = min(x_min, x);
    y_min = min(y_min, y);
    x_max = max(x_max, x);
    y_max = max(y_max, y);

    for(auto& next_y : x_y[x]) {
        dfs(x, next_y);
    }
    for(auto& next_x : y_x[y]) {
        dfs(next_x, y);
    }
}

