pair<ll,ll> dfs(int v, vector<vector<int>> &G, vector<bool> &used){
    used[v] = 1;
    ll x = (v < 100100 ? 1 : 0);
    ll y = 1 - x;
    for (auto nv : G[v]) if (!used[nv]) {
        auto p = dfs(nv,G,used);
        x += p.first;
        y += p.second;
    }
    return make_pair(x,y);
}

int main(){
    int n; cin >> n;
    vector<vector<int>> G(200200);
    rep(i,n){
        int x, y; cin >> x >> y;
        G[x].push_back(y+100100);
        G[y+100100].push_back(x);
    }
    vector<bool> used(200200,0);
    ll ans = 0;
    rep(i,200200){
        if(used[i]) continue;
        auto p = dfs(i,G,used);
        if(p.first <= 1 || p.second <= 1) continue;
        ans += p.first * p.second - p.first - p.second + 1;
    }
    cout << ans << endl;
    return 0;
}

