void dfs(int n, int p, int xy, vector<int> &cnt, int &nEdge){
    cnt[xy]++;
    for(auto v:graph[xy][n]){
        if(v==p) continue;
        nEdge++;
        if(!use[xy^1][v]){
            use[xy^1][v] = true;
            // cout << (xy==0?"x : ":"y : ") << n << " -> " << (xy^1==0?"x : ":"y : ") << v << endl;
            dfs(v, n, xy^1, cnt, nEdge);
        }
    }
}

