    use[1].resize(M+1, true);

    for(int i=0; i<N; i++){
        int x, y;
        cin >> x >> y;
        graph[0][x].push_back(y);
        graph[1][y].push_back(x);
        use[0][x] = false;
        use[1][y] = false;
    }

