            int nEdge = 0;
            // cout << "-----------------------" << endl;
            // cout << i << " " << x << " " << cnt[0] << " " << cnt[1] << endl;
            dfs(x, -1, i, cnt, nEdge);
            ans += cnt[0]*cnt[1] - nEdge;
