unordered_map<int, int> X, Y, cx[N], cy[N];
int ST[N], top;

int find_fa(int x){
    top = 0;
    while(x != fa[x]){
        ST[top++] = x;
        x = fa[x];
    }
    while(top--){
        fa[ST[top]] = x;
    }
    return x;
}

int main(){
    scanf("%d", &n);
    int fx, fy;
    for(int i=1; i<=n; i++){
        fa[i] = i;
        sz[i] = 1;
        scanf("%d %d", x+i, y+i);

        if(!X.count(x[i])){
            X[x[i]] = i;
        }
        fx = find_fa(X[x[i]]);
        if(!Y.count(y[i])){
            Y[y[i]] = i;
        }
        fy = find_fa(Y[y[i]]);

        if(fx != fy){
            if(sz[fx] < sz[fy]){
                swap(fx, fy);
            }
            fa[fy] = fx;
            sz[fx] += sz[fy];
            X[x[i]] = fx;
            Y[y[i]] = fx;
        }
    }

    LL ans = 0;
    for(int i=1; i<=n; i++){
        fx = find_fa(X[x[i]]);

        cx[fx][x[i]]++;
        cy[fx][y[i]]++;
    }

    for(int i=1; i<=n; i++){
        if(fa[i] == i){
            ans = ans + 1LL * cx[i].size() * cy[i].size() - sz[i];
        }
