struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

UnionFind uni(110000);
ll n, a[110000], b[110000], sa[110000], sb[110000], ans, a1;
vector<ll> xl[110000], yl[110000];
set<ll> xs[110000], ys[110000];
bool ok[110000];

int main() {
	cin >> n;
	REP(i, n) {
		cin >> sa[i] >> sb[i];
		a[sa[i]]++;
		b[sb[i]]++;
		xl[sa[i]].push_back(i);
		yl[sb[i]].push_back(i);
	}
	REP(i, 110000) {
		REP(j, (ll)xl[i].size() - 1) uni.unionSet(xl[i][j], xl[i][j + 1]);
		REP(j, (ll)yl[i].size() - 1) uni.unionSet(yl[i][j], yl[i][j + 1]);
	}
	REP(i, n) if (a[sa[i]] >= 2 and b[sb[i]] >= 2) ok[uni.root(i)] = true;
	REP(i, n) {
		if (ok[uni.root(i)]) {
			ans++;
			xs[uni.root(i)].insert(sa[i]);
			ys[uni.root(i)].insert(sb[i]);
		}
	}
	REP(i, n) if (ok[uni.root(i)] and uni.root(i) == i) a1 += xs[i].size() * ys[i].size();
	if (!ok) {
		cout << 0 << endl;
		return 0;
	}
	cout << a1 - ans << endl;
}

