            if(par[x]==x){
                return x;
            }else{
                return par[x]==root(par[x]);
            }
        }

        void unite(ll x, ll y){
            x = root(x);
            y = root(y);

            if(rank[x]<rank[y]){
                par[x]=y;
                sz[y]+=sz[x];
            }else{
                par[y]=x;
                sz[x]+=sz[y];
                if(rank[x]==rank[y]){
                    rank[x]++;
                }
            }
        }

        bool same(ll x, ll y){
            return root(x)==root(y);
        }

        ll size(ll x){
            return sz[root(x)];
        }
    };

