struct Point {
  long long x, y;
  bool operator<(const Point& another) const {
    if (another.x == x) {
      return y < another.y;
    } else {
      return x < another.x;
    }
  }
};

struct Node {
  Point p;
  vector<Node*> edges;
  bool visited;
};

bool y_order(const Point &a, const Point &b) {
  if (a.y == b.y) {
    return a.x < b.x;
  } else {
    return a.y < b.y;
  }
}

void dfs(Node *n, long long &n_points, set<long long> &xlines, set<long long> &ylines) {
  if (!n->visited) {
    n->visited = true;
    ++n_points;
    xlines.insert(n->p.x);
    ylines.insert(n->p.y);
    for (Node* next : n->edges) {
      dfs(next, n_points, xlines, ylines);
    }
  }
  return;
}

void solve(long long N, std::vector<long long> x, std::vector<long long> y){
  vector<Point> points(N);
  map<Point, int> pmap;
  for (int i = 0; i < N; i++) {
    points[i] = {x[i], y[i]};
  }
  for (int i = 0; i < N; i++) {
    pmap[points[i]] = i;
  }

  vector<Node> G;
  for (int i = 0; i < N; i++) {
    G.push_back((Node){points[i], vector<Node*>(), false});
  }

  int u, v;
  sort(points.begin(), points.end());
  for (int i = 1; i < N; i++) {
    if (points[i-1].x == points[i].x) {
      u = pmap[points[i-1]];
      v = pmap[points[i]];
      G[u].edges.push_back(&G[v]);
      G[v].edges.push_back(&G[u]);
    }
  }

  sort(points.begin(), points.end(), y_order);
  for (int i = 1; i < N; i++) {
    if (points[i-1].y == points[i].y) {
      u = pmap[points[i-1]];
      v = pmap[points[i]];
      G[u].edges.push_back(&G[v]);
      G[v].edges.push_back(&G[u]);
    }
  }

  long long n_points, ans;
  set<long long> xlines, ylines;

  ans = 0;

  for (int i = 0; i < N; i++) {
    if (!G[i].visited) {
      n_points = 0;
      xlines.clear();
      ylines.clear();
      dfs(&G[i], n_points, xlines, ylines);
      ans += xlines.size() * ylines.size() - n_points;
    }
  }

  std::cout << ans << std::endl;
}

int main(){
  long long N;
  scanf("%lld",&N);
  std::vector<long long> x(N);
  std::vector<long long> y(N);
  for(int i = 0 ; i < N ; i++){
    scanf("%lld",&x[i]);
    scanf("%lld",&y[i]);
  }
  solve(N, std::move(x), std::move(y));
  return 0;
}

