struct Union_Find {
  vector<int> data;
  Union_Find(int size) { data = vector<int>(size, -1); }
  bool union_set(int x, int y) {
    x = root(x);
    y = root(y);
    if (x != y) {
      if (data[y] < data[x])
        swap(x, y);
      data[x] += data[y];
      data[y] = x;
    }
    return x != y;
  }
  bool find(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

int main() {
  GI(N);
  int siz = 1e5 + 1;
  Union_Find ufx(siz), ufy(siz);
  vector<vector<int>> listx(siz), listy(siz);
  FOR(i, N) {
    GI2(x, y);
    if (listy[y].size() > 0) {
      ufx.union_set(x, listy[y][0]);
    }
    if (listx[x].size() > 0) {
      ufy.union_set(y, listx[x][0]);
    }
    listx[x].push_back(y);
    listy[y].push_back(x);
  }
  vector<unordered_set<int>> unions(siz);
  vector<int> sizes(siz);
  FOR(i, siz) {
    if (ufx.data[i] >= 0) {
      for (int y : listx[i]) {
        unions[ufx.data[i]].insert(y);
      }
      sizes[ufx.data[i]] += listx[i].size();
    } else if (ufx.data[i] < -1) {
      for (int y : listx[i]) {
        unions[i].insert(y);
      }
      sizes[i] += listx[i].size();
    }
  }
  ll ans = 0;
  FOR(i, siz) {
    if (ufx.data[i] < -1) {
      ans += -ufx.data[i] * unions[i].size();
      ans -= sizes[i];
    }
  }
  print(ans);
  return 0;
}

