  } 
}

void unite(int x, int y)
{
  x = find(x);
  y = find(y);
  if(x==y)return;
  if(ranks[x]<ranks[y])
  {
    par[x] = y;
    sizes.at(y)+=sizes.at(x);
  }
  else
  {
    par[y] = x;
    sizes.at(x)+=sizes.at(y);
    if(ranks[x]==ranks[y])ranks[x]++;
  }
}

int sizing(int x)
{
  return sizes.at(find(x));
}

bool same(int x,int y)
{
