				po[f1] += po[f2];
				tt += 1LL * li[f2] * po[f2];
			}
		}
		li[f1]++;
		tt += j - i;
		// cout << "=" << li[f1] << " " << po[f1] << " " << tt << endl;
		ans += li[f1] * po[f1] - tt;
	}
	cout << ans << endl;
	return 0;
}

