#define N 100000
int visited[2*N];
vector<vector<int>> edge(2*N, vector<int>(0));

pair<ll, ll> dfs(int cur){
  if (visited[cur] == 1)
    return pair<int, int>(0, 0);

  visited[cur] = 1;

  ll xs = 0, ys = 0;
  for (int i = 0; i < edge[cur].size(); i++){
    pair<int, int> a = dfs(edge[cur][i]);
    xs += a.first;
    ys += a.second;
  }

  if (cur >= N)
    return pair<int, int>(xs, ys + 1);
  else
    return pair<int, int>(xs + 1, ys);
}


