vi32 edges[200000];

void solve() {
  int n; cin >> n;
  vector<bool> seen(200000, true);
  rep(i, n) {
    int x, y; cin >> x >> y;
    x--, y--;
    y += 100000;
    edges[x].push_back(y);
    edges[y].push_back(x);
    seen[x] = seen[y] = false;
  }
  i64 cnt_x, cnt_y;
  function<void(int)> dfs = [&](int v) {
    seen[v] = true;
    if (v < 100000) cnt_x++; else cnt_y++;
    each(u, edges[v]) {
      if (seen[u]) continue;
      dfs(u);
    }
  };
  i64 ans = 0;
  rep(i, 200000) {
    if (seen[i]) continue;
    cnt_x = 0, cnt_y = 0;
    dfs(i);
    ans += cnt_x * cnt_y;
  }
  cout << ans - n << '\n';
}

