struct UFT{    //O(loga(n))
    int n;
    vi d, r;
    UFT(int n) : n(n), d(n, -1), r(n, 0){};
    int root(int i){
        if(d[i] < 0) return i;
        return d[i] = root(d[i]);
    }
    bool same(int x, int y){
        return root(x) == root(y);
    }
    bool unite(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y) return false;

        if(r[x] < r[y]) swap(x, y);
        else if(r[x] == r[y]) r[x]++;
        d[x] += d[y];
        d[y] = x;
        return true;
    }
    int size(int i){
        return -d[root(i)];
    }
};

int main(){
    int n;
    cin >> n;
    vector<int> x(n), y(n);
    map<int, int> mx, my;

    UFT uf(n);

    rep(i, n) {
        cin >> x[i] >> y[i];
        if(mx.count(x[i])) {
            uf.unite(i, mx[x[i]]);
        }
        else mx[x[i]] = i;
        if(my.count(y[i])) {
            uf.unite(i, my[y[i]]);
        }
        else my[y[i]] = i;
    }

    ll ans = 0LL;
    vector<vector<int>> v(n);
    rep(i, n) {
        v[uf.root(i)].pb(i);
    }

    for(auto&& g : v) {
        if(g.size() == 1) continue;
        set<int> sx, sy;
        for(auto&& i : g) {
            sx.insert(x[i]);
            sy.insert(y[i]);
        }
        ll sz_x = sx.size();
        ll sz_y = sy.size();
        if(sz_x == 1 || sz_y == 1) continue;
        ans += sz_x * sz_y;
        ans -= g.size();
    }
    cout << ans << '\n';
    return 0;
}

