const int maxX = 100005;

vector<bool> seen(maxX*2);

vector<int> nc(2);

void dfs(Graph& _G, int _v){
  seen[_v] = true;
  if(_v < maxX) nc[0] += 1;
  else nc[1] += 1;

  for(auto nv: _G[_v]){
    if(seen[nv]) continue;
    dfs(_G, nv);
  }
}

int main(){
  int N;
  cin >> N;

  Graph G(maxX*2);

  for(int i = 0 ; i < N; i++){
    int x,y;
