    y+=maxX;
    G[x].push_back(y);
    G[y].push_back(x);
  }

  int counter = 0;
  seen.assign(maxX*2, false);

  for(int i = 0; i < maxX*2; i++){  //Graphのすべてのノードについて
    if(seen[i]) continue;
    nc.assign(2, 0);
    dfs(G, i);
    counter += nc[0] * nc[1]; //二部グラフのノード数を掛け合わせれば、辺の数がわかる
  }
  counter -= N;

  cout << counter << endl;

  return 0;
}

// 解き直し.
// ABC 131解説.
// https://img.atcoder.jp/abc131/editorial.pdf
#include <bits/stdc++.h>
using namespace std;
const int MAX_V = 1e5 + 1;
// const int MAX_V = 8;
using LL = long long;
int cX[MAX_V], cY[MAX_V];  // 各頂点X, Y ごとに, 連結成分番号を保存.
LL cVX[MAX_V], cVY[MAX_V]; // 各連結成分 の X, Y の 頂点数を保存.
vector<int> X[MAX_V], Y[MAX_V];

// 深さ優先探索(depth-first search).
// https://ja.wikipedia.org/wiki/深さ優先探索
// @param x: 探索開始の頂点X番号.
// @param l: 連結成分番号(※1以上).
// @return : 特に無し.
void dfs(int x, int l){

    // 1. 終了条件設定.
    // -> 連結成分番号が設定済みであれば, 終了.
    if(cX[x] > 0) return;

    // 2. 頂点 X について, 連結成分情報 を 設定.
    cX[x] = l, cVX[l]++;

    // 3. 頂点 X に, 隣接する 頂点 Y を 探索.
    for(auto &y : X[x]){

        if(cY[y] > 0) continue;
        // 3-1. 頂点 Y に, 連結成分 l を設定し, 連結成分のカウンターを +1 更新.
        cY[y] = l, cVY[l]++;

        // 3-2. 頂点 Y に, 隣接する 頂点 X を 探索(再帰処理).
        for(auto &nx : Y[y]){
            if(cX[nx] > 0) continue;
            dfs(nx, l);
        }
    }
}

int main() {

    // 1. 入力情報取得.
    int N;
    scanf("%d", &N);

    // 以下, 解説通り.
    // 2. グラフ作成.
    for(int i = 0; i < N; i++){
        int u, v;
        scanf("%d %d", &u, &v);
        // u -> v
        X[u].push_back(v);
        // v -> u
        Y[v].push_back(u);
    }

    // グラフ情報確認.
    // for(int i = 1; i < MAX_V; i++){
    //     if(X[i].size() > 0) for(auto &p : X[i]) printf("%d %d\n", i, p);
    // }

    // 3. 連結成分に分解.
    int c = 0;
    for(int i = 1; i < MAX_V; i++) if(X[i].size() > 0 && cX[i] == 0) c++, dfs(i, c);

    // グラフ連結情報確認.
    // for(int i = 1; i < MAX_V; i++){
    //     printf("cX[%d], cY[%d] = [%d, %d]\n", i, i, cX[i], cY[i]);
    //     printf("cVX[%d], cVY[%d] = [%lld, %lld]\n", i, i, cVX[i], cVY[i]);
    // }

    // 4. 後処理.
    // ※各連結成分 の X, Y の 頂点数(cVX, cVY) について, long long で 計算しないと, 
    // テストケース(09.txt, 10.txt, 11.txt, 15.txt) で, WA となるので要注意.
    LL ans = 0;
    for(int i = 1; i < MAX_V; i++){
        if(cVX[i] == 0 || cVY[i] == 0) break;
        ans += cVX[i] * cVY[i];
    }
    ans -= N; // 連結済 の 辺数 を 減算.
    printf("%lld\n", ans);
    return 0;

}

