struct UnionFind {
    vector<int> par;
    vector<int> sz;
    vector<int> tp[2];

    UnionFind(int n, int xsz){
        par.resize(n);
        sz.resize(n);
        tp[0].resize(n);
        tp[1].resize(n);
        int half = n/2;
        for(int i=0; i<n; i++){
            par[i] = i;
            sz[i] = 1;
            tp[i>=xsz][i]++;
        }
    }

    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            return par[x] = find(par[x]);
        }
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(sz[x] > sz[y]) swap(x, y);
        par[x] = y;
        sz[y] += sz[x];
        tp[0][y] += tp[0][x];
        tp[1][y] += tp[1][x];
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    int size(int x){
        return sz[find(x)];
    }
};

