void dfs(LL y, LL x, set<LL>& y_set, set<LL>& x_set, set<pair<LL,LL>>& memo, map<LL, vector<LL>>& h, map<LL, vector<LL>>& v){
    pair<LL,LL> k(y, x);
    if(memo.count(k) > 0) return;
    memo.insert(k);
    if(y_set.count(y) <= 0){
        y_set.insert(y);
        for(LL x2: h[y]){
            dfs(y, x2, y_set, x_set, memo, h, v);
        }
    }
    if(x_set.count(x) <= 0){
        x_set.insert(x);
        for(LL y2: v[x]){
            dfs(y2, x, y_set, x_set, memo, h, v);
        }
    }
}

int main(){
    LL n;
    cin >> n;
    map<LL, vector<LL>> v, h;
    for(LL i = 0; i < n; ++i){
        LL x, y;
        cin >> x >> y;
        v[x].push_back(y);
        h[y].push_back(x);
    }
    set<pair<LL,LL>> memo;
    LL ans = -n;
    for(auto p: h){
        LL y = p.first;
        LL x = p.second[0];
        set<LL> y_set;
        set<LL> x_set;
        dfs(y, x, y_set, x_set, memo, h, v);
        ans += y_set.size() * x_set.size();
    }
    cout << ans << endl;
    return 0;
}

