void merge(vector<int>& v, vector<int>& sz, int x, int y) {
  x = find(v, x);
  y = find(v, y);
  if(x == y) return;
  sz[y] += sz[x];
  v[x] = y;
}
void init(vector<int>& par, vector<int>& sz, int n) {
  par.resize(n+1);
  sz.resize(n+1);
  for(int i = 1; i <= n; i++) {
