  for(auto out: xtoy) {
    for(int i = 1; i < out.second.size(); i++) merge(yPar, ySz, out.second[i-1], out.second[i]);
  }
  for(auto out: ytox) {
    for(int i = 1; i < out.second.size(); i++) merge(xPar, xSz, out.second[i-1], out.second[i]);
