pair<set<ll>, set<ll>> calc(const map<ll, V<ll>> &mp) {
    set<ll> xst, yst;
    for(const auto &ele : mp) {
        if(ele.second.size() <= 1) continue;
        xst.insert(ele.first);
        for(ll y : ele.second) yst.insert(y);
    }
    return move(make_pair(xst, yst));
}

