class UnionFind {
public:
    // parent node index if not root index
    // minus size of the tree if root index
    std::vector<int> data;

    UnionFind( int n ) {
        data.resize( n, -1 );
    }

    int find( int x ) {
        if ( data[x] < 0 ) {
            return x;
        } else {
            int r = find( data[x] );
            data[x] = r;
            return r;
        }
    }

    void unite( int x, int y ) {
        int r = find( x );
        int s = find( y );
        if ( r != s ) {
            data[r] += data[s];
            data[s] = r;
        }
    }

    int count( int x ) {
        return -data[find(x)];
    }
};

int main() {
    int NMAX = 1e5;
    int N;
    cin >> N;
    vector<int> X(N), Y(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> X[i] >> Y[i];
        X[i]--;
        Y[i]--;
    }
    map<int, set<int>> px, py;
    for ( int i = 0; i < N; i++ ) {
        px[X[i]].insert(Y[i]);
        py[Y[i]].insert(X[i]);
    }

    UnionFind ux(NMAX), uy(NMAX);

    for ( auto p : px ) {
        int y0 = *p.second.begin();
        for ( auto y : p.second) {
            uy.unite(y0, y);
        }
    }
    for ( auto p : py ) {
        int x0 = *p.second.begin();
        for ( auto x : p.second) {
            ux.unite(x0, x);
        }
    }

    set<pair<int, int>> used;
    int dots = 0;

    for ( int i = 0; i < N; i++ ) {
        auto pp = make_pair(ux.find(X[i]), uy.find(Y[i]));
        if ( used.find(pp) == used.end() ) {
            used.insert(pp);
            dots += ux.count(pp.first) * ux.count(pp.second);
        }
    }

    ll ans = dots - N;
    cout << ans << '\n';
    return 0;
}

