        if(get<1>(a) == get<1>(b)){
            return get<2>(a) < get<2>(b);
        }
        return get<1>(a) < get<1>(b);
    });

    REP(i, n-1){
        if(get<1>(v[i]) == get<1>(v[i+1])){
            UF.unite(get<0>(v[i]), get<0>(v[i+1]));
        }
    }

    sort(all(v), [](const auto& a, const auto& b){
        if(get<2>(a) == get<2>(b)){
            return get<1>(a) < get<1>(b);
        }
        return get<2>(a) < get<2>(b);
    });

    REP(i, n-1){
        if(get<2>(v[i]) == get<2>(v[i+1])){
            UF.unite(get<0>(v[i]), get<0>(v[i+1]));
