class union_find {
  mutable std::vector<intmax_t> c;

public:
  union_find(size_t n): c(n, -1) {}

  size_t find(size_t v) const {
    if (c[v] < 0) return v;
    return (c[v] = find(c[v]));
  }

  bool unite(size_t u, size_t v) {
    u = find(u);
    v = find(v);
    if (u == v) return false;
    if (-c[u] > -c[v]) std::swap(u, v);
    c[v] += c[u];
    c[u] = v;
    return true;
  }

  bool connected(size_t u, size_t v) const { return (find(u) == find(v)); }

  size_t size() const { return c.size(); }
  size_t size(size_t v) const {
    return -c[find(v)];
  }
};

int main() {
  size_t N;
  scanf("%zu", &N);

  size_t M = 1e5;
  union_find uf(M+M+N);
  for (size_t i = 0; i < N; ++i) {
    int x, y;
    scanf("%d %d", &x, &y);
    --x;
    --y;
    uf.unite(M+M+i, x);
    uf.unite(M+M+i, M+y);
  }

  std::set<size_t> g;
  for (size_t i = 0; i < N; ++i) {
    g.insert(uf.find(M+M+i));
  }

  std::map<size_t, intmax_t> xp, yp, ip;
  for (size_t i = 0; i < M; ++i) {
    ++xp[uf.find(i)];
    ++yp[uf.find(M+i)];
  }
  for (size_t i = 0; i < N; ++i) {
    ++ip[uf.find(M+M+i)];
  }

  intmax_t res = 0;
  for (auto v: g) {
    intmax_t xx = xp.at(v);
    intmax_t yy = yp.at(v);
    intmax_t ii = ip.at(v);
    res += xx*yy - ii;
  }
  printf("%jd\n", res);
}

