#include <iostream>
#include <vector>
#include <map>
using namespace std;

struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

long long N;
vector<long long> x, y, ax, ay;

long long solve() {
    // 座標圧縮
    x.resize(N); y.resize(N); ax.clear(); ay.clear();
    for (int i = 0; i < N; ++i) {
        cin >> x[i] >> y[i];
        ax.push_back(x[i]);
        ay.push_back(y[i]);
    }
    sort(ax.begin(), ax.end());
    ax.erase(unique(ax.begin(), ax.end()), ax.end());
    sort(ay.begin(), ay.end());
    ay.erase(unique(ay.begin(), ay.end()), ay.end());

    // 連結成分分解
    int nx = ax.size(), ny = ay.size();
    UnionFind uf(nx + ny);
    for (int i = 0; i < N; ++i) {
        int ix = lower_bound(ax.begin(), ax.end(), x[i]) - ax.begin();
        int iy = lower_bound(ay.begin(), ay.end(), y[i]) - ay.begin();
        uf.merge(ix, iy+nx);
    }

    // 連結成分ごとに、左ノードと右ノードの個数を数える
    map<int, long long> mx, my;
    for (int i = 0; i < nx; ++i) {
        int r = uf.root(i);
        mx[r]++;
    }
    for (int i = nx; i < nx + ny; ++i) {
        int r = uf.root(i);
        my[r]++;
    }

    long long res = 0;
    for (int r = 0; r < nx + ny; ++r) {
        res += mx[r] * my[r];
    }
    return res - N;
}

int main() {
    cin >> N;
    cout << solve() << endl;
}

