constexpr int X_MAX = 1e5;
vvi all(X_MAX*2+10);

void addPoint(int x, int y) {
  assert(x>0);
  assert(y>0);

  int X = x;
  int Y = X_MAX + y;

  all[X].emplace_back(Y);
  all[Y].emplace_back(X);
}


ll count(const vii& g) {
  si sx;
  si sy;
  for (auto p : g) {
    sx.insert(p.first);
    sy.insert(p.second);
  }

  return ll(sx.size())*ll(sy.size()) - ll(g.size());
}

void dfs(vector<bool>& visited, vii& g, int u) {

  for (int v : all[u]) {
    if (visited[v]) continue;

    if (u<v) {
      g.emplace_back(u,v);
    } else {
      g.emplace_back(v,u);
    }

    visited[v] = true;
    dfs(visited, g, v);
  }

}

