  vector<bool> visited(X_MAX*2+10);
  // 連結成分ごとに
  for (int x=1; x<=X_MAX; x++) {
    if (visited[x]) continue;

    visited[x] = true;

    vii g;
    dfs(visited, g, x);
    ret += count(g);

    //cerr << "x " << x << ", ret " << ret << endl;
  }

  cout << ret << endl;

  return 0;
}

