class UnionFind
{
    vector<int> par;
public:
    UnionFind(int n){par.assign(n,-1);}
    int root(int x)
    {
        if(par[x]<0)return x;
        else return par[x]=root(par[x]);
    }
    bool same(int x,int y)
    {
        return root(x)==root(y);
    }
    bool merge(int x,int y)
    {
        x=root(x);y=root(y);
        if(x==y)return 0;
        if(par[x]>par[y])swap(x,y);
        par[x]+=par[y];
        par[y]=x;
        return 1;
    }
    int size(int x){return -par[root(x)];}
};
