struct UF {
    static const int N = 100100;//書き換え!
    int par[N];
    int rank[N];
    vector<int> group[N];

    UF() {
        rep(i, N) {
            par[i] = -1;
            rank[i] = 0;
            group[i].push_back(i);
        }
    }

    void exist(int x) {
        par[x] = x;
    }

    void init() {
        rep(i, N) {
            par[i] = -1;
            rank[i] = 0;
            group[i].push_back(i);
        }
    }

    int root(int x) {
        if (par[x] == x)return x;
        return par[x] = root(par[x]);
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y)return;
        if (rank[x] < rank[y]) {
            par[x] = y;
            rep(i, group[x].size()) {
                group[y].p_b(group[x][i]);
            }
            group[x].clear();
        } else {
            par[y] = x;
            if (rank[x] == rank[y])++rank[x];
            rep(i, group[y].size()) {
                group[x].p_b(group[y][i]);
            }
            group[y].clear();
        }
    }

    bool top(int x) {
        return x == par[x];
    }
};

