void solve() {
	lli n = 1, m, sum = 0, ans = 0, cnt = 0, cnt0 = 0, ext = 0;
	string s;
	cin >> n;

	v3L num(n);
	set<lli> row[ maxn+1 ];
	set<lli> col[ maxn+1 ];
	bool visX[maxn], visY[maxn];
	MEM( visX, false );
	MEM( visY, false );

	for (auto &x : num) {
		cin >> x.X.X >> x.X.Y;
		x.Y = ++cnt;
		row[ x.X.X-1 ].insert( x.X.Y-1 );
		col[ x.X.Y-1 ].insert( x.X.X-1 );
	}

	queue<lli> nextX, nextY;
	lli nX = maxn, nY = maxn;
	lli flag = 0;

	while ( cnt0 < n ) {
		lli cntX = 1, cntY = 0;

		for ( ext; ext < maxn; ++ext) {
			if ( !visX[ext] ) {
				visX[ext] = true;
				nX = ext;
				nY = maxn;
				break;
			}
		}

		if ( ext == maxn ) break;

		while ( cnt0 < n ) {

			for (auto y : row[nX]) {
				if ( !visY[y] ) {
					visY[y] = true;
					++cnt0;
					++cntY;
					nextY.push(y);
				}
			}

			for (auto x : col[nY]) {
				if ( !visX[x] ) {
					visX[x] = true;
					++cnt0;
					++cntX;
					nextX.push(x);
				}
			}

			if ( !nextX.empty() ) {
				nX = nextX.front();
				nextX.pop();
				++flag;
			}
			else nX = maxn;

			if ( !nextY.empty() ) {
				nY = nextY.front();
				nextY.pop();
				++flag;
			}
			else nY = maxn;

			if ( flag == 0 ) break;
			else flag = 0;
		}

		ans += cntX*cntY;
//		cout << "ans += " << cntX << " * " << cntY << '\n';
	}

	cout << ans-n << '\n';
}

