        setY[idx].insert(y);
    }
    set<int> used;
    ll ans = 0;
    rep(i,0,N){
        int idx = uf.root(i);
        if(used.count(idx) )continue;
        used.insert(idx);
        ll size = uf.size(i);
        ans += ((ll)setX[idx].size() * (ll)setY[idx].size() ) - size;
    }
    cout << ans << endl;
}

