const int MXCOORD = 100000;

int main(int argc, char **argv)
{
  ios_base::sync_with_stdio(false);
  cin.tie(0); cout.tie(0);

  int n; cin >> n;
  vector<pii> pts;
  vector<set<pii>> xpts(MXCOORD+1);
  vector<set<pii>> ypts(MXCOORD+1);

  for(int i=0; i<n; i++) {
    int x, y; cin >> x >> y;
    xpts[x].insert({x, y});
    ypts[y].insert({x, y});
    pts.push_back({x, y});
  }

  map<pair<int, int>, bool> done;

  ll res = 0;
  for(int i=0; i<n; i++) {
    if(!(xpts[pts[i].first].size() > 1 && ypts[pts[i].second].size() > 1)) continue;
    if(done[pts[i]]) continue;

    set<pair<int, int>> ptset;
    queue<pii> q;
    q.push({pts[i]});
    done[pts[i]]= true;

    while(q.size()) {
      pii p = q.front(); q.pop();
      ptset.insert(p);
      for(auto t : xpts[p.first]) {
        if(done[t]) continue;
        q.push(t);
        done[t] = true;
      }
      for(auto t : ypts[p.second]) {
        if(done[t]) continue;
        q.push(t);
        done[t] = true;
      }

      xpts[p.first].clear();
      ypts[p.second].clear();
    }

    set<int> xset, yset;
    for(auto p : ptset) {
      xset.insert(p.first);
      yset.insert(p.second);
    }

    res += 1LL*xset.size()*yset.size() - ptset.size();
  }

  cout << res << endl;

  return 0;
}

