/*
方針として、
x軸かy軸が同じ点の集まりに対して、全(x,y)の格子点が作成される
ので、その点の集まりを作成すればよい

集まりはUnionFindで確認する。
要素は、x軸およびy軸
点(x,y)があると、そのx軸とy軸を統合する。
*/

#include <iostream>
#include <unordered_map>

using namespace std;

const char X = 'x';
const char Y = 'y';

// 軸オブジェクト
struct Axis {
  char name; // x軸かy軸か
  long long value; // 軸の座標
  // unordered_map のキーにするため実装(hashも下で実装している)
  bool operator==(const Axis& other) const { // TODO: 2個めのconstの意味は？
    return name == other.name && value == other.value;
  }
  bool operator!=(const Axis& other) const {
    return !(*this == other);
  }
  string to_s() const { //TODO: << に渡す型は本当は何か？
    return to_string(name) + ":" + to_string(value);
  }
};
namespace std{ //TODO: この書き方面倒くさい… hash()定義するのにstruct外って変じゃない？
    template<>
    class hash<Axis>{
        public:
        size_t operator () ( const Axis &p ) const{ return p.value << 2 + (p.name == X ? 1 : 0);}
        //TODO:どうhash作る？ ひとまずnameは2個しかないので、最終ビットに追加
        //別に一意になる必要はないが、衝突が少ない程良いmapになるはず
    };
}
// 領域
struct Area {
  int x; // x軸の数
  int y; // y軸の数
};
// union find実装
struct UnionFind {
  unordered_map<Axis, Axis> parents;
  unordered_map<Axis, Area> areas; // 領域はrootのみに持たせる。あとで領域ごとに計算するため。

  void add(Axis axis) { // Axisはintみたいな値型とみなして、ポインタ渡しはしない。他の関数も同じ
    if (parents.find(axis) != parents.end()) { //containsがc++17までないので、その代わり
      return;
    }

    parents[axis] = axis;
    areas[axis] = { // 初回はルートになるので、領域を持たせる
      axis.name == X ? 1 : 0,
      axis.name == Y ? 1 : 0};
  }

  void unite(Axis a, Axis b) {
    const Axis& ra = root(a);
    const Axis& rb = root(b);

    if (ra == rb) {
      return;
    }

    parents[rb] = ra;

    // 親になるほうに領域を統合して、他方は削除する
    areas[ra].x += areas[rb].x;
    areas[ra].y += areas[rb].y;
    areas.erase(rb);
  }

  Axis root(Axis a) {
    if (parents[a] != a) {
      parents[a] = root(parents[a]);
    }

    return parents[a];
  }
};

int main() {
  UnionFind uf;
  int n,x,y;
  cin >> n;
  for (int i = 0; i < n; i++) {
    cin >> x;
    cin >> y;
    Axis ax = {X, x};
    Axis ay = {Y, y};
    uf.add(ax); // x軸追加
    uf.add(ay); // y軸追加
    uf.unite(ax, ay); // x,y を統合
  }

  int all_points = 0; // 全操作完了後の点の数
  for (const pair<const Axis, Area>& p : uf.areas) {
    //TODO:debug cout << "axis:" << p.first.to_s() << " area:" << p.second.x << ", " << p.second.y << endl;
    all_points += p.second.x * p.second.y;
  }

  int result = all_points - n; // もともとあったn個を引いたのが、作成された数

  cout << result << endl;

  return 0;
}

