struct SizeAwareUnionFind
{
    vector<int> par, cou;
    SizeAwareUnionFind(int N) : par(N), cou(N) { REP(i, N) par[i] = i, cou[i] = 1; }
    int find(int x) { return (par[x] == x) ? x : (par[x] = find(par[x])); }
    void unite(int x, int y) {
        x = find(x), y = find(y); if (x == y) return;
        if (cou[x] < cou[y]) swap(x, y); 
        par[y] = x, cou[x] += cou[y];
    }
    int count(int x) { return cou[find(x)]; }
    bool same(int x, int y) { return find(x) == find(y); }
};


int main()
{
    int N;
    cin >> N;
    vector<int> x(N);
    vector<int> y(N);
    REP(i, N){ cin >> x[i]; cin >> y[i]; }

    SizeAwareUnionFind uf(200009);

    REP(i, N) uf.unite(x[i], y[i] + 100000);

    map<int, int> eds;
    map<int, set<int>> ex, ey;
    REP(i, N)
    {
        eds[uf.find(x[i])]++;
        ex[uf.find(x[i])].insert(x[i]);
        ey[uf.find(x[i])].insert(y[i]);
    }

    lint ret = 0;
    for (auto pa : eds)
    {
        lint n = uf.count(pa.first);
        ret += (lint)ex[pa.first].size() * ey[pa.first].size() - pa.second;
    }
    cout << ret << endl;
    return 0;
}

