vector<bool> used;

void dfs(int cur, int &cnt, set<int> &xs, set<int> &ys) {
    if (used[cur]) return;
    cnt++;
    used[cur] = true;
    xs.insert(ps[cur].first);
    ys.insert(ps[cur].second);

    for(int to : g[cur]) {
        dfs(to, cnt, xs, ys);
    }
}

