    sort(all(ord), [&](int i, int j){
        return ps[i].first != ps[j].first ? ps[i].first < ps[j].first : ps[i].second < ps[j].second;
    });
    rep(i,n-1){
        if (ps[ord[i]].first == ps[ord[i+1]].first){
            g[ord[i]].push_back(ord[i+1]);
            g[ord[i+1]].push_back(ord[i]);
        }
    }

    sort(all(ord), [&](int i, int j){
        return ps[i].second != ps[j].second ? ps[i].second < ps[j].second : ps[i].first < ps[j].first;
