		int a, b; cin >> a >> b;
		P[i] = pii(a, b);
		x[b].PB(a, i);
		y[a].PB(b, i);
	}

	rep(i, 100010) {
		sort(all(x[i]));
		sort(all(y[i]));
	}

	int ans = 0;

	rep(i, N) {
		if (visited[i]) continue;
		int v = bfs(i);
		ans += v;
	}

	cout << ans << endl;
}

