template <class T>
struct BIT {
	vector<T> data;
	BIT(int n) {
		data.assign(n + 1, 0);
	}

	T sum (int i) {
		T res = 0;
		while (i > 0) {
			res += data[i];
			i -= i & -i;
		}
		return res;
	}

	void add(int i, T x) {
		while (i < data.size()) {
			data[i] += x;
			i += i & -i;
		}
	}
};

int main() {
	int N;
	cin >> N;
	vector<P> v(N);
	for (int i = 0; i < N; ++i) {
		int x, y;
		cin >> x >> y;
		v[i] = P(x, y);
	}
	sort(v.begin(), v.end());

	int sz = 1e5 + 10;
	BIT<ll> bit(sz);
	ll res = 0;
	for (int i = 0; i < N; ++i) {
		int x = v[i].first, y = v[i].second;
		ll s = (bit.sum(y) - bit.sum(y - 1) > 0 ? 1 : 0);
		ll t = bit.sum(sz) - bit.sum(y);
		res += s * t;
		if (s == 0) { bit.add(y, 1); }
	}
	BIT<ll> bit2(sz);
	sort(v.rbegin(), v.rend());
	for (int i = 0; i < N; ++i) {
		int x = v[i].first, y = v[i].second;
		ll s = (bit2.sum(y) - bit2.sum(y - 1) > 0 ? 1 : 0);
		ll t = bit2.sum(y - 1);
		res += s * t;
		if (s == 0) { bit2.add(y, 1); }
	}
	BIT<ll> bit3(sz);
	sort(v.begin(), v.end(), [](const P& a, const P& b){
			if (a.first == b.first) { return a.second < b.second; }
			return a.first > b.first; });
	for (int i = 0; i < N; ++i) {
		int x = v[i].first, y = v[i].second;
		ll s = (bit3.sum(y) - bit3.sum(y - 1) > 0 ? 1 : 0);
		ll t = bit3.sum(sz) - bit3.sum(y);
		res += s * t;
		if (s == 0) { bit3.add(y, 1); }
	}
	BIT<ll> bit4(sz);
	sort(v.begin(), v.end(), [](const P& a, const P& b){
			if (a.first == b.first) { return a.second > b.second; }
			return a.first < b.first; });
	for (int i = 0; i < N; ++i) {
		int x = v[i].first, y = v[i].second;
		ll s = (bit4.sum(y) - bit4.sum(y - 1) > 0 ? 1 : 0);
		ll t = bit4.sum(y - 1);
		res += s * t;
		if (s == 0) { bit4.add(y, 1); }
	}

	cout << res << endl;

	return 0;
}

