class UnionFind
{
    vector<int> par;
public:
    UnionFind(int n){par.assign(n,-1);}
    int root(int x)
    {
        if(par[x]<0)return x;
        else return par[x]==root(par[x]);
    }
    bool same(int x,int y)
    {
        return root(x)==root(y);
    }
    bool merge(int x,int y)
    {
        x=root(x);y=root(y);
        if(x==y)return 0;
        if(par[x]>par[y])swap(x,y);
        par[x]+=par[y];
        par[y]=x;
        return 1;
    }
    int size(int x){return -par[root(x)];}
};
const long long ma=110000;
long long n;
vector<long long> x,y;

long long solve()
{
    cin>>n;
    UnionFind uf(ma*2);
    x.resize(n);y.resize(n);
    for(int i=0;i<n;i++)cin>>x[i]>>y[i],uf.merge(x[i],y[i]+ma);

    map<int,long long> mx,my;
    for(int i=0;i<ma;i++)mx[uf.root(i)]++;
    for(int i=ma;i<2*ma;i++)my[uf.root(i)]++;
    long long res=0;
    for(int r=0;r<ma*2;r++)res+=mx[r]*my[r];
    return res-n;
}
main()
{
    cin.tie(0);
    ios_base::sync_with_stdio(0);
    cout<<solve()<<endl;
    return 0;
}

