struct UnionFind {
	std::vector<int> data;

	UnionFind(int n) {
		data.assign(n, -1);
	}
	void unite(int x, int y) {
		x = find(x); y = find(y);
		if(x == y) return;
		if(data[x] > data[y]) std::swap(x, y);
		data[x] += data[y];
		data[y] = x;
	}
	int find(int k) {
		if(data[k] < 0) return k;
		return data[k] = find(data[k]);
	}
	i64 size(int k) {
		return -data[find(k)];
	}
};

int main() {
	int n; scanf("%d", &n);
	std::vector<std::vector<int>> X(1e5), Y(1e5);
	std::vector<int> x(n), y(n);
	for(int i = 0; i < n; i++) {
		scanf("%d%d", &x[i], &y[i]); x[i]--; y[i]--;

		X[x[i]].push_back(i);
		Y[y[i]].push_back(i);
	}

	UnionFind A(1e5), B(1e5);
	for(int i = 0; i < X.size(); i++) {
		if(X[i].size() < 2) continue;

		bool f = false;
		for(auto p: X[i]) f |= (Y[y[p]].size() > 1);
		if(f) for(auto p: X[i]) B.unite(y[p], y[X[i].front()]);
	}
	for(int i = 0; i < Y.size(); i++) {
		if(Y[i].size() < 2) continue;

		bool f = false;
		for(auto p: Y[i]) f |= (X[x[p]].size() > 1);
		if(f) for(auto p: Y[i]) A.unite(x[p], x[Y[i].front()]);
	}

	i64 ans = 0;
	std::set<int> st;
	for(int i = 0; i < n; i++) {
		int latte = A.find(x[i]), malta = B.find(y[i]);
		if(st.count(latte)) ans--;
		if(A.size(latte) < 2 or B.size(malta) < 2 or st.count(latte)) continue;
		ans += A.size(latte) * B.size(malta) - 1;
		st.insert(latte);
	}
	printf("%lld\n", ans);
	return 0;
}

