    vector<pair<ll,ll>> p(n), pp(n);
    rep(i,n) p[i] = {x[i], y[i]};
    rep(i,n) pp[i] = {y[i], x[i]};
    sort(p.begin(), p.end());
    ll res=0;

    UnionFind tree1(x.size()+1);
    rep(i,n-1){
        if(p[i].first == p[i+1].first) tree1.unite(p[i].second, p[i+1].second);
    }

    UnionFind tree2(y.size()+1);
    rep(i,n-1){
        if(pp[i].first == pp[i+1].first) tree2.unite(pp[i].second, pp[i+1].second);
    }

    vector<bool> used(100001, false);
