void merge(int x,int y,unordered_map<int,int>& uf){
  x=find(x,uf),y=find(y,uf);
  if(x>y)swap(x,y);
  uf[x]+=uf[y];
  uf[y]=x;
}
int find(int x,unordered_map<int,int>& uf){
  auto it=uf.find(x);
  if(it==uf.end()){
    uf[x]=-1;
  }
  if(uf[x]<0)return x;
  return uf[x]=find(uf[x],uf);
}

