struct UnionFind {
    vector<int> parent;
    int size;
    vector<set<int>> V;
    UnionFind(int size) {
        reset(size);
    }
    void reset(int size) {
        this->size = size;
        parent.resize(size);
        REP(i,size) parent[i]=i;
        V.resize(size);
        REP(i,size) V[i].insert(i);
    }
    int root(int i) {
        if (parent[i] == i) return i;
        return parent[i] = root(parent[i]);
    }
    void merge(int i, int j) {
        int ir = root(i);
        int jr = root(j);
        if (ir == jr) return;
        int next = (V[ir].size() >= V[jr].size()) ? ir : jr;
        int hide = (ir == next) ? jr : ir;
        parent[ir] = parent[jr] = next;
        for (int n:V[hide]) V[next].insert(n);
        V[hide].clear();
    }
    bool same(int i, int j) {
        return root(i) == root(j);
    }
    int vsize(int i) {
        return (int)V[i].size();
    }
};


void solve(int _t) {
    cin>>N;
    auto uf = new UnionFind(SIZE);
    int x,y;
