// Union-Find モジュール
struct union_find {
    vector<ull> par;
    vector<ull> num;
    union_find(ull n) : par(n, 0), num(n, 1) { iota(ALL_OF(par), 0); }
    ull root(ull i) { return par[i] == i ? i : (par[i] = root(par[i])); }
    bool same(ull i, ull j) { return root(i) == root(j); }
    void unite(ull i, ull j) {
        ull ri = root(i);
        ull rj = root(j);
        if (ri != rj) {
            if (num[ri] > num[rj]) swap(ri, rj);
            par[ri] = rj;
            num[rj] += num[ri];
        }
    }
};

// 処理内容
int main() {

    ll n; cin >> n;
    vector<ll> x(n), y(n);
    REP(i, n) {
        cin >> x[i] >> y[i];
        --x[i];
        --y[i];
    }

    constexpr ll m = 100000;
    union_find uf(m * 2);
    REP(i, n) {
        ll u = x[i];
        ll v = y[i] + m;
        uf.unite(u, v);
    }
    REP(i, m*2) uf.root(i); // 根につなぎなおす

    vector<ull> unquf = uf.par;
    UNIQUE(unquf);
    ll unqsz = unquf.size();
    map<ll, ll> sahzuf;
    REP(i, unquf.size()) sahzuf[unquf[i]] = i;

    vector<ll> en(unqsz, 0);
    vector<ll> xn(unqsz, 0);
    vector<ll> yn(unqsz, 0);
    REP(i, n) {
        ll p = sahzuf[uf.par[x[i]]];
        ++en[p];
    }
    REP(i, m) {
        ++xn[sahzuf[uf.par[i]]];
        ++yn[sahzuf[uf.par[i+m]]];
    }

    ll ans = 0;
    REP(i, unqsz) {
        ll cplt = xn[i] * yn[i];
        ll curr = en[i];
        ans += cplt - curr;
    }
    cout << ans << endl;

}

