// one-based numbering
struct UnionFind {
    vector<int> data;
    // i: (data[i] < 0) -> group size, (data[i] > 0) -> parent;
    UnionFind(int n) {
        data.resize(n+1, -1);
    }
    int find(int x) {
        if(data[x] < 0) return x;
        else return data[x] = find(data[x]);
    }
    int size(int x) {
        return -data[find(x)];
    }
    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return false;
        if (data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }
    bool same(int x, int y) {
        x = find(x); y = find(y);
        return x == y;
    }
};

vector<int> v[100010];
int main() {
    int n; cin >> n;
    UnionFind uf(100010);
    for (int i = 0; i < n; i++) {
        int a, b; cin >> a >> b;
        v[a].emplace_back(b);
    }
    for (int i = 1; i <= 100010; i++) {
        for (auto &x: v[i]) {
            uf.unite(v[i].front(), x);
        }
    }
    long long cnt = 0;
    for (int i = 1; i <= 100010; i++) {
        if (v[i].empty()) continue;
        cnt += uf.size(v[i].front());
    }
    cout << cnt - n << endl;
    return 0;
}

