}

class UnionFind{
public:
	vector<int> par;
	//0-indexed
	UnionFind(int n){init(n);}
	void init(int n = 1) {
		par.resize(n);
		for (int i = 0; i < n; ++i) par[i] = i;
	}
	int root(int x = 1){
		if(par[x]==x)return x;
		else{
			return par[x] = root(par[x]);
		}
	}
	void unite(int x = 1,int y = 1){
		x = root(x);
		y = root(y);
		if(x==y)return;
		else par[x] = y;
	}
	int setsize(){
		set<int> se;
		for(auto x:par){
			se.insert(root(x));
		}
		return se.size();
	}
};

int main(){
	ll N;
	cin >> N;
	vector<P> pnt;
	vector<ll> X(100001,-1),Y(100001,-1);
	UnionFind uf(100003);
	FOR(i,0,N){
		ll x,y;
		cin >> x >> y;
		pnt.push_back({x,y});
		if(X[x]!=-1){
			uf.unite(i,X[x]);
		}else{
			X[x] = i;
		}
		if(Y[y]!=-1){
			uf.unite(i,Y[y]);
		}else{
			Y[y] = i;
		}
	}
	vector<P> G[N];
	FOR(i,0,N){
		G[uf.root(i)].push_back(pnt[i]);
	}
	ll ans = 0;
	FOR(i,0,N){
		ans += solve(G[i]);
	}
	cout << ans << endl;

}

