vector<bool> visited;
vector<bool> usedX;
vector<bool> usedY;

vector<int> dfs(int x){
    if(visited[x]) return vector<int>();
    visited[x] = true;
    vector<int> ret;
    ret.push_back(x);
    pii p = P[x];
    if(!usedX[p.first]) for(int ix:idX[p.first]){
        usedX[p.first] = true;
        if(!visited[ix]) for(int r:dfs(ix)) ret.push_back(r);
    }
    if(!usedY[p.second]) for(int iy:idY[p.second]){
        usedY[p.second] = true;
        if(!visited[iy]) for(int r:dfs(iy)) ret.push_back(r);
    }
    return ret;
}

ll calc(vector<int> X){
    ll ret = 0LL;
    set<int> mx, my;
    for(auto i:X){
        mx.insert(P[i].first);
        my.insert(P[i].second);
    }
    ret = (ll)mx.size()*(ll)my.size()-(ll)X.size();
    return ret;
}

int solve(){
    visited.assign(N, false);
    usedX.assign(1e5+1, false);
    usedY.assign(1e5+1, false);

    ll ans = 0LL;
    for (int i = 0; i < N; i++)
    {
        vector<int> idx = dfs(i);
        if(!idx.empty()){
            ans += calc(idx);
        }
    }
    cout << ans << endl;
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

