template <typename T>
struct UnionFind {
  vector<int> par, rank;
  vector<T> wSum;

  UnionFind(int n = 1, T init = 0) : par(n), rank(n, 0), wSum(n, init) {
    iota(begin(par), end(par), 0);
  }
  int root(int x) {
    if (par[x] == x) {
      return x;
    } else {
      int r = root(par[x]);
      wSum[x] += wSum[par[x]];
      return par[x] = r;
    }
  }
  T weight(int x) {
    root(x);
    return wSum[x];
  }
  bool isSame(int x, int y) { return root(x) == root(y); }
  void unite(int x, int y, T w = 0) {
    w += weight(x) - weight(y);
    x = root(x);
    y = root(y);
    if (x == y) return;

    if (rank[x] < rank[y]) swap(x, y), w = negate<T>()(w);
    rank[x] += rank[y];
    par[y] = x;
    wSum[y] = w;
  }
  T getDiff(int x, int y) { return weight(y) - weight(x); }
};

const int V = 1e5;

int main() {
  int n;
  cin >> n;

  vector<int> x(n), y(n);
  for (int i = 0; i < n; i++) {
    cin >> x[i] >> y[i];
    y[i] += V;
  }

  UnionFind<int> uf(2 * V);
  for (int i = 0; i < n; i++) uf.unite(x[i], y[i]);

  vector<bool> used(2 * V, false);
  vector<int> cx(2 * V, 0), cy(2 * V, 0);
  for (int i = 0; i < n; i++) {
    int rx = uf.root(x[i]);
    int ry = uf.root(y[i]);
    if (!used[x[i]]) cx[rx]++;
    if (!used[y[i]]) cy[ry]++;
    used[x[i]] = true;
    used[y[i]] = true;
  }

  ll sum = 0;
  for (int i = 0; i < 2 * V; i++) {
    if (!cx[i] || !cy[i]) continue;
    sum += 1LL * cx[i] * cy[i];
  }
  cout << sum - n << endl;
}

