class DSU
{
    vector<ll> par;
    vector<pll> rank;

public:
    pair<ll, pll> Find(ll v)
    {
        if (par[v] != v)
            par[v] = Find(par[v]).first;
        return {par[v], rank[v]};
    }
    void Union(ll v, ll u)
    {
        ll vroot = Find(v).first;
        ll uroot = Find(u).first;
        if (rank[vroot].first + rank[vroot].second < rank[uroot].first + rank[uroot].second)
        {
            par[vroot] = uroot;
            rank[uroot].first += rank[vroot].first;
            rank[uroot].second += rank[vroot].second;
        }
        else if (rank[vroot].first + rank[vroot].second > rank[uroot].first + rank[uroot].second)
        {
            par[uroot] = vroot;
            rank[vroot].first += rank[uroot].first;
            rank[vroot].second += rank[uroot].second;
        }
        else
        {
            par[uroot] = vroot;
            rank[vroot].first += rank[uroot].first;
            rank[vroot].second += rank[uroot].second;
        }
    }
    DSU(ll n)
    {
        for (ll i = 0; i <= n; i++)
        {
            par.push_back(i);
            if (i < xc)
                rank.push_back({1, 0});
            else
                rank.push_back({0, 1});
        }
    }
};
