#define find DSUU
#define merge mergeeee
const int maxn=1e5+10;
int n,pa[maxn],sz[maxn];
bool vis[maxn];
int find(int h){
    return h==pa[h]?h:pa[h]=find(pa[h]);
}
vector<int> b[maxn];
set<int> s[maxn];
void merge(int x,int y){
    x=find(x),y=find(y);
    if(x==y)return;
    if(s[x].size()<s[y].size())swap(x,y);
    pa[y]=x;
    for(auto j:s[y])
        s[x].insert(j);
    sz[x]+=sz[y];
    return;
}


int main(){
    scanf("%d",&n);
    int x,y;
    for(int i=1;i<=n;i++){
        scanf("%d%d",&x,&y);
        s[x].insert(y);
        b[y].push_back(x);
    }
    for(int i=1;i<=100000;i++)
        pa[i]=i,sz[i]=1;
       // cout<<"What did you merge\n";
    for(int i=1;i<=100000;i++){
        if(b[i].empty())continue;
        for(int j:b[i])
        merge(j,b[i].back());
    }
    long long ans=0;
    for(int i=1;i<=100000;i++){
            if(b[i].empty())continue;
            int j=find(b[i][0]);
        if(!vis[j]){
            vis[j]=true;
            ans+=(1LL*(int)s[j].size()*sz[j]);
        }
    }
    printf("%lld\n",ans-n);
}
