/* UnionFind */

struct UnionFind {
  vector<int> data;
  UnionFind(int s): data(s, -1) {}

  int root(int x) {
    if (data[x] < 0) return x;
    return data[x] = root(data[x]);
  }

  bool set(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return true;
  }

  bool check(int x, int y) {
    return root(x) == root(y);
  }

  int size(int x) {
    return -data[root(x)];
  }
};

int N;
int X[SIZE], Y[SIZE];
pair<int,int> pX[SIZE], pY[SIZE];
set<int> ssX[SIZE], ssY[SIZE];

int main() {

  scanf("%d", &N);

  for (int i=0; i<N; i++) {
    scanf("%d%d", X+i, Y+i);
    pX[i] = {X[i], i};
    pY[i] = {Y[i], i};
  }

  sort(pX, pX+N);
  sort(pY, pY+N);

  UnionFind uf(N);

  for (int i=0; i<N-1; i++) {
    if (pX[i].first == pX[i+1].first)
      uf.set(pX[i].second, pX[i+1].second);

    if (pY[i].first == pY[i+1].first)
      uf.set(pY[i].second, pY[i+1].second);
  }


  for (int i=0; i<N; i++) {
    int r = uf.root(i);
    ssX[r].insert(X[i]);
    ssY[r].insert(Y[i]);
  }

  ll ans = 0;

  for (int i=0; i<N; i++) {
    if (i == uf.root(i)) {
      ll num = (ll)ssX[i].size() * ssY[i].size();
      num -= uf.size(i);
      ans += num;
    }
  }

  cout << ans << endl;

  return 0;
}

