bool cmpy (point &a, point &b) {
    return a.y < b.y;
}

int main() {
    int N;
    cin >> N;
    set<int> xaxis, yaxis;
    point xp[N+1], yp[N+1];
    for (int i = 0, x, y; i < N; i++) {
        cin >> x >> y;
        xp[i] = yp[i] = {x, y};
    }
    xp[N] = yp[N] = {-1, -1};
    sort(xp, xp+N, cmpx);
    sort(yp, yp+N, cmpy);
    for (int i = 1, last = 0, nowx = xp[0].x; i <= N; i++) {
        if (xp[i].x != nowx) {
            if (i > last + 1) {
                xaxis.insert(nowx);
                while (last < i) yaxis.insert(xp[last++].y);
            } else last = i;
            nowx = xp[i].x;
        }
    }
    for (int i = 1, last = 0, nowy = yp[0].y; i <= N; i++) {
        if (yp[i].y != nowy) {
            if (i > last + 1) {
                yaxis.insert(nowy);
                while (last < i) xaxis.insert(yp[last++].x);
            } else last = i;
            nowy = yp[i].y;
        }
    }
    cout << xaxis.size() * yaxis.size() - N;
    return 0;
}

