int main(void) {
  // Here your code !

  scanf("%d", &n);

  for (int i = 0; i < n; ++i) {
    scanf("%d %d", &(x[i]), &(y[i]));
  }

  UnionFind uf(MAX_N * 2 + 20);

  for (int i = 0; i < n; ++i) {
    int node_x = x[i];
    int node_y = y[i] + MAX;

    uf.unite(node_x, node_y);
  }

  unordered_map<int, int> conn2edgenum;

  for (int i = 0; i < n; ++i) {
    int node_x = x[i];
    conn2edgenum[uf.find(node_x)] += 1;
  }

  unordered_set<int> xs;
  for (int i = 0; i < n; ++i) {
    int node_x = x[i];
    xs.insert(x[i]);
  }

  unordered_map<int, ll> conn2xnodenum;
  for (auto &e : xs) {
    conn2xnodenum[uf.find(e)] += 1LL;
  }

  unordered_set<int> ys;
  for (int i = 0; i < n; ++i) {
    int node_y = y[i] + MAX;
    ys.insert(node_y);
  }

  unordered_map<int, ll> conn2ynodenum;
  for (auto &e : ys) {
    conn2ynodenum[uf.find(e)] += 1LL;
  }

  ll ans = 0LL;

  for (auto &e : conn2edgenum) {
    int key = e.first;

    ans += (ll)(conn2xnodenum[key] * conn2ynodenum[key]) - (ll)(conn2edgenum[key]);
  }

  printf("%lld\n", ans);

  return 0;
}

