class UnionFind{
	vector<int> to;
	vector<int> cnt;
	vector<int> rank;

public:
	UnionFind(int N) {
		to = vector<int>(N); REP(i, N) to[i] = i;
		cnt = vector<int>(N, 1);
		rank = vector<int>(N, 1);
	}

	size_t size() {
		return to.size();
	}

	int root(int node) {
		if (node == to[node]) {
			return node;
		}
		to[node] = root(to[node]);
		return to[node];
	}

	int count(int node) {
		return cnt[root(node)];
	}

	int same(int a, int b) {
		return root(a) == root(b);
	}


	void unite(int a,int b){
		if (rank[a] < rank[b]) swap(a, b);
		int rootb = root(b), roota = root(a);
		to[rootb] = roota;
		cnt[roota] += cnt[rootb];
		if (rank[a] == rank[b]) ++rank[a];
	}
};

void DFS(int node, unordered_map<int, unordered_set<int> >& G, vector<bool>& check, vector<int>& res) {
	if (check[node]) {
		return;
	}
	check[node] = true;
	res.push_back(node);
	for (auto& to : G[node]) {
		DFS(to, G, check, res);
	}
}

void solve() {
	unordered_map<int, unordered_set<int>> xy;
	unordered_map<int, unordered_set<int>> yx;
	int N; cin >> N;
	vector<pii> ps;
	REP(i, N){
		int x, y; cin >> x >> y;
		ps.emplace_back(x, y);
	}

	for (auto& p : ps) {
		xy[p.first].emplace(p.second);
		yx[p.second].emplace(p.first);
	}

	vector<int> xs;
	vector<int> ys;
	for (auto& a : xy) {
		xs.emplace_back(a.first);
	}
	for (auto& a : yx) {
		ys.emplace_back(a.first);
	}

	unordered_map<int, unordered_set<int> > G;

	REP(i, N) {
		for (auto& xs : yx) {
			int y = xs.first;
			int old = -1;
			for (auto& x : xs.second) {
				if (old != -1) {
					G[old].emplace(x);
					G[x].emplace(old);
				}
				old = x;
			}
		}
	}

	vector<bool> check(1e5+1);
	int cnt = 0;
	for (auto& x : xs) if(not check[x]) {
		vector<int> res;
		DFS(x, G, check, res);

		unordered_set<int> se;
		for (auto& xx : res) {
			for (auto y : xy[xx]) {
				se.emplace(y);
			}
		}

		for (auto& xx : res) {
			cnt += se.size() - xy[xx].size();
		}
	}
	cout << cnt << endl;
}

