const int maxn = 1e6 + 5;

struct dsu0 {
    vector<int> par, siz;
    int n;
    int cc;
    int largest;
    void init(int n) {
	assert(n>0);
	this->n=n;
	cc=n;
	par.resize(n+10);siz.resize(n+10);
	for (int i=0; i<n; i++) par[i]=i,siz[i]=1;
	largest=1;
    }
    int parent(int x) {
	assert(x>=0 && x<n);
	return par[x]==x?x:par[x]=parent(par[x]);
    }
    bool join(int x, int y) {
	x=parent(x);y=parent(y);
	if (x==y) return false;
	cc--;
	if (siz[x]<siz[y]) swap(x,y);
	siz[x]+=siz[y];par[y]=x;
	largest=max(largest,siz[x]);
	return true;
    }
};

int n;
const int N = 1e5;

dsu0 dsu;

int row[maxn], col[maxn];


int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);

    cin>>n;
    dsu.init(N+N);

    for (int i=0; i<n; i++) {
	int x, y;
	cin>>x>>y;
	--x;
	--y;
	dsu.join(x,y+N);
    }

    for (int i=0; i<N; i++) {
	row[dsu.parent(i)]++;
    }
    for (int i=N; i<N+N; i++) {
	col[dsu.parent(i)]++;
    }

