typedef long long ll;
vector<int> xc[100000], yc[100000];
int n, k, t1, t2, x[100000], y[100000], p[100000], vis[100000];
pair<int, int> a[100000];

int g(int x)
{
    if (p[x] != x)
        return p[x] = g(p[x]);
    return x;
}

void stb(vector<int> &a, vector<int> &b)
{
    if (a.size() > b.size())
        swap(a, b);
    for (int i : a)
        b.push_back(i);
    a = vector<int>();
}

void f(int x, int y)
{
    x = g(x);
    y = g(y);
    if (x == y)
        return;

    stb(xc[x], xc[y]);
    stb(yc[x], yc[y]);
    p[x] = y;
}

int main()
{
    memset(x, -1, sizeof x);
    memset(y, -1, sizeof y);
    cin >> n;
    for (int i = 0; i < n; ++i)
    {
        cin >> t1 >> t2;
        a[i] = {t1, t2};
    }
    for (int i = 0; i < n; ++i)
    {
        p[i] = i;
        xc[i].push_back(a[i].first);
        yc[i].push_back(a[i].second);
    }
    for (int i = 0; i < n; ++i)
    {
        int t1, t2;
        tie(t1, t2) = a[i];
        if (x[t1] != -1)
            f(i, x[t1]);
        if (y[t2] != -1)
            f(i, y[t2]);
        x[t1] = i;
        y[t2] = i;
    }
    ll sum = 0;
    for (int i = 0; i < n; ++i)
    {
        int x = g(i);
        if (!vis[x])
        {
            sort(xc[x].begin(), xc[x].end());
            sort(yc[x].begin(), yc[x].end());
            ll a = unique(xc[x].begin(), xc[x].end()) - xc[x].begin(),
               b = unique(yc[x].begin(), yc[x].end()) - yc[x].begin();
            sum += a * b;
            //cout << a << " " << b << endl;
            vis[x] = 1;
        }
    }
    cout << sum - n << endl;
}

