class union_find {
private:
    vector<int> parent, rank, gs;
    int size;

public:
    int count_group;
    union_find() = default;
    union_find(int n) { init(n); }

    void init(int n) {
        size = n;
        count_group = n;
        parent.resize(size);
        rank.assign(size, 0);
        gs.assign(size, 1);
        for (int i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] == x)
            return x;
        else
            return parent[x] = find(parent[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) {
            parent[x] = y;
            gs[y] += gs[x];
        } else {
            parent[y] = x;
            gs[x] += gs[y];
            if (rank[x] == rank[y]) ++rank[x];
        }
        --count_group;
    }

    bool is_same_group(int x, int y) {
        return find(x) == find(y);
    }

    int group_size(int x) {
        return gs[find(x)];
    };
};

void solve() {
    //const i64 mod = 1'000'000'007;

    i64 N;
    cin >> N;

    vector<pair<i64,i64>> xy(N);
    rep(i,0,N) cin >> xy[i].first >> xy[i].second;

    unordered_map<i64,vector<i64>> xtoys;
    rep(i,0,N){
        xtoys[xy[i].first].emplace_back(xy[i].second);
    }

    for(auto& p:xtoys){
        sort(begin(p.second),end(p.second));
    }

    vector<i64> ys;
    rep(i,0,N) ys.emplace_back(xy[i].second);
    sort(begin(ys),end(ys));
    ys.erase(unique(begin(ys),end(ys)),end(ys));

    unordered_map<i64,i64> zip;
    rep(i,0,ys.size()){
        zip[ys[i]]=i;
    }

    vector<i64> cnt(ys.size());

    union_find uf(N);

    i64 ans=0;
    i64 zx=0;
    for(auto& p:xtoys){
        {
            unordered_set<i64> skip;
            for(auto y:p.second){
                i64 zy=zip[y];
                if(skip.find(zy)!=skip.end()) continue;

                ans+=uf.group_size(zy)-1;
                skip.insert(uf.find(zy));
            }
        }
        {
            i64 y0=p.second.front();
            i64 zy0=zip[y0];
            for(auto y:p.second){
                if(y0==y) continue;
                i64 zy=zip[y];
                if(uf.is_same_group(zy0,zy)) continue;
                ans+=zx-cnt[zy];
            }
            for(auto y:p.second){
                if(y0==y) continue;
                i64 zy=zip[y];
                uf.unite(zy0,zy);
            }
        }
        for(auto y:p.second){
            i64 zy=zip[y];
            ++cnt[zy];
        }
        ++zx;
    }

    cout << ans << endl;
}

int main() {
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

