int dfs(int px,int py,int&cntx,int&cnty)
{
    if(!visx[px])cntx++;
    if(!visy[py])cnty++;
    visx[px]=visy[py]=1;
    int ret = 1;
    for(int y:gx[px])
    {
        if(!visy[y])
            ret += dfs(px,y,cntx,cnty);
    }
    for(int x:gy[py])
    {
        if(!visx[x])
            ret += dfs(x,py,cntx,cnty);
    }
    return ret;
}
