const LL mod=1000000007;
const LL LINF=1LL<<60;
const int INF=1<<30;
int dx[]={1,0,-1,0};
int dy[]={0,1,0,-1};


const int M_N=200001;

struct UnionFind{
    int par[M_N];
    int rank[M_N];
    LL number[M_N];

    void init(int n){
        for(int i=0;i<n;i++){
            par[i]=i;
            rank[i]=0;
            number[i]=1;
        }
    }

    int find(int x){
        if(par[x]==x){
            return x;
        }
        else{
            return par[x]=find(par[x]);
        }
    }

    void unite(int x,int y){
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(rank[x]<rank[y]){
            par[x]=y;
            number[y]+=number[x];
        }
        else{
            par[y]=x;
            if(rank[x]==rank[y]) rank[x]++;
            number[x]+=number[y];
        }
    }

    bool same(int x,int y){
        return find(x)==find(y);
    }

    int get(int x){
        return number[find(x)];
    }

};

vector<int> v[100001],u[100001];

int main(){
    int n;cin >> n;
    UnionFind uf;
    uf.init(100001);
    for (int i = 0; i < n; i++) {
        int x,y;cin >> x >> y;
        v[x].pb(y);
        u[y].pb(x);
    }
    for (int i = 1; i <= 100000; i++) {
        for (int j = 1; j < u[i].size(); j++) {
            uf.unite(u[i][j],u[i][j-1]);
        }
    }
    LL ans = 0;
    vector<bool> used(100001,false);
    for (int i = 1; i <= 100000; i++) {
        if(used[uf.find(i)]) continue;
        if(uf.get(i)==1){
            ans += (LL)v[i].size();
            continue;
        }
        LL t = 1;
        bitset<100001> bs;
        for (int j = 0; j < v[i].size(); j++) {
            bs[v[i][j]]=1;
        }
        for (int j = i+1; j <= 100000; j++) {
            if(!uf.same(i,j)) continue;
            t++;
            for (int k = 0; k < v[j].size(); k++) {
                bs[v[j][k]]=1;
            }
        }
        used[uf.find(i)]=true;
        ans += bs.count()*t;
    }
    cout << ans-n << endl;
    return 0;
}

