// size用
struct UnionFind {
    vector<ll> par;
    vector<ll> sizes;

    UnionFind(ll n) : par(n), sizes(n, 1) { REP(i, n) par[i] = i; }

    ll find(ll x) {
        if(x == par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(ll x, ll y) {
        x = find(x);
        y = find(y);

        if(x == y) return;

        if(sizes[x] < sizes[y]) swap(x, y);

        par[y] = x;
        sizes[x] += sizes[y];
        sizes[y] = 0;
    }

    bool same(ll x, ll y) { return find(x) == find(y); }

    ll size(ll x) { return sizes[find(x)]; }
};

void solve() {
    LCIN(N);
    UnionFind xys(2e5);
    VL xs, ys;
    REP(i, N) {
        LCIN(x, y);
        x--, y--;
        xys.unite(x, y + 1e5);
        xs.emplace_back(x), ys.emplace_back(y + 1e5);
    }
    VL xnum(1e5), ynum(1e5);
    VL idx;
    sort(All(xs));
    sort(All(ys));
    xs.erase(unique(All(xs)), xs.end());
    ys.erase(unique(All(ys)), ys.end());
    REP(i, sz(xs)) {
        xnum[xys.find(xs[i])]++;
        ynum[xys.find(ys[i])]++;
        idx.emplace_back(xys.find(xs[i]));
        idx.emplace_back(xys.find(ys[i]));
    }
    sort(All(idx));
    idx.erase(unique(All(idx)), idx.end());
    ll ans = 0;
    FOREACH(i, idx) { ans += xnum[i] * ynum[i]; }
    COUT(ans - N);
}

