	cin>>N;
	int x[MAX], y[MAX];
	rep(i,N)cin>>x[i]>>y[i];
	init(N);

	vector<P> xc(N);
	rep(i,N)xc[i]=mp(x[i], i);
	sort(xc.begin(), xc.end());
	rep(i,N-1)if(xc[i].first==xc[i+1].first){
		unite(xc[i].second,xc[i+1].second);
	}
	vector<P> yc(N);
	rep(i,N)yc[i]=mp(y[i], i);
	sort(yc.begin(), yc.end());
	rep(i,N-1)if(yc[i].first==yc[i+1].first){
		unite(yc[i].second,yc[i+1].second);
	}
	rep(i,N)gr[par[i]].push_back(i);

	ll ans=-N;
	rep(i,N)if(sz(gr[i])!=0){
		set<int> xst, yst;
		rep(k,sz(gr[i])){
			xst.insert(x[k]);
			yst.insert(y[k]);
		}
		ll xsz=(ll)xst.size();
		ll ysz=(ll)yst.size();
		ans+=xsz*ysz;
	}
	cout<<ans<<endl;
}

