vector<int> uf, usz;
int nc;

void init(int n){
  vector<int> uf_(n);
  vector<int> usz_(n, 1);
  uf = uf_;
  usz = usz_;
  nc = n;

  for(int i = 0; i < uf.size(); i++){
    uf[i] = i;
  }
}

int find(int a){
  return (uf[a] == a) ? a : uf[a] = find(uf[a]);
}

void union_(int a, int b){
  a = find(a);
  b = find(b);

  if(a != b){
    if(usz[a] >= usz[b]){
      swap(a, b);
    }
    uf[a] = b;
    usz[b] += usz[a];
    nc--;
  }
}

int check(int a, int b){
  return (find(a) == find(b)) ? 1 : 0;
}

int get_size(int a){
  return usz[find(a)];
}

int main() {
	ll n;
	cin>>n;
	init(100100);
	vector<pair<ll,ll> > v;
	rep(i,0,n){
		ll x,y;
		cin>>x>>y;
		v.pb(mp(x,y));
	}
	sort(all(v));
	rep(i,0,v.sz-1){
		if(v[i].fi==v[i+1].fi){
			union_(v[i].se,v[i+1].se);
		}
	}
	vector<set<ll> > vs(100100,set<ll>());
	rep(i,0,v.sz){
		ll x1 = v[i].fi;
		ll y1 = find(v[i].se);
		vs[y1].insert(x1);
	}
	vector<vector<ll> > vv(100100,vector<ll>());
	rep(i,0,vs.sz){
		vector<ll> v1(all(vs[i]));
		vv[i] = v1;
	}
	ll ans = 0;
	rep(i,0,vs.sz){
		if(vs[i].sz==0)continue;
		ll a = get_size(i);
		if(a==1)continue;
		ll ans1 = a*vs[i].sz;
		ans += ans1;
	}
	rep(i,0,v.sz){
		ll x1 = v[i].fi;
		ll y1 = v[i].se;
		ll a = find(y1);
		ll b = get_size(y1);
		if(b==1)continue;
		set<ll>::iterator itr = vs[a].find(x1);
		if(itr!=vs[a].end()){
			ans--;
		}
	}
	cout << ans << endl;
	return 0;
}

