		sz[i] = P(0, 1);
	}
}

int find(int x) {
	if (parent[x] == x) return x;
	else return parent[x] = find(parent[x]);
}

void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y) return;
	if (sz[x].first + sz[x].second < sz[y].first + sz[y].second) {
		parent[x] = y;
		sz[y].first += sz[x].first;
		sz[y].second += sz[x].second;
	}
	else {
		parent[y] = x;
		sz[x].first += sz[y].first;
		sz[x].second += sz[y].second;
	}
}

