    {
        int n; cin>>n;
        vector<pii> p(n); cin>>p;
        vector<vector<int>> g(201010);
        for(auto q : p)
        {
            g[q.first].emplace_back(100000+q.second);
            g[100000+q.second].emplace_back(q.first);
        }
        queue<int> que;
        i64 ans=-n;
        vector<bool> u(201010);
        for(int i=1; i<=100000; ++i)
        {
            if(u[i])
            {
                continue;
            }
            i64 sz1=0,sz2=0;
            u[i]=1;
            que.emplace(i);
            while(!que.empty())
            {
                int f=que.front();
                que.pop();
                if(f>100000) sz2++;
                else sz1++;
                for(int j : g[i])
                {
                    if(!u[j])
                    {
                        que.emplace(j);
                        u[j]=1;
                    }
                }
            }
            // dump(sz1,sz2);
            ans+=sz1*sz2;
        }
        cout << ans << "\n";
    }
}; // struct solver


