struct DSU {
  int n;
  vector<int> par, sz;
  vector<pair<int, int>> vx;
  int64_t ret = 0;

  DSU() = default;

  DSU(int n) : n(n) {
    par.resize(2 * n);
    iota(par.begin(), par.end(), 0);
    sz.assign(2 * n, 1);
    vx.resize(2 * n);
    for (int i = 0; i < n; ++i) {
      vx[i] = make_pair(1, 0);
    }
    for (int i = n; i < 2 * n; ++i) {
      vx[i] = make_pair(0, 1);
    }
  }

  int get(int x) {
    return x == par[x] ? x : get(par[x]);
  }

  int64_t calc(pair<int, int> p) {
    return (int64_t) p.first * p.second;
  }

  void unite(int x, int y) { // union-by-rank
    x = get(x), y = get(y);
    if (x == y) {
      return;
    }
    if (sz[x] < sz[y]) swap(x, y);
    sz[x] += sz[y];
    par[y] = x;
    ret -= calc(vx[x]);
    ret -= calc(vx[y]);
    vx[x].first += vx[y].first;
    vx[x].second += vx[y].second;
    ret += calc(vx[x]);
  }
};

DSU uf;

void solve(std::istream &in, std::ostream &out) {
  int n;
  in >> n;
  uf = DSU(1 << 19);
  for (int i = 0, x, y; i < n; ++i) {
    in >> x >> y;
    uf.unite(x, y);
  }
  out << uf.ret - n << '\n';
}

