struct UnionFind {
  vector<int> parent; // parent[root] is the negative of the size.
  UnionFind(int n) : parent(n, -1) { };
  bool unite(int u, int v) { 
    u = root(u); v = root(v);
    if (u == v) return false;
    if (parent[u] > parent[v]) swap(u, v);
    parent[u] += parent[v]; parent[v] = u;
    return true;
  }
  bool find(int u, int v) { return root(u) == root(v); }
  int root(int u) { return parent[u] < 0 ? u : parent[u] = root(parent[u]); }
  int size(int u) { return -parent[root(u)]; }
};


int main() {
    int n;
    in(n);

    UnionFind uf(n);

    vector<i64> a(n), b(n);

    map<int, vector<pair<int, int>>> x, y;

    for (int i = 0; i < n; i++) {
        int xx, yy;
        in(xx, yy);

        a[i] = xx;
        b[i] = yy;

        x[xx].push_back({yy, i});
        y[yy].push_back({xx, i});
    }

    for (auto p : x) {
        auto& v = p.second;
        for (int i = 0; i < (int)v.size() - 1; i++) {
            uf.unite(v[i].second, v[i + 1].second);
        }
    }

    for (auto p : y) {
        auto& v = p.second;
        for (int i = 0; i < (int)v.size() - 1; i++) {
            uf.unite(v[i].second, v[i + 1].second);
        }
    }

    map<int, set<int>> m1, m2;
    map<int, int> cnt;

    for (int i = 0; i < n; i++) {
        m1[uf.root(i)].insert(a[i]);
        m2[uf.root(i)].insert(b[i]);
        cnt[uf.root(i)]++;
    }

    i64 ans = 0;

    for (int i = 0; i < n; i++) {
        if (m1.count(i)) {
            ans += m1[i].size() * m2[i].size() - cnt[i];
        }
    }

    out(ans);
}

