struct uf
{
	vector<lint> p;
	vector<lint> s;

	uf(lint n) : p(n), s(n)
	{
		rep(i, n)
		{
			p[i] = i;
			s[i] = 1;
		}
	}

	lint rt(lint n)
	{
		return p[n] == n ? n : p[n] = rt(p[n]);
	}

	void un(lint n, lint m)
	{
		if (rt(n) != rt(m))
		{
			s[rt(m)] += s[rt(n)];
			p[rt(n)] = rt(m);
		}
	}

	bool eq(lint n, lint m)
	{
		return rt(n) == rt(m);
	}

	lint sz(lint n)
	{
		return s[rt(n)];
	}
};


