    vector <int> x(n), y(n);
    vector <P> X(n), Y(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        X[i] = P(x[i], i);
        Y[i] = P(y[i], i);
    }

    sort(X.begin(), X.end());
    for (int i = 0; i < n - 1; i++) {
        if (X[i].first == X[i+1].first) {
            uf.unite(X[i].second, X[i+1].second);
        }
    }

    sort(Y.begin(), Y.end());
    for (int i = 0; i < n - 1; i++) {
        if (Y[i].first == Y[i+1].first) {
            uf.unite(Y[i].second, Y[i+1].second);
