struct DSU {
	vector<int> v;
	int n;

	DSU( int n ) : n(n){
		v.resize(n);
		iota(v.begin(), v.end(), 0);
	}

	// xのグループを求める
	int find(int x){
		if ( x == v[x] )
			return x;
		v[x] = find(v[x]);
		return v[x];
	}

	// xとyが同じグループか?
	bool same( int x, int y ){
		return find(x) == find(y);
	}

	// xとyを同じグループにする
	void unify( int x, int y ){
		x = find(x);
		y = find(y);
		if ( x != y ){
			v[y] = x;
		}
	}
};



ll N;
struct pt{
	ll x, y;
	int i;
};

int main(){
	cin >> N;

	DSU dsu(N);
	vector<pt> v(N);
	for ( int i = 0; i < N; i++ ){
		cin >> v[i].x >> v[i].y;
		v[i].i = i;
	}


	// xかyが同じなら、同じグループにする
	sort(v.begin(), v.end(), [](const pt &l, const pt &r){return l.x < r.x;});
	for ( int i = 1; i < N; i++ )
		if ( v[i-1].x == v[i].x )
			dsu.unify( v[i-1].i, v[i].i );

	sort(v.begin(), v.end(), [](const pt &l, const pt &r){return l.y < r.y;});
	for ( int i = 1; i < N; i++ )
		if ( v[i-1].y == v[i].y )
			dsu.unify( v[i-1].i, v[i].i );



	// それぞれのグループに、操作後の点がいくつあるか調べる
	map<int,pair<set<int>,set<int>>> m;

	for ( int i = 0; i < N; i++ ){
		int group = dsu.find(v[i].i);
		auto &p = m[group];
		p.first.insert(v[i].x);
		p.second.insert(v[i].y);
	}

	int count = 0;
	for ( auto it : m ){
		auto &p = it.second;

		count += p.first.size() * p.second.size();
	}

	cout << (count-N) << endl;

	return 0;
}

