ll solve(int N, vi& x, vi& y) {
    set<int> xe, ye;
    rep(i,N){
        xe.insert(x[i]);
        ye.insert(y[i]);
    }
    int xN = xe.size(), yN = ye.size();
    map<int,int> xZ, yZ;
    int xi=0, yi=0;
    for (int x: xe) xZ[x] = xi++;
    for (int y: ye) yZ[y] = yi++;
    rep(i,N){
        x[i] = xZ[ x[i] ];
        y[i] = yZ[ y[i] ];
    }

    using P = pair<int, ii>;
    vector<P> vert, horiz;

    IntervalTree it(0, xN);

    {
        vvi po(xN);
        rep(i,N) po[x[i]].pb(y[i]);
        rep(x,xN){
            sort(ALL(po[x]));
            int last = -2, from = -2, to = -2;
            for(int y: po[x]){
                if (y == last+1){
                    to = y;
                } else {
                    if (from < to) {
                        vert.emplace_back(x, ii(from, to));
                    }
                    from = to = y;
                }
                last = y;
            }
            if (from < to) {
                vert.emplace_back(x, ii(from, to));
            }
        }
    }

    {
        vvi po(yN);
        rep(i,N) po[y[i]].pb(x[i]);
        rep(y,yN){
            sort(ALL(po[y]));
            int last = -2, from = -2, to = -2;
            for(int x: po[y]){
                if (x == last+1){
                    to = x;
                } else {
                    if (from < to) vert.emplace_back(y, ii(from, to));
                    from = to = x;
                }
                last = x;
            }
            if (from < to) horiz.emplace_back(y, ii(from, to));
        }
    }




    ll ans = 0;
    for(auto &v: vert) {
        int x = v.first;
        int vw = (v.second.second - v.second.first) + 1;
        for(auto &h: horiz) {
            int y = h.first;
            if (!IN(y, v.second.first, v.second.second)) continue;
            int hw = (h.second.second - h.second.first) + 1;
            if (!IN(x, h.second.first, h.second.second)) continue;
            ll area = (ll)vw * hw;
            ans += (area - vw - hw + 1);
        }
    }
    return ans;
}

