class Trees{
    vector<long> par;
    vector<long> rank;
public:
    long root(long i){
        long rt;
        if(par[i]==i){rt=i;rank[i]=1;}
        else{rt=root(par[i]);par[i]=rt;rank[i]=2;}
        return rt;
    }
    void unite(long i,long j){
        long rki=rank[i];long rkj=rank[j];
        if(rki<rkj){par[root(i)]=root(j);rank[i]++;}
        else{par[root(j)]=root(i);rank[j]++;}
    }
    bool same(long i,long j){
        return root(i)==root(j);
    }
    Trees(long n){
        for(long i=0;i<n;i++) {par.push_back(i);rank.push_back(1);};
    }
};
struct Point{
    long x,y;
    long id;
};
bool cmpx(const Point& left, const Point& right){
    return left.x<right.x;
}
bool cmpy(const Point& left, const Point& right){
    return left.y<right.y;
}
bool cmpid(const Point& left, const Point& right){
    return left.id<right.id;
}
