struct UnionFind {
    private:
    vector<int> par,rank;
    vector<ll> size;
    public:
    UnionFind(int N){
        par.resize(N);
        rank.resize(N,0);
        size.resize(N,1);
        for (int i=0;i<N;i++){
            par[i]=i;
        }
    }
    int root(int x){
        if (par[x]==x){
            return x;
        }
        return par[x]=root(par[x]);
    }
    bool merge(int x, int y){
        x=root(x);
        y=root(y);
        if (x==y){
            return false;
        }
        if (rank[x]<rank[y]){
            swap(x,y);
        }
        if (rank[x]==rank[y]){
            ++rank[x];
        }
        par[y]=x;
        size[x]+=size[y];
        return true;
    }
    bool same(int x, int y){
        return root(x)==root(y);
    }
    ll Size(int x){
        return size[root(x)];
    }
};

