map<int, vector<int>> graph;
map<int, bool> visited;
int N = 100001;

pll dfs(int v) {
  ll nx = 0;
  ll ny = 0;
  visited[v] = true;
  for (int v_to : graph[v]) {
    if (visited[v_to]) continue;
    if (v_to >= N) ny += 1;
    else nx += 1;
    pll tmp = dfs(v_to);
    nx += tmp.first;
    ny += tmp.second;
  }
  return make_pair(nx, ny);
}

int main() {
  int n;
  cin >> n;
  for (int i = 0; i < n; ++i) {
    int x, y;
    cin >> x >> y;
    graph[x].push_back(y+N);
    graph[y+N].push_back(x);
    visited[x] = false;
    visited[y+N] = false;
  }
  ll ans = 0;
  for (auto kv : visited) {
    if (kv.second) continue;
    int v = kv.first;
    pll ret = dfs(v);
    ll nx, ny;
    nx = ret.first;
    ny = ret.second;
    if (v >= N) ny += 1;
    else nx += 1;
    ans += nx*ny;
  }
  ans -= n;
  cout << ans << endl;

}

