const i64 H = 100001;
i64 n;
vector<vector<i64>> g;
vector<i64> vis;

tuple<i64, i64, i64> dfs(i64 u) {
  if (vis[u]) return {};
  vis[u] = true;
  i64 c = u < H, r = u >= H, e = 0;
  for (i64 v : g[u]) {
    if (!vis[v]) {
      auto t = dfs(v);
      i64 cv, rv, ev;
      tie(cv, rv, ev) = t;
      c += cv;
      r += rv;
      e += ev + 1;
    }
  }
  return { c, r, e };
}

int main() {
  init_n(g, 2 * H);
  cin >> n;
  for (i64 i = 0; i < n; ++i) {
    i64 x, y;
    cin >> x >> y;
    g[x].push_back(H + y);
    g[H + y].push_back(x);
  }
  init_n(vis, 2 * H);

  i64 ans = 0;
  for (i64 i = 0; i < 2 * H; ++i) {
    auto t = dfs(i);
    i64 c, r, e;
    tie(c, r, e) = t;
    ans += c * r - e;
  }
  cout << ans << '\n';
  return 0;
}

