// Bipartite graph
struct BG {
  int nx; int ny; int nedge;
  int possible(){ return nx * ny - nedge; }
};

int main(){
  cin.tie(0); ios::sync_with_stdio(false);    // Magic for faster cin
  int N; cin >> N;
  vi x(N), y(N);
  rep(i,N) cin >> x[i] >> y[i];
  unordered_map<int, int> dict_x;
  unordered_map<int, int> dict_y;

  int nx = 0; int ny = 0;
  rep(i,N) if(dict_x.find(x[i])==dict_x.end()) dict_x[x[i]] = nx++;
  rep(i,N) if(dict_y.find(y[i])==dict_y.end()) dict_y[y[i]] = ny++;

  vvi G(nx,vi(ny,0));
  rep(i,N){
    G[dict_x[x[i]]][dict_y[y[i]]] = 1;
  }

  UnionFind uf(nx+ny);
  rep(i,nx) rep(j,ny) {
    if(G[i][j]) uf.unite(i,nx+j);
  }

  unordered_map<int, BG> gg;
  rep(i,nx){
    int r = uf.root(i);
    gg[r].nx++;
  }
  rep(i,ny){
    int r = uf.root(nx+i);
    gg[r].ny++;
  }
  rep(i,nx) rep(j,ny) {
    if(G[i][j]){
      int r = uf.root(i);
      gg[r].nedge++;
    }
  }
  int ans = 0;
  for(auto kv : gg){
    ans += kv.second.possible();
  }
  cout << ans << endl;

  return 0;
}

