    FOR(i, 0, N) {
        FOR(j, 0, SZ(id[i][0]) - 1) {
            uf.Union(id[i][0][j], id[i][0][j + 1]);
        }
        FOR(j, 0, SZ(id[i][1]) - 1) {
            uf.Union(id[i][1][j], id[i][1][j + 1]);
        }
