    FOR(i, 0, n) {
        int id = uf.Find(i);
        if(id != i) continue;

        if(SZ(X[id]) == 1 or SZ(Y[id]) == 1) continue;

        res += 1ll * SZ(X[id]) * SZ(Y[id]) - uf.roz[id];
    }

    prln(res);
    ELO;    
}

