  if(x_type.find(x)==x_type.end()) x_type.emplace(x);
  if(y_type.find(y)==y_type.end()) y_type.emplace(y);

  REP(i,yPath[y].size()){
    search_y(yPath[y][i], y, x_type, y_type, count);
  }
  return;
}

void search_y(const ll x, const ll y, set<ll>& x_type, set<ll>& y_type, ll& count){
  pair<ll, ll> P = make_pair(x, y);
  if(flag.find(P)!=flag.end()) return;
  flag.emplace(P);
  count++;
  if(x_type.find(x)==x_type.end()) x_type.emplace(x);
  if(y_type.find(y)==y_type.end()) y_type.emplace(y);

  REP(i,xPath[x].size()){
    search_x(x, xPath[x][i], x_type, y_type, count);
  }
  return;
}

