class UnionFindTree{
private:
  // indexの数の親ノード(ある集合の親を見つけたいときはここを直接参照せず、findを使う)
  vector<int> par;
  // indexを根とする木のランク
  vector<int> rank;
  // 集合のサイズ
  vector<int> cnts;
  // 木の最大値
  int treeSize;
public:
  UnionFindTree(int initTreeSize = 1000){
    // 引数で与えられた値を最大格納数とするUnionFindTreeの作成
    treeSize = initTreeSize;
    init(initTreeSize);
  }
  void init(int sz){
    par.clear(),rank.clear(),cnts.clear();
    treeSize=sz;
    for(int i = 0; i < sz; i++){
      par.push_back(i);
      rank.push_back(0);
      cnts.push_back(1);
    }
  }
  // 与えられた数が格納されている木のルートを探索
  int find(int x){  
    if(par[x] == x)return x;
    else return par[x] = find(par[x]);
  }
  // 和集合をとる。ただしここでは各集合の親の付け替えは起こらない
  void unite(int x,int y){
    x = find(x);
    y = find(y);
    if(x == y)return;
    if(rank[x] < rank[y]){
      par[x] = y;
      cnts[y]+=cnts[x];
    }
    else{
      par[y] = x;
      cnts[x]+=cnts[y];
      if(rank[y] == rank[x])rank[x]++;
    }
  }
  // xの属する集合のサイズ
  int getCnt(int x){
    return cnts[find(x)];
  }
  bool same(int x,int y){
    return find(x) == find(y);
  }

};


int N;
int X[100010];
int Y[100010];
UnionFindTree uft(100010);

int main(){

    cin >> N;
    map<int, vector<int> > xs;
    map<int, vector<int> > ys;
    for(int i = 0; i < N; i++){
        cin >> X[i] >> Y[i];
        xs[X[i]].push_back(i);
        ys[Y[i]].push_back(i);
    }
    for(auto p : xs){
        auto &v = p.second;
        for(int i = 1; i < (int)v.size(); i++){
            uft.unite(v[0], v[i]);
        }
    }
    for(auto p : ys){
        auto &v = p.second;
        for(int i = 1; i < (int)v.size(); i++){
            uft.unite(v[0], v[i]);
        }
    }

    // 同じ値に属するもの同士で分類
    map<int, vector<int> > cls;
    for(int i = 0; i < N; i++){
        cls[uft.find(i)].push_back(i);
    }

    ll ans = 0;
    for(auto p : cls){
        set<int> xs, ys;
        auto &v = p.second;
        for(int idx : v){
            xs.insert(X[idx]);
            ys.insert(Y[idx]);
        }
        ans += (ll)xs.size() * ys.size() - (int)v.size();
    }
    cout << ans << endl;

    return 0;
}

