class UnionFindS{
private:
    vector<int> par;
    vector<set<int>> xc;
    vector<set<int>> yc;
public:
    UnionFindS(int n){
        par=vector<int>(n,-1);
        xc=vector<set<int>>(n,set<int>());
        yc=vector<set<int>>(n,set<int>());
        rep(i,n){
            xc[i].insert(X[i]);
            yc[i].insert(Y[i]);
        }
    }
    int find(int x){
        if(par.at(x)<0) return x;
        else return par.at(x)=find(par.at(x));
    }
    int size(int x){
        return -par.at(find(x));
    }
    void unite(int x, int y, int xx, int yy){
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(size(x)<size(y)) swap(x,y);
        par.at(x)+=par.at(y);
        par.at(y)=x;
        xc[x].insert(xx/200000);
        xc[x].insert(yy/200000);
        yc[x].insert(xx%200000);
        yc[x].insert(yy%200000);
    }
    bool same(int x, int y){
        return find(x)==find(y);
    }
    int get(int x){
        x=find(x);
        return xc[x].size()*yc[x].size()-size(x);
    }
};

