    }](auto i){return rec(rec, i);};
    auto unite = [find, &uf](auto i, auto j) -> long{
        i = find(i);
        j = find(j);
        if(i == j)return 0;
        if(uf[i].first + uf[i].second > uf[j].first + uf[j].second)swap(i, j);
        auto ret = uf[i].first * uf[j].second + uf[i].second * uf[j].first;
        uf[i].first += uf[j].first;
        uf[i].second += uf[j].second;
        uf[j].first = i;
        uf[j].second = 0;
        return ret;
    };
    for(long i = 0, x, y; i < N; ++i){
        cin >> x >> y;
        ans += unite(x + 99999, y - 1);
    }
    cout << ans - N << endl;
    return 0;
}

