struct uft{

    vector<ll> par;

    uft(ll n){
        par.resize(n);
        rep(i,n)par[i]=i;
    }

    ll find(ll a){
        if(par[a]==a)return a;
        return par[a]=find(par[a]);
    }

    void unite(ll a,ll b){
        par[find(a)]= find(b);
    }

    bool same(ll a,ll b){
        return find(a)==find(b);
    }

};

