class UnionFindTree
{
private:
    int n;
    int groupNum;       // グループの数
    vector<int> parent; // 親ノード
    vector<int> rank;   // 木の高さの上限
    vector<int> num;    // グループの要素数
    int find(int i){
        if(parent[i] == i)
            return i;
        else
            return parent[i] = find(parent[i]);
    }
public:
    UnionFindTree(int n){ // コンストラクタ
        this->n = n;
        groupNum = n;
        parent.resize(n);
        for(int i=0; i<n; ++i)
            parent[i] = i;
        rank.assign(n, 0);
        num.assign(n, 1);
    }
    void unite(int a, int b){ // aとbのグループを併合
        if((a = find(a)) != (b = find(b))){
            if(rank[a] < rank[b]){
                parent[a] = b;
                num[b] += num[a];
            }
            else{
                parent[b] = a;
                if(rank[a] == rank[b])
                    ++ rank[a];
                num[a] += num[b];
            }
            -- groupNum;
        }
    }
    bool same(int a, int b){ // aとbのグループが同じかを調べる
        return find(a) == find(b);
    }
    int getNum(){ // グループの数を返す
        return groupNum;
    }
    int getNum(int a){ // aのグループの要素数を返す
        return num[find(a)];
    }
    void getGroup(vector<vector<int> >& group){ // グループ構成を返す
        map<int, int> index;
        group.clear();
        for(int i=0; i<n; ++i){
            int a = find(i);
            if(index.find(a) == index.end()){
                index[a] = group.size();
                group.resize(group.size() + 1);
            }
            group[index[a]].push_back(i);
        }
    }
};

int main()
{
    int n;
    cin >> n;
    vector<int> x(n), y(n);
    for(int i=0; i<n; ++i)
        cin >> x[i] >> y[i];

    UnionFindTree uft(n);
    for(int i=0; i<2; ++i){
        vector<pair<int, int> > v(n);
        for(int i=0; i<n; ++i)
            v[i] = make_pair(x[i], i);
        sort(v.begin(), v.end());
        for(int j=0; j<n-1; ++j){
            if(v[j].first == v[j+1].first)
                uft.unite(v[j].second, v[j+1].second);
        }
        x.swap(y);
    }

    vector<vector<int> > group;
    uft.getGroup(group);
    long long ans = -n;
    for(const auto& v : group){
        set<int> sx, sy;
        for(int i : v){
            sx.insert(x[i]);
            sy.insert(y[i]);
        }
        ans += sx.size() * (long long)sy.size();
    }
    cout << ans << endl;

    return 0;
}

