/*  union_find_tree_size.cpp
    素集合系を union-find tree で管理するライブラリ
    併合時の工夫：union by size

    verified: AtCoder ABC157 D - Friend Suggestions
        https://atcoder.jp/contests/abc157/tasks/abc157_d
*/

#include <bits/stdc++.h>
using namespace std;

/* UnionFind：素集合系管理の構造体(union by size)
    isSame(x, y): x と y が同じ集合にいるか。 計算量はならし O(α(n))
    unite(x, y): x と y を同じ集合にする。計算量はならし O(α(n))
    treeSize(x): x を含む集合の要素数。
*/
struct UnionFind {
    vector<int> size, parents;
    UnionFind() {}
    UnionFind(int n) {  // make n trees.
        size.resize(n, 0);
        parents.resize(n, 0);
        for (int i = 0; i < n; i++) {
            makeTree(i);
        }
    }
    void makeTree(int x) {
        parents[x] = x;  // the parent of x is x
        size[x] = 1;
    }
    bool isSame(int x, int y) { return findRoot(x) == findRoot(y); }
    bool unite(int x, int y) {
        x = findRoot(x);
        y = findRoot(y);
        if (x == y) return false;
        if (size[x] > size[y]) {
            parents[y] = x;
            size[x] += size[y];
        } else {
            parents[x] = y;
            size[y] += size[x];
        }
        return true;
    }
    int findRoot(int x) {
        if (x != parents[x]) {
            parents[x] = findRoot(parents[x]);
        }
        return parents[x];
    }
    int treeSize(int x) { return size[findRoot(x)]; }
};
using ll = long long;
int main() {
    int N;
    cin >> N;
    const int MAX = 110000;
    UnionFind uf(MAX * 2);
    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        uf.unite(x, y + MAX);
    }

    map<int, ll> mx, my;
    for (int i = 0; i < MAX; i++) {
        mx[uf.findRoot(i)]++;
    }
    for (int i = MAX; i < MAX * 2; i++) {
        my[uf.findRoot(i)]++;
    }

    ll ans = 0;
    for (int i = 0; i < 2 * MAX; i++) {
        ans += mx[i] * my[i];
    }
    cout << ans - N << endl;

    return 0;
}

