    const ll MAX_V = e5 * 2;
    vector<ll> G[MAX_V];
    vector<bool> seen(MAX_V);
    vector<ll> c(2);
    auto dfs = [&](auto &&f, ll now) -> void {
        seen[now] = true;
        c[now / e5]++;
        each(e, G[now]) {
            if (!seen[e]) {
                f(f, e);
