constexpr bool bget(ll m, int keta) { return (m >> keta) & 1; }
int bget(ll m, int keta, int sinsuu) {    m /= (ll) pow(sinsuu, keta);    return m % sinsuu;}
ll bit(int n) { return (1LL << (n)); }
