int N;
vector<pii> P;
vector<vector<int>> idX, idY;
void input(){
    fast_io();
    cin >> N;
    for (int i = 0; i < N; i++)
    {
        int x, y; cin >> x >> y;
        P.emplace_back(x, y);
        idX[x].push_back(i);
        idY[y].push_back(i);
    }
}
vector<bool> visited;
vector<int> dfs(int x){
    if(visited[x]) return vector<int>();
    visited[x] = true;
    vector<int> ret;
    ret.push_back(x);
    pii p = P[x];
    for(auto ix:idX[p.first]){
        for(auto r:dfs(ix)) ret.push_back(r);
    }
    for(auto iy:idY[p.second]){
        for(auto r:dfs(iy)) ret.push_back(r);
    }
    return ret;
}

ll calc(vector<int> X){
    ll ret = 0LL;
    set<int> mx, my;
    for(auto i:X){
        mx.insert(P[i].first);
        my.insert(P[i].second);
    }
    ret = (ll)mx.size()*(ll)my.size()-(ll)X.size();
    return ret;
}

int solve(){
    visited.assign(N, false);
    idX.resize(1e5+1);
    idY.resize(1e5+1);
    ll ans = 0LL;
    for (int i = 0; i < N; i++)
    {
        vector<int> idx = dfs(i);
        if(!idx.empty()){
            ans += calc(idx);
        }
    }
    cout << ans << endl;
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

