struct UnionFind {
    vector<int> par, siz;
    UnionFind(int n) {
        par.resize(n);
        siz.resize(n, 1);
        for(int i = 0; i < n; i++)
            par[i] = i;
    }
    int find(int x) {
        if(par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }
    bool unite(int u, int v) {
        u = find(u), v = find(v);
        if(u == v)
            return false;
        if(siz[u] < siz[v])
            swap(u, v);
        par[v] = u;
        siz[u] += siz[v];
        return true;
    }
    bool same(int u, int v) { return find(u) == find(v); }
};
int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n;
    cin >> n;
    vector<vector<int>> y(100010), x(100010);
    for(int i = 0; i < n; i++) {
        int xx, yy;
        cin >> xx >> yy;
        y[xx].push_back(yy);
        x[yy].push_back(xx);
    }
    UnionFind uf(100010);
    for(int i = 0; i <= 100000; i++) {
        for(int j = 1; j < x[i].size(); j++) {
            uf.unite(x[i][j], x[i][j - 1]);
        }
    }
    vector<vector<int>> v(100010);
    for(int i = 0; i <= 100000; i++) {
        v[uf.find(i)].push_back(i);
    }
    ll ans = 0;
    for(int i = 0; i <= 100000; i++) {
        if(uf.find(i) != i) {
            continue;
        }
        set<int> st;
        for(auto& e : v[i]) {
            for(auto& s : y[e]) {
                st.insert(s);
            }
        }
        if(st.empty()) {
            if(y[i].size() > 0) {
                ans += (ll)uf.siz[i];
            }
        } else {
            ll to = uf.siz[i];
            to *= (ll)st.size();
            ans += to;
        }
    }
    cout << ans - n << endl;
}

