    rep(i, n){
        cin >> x[i] >> y[i];
        uni.connect(x[i], y[i]);
    }

    map<int, ll> mx, my;
    rep(i, MAX) ++mx[uni.root(i)];
    repr(i, MAX, 2*MAX) ++my[uni.root(i)];
    ll res=0;
    rep(r, 2*MAX) res += mx[r]*my[r];
    cout << res-n << endl;

    return 0;
}

