  set<ll> xs, ys;
  set<ll>::iterator it;
  for(i = 0; i < n; ++i) {
    scanf("%lld%lld", &x[i], &y[i]);
    xs.insert(x[i]), ys.insert(y[i]);
  }
  p = xs.size(), q = ys.size();
  ll uf[p + q], nx[p], ny[q], cx[p], cy[q], sx[p + q], sy[p + q], sum[p + q];
  for(i = 0, it = xs.begin(); i < p; ++i, ++it) nx[i] = *it, cx[i] = 0;
  for(i = 0, it = ys.begin(); i < q; ++i, ++it) ny[i] = *it, cy[i] = 0;
  for(i = 0; i < p + q; ++i) uf[i] = i, sx[i] = sy[i] = sum[i] = 0;
  for(i = 0; i < n; ++i) {
    na = lower_bound(nx, nx + p, x[i]) - nx, nb = lower_bound(ny, ny + q, y[i]) - ny;
    cx[na]++, cy[nb]++;
    ta = na, tb = nb + p, ra = rb = 0;
    while(ta != uf[ta]) ta = uf[ta], ra++;
    while(tb != uf[tb]) tb = uf[tb], rb++;
    if(ra < rb) uf[na] = tb;
    else uf[nb + p] = ta;
  }
  for(i = 0; i < p + q; ++i) {
    na = i;
    while(uf[na] != na) na = uf[na];
    uf[i] = na;
    if(i < p) sx[na]++, sum[na] += cx[i];
    else sy[na]++, sum[na] += cy[i - p];
  }
  for(i = 0; i < p + q; ++i) ans += sx[i] * sy[i] - sum[i] / 2;
  printf("%lld", ans);
  return 0;
}

