using Pair = pair<int, int>;
const int C = 100000;

int main() {
    int N; cin >> N;
    vector<vector<int>> graph(C * 2);
    for(int i = 0; i < N; ++i) {
        int a, b; cin >> a >> b;
        a--, b = b - 1 + C;
        graph[a].emplace_back(b);
        graph[b].emplace_back(a);
    }
    vector<int> visited(C * 2);
    auto add = [&](Pair &p, int v) {
        if(v < C) p.first++;
        else p.second++;
    };
    auto merge = [&](Pair &p, Pair q) {
        p.first += q.first;
        p.second += q.second;
    };
    auto dfs = [&](auto &&dfs, int cur) -> Pair {
        Pair res;
        if(visited[cur]) return res;
        visited[cur] = 1;
        add(res, cur);
        for(auto &to : graph[cur]) {
            merge(res, dfs(dfs, to));
        }
        return res;
    };
    int64_t ans = 0;
    for(int i = 0; i < C * 2; ++i) {
        auto[x, y] = dfs(dfs, i);
        ans += (int64_t)x * y;
    }
    cout << ans - N << '\n';
    return 0;
}

