struct UnionFindTree{
	vector<int>par,sz,g,h;
	UnionFindTree(int n){
		par.resize(n);
		sz.resize(n);
		g.resize(n);
		h.resize(n);
		for(int i=0;i<n;i++){
			par[i]=i;
			sz[i]=1;
			if(i<n/2)g[i]++;
			else h[i]++;
		}
	}
	int find(int x){
		return x==par[x]?x:par[x]=find(par[x]);
	}
	void unite(int x,int y){
		x=find(x);y=find(y);
		if(x==y)return;
		if(sz[x]<sz[y])swap(x,y);
		sz[x]+=sz[y];
		g[x]+=g[y];
		h[x]+=h[y];
		par[y]=x;
	}
	bool areSame(int x,int y){
		return find(x)==find(y);
	}
	int size(int x){
		return sz[find(x)];
	}
};

const int L=100000;
signed main(){
	int N;
	cin>>N;
	UnionFindTree uf(L*2);
	rep(i,N){
		int x,y;
		cin>>x>>y;
		x--;y--;
		uf.unite(x,L+y);
	}

	int ans=0;
	rep(i,2*L){
		if(uf.find(i)!=i)continue;
		ans+=uf.g[i]*uf.h[i];
	}
	ans-=N;
	cout<<ans<<endl;
	return 0;
}

