struct UnionFind {
  vector<ll> par;

  UnionFind(ll n) : par(n, -1) { }
  void init(ll n) { par.assign(n, -1); }

  ll root(ll x) {
    if (par[x] < 0) return x;
    else return par[x] = root(par[x]);
  }

  bool issame(ll x, ll y) {
    return root(x) == root(y);
  }

  bool merge(ll x, ll y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (par[x] > par[y]) swap(x, y);
    par[x] += par[y];
    par[y] = x;
    return true;
  }

  ll size(ll x) {
    return -par[root(x)];
  }
};

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);
  ll N;
  cin>>N;
  vector<pair<ll,ll>> X(N),Y(N);
  for(ll i=0;i<N;i++){
    ll x,y;cin>>x>>y;
    X[i]=make_pair(x,i);
    Y[i]=make_pair(y,i);
  }
  map<ll,pair<set<ll>,set<ll>>> mp;
  sort(ALL(X));sort(ALL(Y));

  UnionFind uf(N);

  for(ll i=0;i<N-1;i++){
    if(X[i].first==X[i+1].first){
      uf.merge(X[i].second,X[i+1].second);
    }
    if(Y[i].first==Y[i+1].first){
      uf.merge(Y[i].second,Y[i+1].second);
    }
  }
  for(ll i=0;i<N;i++){
    mp[uf.root(i)].first.insert(X[i].first);
    mp[uf.root(i)].second.insert(Y[i].first);
  }
  ll ans=0ll;
  for(auto e : mp){
    ans+=1ll*e.second.first.size()*e.second.second.size();
  }
  cout<<ans-N<<endl;
}

