using namespace std;

class Edge {
public:
    int no = 0;
    int from = 0;
    int to = 0;
    long long weight = 0;

    Edge(int no, int from, int to, long long weight) : no(no), from(from), to(to), weight(weight) {
    }

};

class Graph {
public:
    const int N;    // ノード数
    int M = 0;      // エッジ数
    std::vector<std::vector<Edge>> graph;
    Graph(int N) : N(N) {
        this->graph.resize(N);
    }

    void add_undirected_edge(int no, const int u, const int v, const long long w) {
        this->graph.at(u).emplace_back(Edge(no, u, v, w));
        this->graph.at(v).emplace_back(Edge(no, v, u, w));
        this->M++;
    }

    std::vector<Edge> &operator[](int u) {
        return this->graph[u];
    }

    std::vector<std::vector<int>> make_matrix_graph() {
        std::vector<std::vector<int>> matrix(this->N, std::vector<int>(this->N, INT_MAX));
        for (const auto &v : this->graph) {
            for (const auto &e : v) {
                matrix[e.from][e.to] = e.weight;
            }
        }
        return matrix;
    }

    // mode 0: undirected edge
    // mode 1: directed edge
    void show(int mode = 0) {
        std::cout << this->M << std::endl;
        for (const auto &v : this->graph) {
            for (const auto &e : v) {
                if (mode == 0) {
                    if (e.from < e.to) {
                        std::cout << e.from << " " << e.to << std::endl;
                    }
                }
                else {
                    std::cout << e.from << " " << e.to << std::endl;
                }
            }
        }
    }
};

void dfs(long long u, long long c, std::vector<long long> &color, Graph &graph) {
    color[u] = c;
    for (const auto &edge : graph[u]) {
        if (color[edge.to] == -1) {
            dfs(edge.to, c, color, graph);
        }
    }
}

// 連結成分ごとに色を塗る
std::vector<long long> component(Graph &graph) {
    std::vector<long long> color(graph.N, -1);
    long long c = 0;
    for (long long u = 0; u < graph.N; ++u) {
        if (color[u] == -1) {
            dfs(u, c, color, graph);
            c++;
        }
    }

    return color;
}

