template<int N=1000001>
struct UnionFindTree {
  LL cnt;
  A<LL, N> uftq{}, s{}, rank{};

  UnionFindTree() {
    cnt = N;
    FOR(i,0,N) { uftq[i] = i; s[i] = 1; rank[i] = 1; }
  }
  UnionFindTree(LL n) : cnt(n) {
    FOR(i,0,n) { uftq[i] = i; s[i] = 1; rank[i] = 1; }
  }
  LL find(LL x) {
      LL xParent = uftq[x];
      V<LL> v;
      while(xParent != uftq[xParent]) {
          v.push_back(xParent);
          xParent = uftq[xParent];
      }
      REP(i, v.size()) {
          uftq[v[i]] = xParent;
      }
      return xParent;
  }
  bool unite(LL x, LL y) {
      LL xRoot = find(x), yRoot = find(y);
      if(xRoot == yRoot) return false;
      if(rank[xRoot] > rank[yRoot])
          std::swap(xRoot, yRoot);
      if(rank[xRoot] == rank[yRoot])
          rank[yRoot] += 1 + rank[yRoot] - rank[xRoot];
      s[yRoot] = s[xRoot] + s[yRoot];
      s[xRoot] = 0;
      uftq[xRoot] = yRoot;
      cnt--;
      return true;
  }
  LL size(LL& idx) { return s[find(idx)]; }
  LL count() { return cnt; }
};

LL N;
int xt[100001];
int yt[100001];
set<int> xs[100001], ys[100001];
map<int,int> xm, ym;
UnionFindTree uft;

int main(){
    INIT;
