    REP(i,N) {
        cin >> xt[i] >> yt[i];
        if(xm.count(xt[i])) 
            uft.unite((LL)i,(LL)xm[xt[i]]);
        xm[xt[i]] = i;
        if(ym.count(yt[i])) 
            uft.unite((LL)i,(LL)ym[yt[i]]);
        ym[yt[i]] = i;
    }
    REP(i,N) {
        xs[uft.find((LL)i)].insert(xt[i]); 
        ys[uft.find((LL)i)].insert(yt[i]);
    }
    LL ans = 0;
    REP(i,N) ans += (LL)xs[i].size()*ys[i].size();
    cout << ans-N;
}

