#include <bits/stdc++.h>
using namespace std;

const int MX = 100000;

struct UnionFind {
    vector<int> par;
    vector<int> sz;
    vector<int> tp[2];

    UnionFind(int n){
        par.resize(n);
        sz.resize(n);
        tp[0].resize(n);
        tp[1].resize(n);
        for(int i=0; i<n; i++){
            par[i] = i;
            sz[i] = 1;
            tp[i>=MX][i]++;
        }
    }

    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            return par[x] = find(par[x]);
        }
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(sz[x] > sz[y]) swap(x, y);
        par[x] = y;
        sz[y] += sz[x];
        tp[0][y] += tp[0][x];
        tp[1][y] += tp[1][x];
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    int size(int x){
        return sz[find(x)];
    }
};

int main(){
    int N;
    cin >> N;
    UnionFind uf(2*MX);
    for(int i=0; i<N; i++){
        int x, y;
        cin >> x >> y;
        x--; y--;
        uf.unite(x, MX+y);
    }

    int64_t sum = 0;
    for(int i=0; i<2*MX; i++){
        if(uf.find(i) == i){
            sum += (int64_t) uf.tp[0][i] * uf.tp[1][i];
        }
    }

    int64_t ans = sum - N;
    cout << ans << endl;
    return 0;
}

