pll dfs(int v) {
  ll nx = 0;
  ll ny = 0;
  visited[v] = true;
  for (int v_to : graph[v]) {
    if (visited[v_to]) continue;
    if (v_to >= N) ny += 1;
    else nx += 1;
    pll tmp = dfs(v_to);
    nx += tmp.first;
    ny += tmp.second;
  }
  return make_pair(nx, ny);
}

int main() {
  int n;
