    visited[x] = false;
    visited[y+N] = false;
  }
  ll ans = 0;
  for (auto kv : visited) {
    if (kv.second) continue;
    int v = kv.first;
    pll ret = dfs(v);
    ll nx, ny;
    nx = ret.first;
    ny = ret.second;
    if (v >= N) ny += 1;
    else nx += 1;
    ans += nx*ny;
  }
  ans -= n;
  cout << ans << endl;

