class UnionFind {
public:
    UnionFind(const int n) : par(n), rank(n, 0), sz(n, 1) {
        rep(i, n) par[i] = i; // 全てが根であるとして初期化
    }

    // x が属する木の根を求める
    int find(const int x) {
        if (par[x] == x)
            return x;
        return par[x] = find(par[x]);
    }

    // x と y を併合する
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return;

        if (rank[x] < rank[y]) {
            par[x] = y;
            sz[y] += sz[x];
        } else {
            par[y] = x;
            sz[x] += sz[y];
            if (rank[x] == rank[y]) {
                ++rank[x];
            }
        }
    }

    // x と y が同じ木に属するか
    bool same(const int x, const int y) { return find(x) == find(y); }

    int size(const int x) { return sz[find(x)]; }

private:
    vint par;  // 親
    vint rank; // ランク（根からの距離）
    vint sz;   // 木の要素数
};

void Main() {
    int n = in();
    UnionFind uf(100005 * 2);
    vpint edges;
    rep(i, n) {
        int x = in(), y = in();
        uf.unite(x, 100005 + y);
        edges.eb(x, y);
    }

    map<int, setint> mp1, mp2;
    map<int, int> edge_cnt;

    for (auto [x, y] : edges) {
        mp1[uf.find(x)].insert(x);
        mp2[uf.find(x)].insert(y);
        ++edge_cnt[uf.find(x)];
    }

    ll ans = 0;
    auto itr1 = mp1.begin(), itr2 = mp2.begin();
    auto itr3 = edge_cnt.begin();

    rep(i, edge_cnt.size()) {
        ans += itr1->se.size() * itr2->se.size() - itr3->se;
        ++itr1;
        ++itr2;
        ++itr3;
    }
    out(ans);
}

