int union_find[200000];
int union_search(int now) {
	if (union_find[now] == now) return now;
	return union_find[now] = union_search(union_find[now]);
}
int union_merge(int a, int b) {
	a = union_search(a);
	b = union_search(b);
	union_find[a] = b;
	return 0;
}
