				tot[fu] += tot[fv];
			}
		}
	}

	rep(i, 1, M - 5) {
		int fu;
		if (X[i].size()) fu = Find(X[i][0]);
		for (int j = 0; j < X[i].size(); ++j)
			S[fu].insert(X[i][j]);
	}

	long long ans = 0;

	rep(i, 1, M - 5) if (X[i].size()) {
		int fu = Find(X[i][0]);
		if (!mark[fu]) {
			ans += 1LL * S[fu].size() * tot[fu];
			mark[fu] = 1;
		}
	}

	printf ("%lld\n", ans - n);

	return 0;
}

