    }

    std::vector<int> vec;
    for (int i = 1; i <= N; i++) {
        vec.push_back(i);
    }

    std::sort(vec.begin(), vec.end(), [&](const int i, const int j){
        return y[i] < y[j];
    });

    for (int i = 0; i < N - 1; i++) {
        if (y[vec[i]] == y[vec[i+1]]) {
            uf.unite(vec[i], vec[i+1]);
        }
    }

    std::sort(vec.begin(), vec.end(), [&](const int i, const int j){
        return x[i] < x[j];
    });

    for (int i = 0; i < N - 1; i++) {
        if (x[vec[i]] == x[vec[i+1]]) {
            uf.unite(vec[i], vec[i+1]);
        }
    }

    auto group = uf.get_group(1, N);

    int128_t ret = 0;
    for (auto itr = group.begin(); itr != group.end(); ++itr) {
        std::unordered_set<int> set_x, set_y;
        for (int i : itr->second) {
