struct UnionFind
{
   vector<int> parent, size;

   void init(int n){
      parent.resize(n+1);
      size.resize(n+1);

      for (int i = 1; i <= n; ++i)
      {
         parent[i] = i;
         size[i] = 1;
      }

   }

   int find(int x){

      while(x != parent[x]){
         parent[x] = parent[parent[x]];
         x = parent[x];
      }

      return x;
   }

   bool unite(int x, int y){//merges indexes
      x = find(x);
      y = find(y);
      if(x == y)
         return false;
      if(size[x] < size[y])
         swap(x, y);
      parent[y] = x;
      size[x] += size[y];

      for(auto it: vx[y])
         vx[x].push_back(it);

      for(auto it: vy[y])
         vy[x].push_back(it);

      return true;
   }

   int getSize(int x){
      x = find(x);
      return size[x];
   }

};

