struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) {}
  bool unionSet(int x, int y) {
    x = root(x);
    y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y];
      data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

constexpr int N = 100005;
int n;
int x[N];
int y[N];

void za(int* x) {
  static int z[N];
  for (int i = 0; i < n; ++i) {
    z[i] = x[i];
  }
  sort(z, z + n);
  map<int, int> m;
  for (int i = 0, v = 0; i < n; ++i) {
    if (m.find(z[i]) == m.end()) {
      m[z[i]] = v++;
    }
  }
  for (int i = 0; i < n; ++i) {
    x[i] = m[x[i]];
  }
}

int32_t main() {
  cin >> n;
  for (int i = 0; i < n; ++i) {
    cin >> x[i] >> y[i];
  }
  za(x);
  za(y);
  static int ix[N];
  static int iy[N];
  memset(ix, -1, sizeof(ix));
  memset(iy, -1, sizeof(iy));
  UnionFind uf(n + 1);
  for (int i = 0; i < n; ++i) {
    if (ix[x[i]] == -1) {
      ix[x[i]] = i;
    } else {
      uf.unionSet(ix[x[i]], i);
    }
    if (iy[y[i]] == -1) {
      iy[y[i]] = i;
    } else {
      uf.unionSet(iy[y[i]], i);
    }
  }
  static set<int> sx[N];
  static set<int> sy[N];
  for (int i = 0; i < n; ++i) {
    sx[uf.root(i)].insert(x[i]);
    sy[uf.root(i)].insert(y[i]);
  }
