    rep(i,0,n)uni.merge(x[i],y[i]+n,1);
    map<int,ll> mx,my;
    rep(i,0,n)mx[uni.root(i)]++,my[uni.root(i+n)]++;
    ll res=0;
    rep(i,0,2*n)res+=mx[i]*my[i];
    printf("%lld\n",res-n);
    return 0;
}

