int n;
set<pair<int, int> > st;
set<int> st_x, st_y;
map<int, vector<int> > mp_x, mp_y;
int q[202202];

int main() {
	scanf("%d", &n);
	for(int i=0;i<n;i++) {
		int x, y; 
		scanf("%d%d", &x, &y);
		st.insert(make_pair(x, y));
		mp_x[x].push_back(y);
		mp_y[y].push_back(x);
	}

	long long ans = 0;
	while(st.size() > 0) {
		st_x.clear(); st_y.clear();
		pair<int, int> p = *(st.begin());
		int l = 0, r = 0;
		q[r++] = p.first; q[r++] = p.second;
		while(l<r) {
			int x = q[l++], y = q[l++];
			st.erase(make_pair(x, y));
			st_x.insert(x); st_y.insert(y);
			for(int i = 0; i < mp_x[x].size(); i++) {
				int nxt_x = x; int nxt_y = mp_x[x][i];
				if (st.find(make_pair(nxt_x, nxt_y)) == st.end()) continue;
				q[r++] = nxt_x; q[r++] = nxt_y;
			}
			mp_x[x].clear();
			for(int i = 0; i < mp_y[y].size(); i++) {
				int nxt_x = mp_y[y][i]; int nxt_y = y;
				if (st.find(make_pair(nxt_x, nxt_y)) == st.end()) continue;
				q[r++] = nxt_x; q[r++] = nxt_y;
			}
			mp_y[y].clear();
		}
		ans += 1LL * st_x.size() * st_y.size();
	}
	cout<<ans-n<<endl;

	return 0;
}

