int rec(set<pair<int, int>>& s, set<int>& sx, set<int>& sy, int x, int y) {
    int ret = 0;
    auto it = s.find({x, y});
    if (it != s.end()) {
        ret++;
        s.erase(it);
        sx.emplace(x);
        sy.emplace(y);
        for (auto& e: mx[x]) {
            ret += rec(s, sx, sy, x, e);
        }
        for (auto& e: my[y]) {
            ret += rec(s, sx, sy, e, y);
        }
    }
    return ret;
}


