            }
            if (p){
                auto& g = *p;
                g.first.insert(YX[y].begin(), YX[y].end());
                g.second.insert(XY[x].begin(), XY[x].end());
            }else{
                group.emplace_back();
                auto& g = group.back();
                g.first.insert(YX[y].begin(), YX[y].end());
                g.second.insert(XY[x].begin(), XY[x].end());
            }
        }
    }
