int find(int h){
    return h==pa[h]?h:pa[h]=find(pa[h]);
}
vector<int> b[maxn];
set<int> s[maxn];
void merge(int x,int y){
    x=find(x),y=find(y);
    if(x==y)return;
    if(s[x].size()<s[y].size())swap(x,y);
    pa[y]=x;
    for(auto j:s[y])
        s[x].insert(j);
    sz[x]+=sz[y];
    return;
}


