    for(int i=1;i<=100000;i++)
        pa[i]=i,sz[i]=1;
    for(int i=1;i<=100000;i++){
        if(b[i].empty())continue;
        for(auto j:b[i]){
            merge(i,j);
        }
    }
    long long ans=0;
    for(int i=1;i<=100000;i++){
        if(!b[i].empty()&&!vis[find(i)]){
            vis[find(i)]=true;
            ans+=(1LL*(int)s[find(i)].size()*sz[find(i)]);
        }
    }
    printf("%lld\n",ans-n);
}

