struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

int main() {
	int N;

	cin >> N;
	vector<int> X( N );
	vector<int> Y( N );
	UnionFind uf( N );
	map<int, int> xmap;
	map<int, int> ymap;
	for( int i = 0; i < N; i++ ) {
		cin >> X[i] >> Y[i];
		if( xmap.count( X[i] ) ) {
			uf.unionSet( i, xmap[ X[i] ] );
		}
		xmap[ X[i] ] = i;
		if( ymap.count( Y[i] ) ) {
			uf.unionSet( i, ymap[ Y[i] ] );
		}
		ymap[ Y[i] ] = i;
	}

	vector<set<int>> xset( N );
	vector<set<int>> yset( N );
	for( int i = 0; i < N; i++ ) {
		xset[ uf.root( i ) ].insert( X[i] );
		yset[ uf.root( i ) ].insert( Y[i] );
	}
	long long ans = 0;
	for( int i = 0; i < N; i++ ) {
		ans += (long long)xset[i].size() * yset[i].size();
	}
	ans -= N;

