void dfsutil(vector<int> adj[],stack<int> &s,int x,bool visited[],vector<int> &vx)
{
	if(!visited[x])
	{vx.push_back(x);
		visited[x]=true;
		for(int i=0;i<adj[x].size();i++)
		dfsutil(adj,s,adj[x][i],visited,vx);		
	}	
}

vector<vector<int> > getSCC(vector<int> adj[],int v)
{
	vector<vector<int> > cc;
	stack<int> s;
	bool visited[v+1]={false};
	for(int i=1;i<=v;i++)
	dfsfillorder(adj,s,i,visited);

	vector<int> adjr[v+1];
	rev(adjr,adj,v);

	for(int i=1;i<=v;i++)
	visited[i]=false;

	while(!s.empty())
	{   int x=s.top();
		s.pop();
		if(!visited[x])
		{
		vector<int> vx;
		dfsutil(adjr,s,x,visited,vx);
		 cc.push_back(vx);
	    } 
	}

return cc;		
}



