// template

class UnionFind{
	vector<int> to;
	vector<int> cnt;
	vector<int> rank;

public:
	UnionFind(int N) {
		to = vector<int>(N); REP(i, N) to[i] = i;
		cnt = vector<int>(N, 1);
		rank = vector<int>(N, 1);
	}

	size_t size() {
		return to.size();
	}

	int root(int node) {
		if (node == to[node]) {
			return node;
		}
		to[node] = root(to[node]);
		return to[node];
	}

	int count(int node) {
		return cnt[root(node)];
	}

	int same(int a, int b) {
		return root(a) == root(b);
	}


	void unite(int a,int b){
		if (rank[a] < rank[b]) swap(a, b);
		int rootb = root(b), roota = root(a);
		to[rootb] = roota;
		cnt[roota] += cnt[rootb];
		if (rank[a] == rank[b]) ++rank[a];
	}
};

void DFS(int node, vector<vector<int> >& G, vector<bool>& check, vector<int>& res) {
	if (check[node]) {
		return;
	}
	check[node] = true;
	res.push_back(node);
	for (auto& to : G[node]) {
		DFS(to, G, check, res);
	}
}

void solve() {
	unordered_map<int, vector<int>> xy;
	unordered_map<int, vector<int>> yx;
	int N; cin >> N;
	vector<pii> ps(N);
	REP(i, N){
		int x, y; cin >> x >> y;
		ps[i] = make_pair(x, y);
	}

	UnionFind uf(1e5 + 1);

	REP(i, N) {
		for (auto& yy : yx) {
			int y = yy.first;
			int old = -1;
			for (auto& x : yy.second) {
				if (old != -1) {
					uf.unite(x, old);
				}
				old = x;
			}
		}
	}

	unordered_map<int, unordered_set<int>> memo;
	for (auto xx : xy) {
		int root = uf.root(xx.first);
		for (auto y : xx.second) {
			memo[root].insert(y);
		}
	}

	int cnt = 0;
	for (auto& xx : xy) {
		int x = xx.first;
		cnt += memo[uf.root(x)].size() - xy[x].size();
	}
	cout << cnt << endl;
}

