		x-- , y--;
		dsu.merge(x, MAXN + y);
	}
	rep(i, MAXN){
		a[dsu.root(i)]++;
		b[dsu.root(i + MAXN)]++;
	}
	int ans = 0;
	rep(i, 2 * MAXN) if(dsu.root(i) == i) ans += a[i] * b[i];
	cout << ans - n << endl;
	return 0;
}
