class unionfind {
  vector<int> parent;
  public:  
  void init(int n) {
    for (int i = 0; i < n; i++) {
      parent.push_back(i);
    }
  }

  void merge(int m, int n) {
    if (find(m) == find(n)) return;
    parent.at(find(m)) = find(n);
  }

  int find(int n) {
    if (parent.at(n) == n) return n;
    return parent.at(n) = find(parent.at(n));
  }
};

