const ll N = 100005, INF = 1e9;

int n;
int X[N], Y[N];
int fa[N << 1], totx[N << 1], toty[N << 1];

int mark[N << 1];
int Find(int x) {
	return x == fa[x] ? x : fa[x] = Find(fa[x]);
}
void Uni(int x, int y) {
	x = Find(x), y = Find(y);
	if (x == y) return ;
	fa[x] = y;
	totx[y] += totx[x], toty[y] += toty[x];
}

