typedef long long LL;
const int N = 1e5;

set<int> adjx[N+5], adjy[N+5];

int n;
bool uda[N+5];
bool udy[N+5];

set<int> tmp;

LL bfs(int x){
	LL ret = adjx[x].size();
	LL dptx = 1LL;
	LL dpty = 0LL;
	uda[x] = 1;
	queue<int> qx;
	while(!qx.empty()) qx.pop();
	for(auto cur:adjx[x]){
		udy[cur] = 1;
		dpty++;
		qx.push(cur);
	}
	while(!qx.empty()){
		int now = qx.front(); qx.pop();
		for(auto cur: adjy[now]){
			if(uda[cur]) continue;
			uda[cur] = 1;
			dptx++;
			ret+=adjx[cur].size();
			for(auto lala : adjx[cur]){
				if(udy[lala]) continue;
				udy[lala] = 1;
				dpty++;
				qx.push(lala);
			}
		}
	}
//	cout << dptx << " " << dpty << " " << ret  << endl;
	return dptx*dpty - ret;
}

int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		int x,y;
		scanf("%d%d",&x,&y);
		adjx[x].insert(y);
		adjy[y].insert(x);
	}
	LL ans = 0LL;
	for(int i=1;i<=N;i++){
		if(uda[i]) continue;
		ans+=bfs(i);
	}
	printf("%lld\n",ans);
	return 0;
}

