namespace NyaGadget
{
	struct UnionFindVertex
	{	// 頂点を表現する構造体
		ll self = 0;
		ll root = 0;
		ll size = 0;
	};

	struct UnionFind
	{
		vt<UnionFindVertex> v;

		/**
		@brief コンストラクタ
		@param vsize 頂点の数
		@note
		 vsizeのunion-findを作成する
		**/
		UnionFind(ll vsize)
		{
			v.resize(vsize);
			each(i, e, v)
			{	// 各頂点の根を自分自身で初期化、各頂点の木サイズは１で初期化
				e.self = i;
				e.root = i;
				e.size = 1;
			}
		}
		/**
		@brief 根を検索する関数
		@param i 根を検索する頂点インデックス
		@note
		 引数で指定された頂点の根を返す。
		**/
		ll Find(ll i)
		{
			if (i == v[i].root) return i;

			// 根の探索をすると同時に次からO(1)で根を参照できるようにする(経路圧縮)
			v[i].root = Find(v[i].root);
			return v[i].root;
		}
		/**
		@brief 頂点を併合する関数
		@note
		 頂点i1を含む木と頂点i2を含む木を結合する。
		 ただし、i1とi2が既に同じ木に属しているときは何もしない。
		**/
		void Union(ll i1, ll i2)
		{
			ll root1 = Find(i1);
			ll root2 = Find(i2);

			// 既に同じ木に属しているときは何もしない
			if (root1 == root2) return;

			// サイズの小さい木の根をサイズの大きい木の根に繋いで結合する
			if (v[root1].size < v[root2].size)
			{
				v[root1].root = root2;
				v[root2].size += v[root1].size;
			}
			else
			{
				v[root2].root = root1;
				v[root1].size += v[root2].size;
			}
		}

		/**
		@brief 頂点を併合する関数
		@note
		 頂点i1を含む木と頂点i2を含む木を結合する。
		 ただし、i1とi2が既に同じ木に属しているときは何もしない。
		**/
		void Union(ll i1, ll i2, ll parent)
		{
			ll root1 = Find(i1);
			ll root2 = Find(i2);

			// 既に同じ木に属しているときは何もしない
			if (root1 == root2) return;

			// 子の木を親の木へ併合する。
			if (parent == i1)
			{
				v[root2].root = root1;
				v[root1].size += v[root2].size;
			}
			else
			{
				v[root1].root = root2;
				v[root2].size += v[root1].size;
			}
		}
	};
}

using namespace NyaGadget;

struct Dim2
{
	ll x = 0;
	ll y = 0;
};

int main(void)
{
	const ll MAX = 100000 + nya;
	ll N; cin >> N;
	vt<Dim2> v(N); each(i, e, v) cin >> e.x >> e.y;

	each(i, e, v)
	{
		e.x--; e.y--;
		e.y += MAX;
	}

	UnionFind uf(2 * MAX);
	each(i, e, v) uf.Union(e.x, e.y, e.x);

	// uf.Find(i)=iの頂点に注意して要素数をカウント
	vt<ll> xsize(2 * MAX), ysize(2 * MAX);
	rep(i, 0, MAX) xsize[uf.Find(i)]++;
	rep(i, MAX, 2 * MAX) ysize[uf.Find(i)]++;

	ll ans = 0;
	rep(i, 0, MAX) ans += xsize[i] * ysize[i];
	cout << ans - N;

	return 0;
}

