int main(){
    int N;
    cin >> N;
    int max_x = 0;
    int max_y = 0;
    for(int i = 0; i < N; i++){
        cin >> x[i] >> y[i];
        max_x = max(x[i], max_x);
        max_y = max(y[i], max_y);
        x_count[x[i] - 1] ++;
        y_count[y[i] - 1] ++;
    }

    long long cum_sum = 0;
    for(int i = 0; i < max_x; i++){

        if(x_count[i] > 0){
            cum_sum += x_count[i] * (x_count[i] - 1) / 2;
        }
    }
    long long ans = 0;
    for(int i = 0; i < max_y; i++){
        if(y_count[i] > 0){
            ans += y_count[i] * (y_count[i] - 1) / 2 * cum_sum;
        }
    }
    cout << ans << endl;
    return 0;
}

