#include<bits/stdc++.h>
using namespace std;
const int N=2e5+10;
typedef long long LL;
int n,X,Y;
vector<int> G[N],v;
bool vis[N];

void dfs(int x,int dep) {
	if (dep%2) X++; else Y++;
	v.push_back(x);
	vis[x]=1;
	for (int i=0;i<G[x].size();i++) {
		int t=G[x][i];
		if (vis[t]) continue;
		dfs(t,dep+1);
	}
}

int main()
{
	cin>>n;
	for (int i=1;i<=n;i++) {
		int x,y; scanf("%d%d",&x,&y);
		G[x].push_back(y+100000);
		G[y+100000].push_back(x);
	}

	memset(vis,0,sizeof(vis));
	LL ans=0;
	for (int i=1;i<=200000;i++) 
		if (G[i].size() && !vis[i]) {
			X=0; Y=0; v.clear();
			dfs(i,1);
			LL num=0;
			for (int j=0;j<v.size();j++) num+=G[v[j]].size();
			ans+=(LL)X*Y-num/2;
		}
	cout<<ans<<endl;	
	return 0;
}

