int main()
{
    map<int,vector<int>> xindex;
    map<int,vector<int>> yindex;

    int n = get<int>();
    vector<int> a(n), b(n);
    vector<bool> visited(n);
    for (int i = 0; i < n; i++) {
        a[i] = get<int>(), b[i] = get<int>();
        xindex[a[i]].push_back(i);
        yindex[b[i]].push_back(i);
    }
    long ans = 0;
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;

        vector<int> xset;
        vector<int> yset;
        function<long(int)> dfs = [&](int j) {
            if (visited[j]) return 0L;
            xset.push_back(a[j]);
            yset.push_back(b[j]);
            visited[j] = true;
            long r = 1;
            for (int k : xindex[a[j]])
                r += dfs(k);
            for (int k : yindex[b[j]])
                r += dfs(k);
            return r;
        };
        long r = dfs(i);
        sort(xset.begin(), xset.end());
        long xsize = unique(xset.begin(), xset.end()) - xset.begin();
        sort(yset.begin(), yset.end());
        long ysize = unique(yset.begin(), yset.end()) - yset.begin();
        ans += xsize*ysize - r;
    }
    cout << ans << endl;
    return 0;
}

