    int N; cin>>N;
    map<long, set<long>> xs, ys;
    vector<pair<long, long>> pos;
    for (size_t i = 0; i < N; i++) {
        long x,y; cin>>x>>y;
        xs[x].insert(y);
        ys[y].insert(x);
        pos.emplace_back(x,y);
    }

    long cnt = 0;
    set<long> xx, yy;
    map<pair<long,long>, bool> visited;
    function<void(long,long)> find = [&](long x, long y) {
        if (visited.find({x,y}) != visited.end())
            return;
        visited[{x,y}] = true;
        cnt++;
        xx.insert(x);
        yy.insert(y);
        for (auto cy : xs[x]) {
            if (cy != y)
                find(x, cy);
        }
        for (auto cx : ys[y]) {
            if (cx != x)
                find(cx, y);
        }
    };
    for (auto& p : pos) {
        if (xs[p.first].size() >= 2 and ys[p.second].size() >= 2) {
            find(p.first, p.second);
        }
    }

    long ans = xx.size() * yy.size() - cnt;
    cout << ans << endl;


    return 0;
}

