    scanf("%d %d", &(x[i]), &(y[i]));
  }

  UnionFind uf(MAX_N * 2 + 20);

  for (int i = 0; i < n; ++i) {
    int node_x = x[i];
    int node_y = y[i] + MAX;

    uf.unite(node_x, node_y);
  }

  unordered_map<int, int> conn2edgenum;

  for (int i = 0; i < n; ++i) {
    int node_x = x[i];
    conn2edgenum[uf.find(node_x)] += 1;
  }

  unordered_set<int> xs;
  for (int i = 0; i < n; ++i) {
    xs.insert(x[i]);
  }

  unordered_map<int, int> conn2xnodenum;
  for (auto &e : xs) {
    conn2xnodenum[uf.find(e)] += 1;
  }

  unordered_set<int> ys;
  for (int i = 0; i < n; ++i) {
    ys.insert(y[i]);
  }

  unordered_map<int, int> conn2ynodenum;
