ll ans = 0;

// 隣接リストを用いた深さ優先探索（再帰ver.） O(|V|+|E|)
vector<int> color(2e5, 0);

void dfs(const vector<vector<int>> &G, set<pair<int, int>> &s, int u, int &x, int &y, bool root = true) {
  color[u] = 1; // GRAY
  if (u < 1e5) x++;
  else y++;
  for (int i = 0; i < G[u].size(); i++) {
    s.insert(make_pair(min(u, G[u][i]), max(u, G[u][i])));
    if (color[G[u][i]] == 0) dfs(G, s, G[u][i], x, y, false);
  }
  color[u] = 2; // BLACK
  if (root) {
    if (x >= 2 && y >= 2) ans += x * y - s.size();
  }
  return;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<vector<int>> G(2e5); // 隣接リスト

  for (int i = 0; i < n; i++) {
    int u, v;
    cin >> u >> v;
    u--;
    v--;
    v += 1e5;
    G[u].emplace_back(v);
    G[v].emplace_back(u); // 有向グラフではコメントアウト
  }

  for (int i = 0; i < 1e5; i++) {
    if (color[i] == 0) {
      set<pair<int, int>> s;
      int x = 0, y = 0;
      dfs(G, s, i, x, y);
    }
  }

  cout << ans << '\n';
}

