signed main() {
	int n;
	std::cin >> n;
	std::map<std::pair<int,int> ,int> went;
	std::unordered_map<int,std::vector<int> > X;
	std::unordered_map<int,std::vector<int> > Y;
	std::vector<std::pair<int,int> > points;
	std::vector<std::vector<std::pair<int,int> > > connected;
	points.reserve(n);
	rep(i,n) {
		int x,y;
