		for(auto y:X[point.first]) {
			if(went[std::make_pair(point.first,y)]) continue;
			connected[connected.size()-1].emplace_back(point.first,y);
			went[std::make_pair(point.first,y)] = true;
			dfs(std::make_pair(point.first,y));
		}
		for(auto x:Y[point.second]) {
			if(went[std::make_pair(x,point.second)]) continue;
			connected[connected.size()-1].emplace_back(x,point.second);
			went[std::make_pair(x,point.second)] = true;
			dfs(std::make_pair(x,point.second));
		}
	};
	for(auto&& p:points) {
		if(went[p]) continue;
		connected.push_back(std::vector<std::pair<int,int> > ());
		connected[connected.size()-1].emplace_back(p);
		went[p] = true;
		dfs(p);
	}
	int sum = 0;
	for(auto&& i:connected) {
		std::set<int> ux;
		std::set<int> uy;
		for(auto&& j:i) {
			ux.emplace(j.first);
			uy.emplace(j.second);
		}
		sum += ux.size()*uy.size()-i.size();
	}
	print(sum);
	return 0;
}

