struct UnionFind{
    // 頂点数(1-indexed)
    const int V;
    // par[x]:=xのroot
    vector<int> par;
    // sz[x]:=xを含む集合のサイズ
    vector<int> sz;
    UnionFind(const int V):V(V){
        par.resize(V+1);
        for(int i=0;i<=V;i++) par[i]=i;
        sz.resize(V+1,1);
    }
    bool unite(int x,int y){
        x=root(x),y=root(y);
        if(same(x,y)) return false;
        if(y<x) swap(x,y);
        par[y]=x;
        sz[x]+=sz[y];
        return true;
    }
    int root(int x){
    	if(par[x]==x) return x; // xはroot
    	return (par[x]=root(par[x])); // xの親のroot
    }
    bool same(int x,int y){
    	return (root(x)==root(y));
    }
    int size(int x){
        return sz[root(x)];
    }
};

int main() {
	const int MAX = 100010;
	int n; cin>>n;
	UnionFind ufX(MAX),ufY(MAX);
	int x[n],y[n];
	int px[MAX],py[MAX]; rep(i,MAX) px[i]=py[i]=-1;
	rep(i,n){
		cin>>x[i]>>y[i];
		if(px[x[i]]!=-1){
			ufY.unite(y[i], y[px[x[i]]]);
		}
		if(py[y[i]]!=-1){
			ufX.unite(x[i], x[py[y[i]]]);
		}
		px[x[i]]=i;
		py[y[i]]=i;
	}
	bool usedX[MAX],usedY[MAX];
	int64_t ans=-n;
	rep(i,n){
		if(usedX[ufX.root(x[i])] || usedY[ufY.root(y[i])]) continue;
		ans+=(int64_t)(ufX.size(x[i]))*(int64_t)(ufY.size(y[i]));
		usedX[ufX.root(x[i])] = 1;
		usedY[ufY.root(y[i])] = 1;
	}
	cout<<ans<<endl;
	return 0;
}

