constexpr int MAX = 200010;

typedef struct UnionFindTree{
    vector<int> par, edge;
    vector<array<int, 2>> cnt;

    UnionFindTree(int n){
        par.resize(n, -1);
        cnt.resize(n);
        edge.resize(n);
        rep(i, n){
            if(i < n/2) cnt[i][0] = 1, cnt[i][1] = 0;
            else cnt[i][0] = 0, cnt[i][1] = 1;
        }
    }

    bool is_root(int x){
        return par[x]<0;
    }

    int find(int x){
        if(is_root(x)) return x;
        return par[x] = find(par[x]);
    }

    int size(int x){
        return -par[find(x)];
    }

    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        ++edge[x];
        if(x == y) return false;
        if(size(x) < size(y)) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        rep(i, 2) cnt[x][i] += cnt[y][i];
        edge[x] += edge[y];
        return true;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
}UF;

