    sort(all(ys));
    ys.erase(unique(all(ys)), ys.end());
    for(ll x: xs) mx[uf.root_find(x)]++;
    for(ll y: ys) my[uf.root_find(mid + y)]++;

    ans -= n;
    for (auto& p: mx)
        ans += p.e2 * my[p.e1];
