ll find(ll a)
{
    if (UF[a] == -1)
    {
        return -1;
    }

    if (UF[a] == a)
    {
        return a;
    }
    return UF[a] = find(UF[a]);
}

void unite(ll a, ll b)
{
    if (UF[a] == -1)
        UF[a] = a;
    if (UF[b] == -1)
        UF[b] = b;
    UF[b] = find(a);
}

void dfs(ll pts)
{
    foreach (child, PTS[pts])
    {
        if (UF[child] == -1)
        {
            unite(pts, child);
            dfs(child);
        }
    }
}

