/* 
read_graph(n, m, graph, cost, directed, offset)
    cost: if link cost is fixed, put positive integer
          otherwise -1
    directed: if directed true, olse false
    offset: if the given vertex is 1-indexed, -1.
*/

void solve(){
    in1(n);
    const ll med = 100005;
    UnionFind uf(med * 2);
    set<ll> sx, sy;
    rep(i, n){
        ll x, y; in2(x, y);
        sx.insert(x), sy.insert(y);
        uf.unite(x, med + y);
    }

    mll mx, my;
    answer = 0;
    auto itx = sx.begin(), ity = sy.begin();
    while (itx != sx.end()) mx[uf.root_find(*(itx++))]++;
    while (ity != sy.end()) my[uf.root_find(med + *(ity++))]++;

    for(auto& kv: mx){
        ll p = kv.e1, num = kv.e2;
        answer += num * my[p];
    }

    answer -= n;
    prl(answer);
}

