class UnionFind {
  vector<int> par, rank, potential;
public:
  UnionFind(int n) {
    par.resize(n, -1);
    rank.resize(n, 0);
    potential.resize(n, 0);
  }
  int root(int x) {
    if (par[x] < 0)
      return x;
    int r = root(par[x]);
    potential[x] += potential[par[x]];
    return par[x] = r;
  }
  int size(int x) {
    return -par[root(x)];
  }
  int weight(int x) {
    root(x);
    return potential[x];
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  bool unite(int x, int y, int w = 0) {
    w += weight(x);
    w -= weight(y);
    x = root(x);
    y = root(y);
    if (x == y) {
      return false;
    }
    if (rank[x] < rank[y]) {
      swap(x, y);
      w = -w;
    }
    if (rank[x] == rank[y])
      rank[x]++;
    par[x] += par[y];
    par[y] = x;
    potential[y] = w;
    return true;
  }
  int diff(int x, int y) {
    return weight(y) - weight(x);
  }
};

const int MAX = 100010;

int main() {
  int n;
  cin >> n;
  vector<int> x(n), y(n);
  UnionFind uf(MAX*2);
  rep(i, n) {
    cin >> x[i] >> y[i];
    uf.unite(x[i], y[i]+MAX);
  }
  map<int, ll> xnum, ynum;
  rep(i, MAX) {
    xnum[uf.root(i)]++;
    ynum[uf.root(i+MAX)]++;
  }
  ll mx = 0;
  rep(i, MAX*2)
    mx += xnum[i]*ynum[i];
  cout << mx-n << endl;
  return 0;
}

