using namespace std;

long union_find_find(long num, vector<long> &vec) {
  if (vec[num] == -1) return num;
  long ret = union_find_find(vec[num], vec);
  vec[num] = ret;
  return ret;
}

unordered_map<long, unordered_set<long>> same_x_group;
unordered_map<long, unordered_set<long>> same_y_group;

unordered_map<long, unordered_set<long>> xs;
unordered_map<long, unordered_set<long>> ys;
unordered_set<long> roots;

void solve() {
  long N;
  cin >> N;

  vector<long> vec(N, -1);
  vector<pair<long, long>> points(N);

  rep (i, N) {
    long x, y;
    cin >> x >> y;
    same_x_group[x].insert(i);
    same_y_group[y].insert(i);
    points[i] = make_pair(x, y);
  }

  for (auto _it = same_x_group.begin(); _it != same_x_group.end(); _it++) {
    long tmp_root = *(_it->second.begin());
    for (auto it = _it->second.begin(); it != _it->second.end(); it++) {
      if (it == _it->second.begin()) continue;
      long node = *it;
      vec[node] = tmp_root;
    }
  }

  for (auto _it = same_y_group.begin(); _it != same_y_group.end(); _it++) {
    long first_node = *(_it->second.begin());
    long first_node_root = union_find_find(first_node, vec);
    for (auto it = _it->second.begin(); it != _it->second.end(); it++) {
      if (it == _it->second.begin()) continue;
      long current_node = *it;
      long current_node_root = union_find_find(current_node, vec);
      vec[current_node_root] = first_node_root;
    }
  }

  rep (i, N) {
    long root = union_find_find(i, vec);
    xs[root].insert(points[i].first);
    ys[root].insert(points[i].second);
    roots.insert(root);
  }

  long maximum_points = 0;

  for (auto r: roots) {
    maximum_points += xs[r].size() * ys[r].size();
  }

  cout << maximum_points - N << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

