    cin >> x >> y;
    ps.emplace_back(x, y);
    if (!xp[x].empty()) uf.unite(xp[x].back(), i);
    xp[x].push_back(i);
    if (!yp[y].empty()) uf.unite(yp[y].back(), i);
    yp[y].push_back(i);
  }

  vector<set<i64>> sx(n), sy(n);
  for (i64 i = 0; i < n; ++i) {
    i64 r = uf.root(i);
    sx[r].insert(ps[i].first);
    sy[r].insert(ps[i].second);
  }

  vector<bool> done(n);
  i64 ans = 0;
  for (i64 i = 0; i < n; ++i) {
    i64 r = uf.root(i);
    if (!done[r]) {
      ans += sx[r].size() * sy[r].size() - uf.size(r);
      done[r] = true;
    }
  }
  cout << ans << '\n';
  return 0;
}

