class UnionFind{
public:
  UnionFind(int aN)
  {
    init(aN);
  }

  void init(int aN)
  {
    par.clear(); cnt.clear(); yset.clear();
    par.resize(aN); cnt.resize(aN); yset.resize(aN);
    for (size_t i = 0; i < aN; i++) {
      par[i] = i;
      cnt[i] = 1;
    }
  }

  int find(int aX)
  {
    if(aX == par[aX]) return aX;
    else return par[aX] = find(par[aX]);
  }

  bool same(int aX, int aY)
  {
    return find(aX) == find(aY);
  }

  int size(int aX)
  {
    return cnt[find(aX)];
  }

  void unite(int aX, int aY)
  {
    aX = find(aX);
    aY = find(aY);
    if(aX == aY) return;

    if(cnt[aX] > cnt[aY]) {
      swap(aX, aY);
    }

    par[aX] = aY;
    cnt[aY] += cnt[aX];
    for(auto it : yset[aX]) {
      yset[aY].insert(it);
    }
    // cerr << "UF" << endl;
    // for(auto it : yset[aY]) {
    //   cerr << it << endl;
    // }
  }

  vector<int> par;
  vector<int> cnt;
  vector<set<int>> yset;
};

