    // cerr << "set" << endl;
    // for(auto it : uf.yset[k]) {
    //   cerr << it << endl;
    // }

    if(YMap[Y[n]] != 0) { // 既に他のグループが存在する場合
      uf.unite(YMap[Y[n]], k);
      // cerr << "unite: " << uf.find(YMap[Y[n]]) << ", " << uf.find(k) << endl;
    } else {
      YMap[Y[n]] = k;
    }
  }

  memset(used, 0, sizeof(used));
  int ans = 0;
  REP(n,MAX_N) {
