    this->x = x;
  }
};

int main() {
  int N;
  cin >> N;

  queue<Coord> que;
  map<int, vector<int>> y_list;
  map<int, vector<int>> x_list;

  map <int, map<int, bool>> visited;
  vector<Coord> coords;

  for (int i = 0; i < N; ++i) {
    int x, y;
    cin >> x >> y;

    y_list[x].push_back(y);
    x_list[y].push_back(x);

    visited[y][x] = true;

    coords.push_back(Coord(y, x));
  }

  bool updated = true;
  ll ans = 0;

  while (updated) {
    updated = false;

    vector<Coord> next = coords;

    for (int i = 0; i < coords.size(); ++i) {
      Coord coord = coords[i];

      for (int j = 0; j < x_list[coord.y].size(); ++j) {
        int x = x_list[coord.y][j];

        for (int k = 0; k < y_list[coord.x].size(); ++k) {
          int y = y_list[coord.x][k];

          if (visited[y][x]) continue;
          visited[y][x] = true;

          next.push_back(Coord(y, x));
          updated = true;
          ++ans;
        }
      }
    }

    coords = next;
  }

  cout << ans << endl;

  return 0;
}

