    if(!usedX[p.first]) for(int ix:idX[p.first]){
        usedX[p.first] = true;
        if(visited[ix]) continue;
        for(int r:dfs(ix)) ret.push_back(r);
    }
    if(!usedY[p.second]) for(int iy:idY[p.second]){
        usedY[p.second] = true;
        if(visited[iy]) continue;
        for(int r:dfs(iy)) ret.push_back(r);
    }
    return memo[x] = ret;
}

ll calc(vector<int> X){
    ll ret = 0LL;
    set<int> mx, my;
    for(int i:X){
        mx.insert(P[i].first);
        my.insert(P[i].second);
    }
    ret = (ll)mx.size()*(ll)my.size()-(ll)X.size();
    return ret;
}

int solve(){
    visited.assign(N, false);
    usedX.assign(1e5+1, false);
    usedY.assign(1e5+1, false);
    memo.resize(N);

    ll ans = 0LL;
    for (int i = 0; i < N; i++)
    {
        if(visited[i]) continue;
        vector<int> idx = dfs(i);
        if(!idx.empty()){
            ans += calc(idx);
        }
    }
    cout << ans << endl;
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

