using i64 = long long;

class UF {
    int *par;
    int *rank;

    public:
    UF(int size) : par(new int[size]), rank(new int[size]()) {
        for (int i = 0; i < size; i++) par[i] = i;
    }
    ~UF() { delete[] par; delete[] rank; }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;

        if (rank[x] < rank[y]) par[x] = y;
        else {
            par[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
    }
};

int main() {
    int n;
    std::cin >> n;
    std::vector<std::pair<int, int>> a;
    std::vector<std::deque<int>> xs(100010), ys(100010);
    for (int i = 0; i < n; i++) {
        int x, y;
        std::cin >> x >> y;
        a.emplace_back(x, y);
        xs[x].push_back(i);
        ys[y].push_back(i);
    }

    UF uft(n);
    for (int i = 1; i <= 100000; i++) {
        if (xs[i].size() == 0) continue;
        for (auto v : xs[i]) uft.unite(xs[i].front(), v);
    }
    for (int i = 1; i <= 100000; i++) {
        if (ys[i].size() == 0) continue;
        for (auto v : ys[i]) uft.unite(ys[i].front(), v);
    }

    std::vector<std::set<int>> ux(100010), uy(100010);
    std::set<int> keys;
    for (int i = 0; i < n; i++) {
        ux[uft.root(i)].insert(a[i].first);
        uy[uft.root(i)].insert(a[i].second);
        keys.insert(uft.root(i));
    }

    i64 ret = 0;
    for (auto k : keys) {
        ret += (i64)ux[k].size() * (i64)uy[k].size();
    }
    std::cout << ret - n << std::endl;

    return 0;
}

