struct UnionFind {
    vector<size_t> parent;
    vector<size_t> rank;
    size_t find_parent(size_t x) {
        if (parent[x] == x) {
            return x;
        } else {
            parent[x] = find_parent(parent[x]);
            return parent[x];
        }
    }
    explicit UnionFind(size_t size) {
        parent.resize(size);
        rank.resize(size);
        for (size_t i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }
    virtual ~UnionFind() {}
    void unite(size_t x, size_t y) {
        size_t px = find_parent(x);
        size_t py = find_parent(y);
        if (px == py) {
            return;
        }
        if (rank[px] < rank[py]) {
            parent[px] = py;
        } else if (rank[px] > rank[py]) {
            parent[py] = px;
        } else { // rank[px] == rank[py]
            parent[py] = px;
            rank[px]++;
        }
    }
    bool is_same(size_t x, size_t y) {
        return find_parent(x) == find_parent(y);
    }
};

int main(int argc, char* argv[]) {
    int N;
    cin >> N;
    UnionFind tree(N);
    vector<pair<int, int>> pts;
    map<int, int> x_to_idx;
    map<int, int> y_to_idx;
    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        pts.push_back(make_pair(x, y));
        if (x_to_idx.find(x) != x_to_idx.end()) {
            tree.unite(i, x_to_idx[x]);
        } else {
            x_to_idx[x] = i;
        }
        if (y_to_idx.find(y) != y_to_idx.end()) {
            tree.unite(i, y_to_idx[y]);
        } else {
            y_to_idx[y] = i;
        }
    }
    unordered_map<int, set<int>> parent_idx_to_groups;
    for (int i = 0; i < N; i++) {
        int parent = (int)tree.find_parent(i);
        if (parent_idx_to_groups.find(parent) == parent_idx_to_groups.end()) {
            parent_idx_to_groups[parent] = set<int>{i};
        } else {
            parent_idx_to_groups[parent].insert(i);
        }
    }
    ll count = 0;
    for (const pair<int, set<int>>& parent_group : parent_idx_to_groups) {
        const set<int>& group = parent_group.second;
        set<int> x_coords;
        set<int> y_coords;
        for (int idx : group) {
            x_coords.insert(pts[idx].first);
            y_coords.insert(pts[idx].second);
        }
        count += x_coords.size() * y_coords.size();
    }
    cout << count - pts.size() << endl;
}

