struct UnionFind{
    vector<int> par;
    int count;
    UnionFind(int n) : par(n, -1), count(0){}
    int Find(int x){return par[x] < 0 ? x : Find(par[x]);}
    int Size(int x){return par[x] < 0 ? -par[x] : Size(par[x]);}
    bool Unite(int x, int y){
        x = Find(x);
        y = Find(y);
        if(x == y)
            return false;
        if(par[x] > par[y])
            swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return ++count;
    }
};


bool solve(){

    i64 n;
    input(n);
    vector<i64> x(n), y(n);
    pararell_input(n, x, y);
    i64 cnt = 0;
    map<i64,i64> m;
    map<i64,vector<i64>> y_x;
    for(auto& p : x)
        if(m.find(p) == m.end())
            m[p] = cnt++;
    for(i64 i = 0; i < n; ++i)
        y_x[y[i]].emplace_back(m[x[i]]);
    UnionFind u(cnt);
    for(auto& q : y_x){
        if(q.second.empty())
            continue;
        i64 to = *q.second.begin();
        for(auto& qq : q.second)
            u.Unite(to, qq);
    }
    vector<set<i64>> s(cnt);
    for(i64 i = 0; i < n; ++i)
        s[u.Find(m[x[i]])].emplace(y[i]);

    i64 ans = -n;
    for(i64 i = 0; i < cnt; ++i){
        ans += u.Size(i) * s[i].size();
    }
    cout << ans << endl;

    return false;
}

