int unite(std::vector<long long int> &root, std::vector<long long int> &rank, long long int i1, long long int i2){
  i1 = find_root(root, i1);
  i2 = find_root(root, i2);

  if(rank[i1] < rank[i2]){
    root[i1] = i2;
  }
  else if(rank[i1] > rank[i2]){
    root[i2] = i1;
  }
  else{
    root[i1] = i2;
    rank[i2]++;
  }
  return 0;
}

