      //unite(points, group_tmp, i);
    }
    else{
      group_tmp = i;
    }
  }

  // update group
  for(long long int i = 0; i < N; i++){
    points[i].group = find_root(root, points[i].index);
  }

  std::sort(points.begin(), points.end(), compgrp);

