  std::vector<long long int> xcount(1e5+1), ycount(1e5+1);
  long long int ans = 0;
  long long int grp_xcnt=0, grp_ycnt=0;
  tmp1 = 0;
  group_tmp = -1;
  for(long long int i = 0; i < N; i++){
    // new group is found
    if(points[i].group != group_tmp){
      //std::cerr << "new group found: i = " << i << std::endl;
      // update answer
      ans += grp_xcnt*grp_ycnt - (i-tmp1);
      //std::cerr << grp_xcnt << " " << grp_ycnt << " " << i << " " << tmp1 << std::endl;
      //std::cerr << "ans = " << ans << std::endl;
      //reset state
      for(long long int j = tmp1; j < i; j++){
        grp_xcnt = 0;
        grp_ycnt = 0;
        xcount[points[j].x] = 0;
        ycount[points[j].y] = 0;
