    // update state
    if(xcount[points[i].x] == 0){
      xcount[points[i].x] = 1;
      grp_xcnt++;
    }
    if(ycount[points[i].y] == 0){
      ycount[points[i].y] = 1;
      grp_ycnt++;
    }
  }

  // last group
  //std::cerr << grp_xcnt << " " << grp_ycnt << " " << N << " " << tmp1 << std::endl;
  ans += grp_xcnt*grp_ycnt - (N-tmp1);

  std::cerr << "Answer:" << std::endl;
  std::cout << ans << std::endl;

  return 0;
}

