typedef long long ll;

template <typename S>   //semi group
struct UnionFind
{
    using F = function<S(S, S)>;

    const F f;

    vector<int> par, rank;
    vector<S> dat;

    UnionFind(int n, const F f = [](S a, S b){return a + b;}) : f(f){
        par.resize(n);
        rank.resize(n);
        dat.assign(n, 1);
        for(int i = 0; i < n; i++){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int i){
        if(i == par[i]) return i;
        return par[i] = find(par[i]);
    }

    bool same(int i, int j){
        return find(i) == find(j);
    }

    void unite(int i, int j){
        if(same(i, j)) return;
        i = find(i), j = find(j);
        if(rank[i] < rank[j]){
            par[i] = j;
            dat[j] = f(dat[i], dat[j]);
        }
        else{
            par[j] = i;
            dat[i] = f(dat[i], dat[j]);
            if(rank[i] == rank[j]) rank[i]++;
        }
    }

    S query(int i){
        return dat[find(i)];
    }
};

int main()
{
    int n;
    cin >> n;
    int x[100005], y[100005];
    vector<int> vx[100005], vy[100005];
    for(int i = 0; i < n; i++){
        cin >> x[i] >> y[i];
        x[i]--; y[i]--;
        vx[x[i]].push_back(i);
        vy[y[i]].push_back(i);
    }
    bool b[100005]{0};
    queue<int> que;
    UnionFind<ll> ufs(n), ufx(100005), ufy(100005);
    ll ans = 0;
    for(int i = 0; i < n; i++){
        if(b[i]) continue;
        b[i] = true;
        que.push(i);
        while(que.size()){
            int u = que.front();
            que.pop();
            for(int v : vx[x[u]]){
                if(b[v]) continue;
                b[v] = true;
                ufs.unite(u, v);
                ufy.unite(y[u], y[v]);
                que.push(v);
            }
            for(int v : vy[y[u]]){
                if(b[v]) continue;
                b[v] = true;
                ufs.unite(u, v);
                ufx.unite(x[u], x[v]);
                que.push(v);
            }
        }
        ans += ufx.query(x[i]) * ufy.query(y[i]) - ufs.query(i);
    }
    cout << ans << endl;
}

