	for (auto itr : mpy) {
		auto st = itr.second;
		int base = *st.begin();
		for (auto opp : st)uf.unite(base, opp);
	}

	// mp: par->idx
	map<int, set<int>> par;
	REP(i, N) par[uf.find(i)].insert(i);

	// calc
	ll res = 0;
	for (auto itr : par) res += count(itr.second, xy);
	cout << res - N << endl;
	return 0;
}

