int uf[MAXN], ufcnt[MAXN];
int find(int a) {
	if (uf[a] == a)
		return a;
	return uf[a] = find(uf[a]);
}
void uni(int a, int b) {
	int fa = find(a), fb = find(b);
	if (fa == fb)
		return ;
	// cout<<"Uni Node"<<a<<" Node"<<b<<endl;
	if (ufcnt[fa] > ufcnt[fb])
		uf[fb] = fa, ufcnt[fa] += ufcnt[fb];
	else
		uf[fa] = fb, ufcnt[fb] += ufcnt[fa];
}

int main() {
	int n;
	cin>>n;
	for (int i=0; i<n; i++) 
		uf[i] = i, ufcnt[i] = 1;

	for (int i=0; i<n; i++) {
		cin>>node[i].x>>node[i].y;

		if (mx.find(node[i].x) != mx.end())
			uni(i, *mx[node[i].x].begin());
		else
			mx[node[i].x].insert(i);

		if (my.find(node[i].y) != my.end())
			uni(i, *my[node[i].y].begin());
		else
			my[node[i].y].insert(i);
	}
	mx.clear();
	my.clear();

	for (int i=0; i<n; i++) {
		int gpid = find(i);
		mx[gpid].insert(node[i].x);
		my[gpid].insert(node[i].y);
