void solve()
{
	// とりあえず、座圧しよう。
	// 座圧後のグリッドの世界で、紙とペンで適当に実験してみる。
	// 
	// どうも、縦横でつながってる同士を点で結んだ中身に全部点が打たれる気がする。(証明できないけど)
	// |＊＊・|＊　＊　|＊・＊・
	// |＊・＊|　＊　＊|＊＊・＊
	// |・＊・|＊　・　|＊・・・
	//
	// どうも、列同士の入れ替え、行同士の入れ替えしても結果は変わらない気がする。(証明できないけど)
	// |＊　＊　|＊＊　　|＊＊　　|
	// |　＊　＊|　　＊＊|＊・　　|
	// |＊　・　|＊・　　|　　＊＊|　これは、連結成分分解で見たことあるやつ。
	// 
	// 各矩形の高さｘ幅からあらかじめ打ってあるところの数を引けばよさそう。
	// 座標を添え字にしてないし、結果的には、座圧はしなくてもよかったな。

	READ(int, N);
	auto Ps = read<pair<int, int>>(N);

	UnionFindForest f(N);

	// XかY座標が一緒だったら union したい……どうする？
	{
		// XとYと別々に見て2回やれば O(N) x2 になるか。

		// 同じX座標同士を link
		{
			std::map<int, int> found;
			REP(i, N)
			{
				auto it = found.find(Ps[i].first);
				if (it != found.end()) { f.link(i, it->second); }
				else { found[Ps[i].first] = i; }
			}
		}

		// 同じy座標同士を link
		{
			std::map<int, int> found;
			REP(i, N)
			{
				auto it = found.find(Ps[i].second);
				if (it != found.end()) { f.link(i, it->second); }
				else { found[Ps[i].second] = i; }
			}
		}
	}

	{
		// 各連結成分内に出現する x,y 座標のset
		struct Rect { set<int> Xs, Ys; };
		std::map<int, Rect> rects;
		REP(i, N)
		{
			rects[f.rootOf(i)].Xs.insert(Ps[i].first);
			rects[f.rootOf(i)].Ys.insert(Ps[i].second);
		}

		// 各連結成分について、出現するX座標の数 x 出現するY座標の数 が、矩形を埋めたときの点の数。
		llong total = 0;
		FORE(r : rects)
		{
			Rect rect = r.second;
			total += rect.Xs.size() * rect.Ys.size();
		}

		// あらかじめ打ってあったところを引く。
		WRITE(total - N);
	}
}

