    if (visited[v]) return;
    visited[v] = true;
    if (v < G.size()/2) ++xcnt;
    else                ++ycnt;
    for (auto u : G[v]) {
        if (u == p) continue;
        ++ecnt;
        dfs(G, visited, u, v, xcnt, ycnt, ecnt);
    }
}

