        int xx, yy;
        cin >> xx >> yy;
        y[xx].push_back(yy);
        x[yy].push_back(xx);
    }
    UnionFind uf(100010);
    for(int i = 0; i <= 100000; i++) {
        for(int j = 1; j < x[i].size(); j++) {
            uf.unite(x[i][j], x[i][j - 1]);
        }
    }
    vector<vector<int>> v(100010);
    for(int i = 0; i <= 100000; i++) {
        v[uf.find(i)].push_back(i);
    }
    ll ans = 0;
    for(int i = 0; i <= 100000; i++) {
        if(uf.find(i) != i) {
            continue;
        }
        set<int> st;
        for(auto& e : v[i]) {
            for(auto& s : y[e]) {
                st.insert(s);
            }
        }
        if(st.empty()) {
            ans += (ll)x[i].size();
        } else {
            ll to = uf.siz[i];
            to *= (ll)st.size();
            ans += to;
        }
    }
    cout << ans - n << endl;
}

