typedef long long ll;

struct union_find {
    vector<ll> par;
    vector<ll> rank;

    union_find(ll n) : par(n, 0), rank(n, 0) {
        for(ll i = 0; i < n; ++i){ par.at(i) = i; }
    }

    ll find(ll x){
        if(par.at(x) == x){
            return x;
        }else{
            return par.at(x) = find(par.at(x));
        }
    }

    void unite(ll x, ll y){
        x = find(x);
        y = find(y);
        if(x == y){ return; }
        if(rank.at(x) < rank.at(y)){
            par.at(x) = y;
        }else{
            par.at(y) = x;
            if(rank.at(x) == rank.at(y)){
                rank.at(x)++;
            }
        }
    }

    bool same(ll x, ll y){
        return find(x) == find(y);
    }
};


int main(){
    ll n;
    cin >> n;
    map<pair<int, ll>, ll> c2i;
    vector<pair<ll, ll>> ps;
    for(ll i = 0; i < n; ++i){
        ll x, y;
        cin >> x >> y;
        ps.push_back(make_pair(x, y));

        auto tmpx = make_pair(0, x);
        if(c2i.count(tmpx) == 0){
            c2i.insert(make_pair(tmpx, c2i.size()));
        }
        auto tmpy = make_pair(1, y);
        if(c2i.count(tmpy) == 0){
            c2i.insert(make_pair(tmpy, c2i.size()));
        }
    }

    union_find uf(c2i.size());
    for(auto p : ps){
        uf.unite(
            c2i.at(make_pair(0, p.first)),
            c2i.at(make_pair(1, p.second)));
    }

    map<ll, ll> count_x, count_y;
    for(auto it = c2i.begin(); it != c2i.end(); ++it){
        if(it->first.first == 0){
            count_x[uf.find(it->second)]++;
        }else{
            count_y[uf.find(it->second)]++;
        }
    }

    ll ans = - n;
    for(auto it = count_x.begin(); it != count_x.end(); ++it){
        ans += it->second * count_y.at(it->first);
    }

    cout << ans << endl;
    return 0;
}

