class UnionFind{
public:
    //親の番号を格納する。親だった場合はー（その集合のサイズ）
    vector<int> parents;
    int count;

    //作る時はparentsを-1で初期化する
    //こうすることで全部ばらばらになる
    UnionFind(int n){
        parents = vector<int>(n, -1);
        count = n;
    }

    //Aがどのグループにいるか調べる
    int root(int A){
        if(parents[A]<0) return A;
        return parents[A] = root(parents[A]);
    }

    //自分のいるグループの大きさを調べる
    int size(int A){
        return -parents[root(A)];
    }

    //AとBをくっつける
    bool connect(int A, int B){
        //AとBを直接ではなく親同士をくっつける
        A=root(A);
        B=root(B);
        if(A==B){
            return false;
        }

        //大きい方（A)に小さい方（B)をくっつけたい
        if(size(A)<size(B)) swap(A, B);

        parents[A] += parents[B];
        parents[B] = A;
        --count;

        return true;
    }
};



int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n; cin >> n;
    int base=100010;
    UnionFind uni(2*base);

    vector<int> x(n), y(n);
    rep(i, n){
        cin >> x[i] >> y[i];
        uni.connect(x[i], y[i]+base);
    }

    map<int, ll> mx, my;
    rep(i, base) ++mx[uni.root(i)];
    repr(i, base, 2*base) ++my[uni.root(i)];
    ll ans=0;
    rep(r, 2*base) ans+=mx[r]*my[r];
    cout << ans-n << endl;

    return 0;
}

