pair<int,int> dfs(Graph &G,int v,int color,vector<bool> &seen){
  seen.at(v)=true;
  int zero=0;
  int one=0;
  if(color==0){
    zero++;
  }else{
    one++;
  }
  for(auto nv:G.at(v)){
    if(seen.at(nv)){
      continue;
    }
    pair<int,int> p=dfs(G,nv,1-color,seen);
    zero+=p.first;
    one+=p.second;
  }
  return make_pair(zero,one);
}

