        cnt[root(a)]+=cnt[root(b)];
        par[root(b)]=root(a);
    }
}

void unite2(int a,int b){
    if(root(a)!=root(b)) {
        for(auto it=cntx[root(b)].begin();it != cntx[root(b)].end();it++){
            int z=*it;
            cntx[root(a)].insert(z);
        }
        for(auto it=cnty[root(b)].begin();it != cnty[root(b)].end();it++){
            int z=*it;
            cnty[a].insert(z);
        }
        cnt[root(a)]+=cnt[root(b)];
        par[root(b)]=root(a);
    }
}

