const int max_v = 1e+5;
vector<bool> visited(2*max_v+1, false);

void dfs(int pos, vector<long long>& num_v, vector<vector<int>>& G){
    if(visited[pos]) return;
    visited[pos] = true;
    ++num_v[pos/max_v];
    for(int v: G[pos]){
        dfs(v, num_v, G);
    }
}

int main()
{
    int N;
    cin >> N;
    vector<vector<int>> G(2*max_v+1);  // y は +max_v して頂点にする
    REP(i, N){
        int x, y;
        cin >> x >> y;
        y += max_v;
        G[x].push_back(y);
        G[y].push_back(x);
    }

    long long ans = 0;
    // 答えはグラフを連結成分ごとに完全二部グラフにするのに必要な本数の和
    // つまり、連結成分ごとの x, y の頂点数が必要
    REP(i, 2*max_v){
        vector<long long> num_v(2);
        dfs(i, num_v, G);
        ans += num_v[0]*num_v[1];
    }
    cout << ans-N << endl;

    return 0;
}

