// Initialise the parents of nodes as the nodes itself, and the ranks as 0
struct dis_set
{
    ll parent;
    ll rank;
    ll si;
};

dis_set s[100001];

ll find(ll i)
{
    if(s[i].parent != i)
        s[i].parent = find(s[i].parent);

    return s[i].parent;
}

void Union(ll x, ll y)
{
    ll xroot = find(x);
    ll yroot = find(y);
    // cout << x << " " << y << " " << xroot << " " << yroot << endl;
    if(s[xroot].rank > s[yroot].rank)
    {
        s[yroot].parent = xroot;
        s[xroot].si += s[yroot].si;
    }
    else if(s[yroot].rank > s[xroot].rank)
    {
        s[xroot].parent = yroot;
        s[yroot].si += s[xroot].si;
    }
    else
    {
        s[xroot].parent = yroot;
        s[yroot].rank++;
    	s[yroot].si += s[xroot].si;
    }
}

