const i64 H = 100001;
i64 n;
vector<vector<i64>> g;
vector<i64> vis;

tuple<i64, i64, i64> dfs(i64 u) {
  if (vis[u]) return {};
  vis[u] = true;
  i64 c = u < H, r = u >= H, e = 0;
  for (i64 v : g[u]) {
    if (!vis[v]) {
      auto t = dfs(v);
      i64 cv, rv, ev;
      tie(cv, rv, ev) = t;
      c += cv;
      r += rv;
      e += ev + 1;
    }
  }
  return make_tuple(c, r, e);
}

