    cin >> x >> y;
    x += 1e5;
    y += 1e5;
    xys[x].insert(y);
    yxs[y].insert(x);
  }

  UnionFind uf(2e5 + 1);
  for (auto s : yxs) {
    for (auto e : s) {
      uf.Unite(*begin(s), e);
    }
  }

  ll r = 0;
  for (int i = 0; i < xys.size(); i++) {
    int f = uf.Find(i);
    if (i == f) continue;
    for (auto e : xys[i]) {
      if (xys[f].count(e)) continue;
      xys[f].insert(e);
      r++;
    }
  }
  for (int i = 0; i < xys.size(); i++) {
    int f = uf.Find(i);
    if (i == f) continue;
    r += (ll)xys[f].size() - xys[i].size();
  }
  cout << r << endl;
}

