vector<vector<int> > g;
vector<bool> visited;

pair<int,int> Search(int start) {
  pair<int, int> counts;
  int V = g.size() / 2;
  queue<int> q;

  q.push(start);
  visited[start] = true;
  if (start < V) counts.first += 1;
  else counts.second += 1;

  while (not q.empty()) {
    int x = q.front();
    q.pop();
    for (auto y : g[x]) {
      if (not visited[y]) {
	q.push(y);
	visited[y] = true;
	if (y < V) counts.first += 1;
	else counts.second += 1;
      }
    }
  }

  return counts;
}

