#define LIM 100000
class UnionFind {
	vector<int>par, sz1,sz2;
public:
	UnionFind() {}
	UnionFind(int n) {
		par = sz1 = sz2= vector<int>(n);
		for (int i = 0; i < n; i++) {
			par[i] = i;
			if(i<LIM)sz1[i] = 1;
			else sz2[i]=1;
		}
	}
	int find(int x) {
		if (par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y)return;
		if (sz1[x] > sz1[y]) {
			par[y] = x;
			sz1[x] += sz1[y];
			sz2[x]+=sz2[y];
		}
		else {
			par[x] = y;
			sz1[y] += sz1[x];
			sz2[y]+=sz2[x];
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size1(int x) {
		return sz1[find(x)];
	}
	int size2(int x){
		return sz2[find(x)];
	}
};
