vv adjListY(2e5 + 1);

ll edgeCount = 0;
pll dfs(ll curr, ll prev, bool isX) {
    pll count = {0, 0};

    if (isX) {
        visitedX[curr] = 1;
        count.first++;
    } else {
        count.second++;
        visitedY[curr] = 1;
    }

    const v &neighs = (isX ? adjListX[curr] : adjListY[curr]);

    for (auto neigh : neighs) {
        if (neigh == prev)
            continue;
        edgeCount++;

        if ((isX ? !visitedY[neigh] : !visitedX[neigh])) {
            pll res = dfs(neigh, curr, !isX);
            count.first += res.first;
            count.second += res.second;
        }
    }

    return count;
}

