	pair<ll, ll> t[MAX];

	repn(i, N) cin >> t[i].first >> t[i].second;

	vector<ll> g[MAX];


	ll x[MAX] = {};
	ll y[MAX] = {};

	repn(i, N) {
		if (x[t[i].first] == 0) { x[t[i].first] = i; }
		else { 
			g[x[t[i].first]].push_back(i);
			g[i].push_back(x[t[i].first]);
		}

		if (y[t[i].second] == 0) { y[t[i].second] = i; }
		else {
			g[y[t[i].second]].push_back(i);
			g[i].push_back(y[t[i].second]);
		}
	}

	ll ans = 0;

	ll visit[MAX] = {};

	repn(v, N) {
		if (visit[v] == 1) { continue; }

		stack<ll> st;

		set<ll> xx;
		set<ll> yy;

		st.push(v);

		while (!st.empty()) {
			ll w = st.top();
			visit[w] = 1;
			st.pop();

			xx.insert(t[w].first);
			yy.insert(t[w].second);

			rep(i, g[w].size()) {
				ll u = g[w][i];
				if (visit[u] == 0) { st.push(u); }
			}


		}

		ans += xx.size()*yy.size();


