int main() {
  int n; cin >> n;
  Graph G(n, vi(2));
  rep(i,n) rep(j,2) cin >> G[i][j];

  sort(all(G));

  unordered_map<int, int> order;
  set<int> s;
  rep(i,n) s.insert(G[i][1]);
  int sz = 0;
  for (auto v : s) {
    order[v] = sz;
    ++sz;
  }

  Graph edge(sz), line(sz);
  int x = -1, y = -1;

  rep(i,n) {
    if (G[i][0] == x) {
      edge[y].push_back(order[G[i][1]]);
      edge[order[G[i][1]]].push_back(y);
    }
    else {
      x = G[i][0];
      y = order[G[i][1]];
    }
    line[order[G[i][1]]].push_back(x);
  }

  vb seen(sz, false);
  ll ans = -n;

  rep(i,sz) {
    if (seen[i]) continue;

    seen[i] = true;
    queue<int> q;
    q.push(i);
    unordered_set<int> Xcounter;
    for (auto p : line[i]) Xcounter.insert(p);
    ll Ycounter = 1;

    while (!q.empty()) {
      int v = q.front(); q.pop();
      for (auto nv : edge[v]) {
        if (seen[nv]) continue;

        seen[nv] = true;
        q.push(nv);
        for (auto p : line[nv]) Xcounter.insert(p);
        ++Ycounter;
      }
    }

    ans += Xcounter.size() * Ycounter;
  }

  cout << ans << endl;
  return 0;
}

