class UnionFind {
private:
	vector<int> par;
public:
	vector<set<int>> X;
	vector<set<int>> Y;
	UnionFind(int N) {par = vector<int>(N, -1);}
	int find(int x);
	ll size(int x);
	void unite(int x, int y);
	bool same(int x, int y);
};

int UnionFind::find(int x) {
	if (par[x] < 0) return x;
	else return par[x] = find(par[x]);
}

ll UnionFind::size(int x) {
	return -par[find(x)];
}

void UnionFind::unite(int x, int y) {
	x = find(x);
	y = find(y);
 	if (x == y) return;
	//大きい方に小さい方をくっ付ける
	if (size(x) < size(y)) swap(x, y);
	par[x] += par[y];
	par[y] = x;
}

bool UnionFind::same(int x, int y) {
	x = find(x);
	y = find(y);
	return x == y;
}

bool solve() {
	int n;cin >> n;
	map<int,unordered_set<int>> X;
	map<int,unordered_set<int>> Y;
	UnionFind uf(n);
	int px[n],py[n];
	REP (i,n) {
		//その点は必ず初出
		int x,y;cin>>x>>y;
		px[i] = x, py[i] = y;
		X[x].insert(i);
		Y[y].insert(i);
		if (X[x].size() > 1) {
			for (auto a : X[x]) {
				if (a != i) {uf.unite(a,i);break;}
			}
		}
		if (Y[y].size() > 1) {
			for (auto a : Y[y]) {
				if (a != i) {uf.unite(a,i);break;}
			}
		}
	}
	int ans = 0;
	map<int,pair<set<int>,set<int>>> XY;
	REP (i,n) {
		XY[uf.find(i)].first.insert(px[i]);
		XY[uf.find(i)].second.insert(py[i]);
	}
	for (auto e : XY) {
		ans += (ll)e.second.first.size() * (ll)e.second.second.size();
	}
	ans -= n;
	cout << ans << endl;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	solve();
}

