int mk[SIZE << 1];

void dfs(coint u, ll &le, ll &ri, ll &ecnt) {
    if (mk[u]) return;
    mk[u] = 1, ecnt += deg[u];
    if (u <= SIZE) ++le;
    else ++ri;

    for (int i = head[u]; ~i; i = edge[i].head) {
        coint v = edge[i].v;
        dfs(v, le, ri, ecnt);
    }

    return;
}

