using namespace std;

class UnionFind {
public:
    vector <int> parent;
    vector <int> size;

    UnionFind(int size_) : parent(size_), size(size_, 1) {
        for (int i = 0; i < size_; ++i) parent[i] = i;
    }

    int root(int x) {
        while (parent[x] != x) {
            x = parent[x] = parent[parent[x]];
        }

        return x;
    }

    bool merge(int x, int y) {
        x = root(x);
        y = root(y);

        if (x == y) return  false;

        if (size[x] < size[y]) swap(x, y);

        size[x] += size[y];
        parent[y] = x;
        return true;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int getSize(int x) {
        return size[root(x)];
    }
};

struct xCmp {
    bool operator() (const pair<int, int>& l, const pair<int, int>& r) const{
        return l.first < r.first;
    }
};

int main() {
    int n;

    scanf("%d", &n);
    vector< pair<int, int> > points;
    set< pair<int, int>, xCmp> xs;
    set< pair<int, int>, xCmp> ys;
    UnionFind uf(n);

    for (int i = 0; i < n; ++i) {
        int x, y;

        scanf("%d%d", &x, &y);

        points.push_back(make_pair(x, y));

        auto it = xs.find(make_pair(x, i));

        if (it != xs.end()) {
            uf.merge(i, it->second);
        }

        xs.insert(make_pair(x, i));

        it = ys.find(make_pair(y, i));

        if (it != ys.end()) {
            uf.merge(i, it->second);
        }
        ys.insert(make_pair(y, i));
    }

    map< int, int > treePoints;
    map< int, set<int> > xCnts;
    map< int, set<int> > yCnts;

    for (int i = 0; i < n; i++) {
       int r = uf.root(i);

       if (!treePoints.count(r)) {
           treePoints[r] = 0;
           xCnts[r] = set<int>();
           yCnts[r] = set<int>();
       }

       treePoints[r] += 1;
       xCnts[r].insert(points[i].first);
        yCnts[r].insert(points[i].second);
    }

    long long res = 0;

    for(auto it = treePoints.begin(); it != treePoints.end(); it++) {
        int key = it->first;

        res += (long long)(xCnts[key].size() * yCnts[key].size() - treePoints[key]);
    }

    printf("%lld\n", res);

    return 0;
}

