        st.push(i);
        while (!st.empty()) {
            ll t = st.top();
            st.pop();

            visit[t] = true;
            (t <= MAX ? X_num++ : Y_num++);

            for (ll next : edges[t]) {
                if (!visit[next]) {
                    st.push(next);
                }
            }
        }

        ans += X_num * Y_num;
    }

    cout << ans - N << endl;
