bool y_visited[110000];

void dfs(int i)
{
  if (x_visited[i]) return;
  x_visited[i] = true;
  x_cnt++;
  for (int y: x_edge[i]) {
    if (y_visited[y]) {
      continue;
    }
    y_visited[y] = true;
    y_cnt++;
    for (int x: y_edge[y]) {
      dfs(x);
    }
  }
}

