ll rt(ll x)
{
    while(x!=id[x])
    {
        id[x]=id[id[x]];
        x=id[x];
    }
    return x;
}

void merg(ll x,ll y)
{
    ll rtx=rt(x);
    ll rty=rt(y);
    if(rtx==rty)return;
    if(sz[rtx]>sz[rty])
		swap(rtx, rty);

	sz[rty]+=sz[rtx];
	sz[rtx]=0;
	id[rtx]=id[rty];
	return ;
}

