    map<int, set<int>> mp2;
    rep(i, n){
        mp1[y[i]].insert(x[i]);
        mp2[x[i]].insert(y[i]);
    }

    UnionFind uf(n);
    for(auto s : mp1){
        set<int> st = s.second;
        for(int a : st){
            if(a != *st.begin()) uf.unite(a, *st.begin());
        }
    }

    map<int, set<int>> mp3;
    rep(i, n){
        int p = uf.find(x[i]);
        for(auto s : mp2){
            set<int> st = s.second;
            for(int b : st){
                mp3[p].insert(b);
            }
        }
    }

    ll ans = 0;
    for(auto s : mp3){
        ans += ((ll) s.second.size()) * uf.getSize(s.first);
    }

    cout << ans - n << endl;
}

