/// ユニオンファインド森。ユニオンファインドが必要な問題が解ける。
struct UnionFindForest
{
	vector<int> p{};
	UnionFindForest(int n) : p(n, -1) { }
	int rootOf(int i) { return p[i] < 0 ? i : (p[i] = rootOf(p[i])); }
	int countOf(int i) { return -p[rootOf(i)]; }

	bool linked(int a, int b) { return rootOf(a) == rootOf(b); }
	bool link(int a, int b)
	{
		int x = rootOf(a), y = rootOf(b);
		if (x != y)
		{
			p[x] += p[y];
			p[y] = x;
		}
		return x != y;
	}

	int countOfTrees()
	{
		return count_if(allof(p), PRED(p, p < 0));
	}
};

void solve()
{
	READ(int, N);

	auto Ps = read<pair<int, int>>(N);

	UnionFindForest f(N);

	{
		std::map<int, int> x;
		REP(i, N)
		{
			auto it = x.find(Ps[i].first);
			if (it != x.end())
			{
				f.link(i, it->second);
			}
			else
			{
				x[Ps[i].first] = i;
			}
		}
	}

	{
		std::map<int, int> x;
		REP(i, N)
		{
			auto it = x.find(Ps[i].second);
			if (it != x.end())
			{
				f.link(i, it->second);
			}
			else
			{
				x[Ps[i].second] = i;
			}
		}
	}

	{
		struct R
		{
			set<int> xs, ys;
		};

		std::map<int, R> mp;
		REP(i, N)
		{
			int root = f.rootOf(i);
			mp[f.rootOf(i)].xs.insert(Ps[i].first);
			mp[f.rootOf(i)].ys.insert(Ps[i].second);
		}

		llong total = 0;
		FORE(r : mp)
		{
			R rect = r.second;
			total += rect.xs.size() * rect.ys.size();
		}

		WRITE(total - N);
	}
}

