class UnionFind{
public:
  vector<int> par;
  vector<int> rank;
  vector<int> sz;
  int N;

  UnionFind(int n){N = n;}

  //初期化
  void init(){
      par.resize(N);
      rank.resize(N, 0);
      sz.resize(N, 1);
      for(int i = 0; i < N; i++) par[i] = i;
  }

  //木の根を求める
  int find(int x){
    if(par[x] == x) return x;
    else {
      par[x] = find(par[x]);
      return par[x];
    }
  }

  //xとyの集合の併合
  void unite(int x, int y){
    x = find(x);
    y = find(y);
    if(x == y) return;

    if(rank[x] < rank[y]){
      par[x] = y;
      sz[y] += sz[x];
    }else{
      par[y] = x;
      sz[x] += sz[y];
      if(rank[x] == rank[y]) rank[x]++;
    }
  }

  //x,yが同じ集合にあるか
  bool same(int x, int y){
      return find(x) == find(y);
  }

  //xの木のサイズ
  int size(int x){
      return sz[find(x)];
  }

  //ufの連結成分の数
  int cnt_connection(){
      int res = 0;
      bool ex[N];
      fill(ex, ex + N, false);
      for(int i = 0; i < N; i++){
          ex[find(i)] = true;
      }

      for(int i = 0; i < N; i++){
          if(ex[i]) res++;
      }

      return res;
  }


};

