    uf.init();

    sort(p, p + N, cmpx);
    for(int i = 0; i < N - 1; i++){
        if(p[i].x == p[i + 1].x){
            uf.unite(p[i].id, p[i + 1].id);
        }
    }

    sort(p, p + N, cmpy);
    for(int i = 0; i < N - 1; i++){
        if(p[i].y == p[i + 1].y){
