    UnionFind(int n = 1) {
        init(n);
    }

    void init(int n = 1) {
        par.resize(n + 1); rank.resize(n + 1); Size.resize(n + 1);
        for (int i = 0; i <= n; ++i) par[i] = i, rank[i] = 0, Size[i] = 1;
        for(int i = 0; i <= 1e5; i++) checker[i] = false;
    }

    int root(int x) {
        if (par[x] == x) {
            return x;
        }
        else {
            int r = root(par[x]);
            return par[x] = r;
        }
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x;
        Size[x] += Size[y];
        return true;
    }

    ll size(int x){
        return Size[root(x)];
    }
};

ll N;
ll x[100500], y[100050];
vector<ll> xs, ys;
map<ll, ll> mpx, mpy, invx, invy;
map<ll, ll> appearx, appeary;
int main() {
    //cout.precision(10);
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N;
    for(int i = 1; i <= N; i++) {
        cin >> x[i] >> y[i];
        xs.push_back(x[i]);
        ys.push_back(y[i]);
    }
    UnionFind X(100050), Y(100050);
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    for(auto itr = xs.begin(); itr != xs.end(); itr++) {
        ll val = distance(xs.begin(), itr) + 1;
        mpx[*itr] = val;
        invx[val] = *itr;
    }
    for(auto itr = ys.begin(); itr != ys.end(); itr++) {
        ll val = distance(ys.begin(), itr) + 1;
        mpy[*itr] = val;
