void dfs(int m, set<int> &sx, set<int> &sy) {
    sx.emplace(g[m].x);
    sy.emplace(g[m].y);
    g[m].judge = true;
    for (int e : g[m].to) {
        if (g[e].judge == false) dfs(e, sx, sy);
    }
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        g[i].x = o[i].x = x; g[i].y = o[i].y = y;
        o[i].ind = i; 
    }

    sort(o, o + n, [](const ord &o1, const ord &o2)->bool {
        if (o1.x < o2.x) return true;
        if (o1.x == o2.x && o1.y < o2.y) return true;
        return false;
    });    
    for (int i = 0; i < n - 1; i++) {
        if (o[i].x == o[i + 1].x) {
            g[o[i].ind].to.push_back(o[i + 1].ind);
            g[o[i + 1].ind].to.push_back(o[i].ind);
        }
    }

    sort(o, o + n, [](const ord &o1, const ord &o2)->bool {
        if (o1.y < o2.y) return true;
        if (o1.y == o2.y && o1.x < o2.x) return true;
        return false;
    });    
    for (int i = 0; i < n - 1; i++) {
        if (o[i].y == o[i + 1].y) {
            g[o[i].ind].to.push_back(o[i + 1].ind);
            g[o[i + 1].ind].to.push_back(o[i].ind);
        }
    }

    int sum = 0;
    for (int i = 0; i < n; i++) {
        set<int> s1, s2;
        if (g[i].judge == false) dfs(i, s1, s2);
        sum += s1.size() * s2.size();
    }

    printf("%d\n", sum - n);
    return 0;
}

