    vector<int> M_rank;
    vector<int> M_size;
    vector<int> M_size_x;
    vector<int> M_size_y;

private:
    void init(size_t n = 200010){

        M_par.resize(n);
        M_rank.resize(n);
        M_size.resize(n);
        M_size_x.resize(n);
        M_size_y.resize(n);
        for(int i = 0; i < n; i++){
            M_par[i] = i;
            M_rank[i] = 0;
            M_size[i] = 1;

            if(i <= 100000){
                M_size_x[i] = 1;
                M_size_y[i] = 0;
            }else{
                M_size_x[i] = 0;
                M_size_y[i] = 1;
            }
        }
    }

public:

    UnionFind(size_t n = 200010){
        init(n);
    }

    size_t find(size_t x){
        if(M_par[x] == x) return x;
        size_t r = find(M_par[x]);
        return M_par[x] = r;
    }

    bool same(size_t x, size_t y){
        return find(x) == find(y);
    }

    bool unite(size_t x, size_t y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(M_rank[x] < M_rank[y]) swap(x, y);
        if(M_rank[x] == M_rank[y]) M_rank[x]++;
        M_par[y] = x;
        M_size[x] = M_size[x] + M_size[y];
        M_size_x[x] = M_size_x[x] + M_size_x[y];
        M_size_y[x] = M_size_y[x] + M_size_y[y];
        return true;
    }

    size_t size(size_t x){
        return M_size[find(x)];
    }

    size_t size_x(size_t x){
        return M_size_x[find(x)];
    }

    size_t size_y(size_t x){
        return M_size_y[find(x)];
    }

};

int main(){

  UnionFind uf;
  lint n; cin >> n;
  vector<int> x(n);
  vector<int> y(n);
  rep(i, n){
    int xi, yi; cin >> xi >> yi;
    x[i] = xi;
    y[i] = yi + 100000;
    uf.unite(x[i], y[i]);
  }

  lint cnt = 0;
  set<int> st;
  rep(i, n){

    if(x[i] == uf.find(x[i])){
      if(st.find(x[i]) != st.end()) continue;
      st.insert(x[i]);
      cerr << x[i] << " " << uf.size_x(x[i]) << " " << uf.size_y(x[i]) << endl;
      cnt += max(1LL, (lint)(uf.size_x(x[i]) * uf.size_y(x[i])));
    }
    if(y[i] == uf.find(y[i])){
      if(st.find(y[i]) != st.end()) continue;
      st.insert(y[i]);
      cerr << y[i] << " " << uf.size_x(y[i]) << " " << uf.size_y(y[i]) << endl;
      cnt += max(1LL, (lint)(uf.size_x(y[i]) * uf.size_y(y[i])));
    }
  }
  cout << cnt - n << endl;

  return 0;
}

