class union_find {
	vector<int> data;
public:
	union_find(int n) : data(n, -1) {}
	int find(int x) {
		return data[x] < 0 ? x : data[x] = find(data[x]);
	}
	bool unite(int a, int b) {
		a = find(a);
		b = find(b);
		if (a == b) return false;
		if (data[a] < data[b]) {
			data[a] += data[b];
			data[b] = a;
		}
		else {
			data[b] += data[a];
			data[a] = b;
		}
		return true;
	}
};

