int max_n = 1e5;

void bfs(std::vector<std::vector<int>>& g, std::vector<bool>& v, int x, std::vector<int>& cnt, int dep) {
    if (v[x] == true) return;
    v[x] = true;
    if (x > max_n) ++cnt[1];
    else ++cnt[0];

    for (int i : g[x]) {
        //cout << i << endl;
        bfs(g, v, i, cnt, dep + 1);
    }
}

int main(int argc, char **argv) {
    int n;
    cin >> n;
    std::vector<std::vector<int>> g(max_n*2 + 10, std::vector<int>());
