    for (int i = 0; i < max_n*2+1; ++i) {
        std::vector<i64> cnt(2, 0);
        bfs(g, visit, i, cnt, 0);

        ans += (cnt[0] * cnt[1]);
    }

    cout << (ans - n) << endl;

    return 0;
}

