long xsum=0,ysum=0,K=0;
bool visit[100005];

struct point{
 long x;
 long y;
};

bool cmp(const point &a, const point &b){
 return b.x > a.x;
}

void cal(int i,point* poi,long N){
visit[i]=true;
for(j, N){
  if(visit[j] || i==j) continue;
  if( poi[i].x==poi[j].x ){
    ysum++;
    cal(j,poi,N);
  }
  if( poi[i].y==poi[j].y ){
    xsum++;
    cal(j,poi,N);
  }
}
}

