class UnionFind {
public:
    // 親の番号を格納する。親だった場合-size
    vector<int> parents;

    UnionFind(int n) {
        parents = vector<int>(n, -1);
    }

    // aがどのグループに属しているか
    int root(int a) {
        if (parents[a] < 0) {
            return a;
        }
        return parents[a] = root(parents[a]);
    }

    int size(int a) {
        return -parents[root(a)];
    }

    // aとbをくっつける
    bool connect(int a, int b) {
        int ra = root(a);
        int rb = root(b);
        if (ra == rb) {
            return false;
        }
        // 大きいほうにA
        if (size(ra) < size(rb)) {
            swap(ra, rb);
        }
        parents[ra] += parents[rb];
        parents[rb] = ra;
        return true;
    }

    bool is_union(int a, int b) {
        int ra = root(a);
        int rb = root(b);
        return ra == rb;
    }

    set<int> get_parents() {
        int n = parents.size();
        set<int> r;
        rep(i, n) r.insert(root(i));
        return r;
    }

};

int main() {

    int ma = 10e4 + 1;

    int n;
    cin >> n;
    UnionFind uf(2 * ma);

    vector<P> points(n);
    rep(i, n) cin >> points[i].first >> points[i].second;
    for (P p : points) uf.connect(p.first, p.second + ma);

    map<int, ll> x, y;
    rep(i, 2 * ma) if (i < ma) x[uf.root(i)]++; else y[uf.root(i)]++;

    auto s = uf.get_parents();
    ll res = 0;
    for (int i : s) res += x[i] * y[i];

    cout << res - n << endl;
}

