template<typename T>
struct UnionFind {
	vector<T> Parent;

	UnionFind(T N) {
		Parent = vector<T>(N, -1);
	}

	T root(T A) {
		if (Parent[A] < 0) return A;
		return Parent[A] = root(Parent[A]);
	}

	T size(T A) {
		return -Parent[root(A)];
	}

	bool connect(T A, T B) {
		A = root(A);
		B = root(B);
		if (A == B) return false;
		if (size(A) < size(B)) swap(A, B);
		Parent[A] += Parent[B];
		Parent[B] = A;

		return true;
	}

    bool same(T A,T B){
      return root(A)==root(B);
    }
};

