               const std::map<int, std::vector<int>> &ymap,
               const std::map<std::pair<int, int>, int> &xymap) {
  int count = 0;

  for (const auto &xp : xmap) {
    const auto &x = xp.first;
    const auto &yvec = xp.second;
    if (yvec.size() < 2) {
      continue;
