class UnionFind{
public:
    //親の番号を格納する。親だった場合はー（その集合のサイズ）
    vector<int> parents;
    int count;

    //作る時はparentsを-1で初期化する
    //こうすることで全部ばらばらになる
    UnionFind(int n){
        parents = vector<int>(n, -1);
        count = n;
    }

    //Aがどのグループにいるか調べる
    int root(int A){
        if(parents[A]<0) return A;
        return parents[A] = root(parents[A]);
    }

    //自分のいるグループの大きさを調べる
    int size(int A){
        return -parents[root(A)];
    }

    //AとBをくっつける
    bool connect(int A, int B){
        //AとBを直接ではなく親同士をくっつける
        A=root(A);
        B=root(B);
        if(A==B){
            return false;
        }

        //大きい方（A)に小さい方（B)をくっつけたい
        if(size(A)<size(B)) swap(A, B);

        parents[A] += parents[B];
        parents[B] = A;
        --count;

        return true;
    }
};

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int const base = 100005;
    int N; cin >> N;

    UnionFind uni(2*base);
    rep(i, N) {
        int x, y; cin >> x >> y;
        uni.connect(x, y+base);
    }

    map<int, ll> numOfXWhoseRootIs;
    map<int, ll> numOfYWhoseRootIs;
    rep(i, base) numOfXWhoseRootIs[uni.root(i)]++;
    repr(i, base, 2*base) numOfYWhoseRootIs[uni.root(i)]++;

    ll ans = 0;
    rep(i, 2*base) ans += numOfXWhoseRootIs[i]*numOfYWhoseRootIs[i];
    ans -= N;
    cout << ans << endl;

    return 0;
}

