// Orderd Set 順序付き集合
// Treapで実装
typedef struct OSnode
{
    int val; //値
    struct OSnode* ch[2]; //左右の子
    int pri; //優先度
}OSnode;

// rの子scを上に持ってくる
OSnode* OSrotate(OSnode*r, int sc)
{
    OSnode* nr = r->ch[sc];
    r->ch[sc] = nr->ch[1-sc];
    nr->ch[1-sc] = r;
    return nr;
}

OSnode* OSinsertSub(OSnode* r, OSnode* n)
{
    if(r==NULL) return n;
    int sc = r->val < n->val ? 1 : 0 ; //選択する子
    r->ch[sc] = OSinsertSub(r->ch[sc],n);

    if(r->pri < r->ch[sc]->pri) r = OSrotate(r,sc);
    return r;
}

OSnode* OSsearch(OSnode* r, int val)
{
    OSnode* i = r;
    while(i!=NULL)
    {
        if(i->val == val) return i;
        else if(i->val < val) i = i->ch[1];
        else i = i->ch[0];
    }
    return i;
}

void OSinsert(OSnode** r, int val)
{
#if 1 //uniq
    OSnode* s = OSsearch(*r,val);
    if(s!=NULL) return;
#endif
    OSnode* n = malloc(sizeof(OSnode));
    n->val = val;
    n->pri = rand();
    *r = OSinsertSub(*r, n);
}

// val 以上の最小の値のポインタを返す
OSnode* OSlower_bound(OSnode* r, int val)
{
    if(r==NULL) return NULL;
    else if(r->val >= val)
    {
        OSnode* res = OSlower_bound(r->ch[0], val);
        return res != NULL ? res : r;
    }else{
        return OSlower_bound(r->ch[1], val);
    }
}

// val 以下の最大の値のポインタを返す
OSnode* OSlower_boundRev(OSnode* r, int val)
{
    if(r==NULL) return NULL;
    else if(r->val <= val)
    {
        OSnode* res = OSlower_boundRev(r->ch[1], val);
        return res != NULL ? res : r;
    }else{
        return OSlower_boundRev(r->ch[0], val);
    }
}

void OSerase(OSnode** r, int val)
{
    OSnode** pre = r; // 削除ノードを指す親
    OSnode* i = *r;
    while(i!=NULL)
    {
        if(i->val == val) break;
        int sc = i->val < val ? 1: 0;
        pre = &(i->ch[sc]);
        i = i->ch[sc];
    }
    if(i==NULL) return;

    while(1)
    {
        int sc;
        if(i->ch[0]==NULL && i->ch[1]==NULL)
        {
            *pre = NULL;
            free(i);
            break;
        }
        else if(i->ch[0]==NULL) sc = 1;
        else if(i->ch[1]==NULL) sc = 0;
        else sc = i->ch[0]->pri > i->ch[1]->pri ? 0 : 1; //優先度が大きい方を親にする
        *pre = i->ch[sc];
        pre = &(i->ch[sc]->ch[1-sc]);
        OSrotate(i, sc);
    }
}

void OSmerge(OSnode** l, OSnode** r)
{
    while(*r!=NULL)
    {
        int v = (*r)->val;
        OSerase(r,v);
        OSinsert(l,v);
    }
}

int OSsize(OSnode* r)
{
    if(r==NULL) return 0;
    int size =1;
    if(r->ch[0]!=NULL) size+=OSsize(r->ch[0]);
    if(r->ch[1]!=NULL) size+=OSsize(r->ch[1]);
    return size;
}

