    {
        uf[i].root = i;
        uf[i].size = 1;
    }
}

int UFroot(UFnode* uf,int i)
{
    if(uf[i].root==i) return i;
    uf[i].root = UFroot(uf,uf[i].root);
    return uf[i].root;
}

// 元々根が同じならfalse 違うなら統合してtrue
bool UFunite(UFnode* uf,int i,int j)
{
    int ri = UFroot(uf,i);
