int main()
{
	int i, N, x[100001], y[100001];
	scanf("%d", &N);
	for (i = 1; i <= N; i++) scanf("%d %d", &(x[i]), &(y[i]));

	list *adj[200001] = {}, e[200003];
	for (i = 1; i <= N; i++) {
		e[i*2].v = y[i] + 100000;
		e[i*2+1].v = x[i];
		e[i*2].next = adj[x[i]];
		e[i*2+1].next = adj[y[i]+100000];
		adj[x[i]] = &(e[i*2]);
		adj[y[i]+100000] = &(e[i*2+1]);
	}

	int count, flag[200001] = {}, q[200001], head, tail;
	long long ans = 0;
	list *p;
	for (i = 1; i <= 200000; i++) {
		if (flag[i] != 0 || adj[i] == NULL) continue;
		q[0] = i;
		flag[i] = 1;
		count = 1;
		for (head = 0, tail = 1; head < tail; head++) {
			for (p = adj[q[head]]; p != NULL; p = p->next) {
				if (flag[p->v] == 0) {
					flag[p->v] = -flag[q[head]];
					if (flag[p->v] == 1) count++;
					q[tail++] = p->v;
				}
			}
		}
		ans += (long long)count * (tail - count);
	}

	printf("%lld\n", ans - N);
	fflush(stdout);
	return 0;
}

