typedef struct union_find {
  int32_t *parent;
  int32_t size;
} union_find;

void init_union_find (union_find * const u) {
  for (int32_t i = 0; i < u->size; ++i){
    u->parent[i] = -1;
  }
}

union_find* new_union_find (const int32_t size) {
  union_find * const u = (union_find *) calloc (1, sizeof (union_find));
  u->parent = (int32_t *) calloc (size, sizeof (int32_t));
  u->size = size;
  init_union_find (u);
  return u;
}

void free_union_find (union_find * const u) {
  free (u->parent);
  free (u);
}

int32_t root (union_find * const u, int32_t x) {
  int32_t index[32];
  int32_t top = 0;
  while (u->parent[x] >= 0) {
    index[top++] = x;
    x = u->parent[x];
  }
  while (top > 0) {
    u->parent[index[--top]] = x;
  }
  return x;
}

void unite (union_find * const u, int32_t x, int32_t y) {
  x = root (u, x);
  y = root (u, y);
  if (x == y) return;
  if (u->parent[x] > u->parent[y]) {
    const int32_t swap = x;
    x = y;
    y = swap;
  }
  u->parent[x] += u->parent[y];
  u->parent[y] = x;
}

typedef int32_t i32;
typedef int64_t i64;

#define ALLOC(size,type) ((type*)calloc((size),sizeof(type)))

void run (void) {
  i32 n;
  scanf ("%" SCNi32, &n);
  const i32 m = 100001;
  union_find *u = new_union_find (2 * m);
  i32 *cntX = ALLOC (2 * m, i32);
  i32 *cntY = ALLOC (2 * m, i32);
  for (i32 i = 1; i < m; ++i) {
    cntX[i] = cntY[i + m] = 1;
  }
  for (i32 i = 0; i < n; ++i) {
    i32 x, y;
    scanf ("%" SCNi32 "%" SCNi32, &x, &y);
    y += m;
    i32 a = root (u, x);
    i32 b = root (u, y);
    if (a == b) continue;
    unite (u, x, y);
    i32 c = root (u, x);
    cntX[c] += cntX[a ^ b ^ c];
    cntY[c] += cntY[a ^ b ^ c];
  }
  uint8_t *used = ALLOC (2 * m, uint8_t);
  i64 ans = -n;
  for (i32 i = 1; i < m; ++i) {
    i32 r = root (u, i);
    if (used[r]) continue;
    used[r] = 1;
    ans += (i64) cntX[r] * cntY[r];
  }
  printf ("%" PRIi64 "\n", ans);
}

int main (void) {
  run();
  return 0;
}

