int main(void)
{
    ll n;
    scanf("%ld",&n);

    for(int i=0;i<n;i++)
    {
        int x,y;
        scanf("%d %d",&x,&y);
        ps[i].x=x;
        ps[i].y=y;
        ps[i].id=i;
        pss[i] = ps[i];
    }
    UFinit(ufp,n);
    UFinit(ufx,MAXN);
    UFinit(ufy,MAXN);

    qsort(pss,n,sizeof(point),acs_x);
    for(int i=1;i<n;i++)
    {
        if(pss[i].x == pss[i-1].x)
        {
            UFunite(ufp, pss[i-1].id,pss[i].id);
            UFunite(ufx, ps[pss[i-1].id].x, ps[pss[i].id].x);
            UFunite(ufy, ps[pss[i-1].id].y, ps[pss[i].id].y);
        }
    }
    qsort(pss,n,sizeof(point),acs_y);
    for(int i=1;i<n;i++)
    {
        if(pss[i].y == pss[i-1].y)
        {
            UFunite(ufp, pss[i-1].id,pss[i].id);
            UFunite(ufx, ps[pss[i-1].id].x, ps[pss[i].id].x);
            UFunite(ufy, ps[pss[i-1].id].y, ps[pss[i].id].y);
        }
    }

    int ans=0;
    for(int i=0;i<n;i++)
    {
        if(i==UFroot(ufp,i))
        {
            int rx = UFroot(ufx,ps[i].x);
            int ry = UFroot(ufy,ps[i].y);
            ans += ufx[rx].size * ufy[ry].size - ufp[i].size;
        }
    }


    printf("%d\n",ans);
    return 0;
}

