int queue[100000][2], num=0;
int head=-1;
int tail=-1;

void enqueue(int x, int y){
    tail++;
    queue[tail][0]=x;
    queue[tail][1]=y;
}

void dequeue(){
    head++;
}

int main(){
    int N;
    struct dot dots[100000];
    scanf("%d", &N);
    for(int i=0;i<N;i++){
        scanf("%d %d", &dots[i].x, &dots[i].y);
        dots[i].root=i;
    }

    int h=0, cnt=1, x_cnt=1, y_cnt=1, ans=0;
    dots[0].check=true;
    enqueue(dots[0].x, dots[0].y);
    //printf("%d %d\n", dots[0].x, dots[0].y);
    while(num<N){
        if(head == tail){
            for(;h<N;h++){
                if(dots[h].check==false){
                    dots[h].check=true;
                    enqueue(dots[h].x, dots[h].y);
                    break;
                }
            }
            //printf("%d %d %d %d\n", x_cnt, y_cnt, cnt, x_cnt*y_cnt-cnt);
            ans += x_cnt*y_cnt-cnt;
            cnt=1;
            x_cnt=1;
            y_cnt=1;
        }
        dequeue();
        //printf("%d %d\n", queue[head][0], queue[head][1]);
        num++;
        for(int i=0;i<N;i++){
            if(dots[i].check==false){
                if(dots[i].x == queue[head][0]){
                    dots[i].check=true;
                    enqueue(dots[i].x, dots[i].y);
                    y_cnt++;
                    cnt++;
                    //printf("Y++\n");
                }
                if(dots[i].y == queue[head][1]){
                    dots[i].check=true;
                    enqueue(dots[i].x, dots[i].y);
                    x_cnt++;
                    cnt++;
                    //printf("X++\n");
                }
            }
        }
    }
    ans += x_cnt*y_cnt-cnt;
    printf("%d\n", ans);
    // for(int i=0;i<N;i++){
    //     printf("%d %d %d\n", dots[i].x, dots[i].y, dots[i].root);
    // }
}

