class UnionFind(private val N: Int) {
    private val nodes = (0 until N).toList()
    private val parent = IntArray(N) { it }
    private val roots = parent.toMutableSet()
    private val rank = IntArray(N) { 0 }
    private val size = IntArray(N) { 1 }

    fun group() = nodes.groupBy { find(it) }
    fun groupCount() = roots.size
    fun sameGroupSize(x: Int) = size[find(x)]

    fun find(x: Int): Int = if (parent[x] == x) x else { parent[x] = find(parent[x]); parent[x] }
    fun unite(x: Int, y: Int) {
        val a = find(x)
        val b = find(y)
        if (a == b) return

        if (rank[a] < rank[b]) {
            roots.remove(a)
            parent[a] = b
            size[b] += size[a]
        } else {
            roots.remove(b)
            parent[b] = a
            size[a] += size[b]
            if (rank[a] == rank[b]) rank[a]++
        }
    }
}

