    val n = readLine()!!.toInt()
    val p = (1..n).map { val a = (readLine()!!.split(" ").map { it.toInt() }); Point(it-1, a[0], a[1]) }.sorted()

    val xy = Array(100001) { mutableListOf<Int>() }
    val yx = Array(100001) { mutableListOf<Int>() }
    val uf = UnionFind(n)
    p.forEach {
        xy[it.x].add(it.y)
        yx[it.y].add(it.x)
        uf.xs[it.id].add(it.x)
        uf.ys[it.id].add(it.y)
    }

    (1..100000).forEach { pos ->
        if(xy[pos].size>=2) xy[pos].drop(1).forEach {
            val x = pos
            val y = it
            val i = p.binarySearch(Point(-1,x,xy[x][0]))
            val j = p.binarySearch(Point(-1,x,y))
            uf.unite(p[i].id, p[j].id)
        }
        if(yx[pos].size>=2) yx[pos].drop(1).forEach {
            val y = pos
            val x = it
            val i = p.binarySearch(Point(-1,yx[y][0],y))
            val j = p.binarySearch(Point(-1,x,y))
            uf.unite(p[i].id, p[j].id)
        }

    }

    val sum = uf.roots.map { 1L * uf.xs[it].size * uf.ys[it].size }.sum()
    println(sum-n)
}

data class Point(val id: Int, val x: Int, val y: Int) : Comparable<Point>{
    override fun compareTo(other: Point): Int =
        if (this.x != other.x) this.x.compareTo(other.x)
        else this.y.compareTo(other.y)
}

class UnionFind(N: Int) {
    private val parent = IntArray(N) { it }
    val roots = (0..N-1).toList().toMutableSet()
    private val rank = IntArray(N) { 0 }
    private val size = IntArray(N) { 1 }
    private var numTree = N

    val xs = Array(N){ mutableSetOf<Int>() }
    val ys = Array(N){ mutableSetOf<Int>() }

    fun size() = numTree
    fun find(x: Int): Int = if (parent[x] == x) x else { parent[x] = find(parent[x]); parent[x] }

    fun same(x: Int, y: Int) = find(x) == find(y)
    fun sizeOf(x: Int) = size[find(x)]
    fun unite(x: Int, y: Int) {
        val rx = find(x)
        val ry = find(y)
        if (rx == ry) return else numTree--

        if (rank[rx] < rank[ry]) {
            parent[rx] = ry
            roots.remove(rx)
            size[ry] += size[rx]
            xs[ry].addAll(xs[rx])
            ys[ry].addAll(ys[rx])
        } else {
            parent[ry] = rx
            roots.remove(ry)
            size[rx] += size[ry]
            xs[rx].addAll(xs[ry])
            ys[rx].addAll(ys[ry])
            if (rank[rx] == rank[ry]) rank[rx]++
        }
    }
}

fun main(args:Array<String>){
    val n = readLine()!!.toInt()
    val list = mutableListOf<Pair<Int,Int>>()
    for(i in 1..n){
        val line = readLine()!!.split(" ").map{it.toInt()}
        list.add(Pair(line[0],line[1]))
    }
    list.sortBy { (x,y)->x }
    var i = 0
    var result = 0
    while(true){
        if(i+3>n)break
        if(list[i].first == list[i+1].first && list[i].first != list[i+2].first){
            var count = 0
            for(ii in 0 .. list.size-1){
                if(list[ii].second == list[i].second || list[ii].second == list[i+1].second){
                    count++
                    if(count>=4)break
                }
            }
            if(count==3)result++
            i +=2
        }else{
            i++
        }
    }
    println(result)
}

