import java.io.*;
import java.util.*;


public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		int[][] xy = sc.nextIntArrays(n, 2);

		Map<Integer, List<Integer>> tmx = new TreeMap<>();
		Map<Integer, List<Integer>> tmy = new TreeMap<>();

		for (int i = 0; i < n; i++) {
			List<Integer> list = tmx.get(xy[0][i]);
			if (list == null) {
				list = new ArrayList<>();
				tmx.put(xy[0][i], list);
			}
			list.add(i);
			list = tmy.get(xy[1][i]);
			if (list == null) {
				list = new ArrayList<>();
				tmy.put(xy[1][i], list);
			}
			list.add(i);
		}

		long ans = 0;
		boolean[] used = new boolean[n];
		for (int i = 0; i < n; i++) {
			if (used[i]) {
				continue;
			}

			Deque<Integer> st = new ArrayDeque<>();
			st.push(i);
			used[i] = true;
			int cnt = 1;
			Set<Integer> hsx = new HashSet<>();
			Set<Integer> hsy = new HashSet<>();
			while (!st.isEmpty()) {
				int e = st.pop();
				hsx.add(xy[0][e]);
				hsy.add(xy[1][e]);

				for (int ee : tmx.get(xy[0][e])) {
					if (used[ee]) {
						continue;
					}
					st.push(ee);
					used[ee] = true;
					cnt++;
				}
				for (int ee : tmy.get(xy[1][e])) {
					if (used[ee]) {
						continue;
					}
					st.push(ee);
					used[ee] = true;
					cnt++;
				}
			}

			ans += (long)hsx.size() * hsy.size() - cnt;
		}

		pr.println(ans);
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(System.in);
		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int[] nextIntArray(int n) {
			int[] ret = new int[n];
			for (int i = 0; i < n; i++) {
				ret[i] = sc.nextInt();
			}

			return ret;
		}

		int[][] nextIntArrays(int n, int m) {
			int[][] ret = new int[m][n];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					ret[j][i] = sc.nextInt();
				}
			}

			return ret;
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	static class Printer extends PrintWriter {
		Printer(OutputStream out) {
			super(out);
		}

		void printInts(int... a) {
			StringBuilder sb = new StringBuilder(32);
			for (int i = 0, size = a.length; i < size; i++) {
				if (i > 0) {
					sb.append(' ');
				}
				sb.append(a[i]);
			}

			println(sb);
		}

		void printLongs(long... a) {
			StringBuilder sb = new StringBuilder(64);
			for (int i = 0, size = a.length; i < size; i++) {
				if (i > 0) {
					sb.append(' ');
				}
				sb.append(a[i]);
			}

			println(sb);
		}

		void printStrings(String... a) {
			StringBuilder sb = new StringBuilder(32);
			for (int i = 0, size = a.length; i < size; i++) {
				if (i > 0) {
					sb.append(' ');
				}
				sb.append(a[i]);
			}

			println(sb);
		}
	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		List<List<Integer>> xyList = new ArrayList<>();
		for (int i = 0; i < n; i++) {
			List<Integer> xy = new ArrayList<>();
			xy.add(sc.nextInt());
			xy.add(sc.nextInt());
			xyList.add(xy);
		}

		int count = 0;
		boolean addFlag = true;
		while (addFlag) {
			addFlag = false;
			List<Integer> addPoint = addPoint(xyList);
			if (null != addPoint) {
				addFlag = true;
				count++;
				xyList.add(addPoint);
			}

		}
		System.out.println(count);
	}

	private static List<Integer> addPoint(List<List<Integer>> points) {
		for (List<Integer> point : points) {
			for (List<Integer> sameX : points) {
				if (point == sameX) {
					continue;
				}
				if (point.get(0) != sameX.get(0)) {
					continue;
				}
				for (List<Integer> sameY : points) {
					if (point == sameY) {
						continue;
					}
					if (point.get(1) != sameY.get(1)) {
						continue;
					}
					boolean exist = false;
					for (List<Integer> dPoint : points) {
						if (point == dPoint) {
							continue;
						}
						if (dPoint.get(0) == sameY.get(0) && dPoint.get(1) == sameX.get(1)) {
							exist = true;
							break;
						}
					}
					if (exist) {
						continue;
					}
					List<Integer> ret = new ArrayList<>();
					ret.add(sameY.get(0));
					ret.add(sameX.get(1));
					return ret;
				}
			}
		}
		return null;
	}
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Scanner;
import java.util.Set;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		Map<Integer,Set<Integer>> points = new HashMap<>();
		for (int i = 0; i < n; i++) {
			Integer x = sc.nextInt();
			Set<Integer> ySet = points.get(x);
			if (Objects.isNull(ySet)) {
				ySet = new HashSet<>();
				points.put(x, ySet);
			}
			ySet.add(sc.nextInt());
		}

		addPoint(points);

		int count = 0;
		for (Integer x : points.keySet()) {
			count += points.get(x).size();
		}
		System.out.println(count - n);
	}

	private static void addPoint(Map<Integer,Set<Integer>> points) {
		for (Integer x : points.keySet()) {
			Set<Integer> ySet = points.get(x);
			for (Integer compX : points.keySet()) {
				if (x == compX) continue;
				Set<Integer> compYSet = points.get(compX);
				boolean dupF = false;
				for (Integer compY : compYSet) {
					if (ySet.contains(compY)) {
						dupF = true;
						break;
					}
				}
				if (dupF) {
					ySet.addAll(compYSet);
					compYSet.addAll(ySet);
				}
			}
		}
	}
}

import java.util.*;
class Main {
    static int cntX;
    static int cntY;
    static HashMap<Integer, List<Integer>> map;
    static boolean[] visited;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        map = new HashMap<>();

        for(int i = 0; i<N; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt()+100001;
            if(!map.containsKey(x)) {
                map.put(x, new ArrayList<>());
            }
            if(!map.containsKey(y)) {
                map.put(y, new ArrayList<>());
            }
            map.get(x).add(y);
            map.get(y).add(x);
        }

        visited = new boolean[100001*2];
        long ans = 0;
        for(int i = 0; i<100001; i++) {
            cntX = 0;
            cntY = 0;
            dfs(i);
            ans += cntX*cntY;
        }

        System.out.println(ans-N);

    }
    public static void dfs(int x) {
        if(visited[x]) return;
        visited[x] = true;
        if(x<100001) cntX++;
        else cntY++;
        if(map.containsKey(x)) {
            for(int i: map.get(x)) {
                dfs(i);
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Scanner;
import java.util.Set;

public class Main {
	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		Obj[] arr = new Obj[n];
		Map<Integer, List<Obj>> mapx = new HashMap<>();
		Map<Integer, List<Obj>> mapy = new HashMap<>();
		for (int i = 0; i < n; i++) {
			Obj o = new Obj();
			o.x = sc.nextInt();
			o.y = sc.nextInt();
			arr[i] = o;

			List<Obj> listx = mapx.get(o.x);
			if (listx == null) {
				listx = new ArrayList<>();
				mapx.put(o.x, listx);
			}
			listx.add(o);

			List<Obj> listy = mapy.get(o.y);
			if (listy == null) {
				listy = new ArrayList<>();
				mapy.put(o.y, listy);
			}
			listy.add(o);
		}
		sc.close();

		long ans = 0;
		for (int i = 0; i < n; i++) {
			if (!arr[i].used) {
				Queue<Obj> que = new ArrayDeque<>();
				que.add(arr[i]);
				arr[i].used = true;
				Set<Integer> setx = new HashSet<>();
				Set<Integer> sety = new HashSet<>();
				setx.add(arr[i].x);
				sety.add(arr[i].y);
				while (!que.isEmpty()) {
					Obj cur = que.poll();
					for (Obj next : mapx.get(cur.x)) {
						if (!next.used) {
							que.add(next);
							next.used = true;
							sety.add(next.y);
						}
					}
					for (Obj next : mapy.get(cur.y)) {
						if (!next.used) {
							que.add(next);
							next.used = true;
							setx.add(next.x);
						}
					}
				}
				ans += (long) setx.size() * sety.size();
			}
		}
		System.out.println(ans - n);
	}

	static class Obj {
		int x, y;
		boolean used;
	}
}

