    final int MOD = (int)1e9+7;
    long ceil(long a, long b){return (a + b - 1) / b;}
    long gcd(long a, long b){
        return b == 0 ? a : gcd(b, a % b);
    }
    long lcm(long a, long b){
        return a / gcd(a, b) * b; //オーバーフローに注意
    }

    void solve() throws Exception{
        int N = in.nextInt(), MAX = (int)1e5;
        UnionFind uf = new UnionFind((MAX+1)*2);
        for(int i = 0; i < N; i++){
            int x = in.nextInt(), y = in.nextInt();
            uf.union(x, y + MAX);
        }

        int[] numX = new int[(MAX+1)*2], numY = new int[(MAX+1)*2];
        for(int x = 1; x <= MAX; x++) numX[uf.find(x)]++;
        for(int y = 1; y <= MAX; y++) numY[uf.find(y + MAX)]++;
        long ans = 0;
        for(int i = 0; i < (MAX+1)*2; i++){
            //out.println(numX[i] + " " + numY[i]);
            ans += (long)numX[i] * numY[i];
        }
        ans -= N;
        out.println(ans);
    }
    //end solve

    class UnionFind{
        int[] par;
        int[] rank;
        int[] size;
        int group;

        UnionFind(int n){
            par = new int[n];
            rank = new int[n];
            size = new int[n];
            group = n;
            for(int i = 0; i < n; i++){
                par[i] = i;
                rank[i] = 0;
                size[i] = 1;
            }
        }

        //経路圧縮しながらrootを求める
        int find(int x){
            if(par[x] == x){
                return x;
            }else{
                int f = find(par[x]);
                return par[x] = f;
            }
        }

        //ランクの小さいほうにつなげる
        boolean union(int x, int y){
            x = find(x);
            y = find(y);
            if(x == y) return false;

            if(rank[x] < rank[y]){
                int tmp = x; x = y; y = tmp;
            }

            //y(のroot)をx(のroot)の下にくっつける
            //yのほうが重くなる(ポテンシャルが高くなる)
            if(rank[x] == rank[y]) rank[x]++;
            group--;
            par[y] = x;
            size[x] += size[y];

            return true;
        }

        boolean isSame(int x, int y){
            return find(x) == find(y);
        }
    }

    public static void main(String[] args) throws Exception {
        new Main().m();
    }

    private void m() throws Exception {
        solve();
        out.flush();
    }

