import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        List<Zahyo> zahyoList = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            zahyoList.add(new Zahyo(x, y));
        }
        sc.close();

        for (int i = 0; i < zahyoList.size(); i++) {
            Zahyo zahyoI = zahyoList.get(i);

            for (int j = i + 1; j < zahyoList.size(); j++) {
                Zahyo zahyoJ = zahyoList.get(j);

                for (int k = j + 1; k < zahyoList.size(); k++) {
                    Zahyo zahyoK = zahyoList.get(k);

                    if(!isIikanzi(zahyoI, zahyoJ, zahyoK)) continue;

                    Zahyo kouho = getIikanziNoZahyo(zahyoI, zahyoJ, zahyoK);

                    if(zahyoList.contains(kouho)) {
                        continue;
                    }else {
                        zahyoList.add(kouho);
                    }
                }
            }
        }

        System.out.println(zahyoList.size()-N);
    }

    private static boolean isIikanzi(Zahyo a, Zahyo b, Zahyo c) {
        //3点が一直線上にある場合
        if (a.x == b.x && b.x == c.x)
            return false;
        if (a.y == b.y && b.y == c.y)
            return false;

        //x座標とy座標が全部違う場合
        if (a.x != b.x && b.x != c.x && c.x != a.x)
            return false;
        if (a.y != b.y && b.y != c.y && c.y != a.y)
            return false;

        return true;
    }

    private static Zahyo getIikanziNoZahyo(Zahyo a, Zahyo b, Zahyo c) {
        int xNew = a.x != b.x&& a.x != c.x ? a.x : b.x != a.x && b.x != c.x ? b.x : c.x;
        int yNew = a.y != b.y&& a.y != c.y ? a.y : b.y != a.y && b.y != c.y ? b.y : c.y;
        return new Zahyo(xNew, yNew);
    }

}

class Zahyo {
    int x;
    int y;

    public Zahyo(int x, int y) {
        super();
        this.x = x;
        this.y = y;
    }

    @Override
    public int hashCode() {
        final int prime = 31;
        int result = 1;
        result = prime * result + x;
        result = prime * result + y;
        return result;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj)
            return true;
        if (obj == null)
            return false;
        if (getClass() != obj.getClass())
            return false;
        Zahyo other = (Zahyo) obj;
        if (x != other.x)
            return false;
        if (y != other.y)
            return false;
        return true;
    }

}

import java.io.*;
import java.util.*;

class UnionFind{
	int parent[];
	UnionFind(int N){
		parent = new int[N];
		Arrays.fill(parent, -1);
	}

	boolean same(int x, int y){
		return root(x)==root(y);
	}
	int root(int x) {
		if(parent[x]<0)return x;
		return parent[x] = root(parent[x]);
	}
	int size(int x) {
		return -parent[root(x)];
	}
	void unite(int x, int y) {
		if(size(x)<size(y)) {
			int tmp = x;
			x = y;
			y = tmp;
		}
		int rx = root(x);
		int ry = root(y);
		if(rx==ry)return;
		parent[rx] += parent[ry];
		parent[ry] = rx;
	}
}

public class Main {
	static void solve() {
		int n = ni();
		UnionFind uf = new UnionFind(200200);
		int MAX_XY = 200200;
		boolean xs[] = new boolean[MAX_XY], ys[] = new boolean[MAX_XY];
		for(int i=0;i<n;i++) {
			int x = ni(), y = ni() + 100000;
			xs[x] = true; ys[y] = true;
			uf.unite(x, y);
		}
		Map<Integer, Integer> mapX = new HashMap<>(), mapY = new HashMap<>();
		for(int i=0;i<MAX_XY;i++) {
			if(!xs[i])continue;
			int rt = uf.root(i);
			mapX.putIfAbsent(rt, 0);
			mapX.put(rt, mapX.get(rt) + 1);
		}
		for(int i=0;i<MAX_XY;i++) {
			if(!ys[i])continue;
			int rt = uf.root(i);
			mapY.putIfAbsent(rt, 0);
			mapY.put(rt, mapY.get(rt) + 1);
		}
		long ans = -n;
		for(int key : mapX.keySet()) {
			int vx = mapX.get(key);
			int vy = mapY.getOrDefault(key, 0);
			ans += (long)vx * vy;
		}
		out.println(ans);
	}

	//constant
	static final int inf = Integer.MAX_VALUE / 2;
	static final long linf = Long.MAX_VALUE / 3;
