public class Main {
    private static FastScanner sc = new FastScanner();
    static Node[] V;
    static long size = 0;

    public static void main(String[] args) {
    	int n = sc.nextInt();
    	Point[] p = new Point[n];
    	for(int i=0; i<n; i++) {
    		p[i] = new Point(sc.nextInt(), sc.nextInt());
    	}
    	Arrays.sort(p, (a, b) -> a.x == b.x ? a.y - b.y :a.x - b.x);

    	V = new Node[100001];
    	int lastx = -1;
    	int lasty = -1;
    	for(int i=0; i<n; i++) {
    		if(V[p[i].y] == null) {
    			Node no = new Node();
    			no.y = p[i].y;
    			no.x.add(p[i].x);
    			V[p[i].y] = no;
    		} else {
    			V[p[i].y].x.add(p[i].x);
    		}
    		if(p[i].x == lastx) {
    			V[p[i].y].nbr.add(lasty);
    			V[lasty].nbr.add(p[i].y);
    		}
    		lastx = p[i].x;
    		lasty = p[i].y;
    	}
    	long ans = 0;
    	for(int i=0; i<100001; i++) {
    		if(V[i] == null) continue;
    		HashSet<Integer> xa = new HashSet<>();
    		size = 0;
    		if(!V[i].vst) V[i].dfs(xa);
    		ans += (long)size * xa.size();
    	}
    	System.out.println(ans - n);
    }

    static class Point{
    	int x;
    	int y;
		public Point(int x, int y) {
			this.x = x;
			this.y = y;
		}
    }

    static class Node {
        HashSet<Integer> nbr = new HashSet<>();
        int y;
        HashSet<Integer> x = new HashSet<>();
        boolean vst = false;
        void dfs(HashSet<Integer> xa) {
        	vst = true;
        	size++;
        	for(int xx : x) {
        		xa.add(xx);
        	}
        	for(int i : nbr) {
        		if(!V[i].vst) {
        			V[i].dfs(xa);
        		}
        	}
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte() {
            if(ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch(IOException e) {
                    e.printStackTrace();
                }
                if(buflen <= 0) {
                    return false;
                }
            }
            return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
        public boolean hasNext() { skipUnprintable(); return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            return Long.parseLong(next());
        }
        public int nextInt(){
            return Integer.parseInt(next());
        }
        public double nextDouble(){
            return Double.parseDouble(next());
        }
    }
}

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

class DisjointSet {
  public int[] upper; // minus:num_element(root) plus:root(normal)
//public int[] w;

  public DisjointSet(int n)
  {
      upper = new int[n];
      Arrays.fill(upper, -1);
//    w = new int[n];
  }

  public DisjointSet(DisjointSet ds)
  {
      this.upper = Arrays.copyOf(ds.upper, ds.upper.length);
  }       

  public int root(int x)
  {
      return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
  }

  public boolean equiv(int x, int y)
  {
      return root(x) == root(y);
  }

  public boolean union(int x, int y)
  {
      x = root(x);
      y = root(y);
      if(x != y) {
          if(upper[y] < upper[x]) {
              int d = x; x = y; y = d;
          }
//        w[x] += w[y];
          upper[x] += upper[y];
          upper[y] = x;
      }
      return x == y;
  }

  public int count()
  {
      int ct = 0;
      for(int u : upper){
          if(u < 0)ct++;
      }
      return ct;
  }

  public int[][] toBucket()
  {
      int n = upper.length;
      int[][] ret = new int[n][];
      int[] rp = new int[n];
      for(int i = 0;i < n;i++){
          if(upper[i] < 0)ret[i] = new int[-upper[i]];
      }
      for(int i = 0;i < n;i++){
          int r = root(i);
          ret[r][rp[r]++] = i;
      }
      return ret;
  }
}



public class Main {


  private static void solve() {
    int n = ni();
    int[][] p = new int[n][3];


    for (int i = 0; i < n; i ++) {
      p[i] = new int[] {i, ni(), ni()};
    }

    DisjointSet ds = new DisjointSet(n);

    Arrays.sort(p, (o1, o2) -> o1[1] - o2[1]);
    for (int i = 0; i < n - 1; i ++) {
      if (p[i][1] == p[i + 1][1]) {
        ds.union(p[i][0],  p[i + 1][0]);
      }
    }
    Arrays.sort(p, (o1, o2) -> o1[2] - o2[2]);
    for (int i = 0; i < n - 1; i ++) {
      if (p[i][2] == p[i + 1][2]) {
        ds.union(p[i][0],  p[i + 1][0]);
      }
    }

    int[][] buc = ds.toBucket();

    long ret = 0;
    for (int[] a : buc) {
      if (a != null) {
        ret += f(a, p);
      }

    }
    System.out.println(ret);
  }

  static long f(int[] a, int[][] p) {
    Set<Integer> x = new HashSet<>();
    Set<Integer> y = new HashSet<>();
    for (int i : a) {
      x.add(p[i][1]);
      y.add(p[i][2]);
    }

    if (x.size() <= 1 || y.size() <= 1) {
      return 0;
    }

    return (long)x.size() * y.size() - a.length;

  }

