public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long mod = 1000000007;
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final int[] da = {-1, 0, 1, 0, -1, 1, 1, -1, -1};

    int n;
    Set<Point> visited = new HashSet<>();
    Map<Integer, TreeSet<Integer>> mapX, mapY;
    void solve() {
        int n = in.nextInt();
        Map<Integer, Integer> idMap = new HashMap<>();
        mapX = new HashMap<>();
        mapY = new HashMap<>();
        int[] x = new int[n];
        int[] y = new int[n];
        for (int i = 0; i < n; i++) {
            x[i] = in.nextInt();
            y[i] = in.nextInt();
            mapX.computeIfAbsent(x[i], key -> new TreeSet<>()).add(y[i]);
            mapY.computeIfAbsent(y[i], key -> new TreeSet<>()).add(x[i]);
        }
        int index = 0;
        for (Integer v : mapX.keySet()) {
            idMap.put(v, index);
            index++;
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            Point p = new Point(x[i], y[i]);
            if (!visited.contains(p)) {
                ans += dfs(p);
            }
        }
        out.println(ans);
    }

    long dfs(Point s) {
        Deque<Point> deque = new ArrayDeque<>();
        deque.addFirst(s);
        Set<Integer> setX = new HashSet<>();
        Set<Integer> setY = new HashSet<>();
        int count = 0;
        while (!deque.isEmpty()) {
            Point p = deque.poll();
            if (visited.contains(p)) {
                continue;
            }
            visited.add(p);
            count++;
            setX.add(p.x);
            setY.add(p.y);
            Integer next = mapX.get(p.x).higher(p.y);
            if (next != null) {
                deque.add(new Point(p.x, next));
            }
            next = mapX.get(p.x).lower(p.y);
            if (next != null) {
                deque.add(new Point(p.x, next));
            }
            next = mapY.get(p.y).higher(p.x);
            if (next != null) {
                deque.add(new Point(next, p.y));
            }
            next = mapY.get(p.y).lower(p.x);
            if (next != null) {
                deque.add(new Point(next, p.y));
            }
        }
        return (long)setX.size() * setY.size() - count;
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

class Point implements Comparable<Point> {
    static int h = -1, w = -1;
    final int x, y, z;

    Point(int z) {
        this.x = z % w;
        this.y = z / w;
        this.z = z;
    }

    Point(int x, int y) {
        this.x = x;
        this.y = y;
        this.z = y * w + x;
    }

    Point move(int d) {
        return new Point(x + Main.da[d], y + Main.da[d + 1]);
    }

    boolean isInner() {
        if (h == -1 || w == -1) {
            throw new IllegalStateException("h/w is not initialized!");
        }
        return 0 <= x && x < w && 0 <= y && y < h;
    }

    List<Point> aroundPoints(int type) {
        List<Point> list = new ArrayList<>();
        for (int i = 0; i < type; i++) {
            int nx = x + Main.da[i];
            int ny = y + Main.da[i + 1];
            Point point = new Point(nx, ny);
            if (point.isInner()) {
                list.add(point);
            }
        }
        return list;
    }

    int direction(Point o) {
        for (int i = 0; i < 8; i++) {
            if (move(i).equals(o)) {
                return i;
            }
        }
        return -1;
    }

    @Override
    public int compareTo(Point o) {
        return x == o.x ? Integer.compare(y, o.y) : Integer.compare(x, o.x);
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Point)) {
            return false;
        }
        Point point = (Point)o;
        return x == point.x && y == point.y;
    }

    @Override
    public int hashCode() {
        return z;
    }

    @Override
    public String toString() {
        return String.format("(%d, %d)", x, y);
    }
}

