    private void solveC() {
        int n = nextInt();
        int[] a = IntStream.range(0, n).map(i -> nextInt()).toArray();
        long res = 0;
        //増加傾向と減少傾向を表すためにtru/false
        //切れ目を表現するのに二つ使う
        boolean inc = false;
        boolean dec = false;
        for (int i = 0; i < n - 1; i++) {
            if (inc) {
                if (a[i] > a[i + 1]) {
                    //増加傾向終了
                    inc = false;
                }
            } else if (dec) {
                if (a[i] < a[i + 1]) {
                    //減少傾向終了
                    dec = false;
                }
            } else {
                //増加or減少の傾向把握
                if (a[i] < a[i + 1]) {
                    inc = true;
                    res++;
                } else if (a[i] > a[i + 1]) {
                    dec = true;
                    res++;
                }
                //増加も減少もしない場合はstay
            }
        }
        if (!inc && !dec) {
            //stay状態ではない。まだ残っている。
            res++;
        }
        out.println(res);
    }

