            xs.computeIfAbsent(r, k -> new HashSet<>()).add(ps[i].x);
            ys.computeIfAbsent(r, k -> new HashSet<>()).add(ps[i].y);
        }
        long res = 0;
        for (int k : xs.keySet()) {
            if (!ys.containsKey(k)) {
                throw new RuntimeException();
            }
            res += (long) xs.get(k).size() * ys.get(k).size();
        }
        System.out.println(res - n);
    }

