        for (int i = 0; i < n; i++) {
            int a = nextInt();
            int[][] val = IntStream.range(0, a).mapToObj(x -> new int[]{nextInt() - 1, nextInt()}).toArray(int[][]::new);
            pMap.put(i, val);
