        long res = 0;
        for (int i = 1; i < (1 << n); i++) {
            int bit = i;
            int[] person = new int[n];
            int honest = 0;
            int idx = 0;
            //正直者を決め打ちで作成する
            while (bit > 0) {
                if ((bit & 1) == 1) {
                    person[idx] = 1;
                    honest++;
                }
                idx++;
                bit >>= 1;
            }

            boolean isOk = true;
            for (int j = 0; j < n; j++) {
                //正直者の発言に矛盾がなければよい
                if (person[j] == 1) {
                    int[][] wkPerson = pMap.get(j);
                    for (int[] js : wkPerson) {
                        int js1 = js[0];
                        int js2 = js[1];
                        if (person[js1] != js2) {
                            isOk = false;
                            break;
                        }
                    }
                }
                if (!isOk)
                    break;
            }
            if (isOk) {
                res = Math.max(res, honest);
            }
        }

        out.println(res);
    }

