    int inf = Integer.MAX_VALUE/2;

    void solve(){
        int n = ni();
        int R = 100010;
        boolean[] xseen = new boolean[R];
        boolean[] yseen = new boolean[R];
        long xsum = 0;
        long ysum = 0;
        int[][] res = new int[n][2];
        boolean[] xline = new boolean[R];
        boolean[] yline = new boolean[R];
        for(int i = 0; i < n; i++){
            int x = ni();
            int y = ni();
            res[i][0] = x;
            res[i][1] = y;
            if(!xseen[x]){
                xseen[x] = true;
                xsum++;
            }
            else{
                xline[x] = true;
            }
            if(!yseen[y]){
                yseen[y] = true;
                ysum++;
            }
            else{
                yline[y] = true;
            }
        }
        boolean flag = false;
        for(int i = 0; i < n; i++){
            if(xline[res[i][0]]&&yline[res[i][1]]){
                flag = true;
            }
        }
        long ans = xsum * ysum;
        out.println(flag ? ans-n : 0);
    }

