	static void solve() {
		n = ni();
		g = new ArrayList[2*100000];//頂点は最大で2n個
		for (int i = 0; i < g.length; i++) g[i] = new ArrayList<>();

		for(int i=0;i<n;i++) {
			int x = ni()-1, y = ni()-1;
			y += 100000;
			g[x].add(y);
			g[y].add(x);
		}

		visited = new boolean[2*100000];

		long ans = -n; //追加エッジ = 完全マッチングの時のエッジ数(全ての連結なグラフのcnt[0]*cnt[1]の総和) - 初期エッジ数(n)
		for(int i=0;i<n*2;i++) {
			if(visited[i])continue;
			cnt = new int[2];
			dfs(i);//iに連結な頂点を全て辿り、xの頂点数と、yの頂点数を数える
			ans += (long)cnt[0] * cnt[1];
		}
		out.println(ans);
	}

	static int[] cnt;
	static void dfs(int v) {
		if(visited[v])return;
		visited[v] = true;
		cnt[v/100000]++; //vが[0,n)なら、xの頂点。[n,2n)ならyの頂点なので、v/nで0->x , 1->y
		for(int to:g[v])dfs(to);
	}

