class UnionFindTree {
	int[] par;
	int[] rank;
	int[] xpeers; //集合の要素数用
	int[] ypeers; //集合の要素数用

	public UnionFindTree(int n){
		par = new int[n];
		rank = new int[n];
		xpeers = new int[n];
		ypeers = new int[n];

		for(int i=0;i<n/2;i++){
			par[i] = i;
			xpeers[i] = 1;
		}
		for(int i=n/2;i<n;i++){
			par[i] = i;
			ypeers[i] = 1;
		}
	}

	//木の根を求める
	int find(int x){
		if(par[x] == x){
			return x;
		}
		else{
			return par[x] = find(par[x]);
		}
	}

	//xとyの属する集合を併合
	public void unite(int x, int y){
		int px = find(x);
		int py = find(y);

		if(px == py){
			return;
		}
		else if(rank[px] < rank[py]){
			xpeers[py] += xpeers[px];
			ypeers[py] += ypeers[px];
			par[px] = py;

		}
		else{
			xpeers[px] += xpeers[py];
			ypeers[px] += ypeers[py];
			par[py] = px;
			if(rank[px]==rank[py]){
				rank[px]++;
			}
		}

	}

	//xとyが同じ集合に属するか
	public boolean isSame(int x, int y){
		return find(x) == find(y);
	}

}

class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}
	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}
	public boolean hasNext() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
		return hasNextByte();
	}
	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) nl;
	}
	public int[] nextintArray(int n){
		int[] a = new int[n];
		for(int i=0;i<n;i++){
			a[i] = nextInt();
		}
		return a;
	}
	public long[] nextlongArray(int n){
		long[] a = new long[n];
		for(int i=0;i<n;i++){
			a[i] = nextLong();
		}
		return a;
	}
	public Integer[] nextIntegerArray(int n){
		Integer[] a = new Integer[n];
		for(int i=0;i<n;i++){
			a[i] = nextInt();
		}
		return a;
	}
	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
	static List<List<Integer>> list;
	static boolean[] visit;
	static int mx = 100001;
	static int mx2 = 200003;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		int n = Integer.parseInt(sa[0]);
		list = new ArrayList<>(mx2);
		for (int i = 0; i < mx2; i++) {
			list.add(new ArrayList<>());
		}
		for (int i = 0; i < n; i++) {
			sa = br.readLine().split(" ");
			int x = Integer.parseInt(sa[0]);
			int y = Integer.parseInt(sa[1]) + mx;
			list.get(x).add(y);
			list.get(y).add(x);
		}
		br.close();

		long ans = 0;
		visit = new boolean[mx2];
		for (int i = 1; i <= mx; i++) {
			if (!visit[i]) {
				int[] cnt = dfs(i, 0, new int[2]);
				ans += (long) cnt[0] * cnt[1];
			}
		}
		System.out.println(ans - n);
	}

	static int[] dfs(int cur, int p, int[] cnt) {
		visit[cur] = true;
		cnt[cur / mx]++;
		for (int next : list.get(cur)) {
			if (next != p && !visit[next]) {
				dfs(next, cur, cnt);
			}
		}
		return cnt;
	}
}

import java.io.*;
import java.nio.CharBuffer;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.NoSuchElementException;

public class Main {

    public static void main(String[] args) {
        SimpleScanner scanner = new SimpleScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = scanner.nextInt();
        HashMap<Integer, HashSet<Integer>> xMap = new HashMap<>();
        HashMap<Integer, HashSet<Integer>> yMap = new HashMap<>();
        int[][] point = new int[n][2];
        for (int i = 0; i < n; ++i) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            point[i][0] = x;
            point[i][1] = y;
            xMap.putIfAbsent(x, new HashSet<>());
            xMap.get(x).add(i);
            yMap.putIfAbsent(y, new HashSet<>());
            yMap.get(y).add(i);
        }
        boolean[] visited = new boolean[n];
        Arrays.fill(visited, false);
        long ans = 0;
        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                HashSet<Integer> diffX = new HashSet<>();
                HashSet<Integer> diffY = new HashSet<>();
                dfs(i, point, visited, xMap, yMap, diffX, diffY);
                ans += diffX.size() * diffY.size();
            }
        }
        writer.println(ans - n);

        writer.close();
    }

    private static void dfs(int u, int[][] point, boolean[] visited, HashMap<Integer, HashSet<Integer>> xMap, HashMap<Integer, HashSet<Integer>> yMap, HashSet<Integer> diffX, HashSet<Integer> diffY) {
        visited[u] = true;
        if (diffX.add(point[u][0]))
            for (int v : xMap.get(point[u][0]))
                dfs(v, point, visited, xMap, yMap, diffX, diffY);
        if (diffY.add(point[u][1]))
            for (int v : yMap.get(point[u][1]))
                dfs(v, point, visited, xMap, yMap, diffX, diffY);
    }

    private static class SimpleScanner {

        private static final int BUFFER_SIZE = 10240;

        private Readable in;
        private CharBuffer buffer;
        private boolean eof;

        SimpleScanner(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
            buffer = CharBuffer.allocate(BUFFER_SIZE);
            buffer.limit(0);
            eof = false;
        }


        private char read() {
            if (!buffer.hasRemaining()) {
                buffer.clear();
                int n;
                try {
                    n = in.read(buffer);
                } catch (IOException e) {
                    n = -1;
                }
                if (n <= 0) {
                    eof = true;
                    return '\0';
                }
                buffer.flip();
            }
            return buffer.get();
        }

        void checkEof() {
            if (eof)
                throw new NoSuchElementException();
        }

        char nextChar() {
            checkEof();
            char b = read();
            checkEof();
            return b;
        }

        String next() {
            char b;
            do {
                b = read();
                checkEof();
            } while (Character.isWhitespace(b));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append(b);
                b = read();
            } while (!eof && !Character.isWhitespace(b));
            return sb.toString();
        }

        int nextInt() {
            return Integer.valueOf(next());
        }

        long nextLong() {
            return Long.valueOf(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int[] x = new int[N];
        int[] y = new int[N];
        for (int i = 0; i < N; ++i) {
            x[i] = sc.nextInt();
            y[i] = sc.nextInt();
        }

        System.out.println(solve(x, y));

        sc.close();
    }

    static long solve(int[] x, int[] y) {
        int N = x.length;

        Map<Integer, List<Integer>> xValueToIndices = new HashMap<>();
        Map<Integer, List<Integer>> yValueToIndices = new HashMap<>();
        for (int i = 0; i < N; ++i) {
            if (!xValueToIndices.containsKey(x[i])) {
                xValueToIndices.put(x[i], new ArrayList<>());
            }
            xValueToIndices.get(x[i]).add(i);

            if (!yValueToIndices.containsKey(y[i])) {
                yValueToIndices.put(y[i], new ArrayList<>());
            }
            yValueToIndices.get(y[i]).add(i);
        }

        @SuppressWarnings("unchecked")
        List<Integer>[] adjLists = new List[N];
        for (int i = 0; i < adjLists.length; ++i) {
            adjLists[i] = new ArrayList<>();
        }

        for (List<Integer> indices : Stream.concat(xValueToIndices.values().stream(), yValueToIndices.values().stream())
                .collect(Collectors.toList())) {
            for (int i = 0; i < indices.size(); ++i) {
                if (i != 0) {
                    adjLists[indices.get(i)].add(indices.get(i - 1));
                }
                if (i != indices.size() - 1) {
                    adjLists[indices.get(i)].add(indices.get(i + 1));
                }
            }
        }

        long result = 0;
        boolean[] visited = new boolean[N];
        for (int i = 0; i < N; ++i) {
            if (!visited[i]) {
                List<Integer> group = new ArrayList<>();
                search(group, adjLists, visited, i);

                int xValueNum = (int) group.stream().mapToInt(index -> x[index]).distinct().count();
                int yValueNum = (int) group.stream().mapToInt(index -> y[index]).distinct().count();

                result += (long) xValueNum * yValueNum - group.size();
            }
        }

        return result;
    }

    static void search(List<Integer> group, List<Integer>[] adjLists, boolean[] visited, int node) {
        group.add(node);
        visited[node] = true;

        for (int adj : adjLists[node]) {
            if (!visited[adj]) {
                search(group, adjLists, visited, adj);
            }
        }
    }
}

