        Cord[] XS = new Cord[100_000];
        Cord[] YS = new Cord[100_000];
        UnionFind uf = new UnionFind(N);
        for (int i = 0; i < N; i++) {
            Cord c = C[i];
            if( XS[c.x] != null ) {
                uf.unite(c.i, XS[c.x].i);
            }
            if( YS[c.y] != null ) {
                uf.unite(c.i, YS[c.y].i);
            }

            XS[c.x] = c;
            YS[c.y] = c;
        }

        Map<Integer, Group> map = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int r = uf.root(i);
            if( !map.containsKey(r) ) {
                map.put(r, new Group(i));
            }
            Group g = map.get(r);
            g.add(C[i]);
        }

        long ans = 0;
        for (Group group : map.values()) {
            if( group.xs.size() == 1 || group.ys.size() == 1 ) continue;

            long xy = (long)group.xs.size() * group.ys.size();
            ans += xy - group.cnt;
        }
        return ans;
    }

    static class Group {
        int root;
        Set<Integer> xs = new HashSet<>();
        Set<Integer> ys = new HashSet<>();
        int cnt = 0;

        Group(int root) {
            this.root = root;
        }

        void add(Cord c) {
            xs.add(c.x);
            ys.add(c.y);
            cnt++;
        }
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] count;

        public UnionFind(int n) {
            parent = new int[n];
            count = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                count[i] = 1;
            }
        }

        public int root(int i) {
            if (parent[i] == i) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public int unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if (ri == rj) return ri;


            int big = count[ri] < count[rj] ? rj : ri;
            int small = big == ri ? rj : ri;
            parent[small] = big;
            count[big] += count[small];
            return big;
        }

        public int count(int a) {
            return count[root(a)];
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }

    static class Cord {
        int i, x, y;

        public Cord(int i, int x, int y) {
            this.i = i;
            this.x = x;
            this.y = y;
        }
    }

