class UnionFindTree {
	int[] par;
	int[] rank;
	int[] xpeers; //集合の要素数用
	int[] ypeers; //集合の要素数用

	public UnionFindTree(int n){
		par = new int[n];
		rank = new int[n];
		xpeers = new int[n];
		ypeers = new int[n];

		for(int i=0;i<n/2;i++){
			par[i] = i;
			xpeers[i] = 1;
		}
		for(int i=n/2;i<n;i++){
			par[i] = i;
			ypeers[i] = 1;
		}
	}

	//木の根を求める
	int find(int x){
		if(par[x] == x){
			return x;
		}
		else{
			return par[x] = find(par[x]);
		}
	}

	//xとyの属する集合を併合
	public void unite(int x, int y){
		int px = find(x);
		int py = find(y);

		if(px == py){
			return;
		}
		else if(rank[px] < rank[py]){
			xpeers[py] += xpeers[px];
			ypeers[py] += ypeers[px];
			par[px] = py;

		}
		else{
			xpeers[px] += xpeers[py];
			ypeers[px] += ypeers[py];
			par[py] = px;
			if(rank[px]==rank[py]){
				rank[px]++;
			}
		}

	}

	//xとyが同じ集合に属するか
	public boolean isSame(int x, int y){
		return find(x) == find(y);
	}

}

