    /**
     * https://atcoder.jp/contests/agc013/tasks/agc013_a
     * A - Sorted Arrays
     */
    private void solveC() {
        int n = nextInt();
        int[] a = IntStream.range(0, n).map(i -> nextInt()).toArray();
        long res = 0;
        //増加傾向と減少傾向を表すためにtru/false
        //切れ目を表現するのに二つ使う
        boolean inc = false;
        boolean dec = false;
        for (int i = 0; i < n - 1; i++) {
            if (inc) {
                if (a[i] > a[i + 1]) {
                    //増加傾向終了
                    inc = false;
                }
            } else if (dec) {
                if (a[i] < a[i + 1]) {
                    //減少傾向終了
                    dec = false;
                }
            } else {
                //増加or減少の傾向把握
                if (a[i] < a[i + 1]) {
                    inc = true;
                    res++;
                } else if (a[i] > a[i + 1]) {
                    dec = true;
                    res++;
                }
                //増加も減少もしない場合はstay
            }
        }
        if (!inc && !dec) {
            //stay状態ではない。まだ残っている。
            res++;
        }
        out.println(res);
    }

    /**
     * https://atcoder.jp/contests/abc147/tasks/abc147_c
     * C - HonestOrUnkind2
     */
    private void solveD() {
        int n = nextInt();
        Map<Integer, int[][]> pMap = new HashMap<Integer, int[][]>();
        for (int i = 0; i < n; i++) {
            int a = nextInt();
            int[][] val = IntStream.range(0, a).mapToObj(x -> new int[]{nextInt() - 1, nextInt()}).toArray(int[][]::new);
            pMap.put(i, val);
        }

        long res = 0;
        for (int i = 1; i < (1 << n); i++) {
            int bit = i;
            int[] person = new int[n];
            int honest = 0;
            int idx = 0;
            //正直者を決め打ちで作成する
            while (bit > 0) {
                if ((bit & 1) == 1) {
                    person[idx] = 1;
                    honest++;
                }
                idx++;
                bit >>= 1;
            }

            boolean isOk = true;
            for (int j = 0; j < n; j++) {
                //正直者の発言に矛盾がなければよい
                if (person[j] == 1) {
                    int[][] wkPerson = pMap.get(j);
                    for (int[] js : wkPerson) {
                        int js1 = js[0];
                        int js2 = js[1];
                        if (person[js1] != js2) {
                            isOk = false;
                            break;
                        }
                    }
                }
                if (!isOk)
                    break;
            }
            if (isOk) {
                res = Math.max(res, honest);
            }
        }

        out.println(res);
    }

