import java.io.InputStream;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Scanner;
import java.util.Set;

public class Main {

  public static void main(String[] args) {
    solve(System.in, System.out);
  }

  private static long MOD = 1000000007;

  static void solve(InputStream is, PrintStream os) {
    Scanner sc = new Scanner(is);

    /* read */
    int n = sc.nextInt();
    Map<Integer, Set<Integer>> xoccurs = new HashMap<>();
    Map<Integer, Set<Integer>> yoccurs = new HashMap<>();

    for (int i = 0; i < n; i++) {
      int x = sc.nextInt();
      int y = sc.nextInt();
      Set<Integer> ySetOfX = xoccurs.getOrDefault(x, new HashSet<>());
      ySetOfX.add(y);
      xoccurs.put(x, ySetOfX);

      Set<Integer> xSetOfY = yoccurs.getOrDefault(y, new HashSet<>());
      xSetOfY.add(x);
      yoccurs.put(y, xSetOfY);
    }

    Set<Integer> xMultiples = new HashSet<>();
    Set<Integer> yMultiples = new HashSet<>();

    for (int x : xoccurs.keySet()) {
      if (xoccurs.get(x).size() == 1) continue;
      Set<Integer> ys = xoccurs.get(x);
      yMultiples.addAll(ys);
      for (int y : ys) {
        Set<Integer> xs = yoccurs.get(y);
        if (xs != null) {
          xMultiples.addAll(xs);
        }
      }
    }

    for (int y : yoccurs.keySet()) {
      if (yoccurs.get(y).size() == 1) continue;
      Set<Integer> xs = xoccurs.get(y);
      xMultiples.addAll(xs);
      for (int x : xs) {
        Set<Integer> ys = yoccurs.get(x);
        if (ys != null) {
          yMultiples.addAll(ys);
        }
      }
    }

    int count = 0;
    for (int x : xMultiples) {
      for (int y : yMultiples) {
        if (!xoccurs.containsKey(x) || !xoccurs.get(x).contains(y)) count++;
      }
    }

    os.println(count);
  }

}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
	static List<List<Integer>> list;
	static boolean[] visit;
	static int mx = 100001;
	static int mx2 = 200003;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		int n = Integer.parseInt(sa[0]);
		list = new ArrayList<>(mx2);
		for (int i = 0; i < mx2; i++) {
			list.add(new ArrayList<>());
		}
		for (int i = 0; i < n; i++) {
			sa = br.readLine().split(" ");
			int x = Integer.parseInt(sa[0]);
			int y = Integer.parseInt(sa[1]) + mx;
			list.get(x).add(y);
			list.get(y).add(x);
		}
		br.close();

		long ans = 0;
		visit = new boolean[mx2];
		for (int i = 1; i < mx2; i++) {
			if (!visit[i]) {
				int[] cnt = dfs(i, 0, new int[3]);
				ans += Math.max((long) cnt[0] * cnt[1] - cnt[2], 0);
			}
		}
		System.out.println(ans);
	}

	static int[] dfs(int cur, int p, int[] cnt) {
		visit[cur] = true;
		cnt[cur / mx]++;
		for (int next : list.get(cur)) {
			if (next != p && !visit[next]) {
				cnt[2]++;
				dfs(next, cur, cnt);
			}
		}
		return cnt;
	}
}

