		for(int i=0; i<n; i++){
			x[i]=sc.nextInt()-1;
			int y=sc.nextInt()-1+100000;
			list.get(x[i]).add(y);
			list.get(y).add(x[i]);
		}
		long sum=0;
		for(int i:x){
			xc=0;
			yc=0;
			dfs(0,i);
			sum+=xc*yc;
		}
		System.out.println(sum-n);
	}
	static void dfs(int count,int i){
		if(!visited[i]){
			visited[i]=true;
			if(count%2==0){
				xc++;
			}else{
				yc++;
			}
			for(int j:list.get(i)){
				dfs(count+1,j);
			}
		}
	}
}

