			long cost;
			Edge(int source, int target, long cost) {
				this.source = source;
				this.target = target;
				this.cost = cost;
			}

			@Override
			public int compareTo(Edge e) {
				return Long.compare(this.cost, e.cost);
			}
		}

public void solve() {
	int num = ni();
	int p[][] = new int[num][3];
	for(int i = 0; i < num; i ++) {
		p[i][0] = ni();
		p[i][1] = ni();
		p[i][2] = i;
	}
	UnionFind uf = new UnionFind(num);
	Arrays.sort(p, (sort1, sort2) -> Integer.compare(sort1[0], sort2[0]));
	for(int i = 1; i < num; i ++) {
		if(p[i][0] == p[i - 1][0]) uf.unite(p[i][2], p[i - 1][2]);
	}
	Arrays.sort(p, (sort1, sort2) -> Integer.compare(sort1[1], sort2[1]));
	for(int i = 1; i < num; i ++) {
		if(p[i][1] == p[i - 1][1]) uf.unite(p[i][2], p[i - 1][2]);
	}
	Arrays.sort(p, (sort1, sort2) -> Integer.compare(sort1[2], sort2[2]));

	List<Set<Integer>> x = new ArrayList<>();
	List<Set<Integer>> y = new ArrayList<>();
	for(int i = 0; i < num; i ++) {
		x.add(new HashSet<>());
		y.add(new HashSet<>());
	}
	for(int i = 0; i < num; i ++) {
		x.get(uf.root(i)).add(p[i][0]);
		y.get(uf.root(i)).add(p[i][1]);
	}
	long ans = - num;
	for(int i = 0; i < num; i ++) {
		ans += (long)x.get(i).size() * y.get(i).size();
	}
	prtln(ans);
}

class UnionFind {
	int parent[];
	int size[];

	public UnionFind(int num) {
		parent = new int[num];
		size = new int[num];
		for(int i = 0; i < num; i ++) {
			initNode(i);
		}
	}

	public void initNode(int i) {
		parent[i] = i;
		size[i] = 1;
	}

	public void unite(int x, int y) {
		int xRoot = root(x);
		int yRoot = root(y);
		if(xRoot == yRoot) { return; }
		if(size[yRoot] > size[xRoot]) {
			parent[xRoot] = yRoot;
			size[yRoot] += size[xRoot];
		}else {
			parent[yRoot] = xRoot;
			size[xRoot] += size[yRoot];
		}
	}

	public int size(int i) {
		return size[root(i)];
	}

	public int root(int i) {
		if(i != parent[i]) {
			parent[i] = root(parent[i]);
		}
		return parent[i];
	}

	public boolean same(int x, int y) {
		return root(x) == root(y);
	}
}

	}
}

