    int inf = Integer.MAX_VALUE/2;

    void solve(){
        int n = ni();
        int num = 100000;
        UnionFind uf = new UnionFind(num*2+1);
        for(int i = 0; i < n; i++){
            int x = ni();
            int y = ni()+num;
            uf.union(x,y);
        }
        long[][] res = new long[2*num+1][2];
        for(int i = 0; i <= num; i++){
            res[uf.find(i)][0] += 1;
        }
        for(int i = num+1; i <= 2*num; i++){
            res[uf.find(i)][1] += 1;
        }
        long ans = 0;
        for(int i = 0; i <= 2*num; i++){
            long total = res[i][0]*res[i][1];
            if(total==0) continue;
            ans += total - uf.amount(i) + 1;
        }
        out.println(ans);
    }

    public static class UnionFind{  
        int parent[];
        int rank[];  //depth
        int size[];

        public UnionFind(int n){
            parent = new int[n];
            rank   = new int[n];
            size = new int[n];

            for(int i = 0;i < n;i++){
                parent[i] = i;
                rank[i]   = 0;
                size[i] = 1;
            }        
        }

        boolean same(int x,int y){
            return find(x) == find(y);
        }

        public int find(int x){
            if(parent[x] == x){
               return x;
            }else{
               return parent[x] = find(parent[x]);   
            }        
        }

        public int amount(int x){
            return size[find(x)];
        }

        public void union(int x,int y){
            x = find(x);
            y = find(y);

            if(x != y){
                if(rank[x] > rank[y]){
                   parent[y] = x; 
                   size[x] += size[y];
                }else{
                   parent[x] = y;
                   size[y] += size[x];
                   if(rank[x] == rank[y]){
                       rank[y]++;
                   }
                }            
            }
            else{
                size[x]++;
            }

            return;
        }

        public int count(int n){
            int ret = 0;
            for(int i = 0;i < n;i++){
                if(i == find(i)){
                    ret++;
                }
            }
            return ret;
        }

      } 

