		Map<Integer,TreeSet<Integer>> my = new HashMap<>();
		Map<Integer, Boolean> xused = new HashMap<>();
		Map<Integer, Boolean> yused = new HashMap<>();
		for(int i=0;i<n;i++) {
			int x = ps[i].x, y = ps[i].y;
			if(!mx.containsKey(x))mx.put(x,new TreeSet<Integer>());
