                if (!xCount.ContainsKey(rt))
                {
                    xCount[rt] = new HashSet<long>();
                }
                if (!yCount.ContainsKey(rt))
                {
                    yCount[rt] = new HashSet<long>();
                }
                xCount[rt].Add(item.x);
                yCount[rt].Add(item.y);
            }
            foreach (var item in xy)
            {
                var key = item.x * 10000000 + item.y;
                if (uf.IsRoot(key))
                {
                    if (uf.Count(key) > 2)
                    {
