        for(var i = 0; i < num; i++)
        {
            var xy = Input.ar;
            uf.Union(xy[0], MM + xy[1]);
        }
        var res = 0L;
        var px = new long[2*MM+1];
        var py = new long[2*MM+1];
        for (var i = 0; i <= 2 * MM; i++)
            if (i <= MM)
                px[uf.Parent(i)]++;
            else py[uf.Parent(i)]++;
        for (var i = 0; i <= 2 * MM; i++)
            res += px[i] * py[i];
        WriteLine(res - num);
