namespace AtCoder_Beginner_Contest_131
{
    class Program
    {
        //参照(http://drken1215.hatenablog.com/entry/2019/06/23/004700)
        class UnionFind
        {
            int[] par;
            public UnionFind(int n)
            {
                init(n);
            }
            public void init(int n)
            {
                par = new int[n];
                for (var i = 0; i < n; ++i)
                { par[i] = -1; }
            }
            public int root(int x)
            {
                if (par[x] < 0) return x;
                else return par[x] = root(par[x]);
            }
            public bool issame(int x, int y)
            {
                return root(x) == root(y);
            }
            public bool merge(int x, int y)
            {
                x = root(x); y = root(y);
                if (x == y) return false;
                if (par[x] > par[y])
                {
                    var tmp = y;
                    y = x;
                    x = tmp;
                }
                par[x] += par[y];
                par[y] = x;
                return true;
            }
            public int size(int x)
            {
                return -par[root(x)];
            }
        }
        const int MAX = 110000;
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static void Main(string[] args)
        {

            var N = Sarray()[0];
            UnionFind uf = new UnionFind(MAX * 2);
            var x = new List<int>();
            var y = new List<int>();
            for (var i = 0; i < N; ++i)
            {
                var xy = Sarray();
                x.Add((int)xy[0]);
                y.Add((int)xy[1]);
                uf.merge(x[i], y[i] + MAX);
            }
            var mx = new long[MAX * 2];
            var my = new long[MAX * 2];
            for (var i = 0; i < MAX; ++i) { mx[uf.root(i)]++; }
            for (var i = MAX; i < MAX * 2; ++i) { my[uf.root(i)]++; }
            long res = 0;
            for (var r = 0; r < MAX * 2; ++r) res += mx[r] * my[r];
            WriteLine(res - N);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace MustBeRectangular
{

    public static class Combination
    {
        public static IEnumerable<T[]> Enumerate<T>(IEnumerable<T> items, int k, bool withRepetition)
        {
            if (k == 1)
            {
                foreach (var item in items)
                    yield return new T[] { item };
                yield break;
            }
            foreach (var item in items)
            {
                var leftside = new T[] { item };

                // item よりも前のものを除く （順列と組み合わせの違い)
                // 重複を許さないので、unusedから item そのものも取り除く
                var unused = withRepetition ? items : items.SkipWhile(e => !e.Equals(item)).Skip(1).ToList();

                foreach (var rightside in Enumerate(unused, k - 1, withRepetition))
                {
                    yield return leftside.Concat(rightside).ToArray();
                }
            }
        }
    }

    class MainClass
    {
        public static void Main(string[] args)
        {
            //引数の処理
            var strPointNum = Console.ReadLine();

            if (!int.TryParse(strPointNum, out int pointNum)) return;

            var list = new List<Tuple<int, int>>();
            for(int i=0;i<pointNum;i++)
            {
                var strPoint = Console.ReadLine().Split(' ');

                list.Add(new Tuple<int, int>(Convert.ToInt32(strPoint[0]), Convert.ToInt32(strPoint[1])));
            }

            if(list.Count < 3)
            {
                //点が３つ以上ないときは何もできないので、0を返す
                Console.WriteLine("0");
                return;
            }


            //追加した点の個数
            var countMax = 0;

            IEnumerable<int[]> patternPrev = new List<int[]>();

            while(true)
            {
                //前回分の組み合わせのパターン
                var range = Enumerable.Range(0, list.Count()).ToArray();
                var pattern = Combination.Enumerate(range, 3, withRepetition: false);

                //前回分のパターンを無視
                pattern = pattern.Where(x => !patternPrev.Where(y => y.SequenceEqual(x)).Any()).ToList();

                if (pattern.Count() <= 0) break;

                //追加する点用のリスト
                var listAdd = new List<Tuple<int, int>>();

                foreach (var n in pattern)
                {
                    var (x1, y1) = list.ElementAt(n[0]);
                    var (x2, y2) = list.ElementAt(n[1]);
                    var (x3, y3) = list.ElementAt(n[2]);

                    //新しい点を作成
                    Tuple<int, int> p4 = null;

                    if(x1 == x2)
                    {
                        if(y1 == y3)
                        {
                            p4 = new Tuple<int, int>(x3, y2);
                        }
                        else if(y2 == y3)
                        {
                            p4 = new Tuple<int, int>(x3, y1);
                        }
                    }
                    else if(x1 == x3)
                    {
                        if (y1 == y2)
                        {
                            p4 = new Tuple<int, int>(x2, y3);
                        }
                        else if (y2 == y3)
                        {
                            p4 = new Tuple<int, int>(x2, y1);
                        }
                    }
                    else if(x2 == x3)
                    {
                        if (y2 == y1)
                        {
                            p4 = new Tuple<int, int>(x1, y3);
                        }
                        else if (y3 == y1)
                        {
                            p4 = new Tuple<int, int>(x1, y2);
                        }
                    }

                    if (p4 == null) continue;


                    //まだ追加していない点なら追加
                    if(!list.Contains(p4) && !listAdd.Contains(p4))
                    {
                        listAdd.Add(p4);
                    }
                }

                if (listAdd.Count <= 0) break;

                countMax += listAdd.Count;

                //次回のループの準備
                list.AddRange(listAdd);
                listAdd.Clear();
                patternPrev = pattern.ToList();
            }

            //答え表示
            Console.WriteLine(Convert.ToString(countMax));

        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Diagnostics;

namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int Solve(int N, Tuple<int, int>[] points)
        {
            var set = new HashSet<Tuple<int, int>>(points);
            var xs = new Dictionary<int, List<int>>();
            var ys = new Dictionary<int, List<int>>();
            foreach (var p in set)
            {
                int x = p.Item1;
                int y = p.Item2;
                if (!xs.ContainsKey(y)) { xs[y] = new List<int>(); }
                if (!ys.ContainsKey(x)) { ys[x] = new List<int>(); }
                xs[y].Add(x);
                ys[x].Add(y);
            }
            int cnt = 0;
            foreach (var p1 in points)
            {
                foreach (int x in xs[p1.Item2])
                {
                    if (x == p1.Item1) { continue; }
                    foreach (int y in ys[p1.Item1])
                    {
                        if (y == p1.Item2) { continue; }
                        var p2 = new Tuple<int, int>(x, y);
                        if (!set.Contains(p2))
                        {
                            set.Add(p2);
                            ++cnt;
                        }
                    }
                }
            }
            return cnt;
        }

        static void Main(string[] args)
        {
            int N = ReadInt();
            var points = new Tuple<int, int>[N];
            for (int i = 0; i < N; ++i)
            {
                var V = ReadInts();
                points[i] = new Tuple<int, int>(V[0], V[1]);
            }
            Console.WriteLine(Solve(N, points));
        }
    }
}

