    public class QuestionF : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var n = inputStream.ReadInt();
            var xCount = new int[100001];
            var yCount = new int[100001];

            for (int i = 0; i < n; i++)
            {
                var xy = inputStream.ReadIntArray();
                var x = xy[0];
                var y = xy[1];
                xCount[x]++;
                yCount[y]++;
            }

            var xDuplicated = xCount.Where(i => i >= 2).ToArray();
            var yDuplicated = yCount.Where(i => i >= 2).ToArray();
            yield return (long)xDuplicated.Sum() * yDuplicated.Sum() - (xDuplicated.Sum() + yDuplicated.Sum() - (long)xDuplicated.Length * yDuplicated.Length);
        }
    }
}


