    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }

        const int V = 100005;
        static List<long>[] to = new List<long>[V * 2];
        static bool[] visited = new bool[V * 2];
        static long[] cnt;
        static void dfs(long v)
        {
            if (visited[v]) return;
            visited[v] = true;
            cnt[v / V]++;
            foreach (var u in to[v])
            { dfs(u); }
        }
        static void Main(string[] args)
        {
            for(var i=0;i<V*2; ++i)
            {
                to[i] = new List<long>();
