                y += V;
                to[x].Add(y);
                to[y].Add(x);
            }
            var ans = 0L;
            for (var i = 0; i < V * 2; ++i)
            {
                if (visited[i]) continue;
                cnt = new long[2];
                dfs(i);
                ans += cnt[0] * cnt[1];
            }
            WriteLine(ans - N);
        }
