    public object Calc()
    {
        var N = cr.Int;
        var points = cr.Repeat(N).Select(cr => new Point(cr.Split.Int));
        var xs = new Dictionary<int, List<int>>();
        var ys = new Dictionary<int, List<int>>();
        for (int i = 0; i < points.Length; i++)
        {
            var p = points[i];
            List<int> list;
            if (xs.TryGetValue(p.x, out list))
                list.Add(i);
            else
                xs[p.x] = new List<int> { i };

            if (ys.TryGetValue(p.y, out list))
                list.Add(i);
            else
                ys[p.y] = new List<int> { i };
        }

        var gyaku = new Dictionary<Point, int>(N);
        for (int i = 0; i < points.Length; i++)
            gyaku[points[i]] = i;
        var sumi = new bool[N];
        long cnt = 0;
        for (int i = 0; i < points.Length; i++)
        {
            if (sumi[i]) continue;
            var machi = new Stack<int>();
            machi.Push(i);
            var c = 0;
            var xset = new HashSet<int> { };
            var yset = new HashSet<int>();
            while (machi.Count > 0)
            {
                var index = machi.Pop();
                if (sumi[index])
                    continue;

                var p = points[index];

                c++;
                sumi[index] = true;
                xset.Add(p.x);
                yset.Add(p.y);

                foreach (var x in xs[p.x])
                {
                    if (!sumi[x])
                        machi.Push(x);
                }
                foreach (var y in ys[p.y])
                {
                    if (!sumi[y])
                        machi.Push(y);
                }
            }

            long xc = xset.Count;
            long yc = yset.Count;
            cnt += xc * yc - c;
        }

        return cnt;
    }
