    private object Calc()
    {
        N = cr;
        for (int i = 0; i < N; i++)
        {
            int x = cr, y = cr;
            List<int> l;
            if (!xs.TryGetValue(x, out l))
                xs[x] = l = new List<int>();
            l.Add(y);
            if (!ys.TryGetValue(y, out l))
                ys[y] = l = new List<int>();
            l.Add(x);
        }
        while (xs.Count > 0)
        {
            xsumi = new HashSet<int>();
            ysumi = new HashSet<int>();
            sumi = new HashSet<Tuple<int, int>>();
            var p = xs.First();
            xsumi.Add(p.Key);
            CalcX(p.Key);
            res += (long)xsumi.Count * ysumi.Count - sumi.Count;
            foreach (var x in xsumi) xs.Remove(x);
            foreach (var y in ysumi) ys.Remove(y);
        }
        return res;
    }
    void CalcX(int x)
    {
