        {
            if (ysumi.Add(y))
            {
                sumi.Add(Tuple.Create(x, y));
                CalcY(y);
            }
        }
    }
    void CalcY(int y)
    {
        foreach (var x in ys[y])
        {
            if (xsumi.Add(x))
            {
                sumi.Add(Tuple.Create(x, y));
                CalcX(x);
            }
        }
    }
