    void Solve()
    {

        //http://drken1215.hatenablog.com/entry/2019/06/23/004700
        Scanner cin = new Scanner();
        int n = cin.NextInt();
        int MAX = 110000;

        UnionFind uf = new UnionFind(MAX * 2);
        for (int i = 0; i < n; i++)
        {
            uf.Merge(cin.NextInt(), cin.NextInt() + MAX);
        }

        List<int> index = Enumerable.Range(0, MAX * 2).ToList();
        Dictionary<int, long> mx = index.ToDictionary(i => i, i => 0L);
        Dictionary<int, long> my = index.ToDictionary(i => i, i => 0L);

        for (int i = 0; i < MAX; i++)
        {
            mx[uf.Root(i)]++;
        }

