                else if (k1 && !k2)
                {
                    _par[key2] = Root(key1);
                    _count[_par[key2]]++;
                }
                else
                {
                    var r1 = Root(key1);
                    var r2 = Root(key2);
                    if (r1 == r2) return;
                    _count[r2] += _count[r1];
                    _par[r1] = r2;
