                        {
                            if (!done.ContainsKey(y))
                            {
                                done[y] = new HashSet<long>();
                            }
                            if (done[y].Contains(x)) continue;
                            done[y].Add(x);
                            var key = x * 10000000 + y;
                            uf.Unite(keymaster, key);
                        }
                    }
                }
