public class Solver
{
	public static readonly int MAX = 100000;

	public void Solve()
	{
		int N = GetInt();
		int[] x = new int[N];
		int[] y = new int[N];
		for(int i = 0; i < N; i++)
		{
			x[i] = GetInt() - 1;
			y[i] = GetInt() - 1 + MAX;
		}

		var uf = new UnionFind(2 * MAX);
		for(int i = 0; i < N; i++)
		{
			if(!uf.IsSame(x[i], y[i]))
				uf.Merge(x[i], y[i]);
		}

		var set = new HashSet<int>();
		var cntX = new Dictionary<int, long>();
		var cntY = new Dictionary<int, long>();
		for(int i = 0; i < MAX; i++)
		{
			long tmpX = 0;
			cntX.TryGetValue(uf.Root(i), out tmpX);
			cntX[uf.Root(i)] = tmpX + 1;
			set.Add(uf.Root(i));
		}

		for(int i = MAX; i < 2 * MAX; i++)
		{
			long tmpY = 0;
			cntY.TryGetValue(uf.Root(i), out tmpY);
			cntY[uf.Root(i)] = tmpY + 1;
			set.Add(uf.Root(i));
		}

		long ans = 0;
		foreach(int r in set)
		{
			long tmpX = 0;
			cntX.TryGetValue(r, out tmpX);
			long tmpY = 0;
			cntY.TryGetValue(r, out tmpY);
			ans += tmpX * tmpY;
		}

		Console.WriteLine(ans - N);
	}
}


public class UnionFind
{
	private int[] par = null;
	private int[] rank = null;
	private int[] ccSize = null;

	public UnionFind(int n)
	{
		par = new int[n];
		rank = new int[n];
		ccSize = new int[n];
		for(int i = 0; i < n; i++)
		{
			par[i] = i;
			rank[i] = 0;
			ccSize[i] = 1;
		}
	}

	public bool IsSame(int x, int y)
	{
		return (Root(x) == Root(y));
	}

	public int Root(int x)
	{
		if(par[x] == x)
			return x;

		int r = Root(par[x]);
		par[x] = r;
		return r;
	}

	public bool Merge(int x, int y)
	{
		int rx = Root(x);
		int ry = Root(y);
		if(rx == ry)
			return false;

		if(rank[rx] < rank[ry])
		{
			int tmp = rx;
			rx = ry;
			ry = tmp;
		}
		else if(rank[rx] == rank[ry])
			rank[rx]++;

		par[ry] = rx;
		ccSize[rx] = ccSize[rx] + ccSize[ry];
		return true;
	}

	public int Size(int x)
	{
		return ccSize[Root(x)];
	}
}


