public class UnionFind
{
    public int GroupCount { get; private set; }
    protected int[] data,edge,x,y;
    public virtual int this[int i] => Find(i);
    public UnionFind(int size)
    {
        x = new int[size];y = new int[size];
        for (int i = 0; i < 100000; i++) x[i] = y[i + 100000] = 1;
        edge = new int[size];
        data = Create(size, () => -1);
        GroupCount = size;
    }
    protected int Find(int i)
        => data[i] < 0 ? i : (data[i] = Find(data[i]));
    public int Size(int i)
        => -data[Find(i)];
    public int Edge(int i) => edge[Find(i)];
    public long cnt(int i) => (long)x[Find(i)] * y[Find(i)];
    public virtual bool Union(int u, int v)
    {
        u = Find(u); v = Find(v);
        if (u == v) { edge[u]++; return false; }
        if (data[u] > data[v])
            swap(ref u, ref v);
        GroupCount--;
        x[u] += x[v];
        y[u] += y[v];
        edge[u] += edge[v] + 1;
        data[u] += data[v];
        data[v] = u;
        return true;
    }
}
