        var ID = Enumerable.Range(0, N).ToArray();
        Array.Sort(ID, (x, y) => X[x].CompareTo(X[y]) != 0 ? X[x].CompareTo(X[y]) : Y[x].CompareTo(Y[y]));

        for (int i = 0; i < N; i++)
        {
            X[i] = cin.nextint - 1;
            Y[i] = cin.nextint - 1;

            H[X[i]]++;
            W[Y[i]]++;
        }

        long ans = 0;

        var P = new long[M];
        var Q = new long[M];
        for (int i = 0; i < M; i++)
        {
            P[i] = H[i];
            Q[i] = W[i];
        }

        for (int i = 0; i < N; i++)
        {
            ans += (P[X[ID[i]]] - 1) * (Q[Y[ID[i]]] - 1);
            var d = (H[X[ID[i]]] - 1) * (W[Y[ID[i]]] - 1);
            if (d > 0)
            {
                P[X[ID[i]]]--;
                Q[Y[ID[i]]]--;
            }
            //ans += d;
        }
        WriteLine(ans);
    }

