class Program
{
    SortedDictionary<int, HashSet<int>> xl, yl;
    void Run()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        xl = new SortedDictionary<int, HashSet<int>>();
        yl = new SortedDictionary<int, HashSet<int>>();
        for (int i = 0; i < n; i++)
        {
            int x = sc.NextInt();
            int y = sc.NextInt();
            if (!xl.ContainsKey(x)) xl.Add(x, new HashSet<int>());
            xl[x].Add(y);
            if (!yl.ContainsKey(y)) yl.Add(y, new HashSet<int>());
            yl[y].Add(x);
        }
        int res = 0;
        foreach (int xa in xl.Keys.ToList())
        {
            foreach (int y1 in xl[xa].ToList())
            {
                foreach (int y2 in xl[xa].ToList())
                {
                    if (Check(xa, y1, y2)) res++;
                }
            }
        }

        Console.WriteLine(res);
    }

    bool Check(int x, int y1, int y2)
    {
        int d = Math.Abs(y2 - y1);
        if (d == 0) return false;
        return Check(x, x + d, y1, y2) || Check(x, x - d, y1, y2);
    }

    bool Check(int x, int xx, int y1, int y2)
    {
        if (xx < 0) return false;
        if (yl[y1].Contains(xx) ^ yl[y2].Contains(xx))
        {
            if (yl[y1].Contains(xx))
            {
                yl[y2].Add(xx);
                xl[xx].Add(y2);
                Console.WriteLine("{0} {1}", xx, y2);
            }
            else
            {
                yl[y1].Add(xx);
                xl[xx].Add(y1);
                Console.WriteLine("{0} {1}", xx, y1);
            }
            return true;
        }
        return false;
    }

    static long Count(long a, long b)
    {
        return a / b;
    }

    static void Main(string[] args)
    {
        new Program().Run();
    }

    static long Gcd(long a, long b)
    {
        if (a < b) return Gcd(b, a);
        if (b == 0) return a;
        return Gcd(b, a % b);
    }

    static long Lcm(long a, long b)
    {
        long d = Gcd(a, b);
        return a * b / d;
    }
}

