using System;
using System.Collections.Generic;
using System.Linq;
using MustBeRectangular;

namespace MustBeRectangular
{
    public class Point
    {
        int x;
        int y;

        public int X { get { return x; } set { x = value; } }
        public int Y { get { return y; } set { y = value; } }

        public Point(int x, int y)
        {
            this.x = x;
            this.y = y;
        }
    }

    public static class Combination
    {
        public static IEnumerable<T[]> Enumerate<T>(IEnumerable<T> items, int k, bool withRepetition)
        {
            if (k == 1)
            {
                foreach (var item in items)
                    yield return new T[] { item };
                yield break;
            }
            foreach (var item in items)
            {
                var leftside = new T[] { item };

                // item よりも前のものを除く （順列と組み合わせの違い)
                // 重複を許さないので、unusedから item そのものも取り除く
                var unused = withRepetition ? items : items.SkipWhile(e => !e.Equals(item)).Skip(1).ToList();

                foreach (var rightside in Enumerate(unused, k - 1, withRepetition))
                {
                    yield return leftside.Concat(rightside).ToArray();
                }
            }
        }
    }

    class MainClass
    {
        public static void Main(string[] args)
        {
            //引数の処理
            var strPointNum = Console.ReadLine();

            int pointNum = 0;
            if (!int.TryParse(strPointNum, out pointNum)) return;

            var list = new List<Point>();
            for(int i=0;i<pointNum;i++)
            {
                var strPoint = Console.ReadLine().Split(' ');

                list.Add(new Point(Convert.ToInt32(strPoint[0]), Convert.ToInt32(strPoint[1])));
            }

            if(list.Count < 3)
            {
                //点が３つ以上ないときは何もできないので、0を返す
                Console.WriteLine("0");
                return;
            }


            //追加した点の個数
            var countMax = 0;

            IEnumerable<int[]> patternPrev = new List<int[]>();

            while(true)
            {
                //前回分の組み合わせのパターン
                var range = Enumerable.Range(0, list.Count()).ToArray();
                var pattern = Combination.Enumerate(range, 3, withRepetition: false);

                //前回分のパターンを無視
                pattern = pattern.Where(x => !patternPrev.Where(y => y.SequenceEqual(x)).Any()).ToList();

                if (pattern.Count() <= 0) break;

                //追加する点用のリスト
                var listAdd = new List<Point>();

                foreach (var n in pattern)
                {


                    var p1 = list.ElementAt(n[0]);
                    var p2 = list.ElementAt(n[1]);
                    var p3 = list.ElementAt(n[2]);

                    //新しい点を作成
                    Point p4 = null;

                    if(p1.X == p2.X)
                    {
                        if(p1.Y == p3.Y)
                        {
                            p4 = new Point(p3.X, p2.Y);
                        }
                        else if(p2.Y == p3.Y)
                        {
                            p4 = new Point(p3.X, p1.Y);
                        }
                    }
                    else if(p1.X == p3.X)
                    {
                        if (p1.Y == p2.Y)
                        {
                            p4 = new Point(p2.X, p3.Y);
                        }
                        else if (p2.Y == p3.Y)
                        {
                            p4 = new Point(p2.X, p1.Y);
                        }
                    }
                    else if(p2.X == p3.X)
                    {
                        if (p2.Y == p1.Y)
                        {
                            p4 = new Point(p1.X, p3.Y);
                        }
                        else if (p3.Y == p1.Y)
                        {
                            p4 = new Point(p1.X, p2.Y);
                        }
                    }

                    if (p4 == null) continue;


                    //まだ追加していない点なら追加
                    if(!list.Contains(p4) && !listAdd.Contains(p4))
                    {
                        listAdd.Add(p4);
                    }
                }

                if (listAdd.Count <= 0) break;

                countMax += listAdd.Count;

                //次回のループの準備
                list.AddRange(listAdd);
                listAdd.Clear();
                patternPrev = pattern.ToList();
            }

            //答え表示
            Console.WriteLine(Convert.ToString(countMax));

        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace atcoder
{
    class Program
    {
        static List<bool> checkList;
        static List<List<int>> list;

        static void Main(string[] args)
        {
            var n = Int32.Parse(Console.ReadLine());
            list = new List<List<int>>();
            for (int i = 0; i < 200000; i++)
            {
                list.Add(new List<int>());
            }
            for (var i = 0; i < n; i++)
            {
                var s = Console.ReadLine();
                var l = s.Split(" ");
                var x = Int32.Parse(l[0]) - 1;
                var y = Int32.Parse(l[1]) + 100000 - 1;

                list[x].Add(y);
                list[y].Add(x);
            }

            checkList = new List<bool>(new bool[200000]);
            long sum = 0;

            for (var i = 0; i < 100000; i++)
            {
                var group = new List<int>();
                DFS(group, i);
                int xc = 0, yc = 0;
                foreach (var g in group)
                {
                    if (g < 100000)xc++;
                    else yc++;
                }
                if (xc + yc >= 4)
                {
                    sum += xc * yc - (xc + yc - 1);
                }
            }

            Console.WriteLine(sum);
        }

        static void DFS(List<int> group, int index)
        {
            if (!checkList[index])
            {
                checkList[index] = true;
                group.Add(index);
                foreach (var l in list[index])
                {
                    DFS(group, l);
                }
            }
        }
    }
}

