        {
            var N = NextInt;
            var xy = Repeat(0, N).Select(_ => new { x = NextInt, y = NextInt }).ToList();
            var xDic = new Dictionary<int, List<int>>();
            foreach (var item in xy)
            {
                if (!xDic.ContainsKey(item.x))
                {
                    xDic[item.x] = new List<int>();
                }
                xDic[item.x].Add(item.y);
            }
            var yDic = new Dictionary<int, List<int>>();
            foreach (var item in xy)
            {
                if (!yDic.ContainsKey(item.y))
                {
                    yDic[item.y] = new List<int>();
                }
                yDic[item.y].Add(item.x);
            }
            var ans = 0L;
            foreach (var item in xDic)
            {
                if (item.Value.Count > 1)
                {
                    var xCount = new Dictionary<int, int>();
                    foreach (var item2 in item.Value)
