                        var op = yDic[item2];
                        foreach (var item3 in op)
                        {
                            if (!xCount.ContainsKey(item3))
                            {
                                xCount[item3] = 0;
                            }
                            xCount[item3]++;
                        }
                    }
                    ans += xCount.Values.Sum(e => item.Value.Count - e);
                }
            }
            Console.WriteLine(ans);

        }

