using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		int N = int.Parse(Console.ReadLine());
		int[,]A = new int[N,2];
		var uf = new UnionFind(100001);
		var list = new List<int>[100001];
		for(var i=0;i<100001;i++){
			list[i] = new List<int>();
		}
		for(var i=0;i<N;i++){
			string[] str = Console.ReadLine().Split();
			A[i,0] = int.Parse(str[0]);
			A[i,1] = int.Parse(str[1]);
			list[A[i,0]-1].Add(A[i,1]-1);
		}
		var dic = new Dictionary<int,int>();
		for(var i=0;i<100001;i++){
			dic[i] = 1;
		}
		for(var i=0;i<100001;i++){
			if(list[i].Count >= 2){
				for(var j=1;j<list[i].Count;j++){
					if(!uf.IsSameGroup(list[i][0],list[i][j])){
						int a = dic[uf.Root(list[i][0])];
                      　int b = dic[uf.Root(list[i][j])];
						uf.Unite(list[i][0],list[i][j]);
						dic[uf.Root(list[i][0])] = a+b;
					}
				}
			}
		}
		long ans = 0;
		for(var i=0;i<100001;i++){
			if(list[i].Count >= 1){
				ans += dic[uf.Root(list[i][0])] - list[i].Count;
			}
		}
		Console.WriteLine(ans);
	}

	public class UnionFind
{
    private int[] data;
	public UnionFind(int size){
        data = new int[size];
        for (int i = 0; i < size; i++) data[i] = -1;
    }
    public bool Unite(int x, int y){
        x = Root(x);
        y = Root(y);
        if (x != y){
            if (data[y] < data[x]){
                var tmp = y;
                y = x;
                x = tmp;
            }
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }
	public bool IsSameGroup(int x, int y){
        return Root(x) == Root(y);
    }
    public int Root(int x){
        return data[x] < 0 ? x : data[x] = Root(data[x]);
    }
}

