using System;
using System.Collections.Generic;

public class Program
{
    public void Solve()
    {
        var sc = new Scanner();


        int N = sc.NextInt();
        HashSet<int> X, Y;
        X = new HashSet<int>();
        Y = new HashSet<int>();
        var uf = new UnionFind(200001);

        for (int i = 0; i < N; i++)
        {
            int x = sc.NextInt();
            int y = sc.NextInt();
            X.Add(x);
            Y.Add(y);
            uf.Union(x, y + 100000);
        }

        var mapX = new HashMap<int, int>();
        var mapY = new HashMap<int, int>();
        foreach (int i in X)
        {
            mapX[uf.Find(i)]++;
        }

        foreach (int i in Y)
        {
            mapY[uf.Find(i)]++;
        }

        long ans = 0;

        foreach (KeyValuePair<int, int> pair in mapX)
        {
            //Console.WriteLine($"{pair.Value} {mapY[pair.Key]}");
            ans += (long) pair.Value * mapY[pair.Key];
        }

        Console.WriteLine(ans - N);
    }

