class UnionFind
{
    private int[] Par, Rank;

    public UnionFind(int max)
    {
        Par = new int[max];
        Rank = new int[max];
        for (int i = 0; i < max; i++)
        {
            Par[i] = i;
        }
    }

    public int Find(int n)
    {
        if (Par[n] == n)
        {
            return n;
        }
        else
        {
            return Find(Par[n]);
        }
    }

    public bool Same(int a, int b)
    {
        return Find(a) == Find(b);
    }

    public void Union(int a, int b)
    {
        a = Find(a);
        b = Find(b);
        if (a == b) return;
        if (Rank[a] < Rank[b])
        {
            Par[a] = b;
        }
        else
        {
            Par[b] = a;
            if (Rank[a] == Rank[b]) Rank[a]++;
        }
    }
}

class Scanner
{
    public Scanner()
    {
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = Console.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = Console.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

using System;
using System.Collections.Generic;
using System.IO;

namespace Sandbox
{
    internal class Program
    {
        private static void Main(string[] args)
        {
            var scanner = new Scanner();
            var n = scanner.GetNextAsInt();

            var maxX = int.MinValue;
            var maxY = int.MinValue;
            var xy = new int[n, 2];

            for (var i = 0; i < n; i++)
            {
                var xi = scanner.GetNextAsInt();
                var yi = scanner.GetNextAsInt();
                maxX = Math.Max(maxX, xi);
                maxY = Math.Max(maxY, yi);
                xy[i, 0] = xi - 1;
                xy[i, 1] = yi - 1;
            }

            var countXy = maxX + maxY;
            var unionFind = new DisjointSet(countXy);

            for (var i = 0; i < n; i++)
            {
                unionFind.TryUnite(xy[i,0], xy[i, 1] + maxX);
            }

            var counterX = new int[countXy];
            var counterY = new int[countXy];

            for (var i = 0; i < maxX; i++)
            {
                var rootForX = unionFind.GetRoot(i);
                counterX[rootForX]++;
            }

            for (var i = maxX; i < countXy; i++)
            {
                var rootForY = unionFind.GetRoot(i);
                counterY[rootForY]++;
            }

            var result = 0L;

            for (var i = 0; i < countXy; i++)
            {
                result += (long)counterX[i] * (long)counterY[i];
            }

            Console.WriteLine(result - n);
        }

    #region Disjoint Set

    /// <summary>
    /// いくつかの要素を素集合に分割して保持するコレクションです．(Union Find)
    /// </summary>
    public class DisjointSet
    {
        // 正: Parent / 負: Size
        private readonly int[] _ParentOrSize;
        private readonly byte[] _Rank;
        private readonly HashSet<int> _Items = new HashSet<int>();

        /// <summary>
        /// 0 から <paramref name="n"/>-1 までの番号がついた <paramref name="n"/> 個の要素からなる集合を作成します．
        /// </summary>
        /// <param name="n">要素数</param>
        /// <remarks>このコンストラクタは O(N) で実行されます．</remarks>
        public DisjointSet(int n)
        {
            this._ParentOrSize = new int[n];
            this._Rank = new byte[n];
            this.Count = n;
            for (var i = 0; i < n; i++)
            {
                this._ParentOrSize[i] = -1;
            }
        }

        /// <summary>
        /// 指定した要素が属する集合の代表値を取得します．
        /// </summary>
        /// <param name="id">調べたい要素の 0-indexed での番号</param>
        /// <returns>指定した要素が属する集合の代表値</returns>
        /// <remarks>最悪計算量 O(α(N)) で実行されます．</remarks>
        public int GetRoot(int id)
        {
            if (this._ParentOrSize[id] < 0)
            {
                return id;
            }

            // 経路圧縮
            return this._ParentOrSize[id] = this.GetRoot(this._ParentOrSize[id]);
        }

        /// <summary>
        /// 指定した 2 つの要素が属する集合同士を 1 つに統合することを試みます．
        /// </summary>
        /// <param name="x">最初の要素の 0-indexed での番号</param>
        /// <param name="y">2 つ目の要素の 0-indexed での番号</param>
        /// <returns>統合に成功したならば true，そうでなければ false．</returns>
        /// <remarks>最悪計算量 O(α(N)) で実行されます．</remarks>
        public bool TryUnite(int x, int y)
        {
            this._Items.Add(x);
            this._Items.Add(y);

            x = this.GetRoot(x);
            y = this.GetRoot(y);
            if (x == y)
            {
                return false;
            }

            if (this._Rank[x] < this._Rank[y])
            {
                var tmp = x;
                x = y;
                y = tmp;
            }

            this._ParentOrSize[x] += this._ParentOrSize[y];
            this._ParentOrSize[y] = x;
            if (this._Rank[x] == this._Rank[y])
            {
                this._Rank[x]++;
            }

            this.Count--;
            return true;
        }

        public IReadOnlyCollection<int> GetItems() => this._Items;

        /// <summary>
        /// 指定した要素が属する集合のサイズを取得します．
        /// </summary>
        /// <param name="x">指定する要素の 0-indexed での番号</param>
        /// <returns>集合のサイズ</returns>
        /// <remarks>最悪計算量 O(α(N)) で実行されます．</remarks>
        public int Size(int x) => - this._ParentOrSize[this.GetRoot(x)];

        /// <summary>
        /// 指定した 2 つの要素が属する集合が同じかどうかを判定する．計算量 O(α(N))．
        /// </summary>
        /// <param name="x">最初の要素の 0-indexed での番号</param>
        /// <param name="y">2 つ目の要素の 0-indexed での番号</param>
        /// <returns>同じならば true，そうでなければ false．</returns>
        /// <remarks>最悪計算量 O(α(N)) で実行されます．</remarks>
        public bool IsSame(int x, int y) => this.GetRoot(x) == this.GetRoot(y);

        /// <summary>
        /// 集合の数を取得します。
        /// </summary>
        /// <returns></returns>
        public int Count { get; private set; }
    }

