namespace Program
{
    public static class ABC131F
    {
        class UF1
        {
            public Dictionary<long, long> _par = new Dictionary<long, long>();
            public Dictionary<long, long> _count = new Dictionary<long, long>();
            public long Root(long key)
            {
                if (_par[key] == key) return key;
                return _par[key] = Root(_par[key]);
            }
            public void Unite(long key1, long key2)
            {
                var k1 = _par.ContainsKey(key1);
                if (key1 == key2)
                {
                    if (!k1)
                    {
                        _par[key1] = key1;
                        _count[key1] = 1;
                    }
                    return;
                }
                var k2 = _par.ContainsKey(key2);
                if (!k1 && !k2)
                {
                    _par[key1] = key1;
                    _par[key2] = key1;
                    _count[key1] = 2;
                }
                else if (!k1 && k2)
                {
                    var rt = Root(key2);
                    _par[key1] = rt;
                    _count[rt]++;
                }
                else if (k1 && !k2)
                {
                    var rt = Root(key1);
                    _par[key2] = rt;
                    _count[rt]++;
                }
                else
                {
                    var r1 = Root(key1);
                    var r2 = Root(key2);
                    if (r1 == r2) return;
                    _count[r2] += _count[r1];
                    _par[r1] = r2;
                }
            }
        }
        class UF2
        {
            public int[] _par = new int[100001];
            public int[] _count = new int[100001];
            public UF2()
            {
                for (int i = 0; i < 100001; i++)
                {
                    _par[i] = i;
                    _count[i] = 1;
                }
            }
            public int Root(int key)
            {
                if (_par[key] == key) return key;
                return _par[key] = Root(_par[key]);
            }
            public void Unite(int key1, int key2)
            {
                var r1 = Root(key1);
                var r2 = Root(key2);
                if (r1 == r2) return;
                _count[r2] += _count[r1];
                _par[r1] = r2;
            }
        }
        static public void Solve()
        {
            var N = NextInt;
            var xy = Enumerable.Repeat(0, N).Select(_ => new { x = NextInt, y = NextInt }).ToList();
            var xDic = xy.GroupBy(e => e.x).ToDictionary(e => e.Key, e => e.Select(e2 => e2.y).ToList());
            var yDic = xy.GroupBy(e => e.y).ToDictionary(e => e.Key, e => e.Select(e2 => e2.x).ToList());
            var uf = new UF1();
            var xuf = new UF2();
            var yuf = new UF2();
            var done = Enumerable.Repeat(0, 100001).Select(_ => new HashSet<int>()).ToArray();
            foreach (var item in xDic)
            {
                if (item.Value.Count > 1)
                {
                    var masterKey = 0;
                    var masterY = 0;
                    foreach (var y in item.Value)
                    {
                        if (masterKey == 0)
                        {
                            masterKey = item.Key * 1000000 + y;
                            masterY = y;
                        }
                        foreach (var x in yDic[y])
                        {
                            if (done[x].Contains(y)) continue;
                            done[x].Add(y);
                            uf.Unite(masterKey, x * 1000000 + y);
                            xuf.Unite(item.Key, x);
                            yuf.Unite(masterY, y);
                        }
                    }
                }
            }
            var inputPointCount = 0L;
            var totalPointCount = 0L;
            foreach (var item in uf._par)
            {
                if (item.Key != item.Value) continue;
                if (uf._count[item.Key] > 2)
                {
                    inputPointCount += uf._count[item.Key];
                    totalPointCount += (long)xuf._count[xuf.Root((int)(item.Key / 1000000))] * (long)yuf._count[yuf.Root((int)(item.Key % 1000000))];
