    internal class Program
    {
        private static readonly int MaxNumber = 100001;

        private static readonly List<int>[] XtoY = Enumerable.Range(0, MaxNumber).Select(_ => new List<int>()).ToArray();
        private static readonly List<int>[] YtoX = Enumerable.Range(0, MaxNumber).Select(_ => new List<int>()).ToArray();
        private static readonly bool[] VisitedX = new bool[MaxNumber];
        private static readonly bool[] VisitedY = new bool[MaxNumber];

        private static void Main(string[] args)
        {
            var scanner = new Scanner();
            var n = scanner.GetNextAsInt();
            var maxX = int.MinValue;
            var maxY = int.MinValue;

            for (var i = 0; i < n; i++)
            {
                var xi = scanner.GetNextAsInt();
                var yi = scanner.GetNextAsInt();
                XtoY[xi].Add(yi);
                YtoX[yi].Add(xi);
                maxX = Math.Max(xi, maxX);
                maxY = Math.Max(xi, maxY);
            }

            var result = 0L;
            for (var xx = 1; xx <= maxX; xx++)
            {
                var countX = 0;
                var countY = 0;

                DfsX(xx, ref countX, ref countY);

                result += (long)countX * (long)countY;
            }

            result -= n;

            Console.WriteLine(result);
        }

        private static void DfsX(int x, ref int countX, ref int countY)
        {
            if (VisitedX[x])
            {
                return;
            }

            countX++;
            VisitedX[x] = true;
            foreach (var yy in XtoY[x])
            {
                DfsY(yy, ref countX, ref countY);
            }
        }

        private static void DfsY(int y, ref int countX, ref int countY)
        {
            if (VisitedY[y])
            {
                return;
            }

            countY++;
            VisitedY[y] = true;
            foreach (var xx in YtoX[y])
            {
                DfsX(xx, ref countX, ref countY);
            }
        }

