namespace AtCoder
{
    class Program
    {
        private int N;
        private int[] X, Y;
        static void Main(string[] args)
        {
            new Program().Solve();
        }

        public void Solve()
        {
            var sc = new Scanner();
            N = sc.NextInt();
            X = new int[N];
            Y = new int[N];

            for (int i = 0; i < N; i++)
            {
                X[i] = sc.NextInt();
                Y[i] = sc.NextInt();
            }
            var uf = new UnionFind(200001);
            for (int i = 0; i < N; i++)
            {
                uf.Union(X[i], Y[i] + 100000);
            }

            // Xの同じ連結成分の個数
            var xhs = new HashSet<int>();
            var yhs = new HashSet<int>();
            var xmap = new HashMap<int, int>();
            var ymap = new HashMap<int,int>();
            for (int i = 0; i < N; i++)
            {
                if(xhs.Add(X[i]))
                    xmap[uf.Find(X[i])]++;

                if(yhs.Add(Y[i]))
                    ymap[uf.Find(Y[i] + 100000)]++;
            }

            long sum = 0;

            foreach (var i in xmap)
            {
                sum += (long) i.Value * ymap[i.Key];
            }
            Console.WriteLine(sum-N);
        }
    }
}

