        var ys = new Dictionary<int, List<int>>();
        for (int i = 0; i < points.Length; i++)
        {
            var p = points[i];
            List<int> list;
            if (xs.TryGetValue(p.x, out list))
                list.Add(i);
            else
                xs[p.x] = new List<int> { i };

            if (ys.TryGetValue(p.y, out list))
                list.Add(i);
            else
                ys[p.y] = new List<int> { i };
        }

        var gyaku = new Dictionary<Point, int>(N);
        for (int i = 0; i < points.Length; i++)
            gyaku[points[i]] = i;
        var sumi = new bool[N];
        long cnt = 0;
        for (int i = 0; i < points.Length; i++)
        {
            if (sumi[i]) continue;
            sumi[i] = true;

            var queue = new Queue<int>();
            queue.Enqueue(i);
            var hashset = new HashSet<int> { };
            var xset = new HashSet<int> { };
            var yset = new HashSet<int>();
            while (queue.Count > 0)
            {
                var index = queue.Dequeue();
                if (!hashset.Add(index))
                    continue;

                var p = points[index];

                sumi[index] = true;
                hashset.Add(i);
                xset.Add(p.x);
                yset.Add(p.y);

                foreach (var x in xs[p.x])
                {
                    if (!hashset.Contains(x))
                        queue.Enqueue(x);
                }
                foreach (var y in ys[p.y])
                {
                    if (!hashset.Contains(y))
                        queue.Enqueue(y);
                }
            }

            long xc = xset.Count;
            long yc = yset.Count;
            cnt += xc * yc - hashset.Count;
        }

        return cnt;
    }
}
struct Point : IEquatable<Point>, IComparable<Point>
{
    public int x;
    public int y;
    public Point(int[] arr) : this(arr[0], arr[1]) { }
    public Point(int x, int y)
    {
        this.x = x;
        this.y = y;
    }

    public int Inner(Point other) => x * other.x + y * other.y;
    public int Cross(Point other) => x * other.y - y * other.x;
    public static Point operator +(Point a, Point b) => new Point(a.x + b.x, a.y + b.y);
    public static Point operator -(Point a, Point b) => new Point(a.x - b.x, a.y - b.y);

    public int CompareTo(Point other) => this.x.CompareTo(other.x);

    public bool Equals(Point other) => this.x == other.x && this.y == other.y;
    public override bool Equals(object obj)
    {
        if (obj is Point) return Equals((Point)obj);
        return false;
    }
    public override int GetHashCode() => ((x << 5) + x) ^ y;
    public override string ToString() => $"({x}, {y})";
}

