    //参照(http://drken1215.hatenablog.com/entry/2019/06/23/004700)
    class Program
    {
        class UnionFind
        {
            int[] par;
            public UnionFind(int n)
            {
                init(n);
            }
            public void init(int n)
            {
                par = new int[n];
                for (var i = 0; i < n; ++i)
                { par[i] = -1; }
            }
            public int root(int x)
            {
                if (par[x] < 0) return x;
                else return par[x] = root(par[x]);
            }
            public bool issame(int x, int y)
            {
                return root(x) == root(y);
            }
            public bool merge(int x, int y)
            {
                x = root(x); y = root(y);
                if (x == y) return false;
                if (par[x] > par[y])
                {
                    var tmp = y;
                    y = x;
                    x = tmp;
                }
                par[x] += par[y];
                par[y] = x;
                return true;
            }
            public int size(int x)
            {
                return -par[root(x)];
            }
        }
        const int MAX = 110000;
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static void Main(string[] args)
        {

            var N = Sarray()[0];
            UnionFind uf = new UnionFind(MAX * 2);
            var x = new List<int>();
            var y = new List<int>();
            for (var i = 0; i < N; ++i)
            {
                var xy = Sarray();
                x.Add((int)xy[0]);
                y.Add((int)xy[1]);
                uf.merge(x[i], y[i] + MAX);
            }
            var mx = new int[MAX * 2];
            var my = new int[MAX * 2];
            for (var i = 0; i < MAX; ++i) { mx[uf.root(i)]++; }
            for (var i = MAX; i < MAX * 2; ++i) { my[uf.root(i)]++; }
            int res = 0;
            for (var r = 0; r < MAX * 2; ++r) res += mx[r] * my[r];
            WriteLine(res - N);
        }
    }
}

