		var hx=new Dictionary<int,int>();
		var hy=new Dictionary<int,int>();
		int[] x=new int[n];
		int[] y=new int[n];
		bool[] b=new bool[n];
		Uf uf=new Uf(n);
		for(int i = 0;i<n;i++) {
			var e=sc.Ia;
			if(hx.ContainsKey(e[0])){uf.Union(i,hx[e[0]]);}
			else{hx.Add(e[0],i);}
			if(hy.ContainsKey(e[1])){uf.Union(i,hy[e[1]]);}
			else{hy.Add(e[1],i);}
		}
		foreach(var e in hx){x[uf.Root(e.Value)]++;}
		foreach(var e in hy){y[uf.Root(e.Value)]++;}
		long ans=0;
		for(int i = 0;i<n;i++) {
			if(b[uf.Root(i)]){continue;}
			b[uf.Root(i)]=true;
			ans+=(long)x[uf.Root(i)]*y[uf.Root(i)]-uf.Total(i);
