namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int Solve(int N, Tuple<int, int>[] points)
        {
            var xs = new Dictionary<int, List<int>>();
            var ys = new Dictionary<int, List<int>>();
            foreach (var p in points)
            {
                int x = p.Item1;
                int y = p.Item2;
                if (!xs.ContainsKey(y)) { xs[y] = new List<int>(); }
                if (!ys.ContainsKey(x)) { ys[x] = new List<int>(); }
                xs[y].Add(x);
                ys[x].Add(y);
            }
            var set = new HashSet<Tuple<int, int>>();
            var X = new HashSet<int>();
            var Y = new HashSet<int>();
            foreach (var p in points)
            {
                if (xs[p.Item2].Count >= 2 && ys[p.Item1].Count >= 2)
                {
                    foreach (int x in xs[p.Item2])
                    {
                        set.Add(new Tuple<int, int>(x, p.Item2));
                        X.Add(x);
                    }
                    foreach (int y in ys[p.Item1])
                    {
                        set.Add(new Tuple<int, int>(p.Item1, y));
                        Y.Add(y);
                    }
                }
            }
            return X.Count * Y.Count - set.Count;
        }

        static void Main(string[] args)
        {
            int N = ReadInt();
            var points = new Tuple<int, int>[N];
            for (int i = 0; i < N; ++i)
            {
                var V = ReadInts();
                points[i] = new Tuple<int, int>(V[0], V[1]);
            }
            Console.WriteLine(Solve(N, points));
        }
    }
}

