using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Text;

namespace AtCoder
{
	public class Program
	{
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();

			var toY = new HashMap<int, List<int>>(x => new List<int>());
			var toX = new HashMap<int, List<int>>(x => new List<int>());
			for (int i = 0; i < n; i++) {
				int x = cin.Int();
				int y = cin.Int();
				toY[x].Add(y);
				toX[y].Add(x);
			}

			long ans = 0;
			var done = new HashSet<int>();
			foreach (var x in toY.Keys) {
				if (done.Contains(x)) {
					continue;
				}

				var xx = new HashSet<int>();
				var yy = new HashSet<int>();
				var xq = new Queue<int>();
				var yq = new Queue<int>();
				xq.Enqueue(x);
				while (xq.Count > 0) {
					int xc = xq.Dequeue();
					xx.Add(xc);
					foreach (var ny in toY[xc]) {
						if (yy.Contains(ny) == false) {
							yq.Enqueue(ny);
						}
					}

					while(yq.Count > 0){
						int yc = yq.Dequeue();
						yy.Add(yc);
						foreach (var nx in toX[yc]) {
							if (xx.Contains(nx) == false) {
								xq.Enqueue(nx);
							}
						}
					}
				}

				int count = 0;
				foreach (var tx in xx) {
					done.Add(tx);
					count += toY[tx].Count;
				}

				if (xx.Count > 1 && yy.Count > 1) {
					ans += (long)xx.Count * yy.Count - count;
				}
			}

			Console.WriteLine(ans);
		}
	}

	public class HashMap<TKey, TValue> : Dictionary<TKey, TValue>
	{
		private readonly Func<TKey, TValue> initialzier_;
		public HashMap(Func<TKey, TValue> initialzier)
			: base()
		{
			initialzier_ = initialzier;
		}

		public HashMap(Func<TKey, TValue> initialzier, int capacity)
			: base(capacity)
		{
			initialzier_ = initialzier;
		}

		new public TValue this[TKey key]
		{
			get
			{
				if (ContainsKey(key) == false) {
					base[key] = initialzier_(key);
				}

				return base[key];
			}

			set { base[key] = value; }
		}
	}

	public static class Helper
	{
		public static void UpdateMin<T>(ref T target, T value) where T : IComparable<T>
			=> target = target.CompareTo(value) > 0 ? value : target;

		public static void UpdateMin<T>(ref T target, T value, Action<T> onUpdated) where T : IComparable<T>
		{
			if (target.CompareTo(value) > 0) {
				target = value;
				onUpdated(value);
			}
		}

		public static void UpdateMax<T>(ref T target, T value) where T : IComparable<T>
			=> target = target.CompareTo(value) < 0 ? value : target;
		public static void UpdateMax<T>(ref T target, T value, Action<T> onUpdated) where T : IComparable<T>
		{
			if (target.CompareTo(value) < 0) {
				target = value;
				onUpdated(value);
			}
		}

		public static T[] Array<T>(int n, Func<int, T> init)
			=> Enumerable.Range(0, n).Select(x => init(x)).ToArray();
		public static List<T> List<T>(int n, Func<int, T> init)
			=> Enumerable.Range(0, n).Select(x => init(x)).ToList();
		public static T[,] Array2<T>(int n, int m, T init)
		{
			var array = new T[n, m];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					array[i, j] = init;
				}
			}

			return array;
		}

		public static T[,] Array2<T>(int n, int m, Func<int, int, T> initializer)
		{
			var array = new T[n, m];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					array[i, j] = initializer(i, j);
				}
			}

			return array;
		}

		public static T[,,] Array3<T>(int n1, int n2, int n3, T init)
		{
			var array = new T[n1, n2, n3];
			for (int i1 = 0; i1 < n1; i1++) {
				for (int i2 = 0; i2 < n2; i2++) {
					for (int i3 = 0; i3 < n3; i3++) {
						array[i1, i2, i3] = init;
					}
				}
			}

			return array;
		}

		private static readonly int[] delta4_ = { 1, 0, -1, 0, 1 };
		public static void DoAt4(int i, int j, int imax, int jmax, Action<int, int> action)
		{
			for (int n = 0; n < 4; n++) {
				int ii = i + delta4_[n];
				int jj = j + delta4_[n + 1];
				if ((uint)ii < (uint)imax && (uint)jj < (uint)jmax) {
					action(ii, jj);
				}
			}
		}
	}

	public class Scanner
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private readonly Func<string> reader_;
		private string[] buf_;
		private int index_;

		public Scanner(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace atcoder
{
    class Program
    {
        static List<bool> checkList;
        static List<List<int>> list;

        static void Main(string[] args)
        {
            var n = Int32.Parse(Console.ReadLine());
            list = new List<List<int>>();
            for (int i = 0; i < 200000; i++)
            {
                list.Add(new List<int>());
            }
            for (var i = 0; i < n; i++)
            {
                var s = Console.ReadLine();
                var l = s.Split(" ");
                var x = Int32.Parse(l[0]) - 1;
                var y = Int32.Parse(l[1]) + 100000 - 1;

                list[x].Add(y);
                list[y].Add(x);
            }

            checkList = new List<bool>(new bool[200000]);
            checkList = checkList.Select(c => c=false).ToList();
            long sum = 0;

            for (var i = 0; i < 200000; i++)
            {
                var group = new List<int>();
                DFS(group, i);
                int xc = 0, yc = 0, branches = 0;
                foreach (var g in group)
                {
                    if (g < 100000){
                        xc++;
                        branches += list[g].Count;
                        }
                    else yc++;
                }
                if (xc + yc >= 4)
                {
                    sum += xc * yc - branches;
                }
            }

            Console.WriteLine(sum);
        }

        static void DFS(List<int> group, int index)
        {
            if (!checkList[index])
            {
                checkList[index] = true;
                group.Add(index);
                foreach (var l in list[index])
                {
                    DFS(group, l);
                }
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.CompilerServices;
using static System.Math;
using System.Text;

namespace Program
{
    public static class ABC131F
    {
        class UF
        {
            private Dictionary<long, long> _par = new Dictionary<long, long>();
            private Dictionary<long, long> _count = new Dictionary<long, long>();
            private Dictionary<long, List<long>> _keyList = new Dictionary<long, List<long>>();
            public long Root(long key)
            {
                if (!_par.ContainsKey(key)) Unite(key, key);
                if (_par[key] == key) return key;
                return _par[key] = Root(_par[key]);
            }
            public bool IsRoot(long key)
            {
                if (!_par.ContainsKey(key)) return false;
                return _par[key] == key;
            }
            public List<long> List(long key)
            {
                return _keyList[Root(key)];
            }
            public long Count(long key)
            {
                return _count[Root(key)];
            }
            public void Unite(long key1, long key2)
            {
                var k1 = _par.ContainsKey(key1);
                if (key1 == key2)
                {
                    if (!k1)
                    {
                        _par[key1] = key1;
                        _count[key1] = 1;
                        _keyList[key1] = new List<long>();
                        _keyList[key1].Add(key1);
                    }
                    return;
                }
                var k2 = _par.ContainsKey(key2);
                if (!k1 && !k2)
                {
                    _par[key1] = key1;
                    _par[key2] = key1;
                    _count[key1] = 2;
                    _keyList[key1] = new List<long>();
                    _keyList[key1].Add(key1);
                    _keyList[key1].Add(key2);
                }
                else if (!k1 && k2)
                {
                    _par[key1] = Root(key2);
                    _count[_par[key1]]++;
                    _keyList[_par[key1]].Add(key1);
                }
                else if (k1 && !k2)
                {
                    _par[key2] = Root(key1);
                    _count[_par[key2]]++;
                    _keyList[_par[key2]].Add(key2);
                }
                else
                {
                    var r1 = Root(key1);
                    var r2 = Root(key2);
                    if (r1 == r2) return;
                    _count[r2] += _count[r1];
                    _par[r1] = r2;
                    _keyList[r2].AddRange(_keyList[r1]);
                }
            }
        }
        static public void Solve()
        {
            var N = NextInt;
            var xy = Enumerable.Repeat(0, N).Select(_ => new { x = NextLong, y = NextLong }).ToList();
            var xDic = xy.GroupBy(e => e.x).ToDictionary(e => e.Key, e => e.Select(e2 => e2.y).ToList());
            var yDic = xy.GroupBy(e => e.y).ToDictionary(e => e.Key, e => e.Select(e2 => e2.x).ToList());
            var uf = new UF();
            foreach (var item in xDic)
            {
                if (item.Value.Count > 1)
                {
                    var keymaster = 0L;
                    foreach (var y in item.Value)
                    {
                        if (keymaster == 0L)
                        {
                            keymaster = item.Key * 10000000 + y;
                        }
                        foreach (var x in yDic[y])
                        {
                            var key = x * 10000000 + y;
                            uf.Unite(keymaster, key);
                        }
                    }
                }
            }
            var inputPointCount = 0L;
            var totalPointCount = 0L;
            foreach (var item in xy)
            {
                var key = item.x * 10000000 + item.y;
                if (uf.IsRoot(key))
                {
                    if (uf.Count(key) > 2)
                    {
                        var xList = new List<long>();
                        var yList = new List<long>();
                        foreach (var item2 in uf.List(key))
                        {
                            xList.Add(item2 / 10000000);
                            yList.Add(item2 % 10000000);
                        }
                        inputPointCount += uf.Count(key);
                        totalPointCount += xList.Distinct().LongCount() * yList.Distinct().LongCount();
                    }
                }
            }
            Console.WriteLine(totalPointCount - inputPointCount);
        }

        static public void Main(string[] args)
        {
            if (args.Length == 0)
            {
                var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
                Console.SetOut(sw);
            }
            Solve();
            Console.Out.Flush();
        }
        static class Console_
        {
            private static Queue<string> param = new Queue<string>();
            public static string NextString()
