class Program
{
static long n = 200000;
static long q = long.Parse(Console.ReadLine());
static long[] parents = new long[n];//親
static long[] edgeCounts = new long[n];
static List<long>[] parentList = new List<long>[n];

	static void Main()
	{
    long answer = 0;

    for(int i = 0; i < (int)n; i++) parentList[i] = new List<long>();//リストの宣言
    for(long i = 1; i < n; i++)
    {
      parents[i] = i;
    }

    for(long i = 0; i < q; i++)
    {
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      edgeCounts[nums[0]-1]++;
      if(whatParent(nums[0]-1) != whatParent(nums[1]-1+100000))
        parents[whatParent(nums[0]-1)] = whatParent(nums[1]-1+100000);//親を結合して統一。親が2人できることはない。
    }

    for(int i = 0; i < n; i++) parentList[whatParent(i)].Add(i);

    for(int i = 0; i < n; i++)
    {
      int x = 0;
      int y = 0;
      long ll = 0;
      for(int j = 0; j < parentList[i].Count(); j++)
      {
        if(parentList[i][j] < 100000) x++;
        else y++;

        ll += edgeCounts[parentList[i][j]];
      }
      answer += x*y-ll;
    }
    Console.WriteLine(answer);
	}

  static long whatParent(long child)
  {
    if(parents[child] == child) return child;
    else return parents[child] = whatParent(parents[child]);
  }

}

