class Solver
{
    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        var uf = new UnionFind(201010);
        const int M = 100000;
        for (int i = 0; i < N; i++)
        {
            int x, y;
            sc.Make(out x, out y);x--;y--;
            uf.Union(x, y + M);
        }
        var res = 0L;
        var use = new bool[101010];
        for (int i = 0; i < M; i++)
        {
            if (use[uf[i]]) continue;
            use[uf[i]] = true;
            if (uf.Size(i) < 4) continue;
            res += uf.Size(i) / 2 * ((uf.Size(i) + 1) / 2) - uf.Edge(i);
        }
        WriteLine(res);
    }
}

