	}
	for i := 0; i < 100000; i++ {
		xcount[i] = 1
	}
	for i := 100000; i < 200000; i++ {
		ycount[i] = 1
	}

	root := func(i int) int {
		for par[i] != i {
			i = par[i]
		}
		return i
	}

	union := func(x int, y int) {
		xroot := root(x)
		yroot := root(y)
		if xroot == yroot {
			return
		}

		par[xroot] = yroot
		xcount[yroot] += xcount[xroot]
		ycount[yroot] += ycount[xroot]
	}

