	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	xx := make([]int, n)
	yy := make([]int, n)
	cx := make([]int, int(1e5))
	cy := make([]int, int(1e5))
	ux := make([]int, int(1e5))
	uy := make([]int, int(1e5))

	for i := 0; i < n; i++ {
		xx[i] = getNextInt(scanner) - 1
		yy[i] = getNextInt(scanner) - 1
		cx[xx[i]]++
		cy[yy[i]]++
	}

	var exists, sx, sy int64
	for i := 0; i < n; i++ {
		if cx[xx[i]] > 1 && cy[yy[i]] > 1 {
			ux[xx[i]] = 1
			uy[yy[i]] = 1
		}
	}
	for i := 0; i < n; i++ {
		if ux[xx[i]] > 0 || uy[yy[i]] > 0 {
			exists++
			ux[xx[i]] = 1
			uy[yy[i]] = 1
		}
	}

	for i := 0; i < int(1e+5); i++ {
		sx += int64(ux[i])
		sy += int64(uy[i])
	}

	fmt.Fprintln(writer, sx*sy-exists)

	writer.Flush()
}

