func main() {
  input := Input{bufio.NewReaderSize(os.Stdin,100)}
  n := input.NextInt()
  p := Points{}
  m := make(map[Point]struct{})
  for i:=0;i<n;i++ {
    x,y := input.NextInts()
    p = append(p,Point{x,y})
    m[p[i]] = struct{}{}
  }
  for {
    x := len(m)
    for i:=0;i<x-1;i++ {
      for j:=i+1;j<x;j++ {
        if p[j].x == p[i].x && p[j].y == p[i].y { continue }
        _,ok1 := m[Point{p[j].x,p[i].y}]
        _,ok2 := m[Point{p[i].x,p[j].y}]
        if ok1 == ok2 { continue }
        if ok1 {
          m[Point{p[i].x,p[j].y}] = struct{}{}
          p = append(p,Point{p[i].x,p[j].y})
        } else {
          m[Point{p[j].x,p[i].y}] = struct{}{}
          p = append(p,Point{p[j].x,p[i].y})
        }
      }
    }
    if len(m) == x { break }
  }
  fmt.Println(len(m)-n)
}

