type Coodinate struct {
  x int
  y int
  index int
}
type Coodinates []Coodinate
func (C Coodinates) Len() int { return len(C) }
func (C Coodinates) Less(i, j int) bool { return C[i].x < C[j].x }
func (C Coodinates) Swap (i, j int) { C[i], C[j] = C[j], C[i] }
type xAxis struct {
  Coodinates
}
func (A xAxis) Less(i, j int) bool { return A.Coodinates[i].x < A.Coodinates[j].x }
type yAxis struct {
  Coodinates
}
func (A yAxis) Less(i, j int) bool { return A.Coodinates[i].y < A.Coodinates[j].y }

func Find(R *[]int, i int) int {
  if (*R)[i] == i { return i }
  (*R)[i] = Find(R, (*R)[i])
  return (*R)[i]
}
func Union(R *[]int, i, j int) {
  Ri := Find(R, i)
  Rj := Find(R, j)
  if Ri < Rj {
    (*R)[Rj] = Ri
  } else {
    (*R)[Ri] = Rj
  }
}

func main() {
  N := NextInt()
  R := make([]int, N)
  A := make([]Coodinate, N)
  for i := range A {
    XY := NextIntVec()
    R[i] = i
    A[i] = Coodinate{XY[0], XY[1], i}
  }
  sort.Sort(xAxis{A})
  for i := 1; i < N; i++ {
    if A[i - 1].x == A[i].x {
      Union(&R, A[i - 1].index, A[i].index)
    }
  }
  sort.Sort(yAxis{A})
  for i := 1; i < N; i++ {
    if A[i - 1].y == A[i].y {
      Union(&R, A[i - 1].index, A[i].index)
    }
  }
  Lattice := make([][]Coodinate, N)
  for i := range Lattice {
    Lattice[i] = make([]Coodinate, 0)
  }
  for _, a := range A {
    r := Find(&R, a.index)
    Lattice[r] = append(Lattice[r], a)
  }
  cnt := 0
  for _, L := range Lattice {
    x := 0
    y := 0
    sort.Sort(xAxis{L})
    current := 0
    for _, l := range L {
      if current < l.x {
        x++
        current = l.x
      }
    }
    sort.Sort(yAxis{L})
    current = 0
    for _, l := range L {
      if current < l.y {
        y++
        current = l.y
      }
    }
    if x > 1 && y > 1 {
      cnt += x * y - len(L)
    }
  }
  Write(cnt)
  Output()
}

