	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	tree := make([]int, n)
	colors := make([]int, n)
	pp := make(Points, n)
	cx := make([]int, int(1e5))
	cy := make([]int, int(1e5))
	ux := make([]int, int(1e5))
	uy := make([]int, int(1e5))

	for i := 0; i < n; i++ {
		tree[i] = i
		pp[i].x = getNextInt(scanner) - 1
		pp[i].y = getNextInt(scanner) - 1
		pp[i].i = i
		pp[i].sk = pp[i].x
		cx[pp[i].x]++
		cy[pp[i].y]++
	}

	sort.Sort(pp)

	for i := 1; i < n; i++ {
		if pp[i].sk == pp[i-1].sk {
			tree[root(pp[i].i, tree)] = root(pp[i-1].i, tree)
		}
	}
	for i := 0; i < n; i++ {
		pp[i].sk = pp[i].y
	}
	sort.Sort(pp)

	for i := 1; i < n; i++ {
		if pp[i].sk == pp[i-1].sk {
			tree[root(pp[i].i, tree)] = root(pp[i-1].i, tree)
		}
	}
	for i := 0; i < n; i++ {
		pp[i].sk = pp[i].i
	}
	sort.Sort(pp)

	var exists int64
	color := 0
	for i := 0; i < n; i++ {
		if cx[pp[i].x] > 1 && cy[pp[i].y] > 1 {
			r := root(pp[i].i, tree)

			if colors[r] == 0 {
				color++
				colors[r] = color
			}
		}
	}
	for i := 0; i < n; i++ {
		r := root(pp[i].i, tree)
		ux[pp[i].x] = colors[r]
		uy[pp[i].y] = colors[r]
		if colors[r] > 0 {
			exists++
		}
	}

	imx := IntMap{}
	imy := IntMap{}

	for i := 0; i < int(1e+5); i++ {
		if ux[i] > 0 {
			imx.increment(ux[i])
		}
		if uy[i] > 0 {
			imy.increment(uy[i])
		}
	}

	var sum int64
	for k, c := range imx {
		sum += int64(c) * int64(imy.get(k))
	}

	fmt.Fprintln(writer, sum-exists)

	writer.Flush()
