type Point struct {
	i, x, y, sk int
}

type Points []Point

func (a Points) Len() int           { return len(a) }
func (a Points) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a Points) Less(i, j int) bool { return a[i].sk < a[j].sk }

func root(i int, tree []int) int {
	if i == tree[i] {
		return i
	}
	tree[i] = root(tree[i], tree)
	return tree[i]
}

