module UnionFind =
  struct
    type unionfind = { size : int array; parent : int array };;
    let make n = {size = Array.make n 1; parent = Array.init n (fun i -> i)};;
    let rec find uf x = (
        if uf.parent.(x) = x then
          x
        else (
          let y = find uf (uf.parent.(x)) in
          uf.parent.(x) <- y;
          y
        )
      );;
    let unite uf x y = (
        let x = find uf x in
        let y = find uf y in
        if x <> y then (
          let x, y = if uf.size.(x) > uf.size.(y) then x, y else y, x in
          uf.size.(x) <- uf.size.(x) + uf.size.(y);
          uf.parent.(y) <- x;
        );
      )
  end;;

