module Union_find : sig
  type t
  val make : int -> t
  val find : int -> t -> int
  val size : int -> t -> int
  val same : int -> int -> t -> bool
  val unite : int -> int -> t -> unit
end = struct
  type t = int array
  let make n = Array.make n (-1)
  let rec find x uf =
    if uf.(x) < 0 then x
    else (( let x' = find uf.(x) uf in uf.(x) <- x'; x' ))
  let same x y uf = find x uf = find y uf
  let size x uf = - uf.(find x uf)
  let unite x y uf =
    let x = find x uf and y = find y uf in
    if x <> y then
      if uf.(x) < uf.(y) then ((
        uf.(x) <- uf.(x) + uf.(y);
        uf.(y) <- x
      )) else ((
        uf.(y) <- uf.(x) + uf.(y);
        uf.(x) <- y
      ))
end
module UF = Union_find

