my ($n) = map { $_ - 0 } split(/\s+/,<STDIN>);
my @xy = ();
my %xx = ();
my %yy = ();
for(my $i=0;$i<$n;$i++){
  my @a = split(/\s+/,<STDIN>);
  push(@xy,\@a);
  $xx{$a[0]}++;
  $yy{$a[1]}++;
}

my %xx2 = ();
my %yy2 = ();
for(my $i=0;$i<$n;$i++){
  if( ( $xx{$xy[$i]->[0]} >= 2 or $yy{$xy[$i]->[1]} >= 2 ) and $xx{$xy[$i]->[0]} >= 1 and $yy{$xy[$i]->[1]} >= 1 ){
    $xx2{$xy[$i]->[0]} ++;
    $yy2{$xy[$i]->[1]} ++;
  }
}

$cnt = 0;
for(my $i=0;$i<$n;$i++){
  if( $xx2{$xy[$i]->[0]} > 0 and $yy2{$xy[$i]->[1]} > 0 ){
    $cnt ++;
  }
}

my @kx2 = keys %xx2;
my @ky2 = keys %yy2;

my $res = (1 + $#kx2) * (1 + $#ky2) - $cnt;
print "$res\n";

exit(0);

