		if(nd.group.id != nd.id) continue;
		long xc, yc;
		foreach(k; nd.group.nodes){
			if(k.value == 1) xc += 1; else yc += 1;
		}
		ans += xc * yc;
	}

	ans -= n;

	ans.writeln;

}
