auto solve( long[ 3 ][] xyis )
{
	// X座標orY座標が同じ頂点を同じ集合にまとめる
	auto uft = UnionFindTree( xyis.length );
	long[ 3 ] p = [ -1L, -1L, -1L ];
	foreach( xyi; xyis.sort() )
	{
		if( p[ 0 ] == xyi[ 0 ] ) uft.unite( p[ 2 ], xyi[ 2 ] );
		else                     p = xyi;
	}
	foreach( xyi; xyis.sort!( ( p, xyi ) => p[ 1 ] < xyi[ 1 ] ) )
	{
		if( p[ 1 ] == xyi[ 1 ] ) uft.unite( p[ 2 ], xyi[ 2 ] );
		else                     p = xyi;
	}

	// 各集合ごとにx座標とy座標の種類数を集計
	bool[ long ][ long ] xys;
	bool[ long ][ long ] rxs;
	bool[ long ][ long ] rys;
	foreach( xyi; xyis )
	{
		auto r = uft.root( xyi[ 2 ] );
		xys[ xyi[ 0 ] ][ xyi[ 1 ] ] = true;
		rxs[ r ][ xyi[ 0 ] ] = true;
		rys[ r ][ xyi[ 1 ] ] = true;
	}

	// 各集合ごとに追加できる頂点の数を計算
	auto ans = 0L;
	foreach( r; rxs.keys )
	{
		foreach( x; rxs[ r ].keys )
		{
			foreach( y; rys[ r ].keys )
			{
				if( x !in xys || y !in xys[ x ] ) ans++;
			}
		}
	}
	return ans;
}

// UnionFind木
struct UnionFindTree
{
	private long[] ps;
	private long[] rs;

	public this( long n )
	{
		ps.length = n;
		ps[] = -1;
		rs.length = n;
	}

	public long root( long i )
	{
		if( ps[ i ] < 0 ) return i;
		else              return ps[ i ] = root( ps[ i ] );
	}

	public bool same( long i, long j )
	{
		return root( i ) == root( j );
	}

	public void unite( long i, long j )
	{
		i = root( i );
		j = root( j );
		if( i == j ) return;
		if( rs[ i ] < rs[ j ] )
		{
			ps[ j ] += ps[ i ];
			ps[ i ] = j;
		}
		else
		{
			ps[ i ] += ps[ j ];
			ps[ j ] = i;
			if( rs[ i ] == rs[ j ] ) rs[ i ]++;
		}
	}
}

import std.stdio, std.algorithm, std.conv, std.array, std.string, std.math, std.typecons, std.numeric, std.container, std.range;

struct UFTree(T)
{
    struct Node
    {
        T parent;
        T rank = 1;
    }

    ///
    T min_size, max_size;

    ///
    this(T n)
    {
        nodes.length = n;
        sizes.length = n;
        foreach (i, ref node; nodes) {
            node = Node(i.to!T);
            sizes[i] = 1;
        }

        min_sizes.length = n + 1;
        min_sizes[1] = n;
        min_size = 1;
        max_size = 1;
    }

    ///
    bool unite(T a, T b)
    {
        a = root(a);
        b = root(b);

        if (a == b) return false;

        auto a_size = sizes[a];
        auto b_size = sizes[b];
        --min_sizes[a_size];
        --min_sizes[b_size];
        ++min_sizes[a_size + b_size];
        foreach (nxt_size; min(a_size, b_size)..min_sizes.length) if (min_sizes[nxt_size] != 0) {
            min_size = nxt_size.to!T;
            break;
        }
        max_size = max(max_size, a_size + b_size);

        if (nodes[a].rank < nodes[b].rank) {
            sizes[a] += sizes[b];
            nodes[b].parent = a;
        } else {
            sizes[b] += sizes[a];
            nodes[a].parent = b;
            if (nodes[a].rank == nodes[b].rank) ++nodes[b].rank;
        }

        return true;
    }

    ///
    bool is_same(T a, T b)
    {
        return root(a) == root(b);
    }

    ///
    T size(T i)
    {
        return sizes[root(i)];
    }

    T root(T i)
    {
        if (nodes[i].parent == i) return i;

        return nodes[i].parent = root(nodes[i].parent);
    }

private:
    Node[] nodes;
    T[] sizes;
    T[] min_sizes;
}

///
UFTree!T uftree(T)(T n)
{
    return UFTree!T(n);
}

