    P[] ps;
    foreach (i; 0..N) {
        auto xy = readln.split.to!(int[]);
        ps ~= P(i, xy[0], xy[1]);
    }
    auto uft = uftree(N);
    sort!"a.x < b.x"(ps);
    foreach (i; 1..N) if (ps[i-1].x == ps[i].x) uft.unite(ps[i-1].i, ps[i].i);
    sort!"a.y < b.y"(ps);
    foreach (i; 1..N) if (ps[i-1].y == ps[i].y) uft.unite(ps[i-1].i, ps[i].i);
    auto xs = new long[][N];
    auto ys = new long[][N];
    foreach (i; 0..N) {
        auto r = uft.root(i);
        xs[r] ~= ps[i].x;
        ys[r] ~= ps[i].y;
    }

    long res;
    foreach (i; 0..N) if (!xs[i].empty) {
        sort(xs[i]);
        auto xx = xs[i].uniq.array;
        sort(ys[i]);
        auto yy = ys[i].uniq.array;
        if (xx.length <= 1 || yy.length <= 1) continue;
        res += xx.length * yy.length - uft.size(i);
    }
    writeln(res);
}

