	}
	return tuple( xys );
}

auto solve( long[ 2 ][] xys )
{
	const XM = 10 ^^ 5;
	const YM = 10 ^^ 5 * 2;

	// X座標とY座標で二部グラフを作る
	auto uft = UnionFindTree( YM + 1 );
	foreach( xy; xys )
	{
		uft.unite( xy[ 0 ], XM + xy[ 1 ] );		// X座標とかぶらないようにY座標は下駄を履かせる
	}

	// 連結成分ごとにX座標とY座標の種類数を数える
	long[ long ] rxs;
	long[ long ] rys;
	for( auto i = 1L; i <= XM; i++ )
	{
		if( uft.weight( i ) <= 1 ) continue;		// このX座標には頂点が無い
		rxs[ uft.root( i ) ]++;
	}
	for( auto i = XM + 1; i <= YM; i++ )
	{
		if( uft.weight( i ) <= 1 ) continue;		// このY座標には頂点が無い
		rys[ uft.root( i ) ]++;
	}

	// 連結成分ごとに完全グラフにしたときの頂点の数を計算
	auto ans = 0L;
	for( auto i = 1L; i <= YM; i++ )
	{
		if( i !in rxs || i !in rys ) continue;
		ans += rxs[ i ] * rys[ i ];
	}

	// 完全グラフの頂点数から元の頂点数を抜くと追加する頂点数になる
	return ans - xys.length;
}

// UnionFind木
struct UnionFindTree
{
	private long[] ps;
	private long[] rs;

	public this( long n )
	{
		ps.length = n;
		ps[] = -1;
		rs.length = n;
	}

	public long root( long i )
	{
		if( ps[ i ] < 0 ) return i;
		else              return ps[ i ] = root( ps[ i ] );
	}

	public bool same( long i, long j )
	{
		return root( i ) == root( j );
	}

	public void unite( long i, long j )
	{
		i = root( i );
		j = root( j );
		if( i == j ) return;
		if( rs[ i ] < rs[ j ] )
		{
			ps[ j ] += ps[ i ];
			ps[ i ] = j;
		}
		else
		{
			ps[ i ] += ps[ j ];
			ps[ j ] = i;
			if( rs[ i ] == rs[ j ] ) rs[ i ]++;
		}
	}

	public long weight( long i )
	{
		return -ps[ root( i ) ];
	}
}

import std.stdio, std.algorithm, std.conv, std.array, std.string, std.math, std.typecons, std.numeric, std.container, std.range;

struct UFTree(T)
{
    struct Node
    {
        T parent;
        T rank = 1;
    }

    ///
    T min_size, max_size;

    ///
    this(T n)
    {
        nodes.length = n;
        sizes.length = n;
        foreach (i, ref node; nodes) {
            node = Node(i.to!T);
            sizes[i] = 1;
        }

        min_sizes.length = n + 1;
        min_sizes[1] = n;
        min_size = 1;
        max_size = 1;
    }

    ///
    bool unite(T a, T b)
    {
        a = root(a);
        b = root(b);

        if (a == b) return false;

        auto a_size = sizes[a];
        auto b_size = sizes[b];
        --min_sizes[a_size];
        --min_sizes[b_size];
        ++min_sizes[a_size + b_size];
        foreach (nxt_size; min(a_size, b_size)..min_sizes.length) if (min_sizes[nxt_size] != 0) {
            min_size = nxt_size.to!T;
            break;
        }
        max_size = max(max_size, a_size + b_size);

        if (nodes[a].rank < nodes[b].rank) {
            sizes[a] += sizes[b];
            nodes[b].parent = a;
        } else {
            sizes[b] += sizes[a];
            nodes[a].parent = b;
            if (nodes[a].rank == nodes[b].rank) ++nodes[b].rank;
        }

        return true;
    }

    ///
    bool is_same(T a, T b)
    {
        return root(a) == root(b);
    }

    ///
    T size(T i)
    {
        return sizes[root(i)];
    }

    T root(T i)
    {
        if (nodes[i].parent == i) return i;

        return nodes[i].parent = root(nodes[i].parent);
    }

private:
    Node[] nodes;
    T[] sizes;
    T[] min_sizes;
}

///
UFTree!T uftree(T)(T n)
{
    return UFTree!T(n);
}

alias P = Tuple!(int, "i", int, "x", int, "y");

void main()
{
    auto N = readln.chomp.to!int;
    P[] ps;
    foreach (i; 0..N) {
        auto xy = readln.split.to!(int[]);
        ps ~= P(i, xy[0], xy[1]);
    }
    auto uft = uftree(N);
    sort!"a.x < b.x"(ps);
    foreach (i; 1..N) if (ps[i-1].x == ps[i].x) uft.unite(ps[i-1].i, ps[i].i);
    sort!"a.y < b.y"(ps);
    foreach (i; 1..N) if (ps[i-1].y == ps[i].y) uft.unite(ps[i-1].i, ps[i].i);
    auto xs = new long[][N];
    auto ys = new long[][N];
    foreach (i; 0..N) {
        auto r = uft.root(i);
        xs[r] ~= ps[i].x;
        ys[r] ~= ps[i].y;
    }

    long res;
    foreach (i; 0..N) if (!xs[i].empty) {
        sort(xs[i]);
        sort(ys[i]);
        res += xs[i].uniq.array.length * ys[i].uniq.array.length - uft.size(i);
    }
    writeln(res);
}

