void main() {
    int N;
    scan(N);
    auto x = new int[](N);
    auto y = new int[](N);
    iota(N).each!(i => scan(x[i], y[i]));
    x[] -= 1;
    y[] -= 1;

    int L = 10^^5;
    auto adj = new int[][](2 * L, 0);
    foreach (i ; 0 .. N) {
        adj[x[i]] ~= y[i] + L;
        adj[y[i] + L] ~= x[i];
    }

    auto visited = new bool[](2 * L);

    long ans;
    long cx, cy;

    void dfs(int v) {
        visited[v] = true;
        (v >= L ? cy : cx)++;

        foreach (u ; adj[v]) {
            if (!visited[u]) dfs(u);
        }
    }

    foreach (i ; 0 .. 2 * L) {
        cx = cy = 0;
        if (!visited[i]) {
            dfs(i);
        }
        ans += cx * cy;
    }

    ans -= N;
    writeln(ans);
}








