type BipartileGraph = ref object
  n: int
  is_directed: bool
  nodes1: Table[int,seq[(int, int)]]
  nodes2: Table[int,seq[(int, int)]]

proc newBipartileGraph(n: int, is_directed: bool): BipartileGraph =
  let nodes = initTable[int, seq[(int, int)]]()
  return BipartileGraph(n: n+1, is_directed: is_directed, nodes1: nodes, nodes2: nodes)

proc add_edge(g: BipartileGraph, x: int, y: int, w: int) =
  if not g.nodes1.contains(x):
    g.nodes1[x] = newSeq[(int, int)]()
  g.nodes1[x].add((y, w))
  if not g.is_directed:
    if not g.nodes2.contains(y):
      g.nodes2[y] = newSeq[(int, int)]()
    g.nodes2[y].add((x, w))

