def qfind(q,p,s,e):
	l=int((s+e)/2)

	if q[l]==p:
		if(l<=s or q[l-1]!=p):
			return l
		else:
			return qfind(q,p,s,l-1)
	elif q[l]>p:
		if l<=s:
			return -1
		else:
			return qfind(q,p,s,l-1)
	else:
		if l>=e:
			return -1
		else:
			return qfind(q,p,l+1,e)

