        b, d = sety[bi], sety[di]
        # print(a, c, b, d)
        flag = [False]*4
        f_ = bisect_left(xy, (a, b))
        buf = None
        if f_ < len(xy) and xy[f_] == (a, b):
            flag[0] = True
        else:
            buf = (a, b)

        f_ = bisect_left(xy, (a, d))
        if f_ < len(xy) and xy[f_] == (a, d):
            flag[1] = True
        else:
            buf = (a, d)

        f_ = bisect_left(xy, (c, b))
        if f_ < len(xy) and xy[f_] == (c, b):
            flag[2] = True
        else:
            buf = (c, b)

        f_ = bisect_left(xy, (c, d))
        if f_ < len(xy) and xy[f_] == (c, d):
            flag[3] = True
        else:
            buf = (c, d)

        if sum(flag) == 3:
            s += 1
            insort_left(xy, buf)
