class UnionFind():
  def __init__(self):
    self.group = []

  def merge(self,i,j):
    ## i <- j
    self.group[i][0] |= self.group[j][0]
    self.group[i][1] |= self.group[j][1]
    self.group[i][2] += self.group[j][2]
    self.group.pop(j)

  def new(self,x,y):
    merge_i = -1
    l,r = [0,len(self.group)]
    while l < r:
      if x in self.group[l][0] or y in self.group[l][1]:
        if merge_i >= 0:
          self.merge(merge_i,l)
          l -= 1
          r -= 1
        else:
          self.group[l][0].add(x)
          self.group[l][1].add(y)
          self.group[l][2] += 1
          merge_i = l
      l += 1
    if merge_i < 0:
      self.group.append([{x},{y},1])

  def output(self):
    ret = 0
    for i in range(len(self.group)):
      x = len(self.group[i][0])
      y = len(self.group[i][1])
      if min([x,y]) >= 2:
        ret += x*y-self.group[i][2]
    return ret



def main():
  N = int(input())
  uf = UnionFind()
  for _ in range(N):
    x,y = map(int, input().split())
    uf.new(x,y)
  print(uf.output())

