from collections import deque



class UnionFind():
  def __init__(self):
    self.group = deque()

  def merge(self,i,j):
    ## i <- j
    self.group[i][0] |= self.group[j][0]
    self.group[i][1] |= self.group[j][1]
    self.group[i][2] += self.group[j][2]
    self.group.pop(j)

  def new(self,x,y):
    merge_i = -1
    l = len(self.group)
    for i in range(l):
      if x in self.group[i][0] or y in self.group[i][1]:
        if merge_i >= 0:
          self.merge(merge_i,i)
        else:
          self.group[i][0].add(x)
          self.group[i][1].add(y)
          self.group[i][2] += 1
          merge_i = i
    if merge_i < 0:
      self.group.append([set([x]),set([y]),1])

  def output(self):
    ret = 0
    for i in range(len(self.group)):
      x = len(self.group[i][0])
      y = len(self.group[i][1])
      if x*y >= 4:
        ret += x*y-self.group[i][2]
    return ret



def main():
  N = int(input())
  uf = UnionFind()
  for _ in range(N):
    x,y = map(int, input().split())
    uf.new(x,y)
  print(uf.output())

