class UnionFind(object):
    def __init__(self, n, recursion = False):
        self._par = list(range(n))
        self._size = [1] * n
        self._recursion = recursion

    def root(self, k):
        if self._recursion:
            if k == self._par[k]:
                return k
            self._par[k] = self.root(self._par[k])
            return self._par[k]
        else:
            root = k
            while root != self._par[root]: root = self._par[root]
            while k != root: k, self._par[k] = self._par[k], root
            return root

    def unite(self, i, j):
        i, j = self.root(i), self.root(j)
        if i == j: return False
        if self._size[i] < self._size[j]: i, j = j, i
        self._par[j] = i
        self._size[i] += self._size[j]
        return True

    def is_connected(self, i, j):
        return self.root(i) == self.root(j)

    def size(self, k):
        return self._size[self.root(k)]

def resolve():
    n = int(input())
    uf = UnionFind(n)
    potential = [[1, 1] for _ in range(n)]
    x_to_index = {}
    y_to_index = {}

    for i in range(n):
        x, y = map(int, input().split())

        # x を共有する index が存在する
        if x in x_to_index:
            uf.unite(x_to_index[x], i)
            potential[uf.root(i)][1] += 1 # y が追加される

        # y を共有する index が存在する
        if y in y_to_index:
            j = y_to_index[y]
            # x を共有するときに既に追加されている場合、y は増えていないので戻す
            if uf.is_connected(i, j):
                potential[uf.root(i)][1] -= 1
            # そうでない場合、x が追加される
            else:
                x0 = potential[uf.root(i)][0]
                x1 = potential[uf.root(j)][0]
                uf.unite(i, j)
                potential[uf.root(i)][0] = x0 + x1

        x_to_index[x] = i
        y_to_index[y] = i

    res = -n
    for v in range(n):
        if v != uf.root(v):
            continue
        x, y = potential[v]
        res += x * y

    print(res)
