class UnionFind:
    def __init__(self, n):
        self.n = n
        self.par = [-1]*(n+1)#それぞれの要素がどの要素の子であるか

    def find(self, x):
        if self.par[x] < 0:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]#それぞれの要素の根を再帰的に求める

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return
        if self.par[x] > self.par[y]:
            x, y = y, x

        self.par[x] += self.par[y]
        self.par[y] = x

    def same(self, x, y):
        return self.find(x) == self.find(y)#x,yが同じ集合に属するかどうか

    def size(self, x):
        return -self.par[self.find(x)]

    def members(self, x):
        root = self.find(x)
        return [i for i in range(self.n) if root == self.find(i)]        

def compress(lis, n=2, last_sort=False):
    length = len(lis)
    first_value = -1
    for i in range(n):
        lis.sort(key=itemgetter(i))
        value = first_value
        index = 0
        for j in range(length):
            if lis[j][i] != value:
                index += 1
            value = lis[j][i]
            lis[j][i] = index

    if last_sort: lis.sort()
    return lis


def main():
    n = int(input())
    p = [list(map(int, input().split())) for _ in range(n)]

    compress(p, last_sort=True)

    key = [set() for _ in range(n+1)]
    for i in range(n):
        key[p[i][1]].add(p[i][0])

    member = [{i} for i in range(n+1)]
    union = UnionFind(n)
    for i in range(n-1):
        if p[i][0] == p[i+1][0]:
            union.union(p[i][1], p[i+1][1])
            member[union.find(p[i][1])].add(p[i+1][1])

    ans = 0
    already = [False]*(n+1)
    for i in range(1, n+1):
        if already[i]:
            continue
        table = member[i]
        judge = set()
        field = 0
        for v in table:
            already[v] = True
            judge = judge | key[v]
            field -= len(key[v])
        field += len(table)*len(judge)
        ans += field

    print(ans)




