def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, XY):
    g = defaultdict(list)
    for x, y in XY:
        g[(0, x)].append((1, y))
        g[(1, y)].append((0, x))

    ans = 0
    while g:
        for k in g:
            q = [g[k]][0]
            break
        done = set()
        while q:
            v = q.pop()
            for u in g[v]:
                if v[0] == 1:
                    e = (u, v)
                else:
                    e = (v, u)
                if e not in done:
                    q.append(u)
                    done.add(e)
        xn = set()
        yn = set()
        for v, u in done:
            for i, z in (v, u):
                if i == 0:
                    xn.add(z)
                elif i == 1:
                    yn.add(z)
        ans += (len(xn) * len(yn)) - len(done)
        for v, u in done:
            g.pop(v, None)
            g.pop(u, None)

    return ans

