from collections import defaultdict
class UnionFind:
    def __init__(self, N=None):
        if N is None or N < 1:
            self.parent = defaultdict(lambda: -1)
            self.children = defaultdict(list)
        else:
            self.parent = [-1]*int(N)
            self.children = [ [] for i in range(int(N)) ]

    def root(self, n):
        if self.parent[n] < 0:
            return n
        else:
            m = self.root(self.parent[n])
            self.parent[n] = m
            self.children[m].extend(self.children[n])
            self.children[n] = []
            return m

    def merge(self, m, n):
        rm = self.root(m)
        rn = self.root(n)
        if rm != rn:
            if -self.parent[rm] < -self.parent[rn]:
                rm, rn = rn, rm
            self.parent[rm] += self.parent[rn]
            self.parent[rn] = rm
            self.children[rm].append(rn)
            self.children[rm].extend(self.children[rn])
            self.children[rn] = []

    def size(self, n):
        return -self.parent[self.root(n)]

    def connected(self, m, n):
        return self.root(m) == self.root(n)

    def groups(self):
        if isinstance(self.parent,list):
            return list(map(lambda x: x<0, self.parent)).count(True)
        else: # self.parent: defaultdict
            return list(map(lambda x: x<0, self.parent.values())).count(True) 

    def collect_descendants(self, n):
        des = []
        for c in self.children[n]:
            self.collect_descendants(c)
            des.extend(self.children[c])
            self.children[c] = []
        self.children[n].extend(des)

    def all_groups(self):
        ans = []
        for r in range(N):
            if self.parent[r] >= 0:
                continue
            else:
                self.collect_descendants(r)
                ans.append( [r] + self.children[r] )
        return ans

