      if x in self.group[i][0] or y in self.group[i][1]:
        if merge_i >= 0:
          self.merge(merge_i,i)
        else:
          self.group[i][0].add(x)
          self.group[i][1].add(y)
          self.group[i][2] += 1
          merge_i = i
    if merge_i < 0:
      self.group.extend([[{x},{y},1,len(self.group)]])

  def output(self):
    xyn = [[set(),set(),0] for _ in range(len(self.group))]
    for i in range(len(self.group)):
      ids = self.group[i][3]
      xyn[ids][0] |= self.group[i][0]
      xyn[ids][1] |= self.group[i][1]
      xyn[ids][2] += self.group[i][2]

    ret = 0
    for x,y,n in xyn:
      if len(x)>=2 and len(y)>=2:
        ret += len(x)*len(y)-n
    return ret



