  XY = [[int(i) for i in input().split()] for i in range(N)]
  if N < 3: return 0
  setY = set()
  XYdict = {}
  for x, y in XY:
    setY.add(y)
    if x not in XYdict:
      XYdict[x] = set([y])
    else:
      XYdict[x].add(y)

  ans = 0

  for i in XYdict:
    for j in XYdict:
      if i == j: continue
      xor = XYdict[i] ^ XYdict[j]
      ans += len(xor)
      XYdict[i] |= XYdict[j]
      XYdict[j] |= XYdict[i]

  return ans

