def main():
    n = int(input())
    p = [list(map(int, input().split()))+[i+1] for i in range(n)]
    tree = [[] for _ in range(10**5)]

    p.sort()
    for i in range(n-1):
        if p[i][0] == p[i+1][0]:
            tree[p[i][2]-1].append(p[i+1][2]-1)
            tree[p[i+1][2]-1].append(p[i][2]-1)

    q = copy(p)
    q.sort(key=itemgetter(1))

    for i in range(n-1):
        if q[i][1] == q[i+1][1]:
            tree[q[i][2]-1].append(q[i+1][2]-1)
            tree[q[i+1][2]-1].append(q[i][2]-1)

    ans = -n
    already = [False]*n

    for i in range(n):
        if already[i]:
            continue
        already[i] = True

        not_yet = [i]
        key_x = {p[i][0]}
        key_y = {p[i][1]}
        while not_yet:
            key = not_yet.pop()
            for v in tree[key]:
                if already[v]:
                    continue
                already[v] = True
                not_yet.append(v)
                key_x.add(p[v][0])
                key_y.add(p[v][1])

        ans += len(key_x)*len(key_y)

