    union = UnionFind(n)
    for i in range(n-1):
        if p[i][0] == p[i+1][0]:
            union.union(p[i][1], p[i+1][1])

    already = [False]*(n+1)

    ans = 0
    for i in range(1, n+1):
        if already[i]:
