// この解法ではすでに長方形ができてる場合を余分に数えてる。
// すでにできてるかの判定が面倒なので、ありうる辺の数を数えて最後にnを引きたい。
// これは二部グラフの各連結成分を完全グラフにした時の辺の数。連結成分内なら絶対に長方形が作れる。
// 逆に連結成分でない頂点と長方形を作ろうとすると新たに辺が２本必要になるので無理。

use std::collections::HashSet;
use std::fs;
use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let m: usize = 100010;
    let mut g = vec![vec![]; 2 * m];
    for _ in 0..n {
        let (x, y): (usize, usize) = parse!(it, 2);
        g[x - 1].push(y - 1 + m);
        g[y - 1 + m].push(x - 1);
    }
    let mut ret = 0;
    let mut seen: HashSet<usize> = HashSet::new();
    for i in 0..(2 * m) {
        if !seen.contains(&i) {
            let mut part = HashSet::new();
            dfs(&g, i, &mut part);
            ret += get_cap(&g, &part, m);
            seen.extend(part.iter());
        }
    }
    println!("{}", ret);
}

fn get_cap(g: &Vec<Vec<usize>>, vs: &HashSet<usize>, n: usize) -> usize {
    let nx = vs.iter().filter(|&&i| i < n).count();
    let ny = vs.len() - nx;
    let ne = vs.iter().map(|&i| g[i].len()).sum::<usize>() / 2;
    nx * ny - ne
}

fn dfs(g: &Vec<Vec<usize>>, u: usize, seen: &mut HashSet<usize>) {
    seen.insert(u);
    for &v in &g[u] {
        if !seen.contains(&v) {
            dfs(g, v, seen);
        }
    }
}

fn test() {
    let mut f = fs::File::open("foo.txt").unwrap();
    let mut s = String::new();
    f.read_to_string(&mut s).unwrap();
