use std::collections::{BTreeMap, BTreeSet};

fn dfs(xys: &BTreeMap<u32, BTreeSet<u32>>, yxs: &BTreeMap<u32, BTreeSet<u32>>, visited: &mut BTreeSet<(u32, u32)>, x: u32, y: u32) {
  visited.insert((x, y));
  if !yxs.contains_key(&y) {
    return;
  }
  for z in yxs.get(&y).unwrap() {
    if x == *z {
      continue;
    }
    if !xys.contains_key(&x) {
      continue;
    }
    for w in xys.get(&x).unwrap() {
      if y == *w {
        continue;
      }
      if visited.contains(&(*z, *w)) {
        continue;
      }
      dfs(xys, yxs, visited, *z, *w);
    }
  }
}

fn main() {
  let stdin = io::stdin();
  let mut lines = stdin.lock().lines();
  let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
  let mut xys: BTreeMap<u32, BTreeSet<u32>> = BTreeMap::new();
  let mut yxs: BTreeMap<u32, BTreeSet<u32>> = BTreeMap::new();
  for _ in 0..n {
    let xs: Vec<u32> = lines.next().unwrap().unwrap().split(' ').map(|x| x.parse().unwrap()).collect();
    let (x, y) = (xs[0], xs[1]);
    if !xys.contains_key(&x) {
      xys.insert(x, BTreeSet::new());
    }
    if let Some(ys) = xys.get_mut(&x) {
      ys.insert(y);
    }
    if !yxs.contains_key(&y) {
      yxs.insert(y, BTreeSet::new());
    }
    if let Some(xs) = yxs.get_mut(&y) {
      xs.insert(x);
    }
  }
  let mut visited: BTreeSet<(u32, u32)> = BTreeSet::new();
  for (x, ys) in &xys {
    for y in ys {
      dfs(&xys, &yxs, &mut visited, *x, *y);
    }
  }
  println!("{}", visited.len() - n);
}

