fn main() {
    input!{
      n: usize,
      mut xys: [(usize, usize); n],
    }
    let mut xs: Vec<_> = xys.iter().map(|v|v.0).collect();
    xs.sort();
    xs.dedup();
    let mut ys: Vec<_> = xys.iter().map(|v|v.1).collect();
    ys.sort();
    ys.dedup();

    let xn = xs.len();
    let yn = ys.len();
    let m = xn+yn;
    let mut edges = vec![vec![]; m];
    for &(x, y) in xys.iter() {
         let a = xs.binary_search(&x).unwrap();
         let b = ys.binary_search(&y).unwrap() + xn;
         edges[a].push(b);
         edges[b].push(a);
    }

    let mut grp = vec![m; m];
    for i in 0..m {
        if grp[i] == m {
            dfs(&edges, i, m, i, &mut grp);
        }
    }
    let mut g_nodes = vec![vec![]; m];
    for &(x, y) in xys.iter() {
         let a = xs.binary_search(&x).unwrap();
         let g = grp[a];
         g_nodes[g].push((x, y));
    }

    let mut ans = 0u64;
    for mut nodes in g_nodes {
        nodes.sort();
        let mut xs: Vec<_> = nodes.iter().map(|v|v.0).collect();
        xs.sort();
        xs.dedup();
        let mut ys: Vec<_> = nodes.iter().map(|v|v.1).collect();
        ys.sort();
        ys.dedup();
        ans += xs.len() as u64 * ys.len() as u64;
    }
    println!("{}", ans-n as u64);
}

