fn solve() {
    let n = get!(usize);
    let xy = get!(usize, usize; n);

    if n < 3 {
        println!("0");
        return;
    }

    let xmax = 100_001;
    let mut nodes = vec![Vec::new(); 2*xmax];
    for &(x,y) in &xy {
        nodes[x].push(xmax+y);
        nodes[xmax+y].push(x);
    }

    let mut queue = VecDeque::new();
    let mut visited = vec![false; 2*xmax];
    let mut sum = 0usize;
    for &(x,_) in &xy {
        if visited[x] {
            continue;
        }
        queue.push_back(x);
        visited[x] = true;
        let mut ncount = 0;
        while let Some(node) = queue.pop_front() {
            ncount += 1;
            for &next in &nodes[node] {
                if visited[next] {
                    continue;
                }
                visited[next] = true;
                queue.push_back(next);
            }
        }
        sum += (ncount-ncount/2)*(ncount/2);
    }
    println!("{}", sum-n);
}

