const K: usize = 100_000;

fn dfs(i: usize, edge: &Vec<Vec<usize>>, used: &mut Vec<bool>, count: &mut [i64; 2]) -> i64 {
  used[i] = true;
  count[i / K] += 1;
  for &j in &edge[i] {
    if ! used[j] {
      dfs(j, edge, used, count);
    }
  }
  count[0] * count[1]
}

