    let y = y + K;
    edge[x].push(y);
    edge[y].push(x);
  }
  let mut used = vec![false; 2 * K];
  let mut ans = 0;
  for i in 0 .. 2 * K {
    ans += dfs(i, &edge, &mut used, &mut [0, 0]);
  }

  println!("{}", ans - n as i64);
}

