const BIG_STACK_SIZE: bool = true;

#[allow(dead_code)]
fn main() {
    use std::thread;
    if BIG_STACK_SIZE {
        thread::Builder::new()
            .stack_size(32 * 1024 * 1024)
            .name("solve".into())
            .spawn(solve)
            .unwrap()
            .join()
            .unwrap();
    } else {
        solve();
    }
}

fn solve() {
    let n = get!(usize);
    let xy = get!(usize, usize; n);

    let xmax = 100_001;
    let mut nodes = vec![Vec::new(); 2*xmax];
    for &(x,y) in &xy {
        nodes[x].push(xmax+y);
        nodes[xmax+y].push(x);
    }

    let mut queue = VecDeque::new();
    let mut visited = vec![false; 2*xmax];
    let mut sum = 0usize;
    for &(x,_) in &xy {
        if visited[x] {
            continue;
        }
        queue.push_back(x);
        visited[x] = true;
        let mut ncount = 0;
        let mut ecount = 0;
        while let Some(node) = queue.pop_front() {
            ncount += 1;
            for &next in &nodes[node] {
                ecount += 1;
                if visited[next] {
                    continue;
                }
                visited[next] = true;
                queue.push_back(next);
            }
        }
        if ncount <= 2 {
            continue;
        }
        sum += (ncount-ncount/2)*(ncount/2)-ecount/2;
    }
    println!("{}", sum);
}

