use std::io::Read;

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let m = 100_000;
    let mut u = union_find::UF::new(2 * m);
    let mut cnt = vec![(1, 0); 2 * m];
    for p in &mut cnt[m..] {
        *p = (0, 1);
    }
    for _ in 0..n {
        let x = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let y = it.next().unwrap().parse::<usize>().unwrap() - 1 + m;
        if let Some((a, b)) = u.unite(x, y) {
            cnt[a].0 += cnt[b].0;
            cnt[a].1 += cnt[b].1;
            cnt[b] = (0, 0);
        }
    }
    let ans = cnt.iter().fold(0, |s, p| s + p.0 * p.1) - n;
    println!("{}", ans);
}

fn main() {
    run();
}

