#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n = read::<usize>();
    let mut ps = vec![vec![0, 0]; n];
    let mut sort_ps: Vec<HashMap<i64, Vec<usize>>> = vec![HashMap::new(); 2];
    for i in 0..n {
        let x = read::<i64>();
        let y = read::<i64>();
        ps[i] = vec![x, y];
        sort_ps[0].entry(x).or_insert(vec![]).push(i);
        sort_ps[1].entry(y).or_insert(vec![]).push(i);
    }
    let mut used = vec![false; n];
    let mut ans = 0;
    for i in 0..n {
        if used[i] {
            continue;
        }
        used[i] = true;
        let mut que = vec![(0, ps[i][0]), (1, ps[i][1])];
        let mut visit: HashSet<(usize, i64)> = HashSet::new();
        visit.insert((0, ps[i][0]));
        visit.insert((1, ps[i][1]));
        let mut cnts = vec![1, 1];
        while let Some((dir, pos)) = que.pop() {
            for &index in sort_ps[dir][&pos].iter() {
                used[index] = true;
                let ndir = dir ^ 1;
                let npos = ps[index][ndir];
                if visit.contains(&(ndir, npos)) {
                    continue;
                }
                // println!("{} {}", ndir, npos);
                visit.insert((ndir, npos));
                cnts[ndir] += 1;
                que.push((ndir, npos));
            }
        }
        // println!("{:?}", cnts);
        ans += cnts[0] * cnts[1];
    }
    ans -= n;
    println!("{}", ans);
}

