pub struct UnionFind {
    n: usize,
    par: Vec<usize>,
    rank: Vec<usize>
}

impl UnionFind {

    pub fn new(n:usize) -> UnionFind {
        UnionFind{
            n:n,
            par:(0..n).map(|i|i).collect(),
            rank:vec![0;n],
        }
    }

    pub fn size(&self) -> usize {self.n}

    pub fn find(&mut self,v:usize) -> usize {
        if self.par[v] == v {
            v
        }
        else {
            let p = self.find(self.par[v]);
            self.par[v] = p;
            p
        }
    }

    pub fn unite(&mut self,a:usize,b:usize){
        let a = self.find(a);
        let b = self.find(b);
        if a==b {
            return
        }
        else {
            if self.rank[a]<self.rank[b] {
                self.par[a] = b;
            }
            else {
                if self.rank[a]==self.rank[b] {
                    self.rank[a] += 1;
                }
                self.par[b] = a;
            }
        }
    }

    pub fn is_same(&mut self,a:usize,b:usize) -> bool {
        self.find(a)==self.find(b)
    }

}

