use std::collections::{BTreeMap, BTreeSet, VecDeque};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut x: Vec<u64> = vec![];
    let mut y: Vec<u64> = vec![];
    for _ in 0..n {
        x.push(sc.read());
        y.push(sc.read());
    }

    let x_map = x
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .enumerate()
        .map(|(i, x)| (x, i as i64))
        .collect::<BTreeMap<_, _>>();
    let y_map = y
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .enumerate()
        .map(|(i, y)| (y, i as i64))
        .collect::<BTreeMap<_, _>>();

    let x = x
        .into_iter()
        .map(|x| *x_map.get(&x).unwrap())
        .collect::<Vec<_>>();
    let y = y
        .into_iter()
        .map(|y| *y_map.get(&y).unwrap())
        .collect::<Vec<_>>();
    let mut set = (0..n).map(|i| (x[i], y[i])).collect::<BTreeSet<_>>();
    let mut q = VecDeque::new();
    for i in 0..n {
        let x = x[i];
        let y = y[i];
        for dx in (-1)..2 {
            for dy in (-1)..2 {
                let x = x + dx;
                let y = y + dy;
                if is3(x, y, &set) {
                    q.push_back((x, y));
                }
            }
        }
    }
    let mut ans = 0;

    while let Some((x, y)) = q.pop_front() {
        if set.contains(&(x, y)) {
            continue;
        }
        set.insert((x, y));
        ans += 1;
        for dx in (-1)..2 {
            for dy in (-1)..2 {
                let x = x + dx;
                let y = y + dy;
                if is3(x, y, &set) {
                    q.push_back((x, y));
                }
            }
        }
    }
    println!("{}", ans);
}

fn is3(x: i64, y: i64, set: &BTreeSet<(i64, i64)>) -> bool {
    if set.contains(&(x, y)) {
        return false;
    }
    for (px, py) in vec![(1, -1), (1, 1), (-1, 1), (-1, -1)].into_iter() {
        let mut count = 0;
        for dx in 0..2 {
            for dy in 0..2 {
                if set.contains(&(x + px * dx, y + py * dy)) {
                    count += 1;
                }
            }
        }
        if count == 3 {
            return true;
        }
    }
    false
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

