pub struct UnionFindRank {
    parent: Vec<usize>,
    rank: Vec<usize>,
}
impl UnionFindRank {
#[allow(dead_code)]
    pub fn new(n: usize) -> Self {
        let mut parent = vec![0; n];
        for i in 0..n {
            parent[i] = i;
        }
        UnionFindRank {
            parent: parent,
            rank: vec![0; n],
        }
    }
#[allow(dead_code)]
    pub fn root(&mut self, a: usize) -> usize {
        if self.parent[a] == a {
            a
        } else {
            let tmp = self.parent[a];
            self.parent[a] = self.root(tmp);
            self.parent[a]
        }
    }
#[allow(dead_code)]
    pub fn unite(&mut self, a: usize, b: usize) {
        let a = self.root(a);
        let b = self.root(b);
        if a == b {
            return;
        }
        if self.rank[a] > self.rank[b] {
            self.parent[b] = a;
        } else {
            self.parent[a] = b;
            if self.rank[a] == self.rank[b] {
                self.rank[b] += 1;
            }
        }
    }
#[allow(dead_code)]
    pub fn is_same(&mut self, a: usize, b: usize) -> bool {
        self.root(a) == self.root(b)
    }
}

fn solve() {
    let n = get!(usize);
    let xy = get!(usize, usize; n);

    if n < 3 {
        println!("0");
        return;
    }

    let xmax = 100_001;
    let mut tree = UnionFindRank::new(300_000);
    for &(x,y) in &xy {
        tree.unite(x, y+xmax);
    }
    let mut xmap = BTreeMap::new();
    let mut ymap = BTreeMap::new();
    for i in 0..xmax {
        *xmap.entry(tree.root(i)).or_insert(0usize) += 1;
    } 
    for i in xmax..(2*xmax) {
        *ymap.entry(tree.root(i)).or_insert(0usize) += 1;
    }

    let mut sum = 0usize;
    for i in 0..2*xmax {
        sum += xmap.get(&i).unwrap_or(&0) * ymap.get(&i).unwrap_or(&0);
    }
    println!("{}", sum-n);
}

