fn main() {
    use std::collections::{HashMap, HashSet};
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let xy: Vec<(usize, usize)> = vec(n, |_| (scan(tokens), scan(tokens)));
    let xs: HashSet<usize> = xy.iter().map(|&(x, _)| x).collect();
    let ys: HashSet<usize> = xy.iter().map(|&(_, y)| y).collect();
    let x2i: HashMap<usize, usize> = xs.into_iter().enumerate().map(|(i, x)| (x, i)).collect();
    let y2j: HashMap<usize, usize> = ys.into_iter().enumerate().map(|(j, y)| (y, j)).collect();
    let nx: usize = x2i.len();
    let ny: usize = y2j.len();
    let mut i2j = vec![Vec::new(); nx];
    let mut j2i = vec![Vec::new(); ny];
    for &(x, y) in &xy {
        let i: usize = x2i[&x];
        let j: usize = y2j[&y];
        i2j[i].push(j);
        j2i[j].push(i);
    }
    let mut ci = vec![0; nx];
    let mut cj = vec![0; ny];
    let mut k = 0;
    for i in 0..nx {
        if ci[i] == 0 {
            k += 1;
            dfs_i(i, k, &mut ci, &mut cj, &i2j, &j2i);
        }
    }
    let mut kc: Vec<usize> = vec![0; k + 1];
    for &c in &ci {
        kc[c] += 1;
    }
    let mut lc: Vec<usize> = vec![0; k + 1];
    for &c in &cj {
        lc[c] += 1;
    }
    let mut ans = 0;
    for c in 1..k + 1 {
        ans += kc[c] * lc[c];
    }
    ans -= n;
    println!("{}", ans);
}

fn dfs_i(
    i: usize,
    c: usize,
    ci: &mut Vec<usize>,
    cj: &mut Vec<usize>,
    i2j: &Vec<Vec<usize>>,
    j2i: &Vec<Vec<usize>>,
) {
    if ci[i] != 0 {
        return;
    }
    ci[i] = c;
    for &j in &i2j[i] {
        dfs_j(j, c, ci, cj, i2j, j2i);
    }
}

fn dfs_j(
    j: usize,
    c: usize,
    ci: &mut Vec<usize>,
    cj: &mut Vec<usize>,
    i2j: &Vec<Vec<usize>>,
    j2i: &Vec<Vec<usize>>,
) {
    if cj[j] != 0 {
        return;
    }
    cj[j] = c;
    for &i in &j2i[j] {
        dfs_i(i, c, ci, cj, i2j, j2i);
    }
}

use std::collections::{BTreeMap, BTreeSet, VecDeque};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut x: Vec<u64> = vec![];
    let mut y: Vec<u64> = vec![];
    for _ in 0..n {
        x.push(sc.read());
        y.push(sc.read());
    }

    let x_map = x
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .enumerate()
        .map(|(i, x)| (x, i as i64))
        .collect::<BTreeMap<_, _>>();
    let y_map = y
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .enumerate()
        .map(|(i, y)| (y, i as i64))
        .collect::<BTreeMap<_, _>>();

    let x = x
        .into_iter()
        .map(|x| *x_map.get(&x).unwrap())
        .collect::<Vec<_>>();
    let y = y
        .into_iter()
        .map(|y| *y_map.get(&y).unwrap())
        .collect::<Vec<_>>();
    let mut set = (0..n).map(|i| (x[i], y[i])).collect::<BTreeSet<_>>();
    let mut q = VecDeque::new();
    for i in 0..n {
        let x = x[i];
        let y = y[i];
        for dx in (-1)..2 {
            for dy in (-1)..2 {
                let x = x + dx;
                let y = y + dy;
                if is3(x, y, &set) {
                    q.push_back((x, y));
                }
            }
        }
    }
    eprintln!("{:?}", q);
    let mut ans = 0;

    while let Some((x, y)) = q.pop_front() {
        if set.contains(&(x, y)) {
            continue;
        }
        set.insert((x, y));
        ans += 1;
        for dx in (-1)..2 {
            for dy in (-1)..2 {
                let x = x + dx;
                let y = y + dy;
                if is3(x, y, &set) {
                    q.push_back((x, y));
                }
            }
        }
    }
    println!("{}", ans);
}

fn is3(x: i64, y: i64, set: &BTreeSet<(i64, i64)>) -> bool {
    if set.contains(&(x, y)) {
        return false;
    }
    for (px, py) in vec![(1, -1), (1, 1), (-1, 1), (-1, -1)].into_iter() {
        let mut count = 0;
        for dx in 0..2 {
            for dy in 0..2 {
                if set.contains(&(x + px * dx, y + py * dy)) {
                    count += 1;
                }
            }
        }
        if count == 3 {
            return true;
        }
    }
    false
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

