use std::collections::{BTreeMap, BTreeSet};

fn dfs(xys: &BTreeMap<usize, BTreeSet<usize>>, yxs: &BTreeMap<usize, BTreeSet<usize>>, visited: &mut BTreeSet<(usize, usize)>, x: usize, y: usize) {
  visited.insert((x, y));
  for z in yxs.get(&y).unwrap_or(&BTreeSet::new()) {
    if x == *z {
      continue;
    }
    for w in xys.get(&x).unwrap_or(&BTreeSet::new()) {
      if y == *w {
        continue;
      }
      if visited.contains(&(*z, *w)) {
        continue;
      }
      dfs(xys, yxs, visited, *z, *w);
    }
  }
}

fn main() {
  let stdin = io::stdin();
  let mut lines = stdin.lock().lines();
  let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
  let mut xys: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
  let mut yxs: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
  for _ in 0..n {
    let xs: Vec<usize> = lines.next().unwrap().unwrap().split(' ').map(|x| x.parse().unwrap()).collect();
    let (x, y) = (xs[0], xs[1]);
    match xys.get_mut(&x) {
      None => {
        let mut ys = BTreeSet::new();
        ys.insert(y);
        xys.insert(x, ys);
      },
      Some(ys) => {
        ys.insert(y);
      },
    }
    match yxs.get_mut(&y) {
      None => {
        let mut xs = BTreeSet::new();
        xs.insert(x);
        yxs.insert(y, xs);
      },
      Some(xs) => {
        xs.insert(x);
      }
    }
  }
  let mut visited: BTreeSet<(usize, usize)> = BTreeSet::new();
  for (x, ys) in &xys {
    for y in ys {
      dfs(&xys, &yxs, &mut visited, *x, *y);
    }
  }
  println!("{}", visited.len() - n);
}

