pub struct UnionFind {
    parent: Vec<i32>,
}
impl UnionFind {
    pub fn new(n: usize) -> Self {
        UnionFind {
            parent: vec![-1; n],
        }
    }
    pub fn root(&mut self, a: i32) -> i32 {
        if self.parent[a as usize] < 0 {
            return a;
        } else {
            let index = self.parent[a as usize];
            self.parent[a as usize] = self.root(index);
            return self.parent[a as usize];
        }
    }
    pub fn rank(&mut self, a: i32) -> i32 {
        let tmp = self.root(a);
        return -1 * self.parent[tmp as usize];
    }
    pub fn ranks(&mut self, ret: &mut Vec<i32>) -> bool {
        for item in self.parent.iter().filter(|&x| *x < 0) {
            ret.push(item.clone());
        }
        return true;
    }
    pub fn join(&mut self, a: i32, b: i32) -> bool {
        let mut a_root = self.root(a);
        let mut b_root = self.root(b);
        if (a_root == b_root) {
            return false;
        }
        if (self.rank(b_root) > self.rank(a_root)) {
            std::mem::swap(&mut a_root, &mut b_root);
        }
        self.parent[a_root as usize] += self.parent[b_root as usize];
        self.parent[b_root as usize] = a_root;
        return true;
    }
}

