        n: usize,
        xy: [(usize, usize); n],
    }
    const W: usize = 100_100;
    let mut uf = UnionFind::new(2 * W);
    let mut row = vec![vec![]; W];
    let mut col = vec![vec![]; W];
    for &(x, y) in &xy {
        uf.unite(x, W + y);
        row[x].push(y);
        col[y].push(x);
    }
    for i in 0..W {
        if row[i].is_empty() { continue; }
        for j in 0..row[i].len() - 1 {
            let x = row[i][j];
            let y = row[i][j + 1];
            uf.unite(W + x, W + y);
        }
    }
    for i in 0..W {
        if col[i].is_empty() { continue; }
        for j in 0..col[i].len() - 1 {
            let x = col[i][j];
            let y = col[i][j + 1];
            uf.unite(x, y);
        }
    }
    let mut tot: i64 = 0;
    let mut sz = vec![(0, 0); 2 * W];
    for i in 0..2 * W {
        let r = uf.root(i);
        if i < W {
            sz[r].0 += 1;
        } else {
            sz[r].1 += 1;
        }
    }
    for i in 0..2 * W {
        let (x, y) = sz[i];
        tot += x * y;
    }
    puts!("{}\n", tot - n as i64);
}

