fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut x: Vec<u64> = vec![];
    let mut y: Vec<u64> = vec![];
    for _ in 0..n {
        x.push(sc.read());
        y.push(sc.read());
    }

    let sx = x
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .enumerate()
        .map(|(i, v)| (v, i))
        .collect::<BTreeMap<_, _>>();
    let sy = y
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .enumerate()
        .map(|(i, v)| (v, i))
        .collect::<BTreeMap<_, _>>();

    let mut graph = vec![vec![]; sx.len() + sy.len()];
    for i in 0..n {
        let x = *sx.get(&x[i]).unwrap();
        let y = *sy.get(&y[i]).unwrap() + sx.len();
        graph[x].push(y);
        graph[y].push(x);
    }

    let mut color = vec![0; sx.len() + sy.len()];
    let mut cur = 1;
    for t in 0..color.len() {
        if color[t] != 0 {
            continue;
        }

        let mut q = VecDeque::new();
        q.push_front(t);
        color[t] = cur;
        while let Some(v) = q.pop_front() {
            for &next in graph[v].iter() {
                if color[next] == 0 {
                    q.push_back(next);
                    color[next] = cur;
                }
            }
        }
        cur += 1;
    }

    let mut count = vec![(0, 0); cur];
    for (i, color) in color.into_iter().enumerate() {
        if i < sx.len() {
            count[color].0 += 1;
        } else {
            count[color].1 += 1;
        }
    }

    let mut all = 0;
    for (x, y) in count.into_iter() {
        all += x * y;
    }
    println!("{}", all - n);
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::*;

mod disjoint_set {
    pub struct DisjointSet {
        parent: Vec<usize>,
        size: Vec<usize>,
    }
    impl DisjointSet {
        pub fn new(n: usize) -> DisjointSet {
            DisjointSet {
                parent: (0..n).collect(),
                size: vec![1; n],
            }
        }
        pub fn root(&mut self, x: usize) -> usize {
            if x == self.parent[x] {
                x
            } else {
                let tmp = self.parent[x];
                self.parent[x] = self.root(tmp);
                self.parent[x]
            }
        }
        pub fn merge(&mut self, x: usize, y: usize) {
            let x = self.root(x);
            let y = self.root(y);
            if x == y {
                return;
            }
            if self.size[x] > self.size[y] {
                self.size[x] += self.size[y];
                self.parent[y] = x;
            } else {
                self.size[y] += self.size[x];
                self.parent[x] = y;
            }
        }
    }
}

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let a: Vec<(usize, usize)> = (0..n)
        .map(|_| {
            (
                itr.next().unwrap().parse::<usize>().unwrap() - 1,
                itr.next().unwrap().parse::<usize>().unwrap() - 1,
            )
        })
        .collect();

    let mut ds = disjoint_set::DisjointSet::new(200001);

    let mut root_seen = vec![false; 200001];
    let mut xseen = vec![false; 100001];
    let mut yseen = vec![false; 100001];
    let mut xsize = vec![0usize; 200001];
    let mut ysize = vec![0usize; 200001];

    for i in 0..n {
        ds.merge(a[i].0, a[i].1 + 100000);
    }

    // rootのxsize, ysizeを計算
    for i in 0..n {
        if !xseen[a[i].0] {
            xsize[ds.root(a[i].0)] += 1;
            xseen[a[i].0] = true;
        }
        if !yseen[a[i].1] {
            ysize[ds.root(a[i].1)] += 1;
            yseen[a[i].1] = true;
        }
    }

    let mut ans = 0usize;
    for i in 0..n {
        let root = ds.root(a[i].0);
        if !root_seen[root] {
            ans += xsize[root] * ysize[root];
            root_seen[root] = true;
        }
    }
    println!("{}", ans - n);
}

