    let nx = X.len();

    let mut Y: Vec<i64> = Y.into_iter().collect();
    Y.sort();
    let ny = Y.len();

    let mut uf = UnionFind::new(nx+ny);
    for i in 0..n {
        let (x,y) = xy[i];
        let xi = X.lower_bound(&x);
        let yi = Y.lower_bound(&y);
        uf.merge(xi, nx+yi);
    }

    let mut hm = HashMap::new();
    for i in 0..nx {
        let k = i;
        hm.entry(uf.root(k)).or_insert(vec![]).push(k);
    }
    for i in 0..ny {
        let k = nx + i;
        hm.entry(uf.root(k)).or_insert(vec![]).push(k);
    }
    let mut tot = 0;
