        xy:[(usize,usize);n]
    }
    let m = 1e5 as usize;
    //0~1e5:x,1e5~2e5:y
    let mut g = Graph::new(2 * m);
    for (x, y) in xy.iter() {
        let (x, y) = (x - 1, y - 1);
        g.add_undirectional_edge(x, y + m, 1);
    }
    let mut visited = vec![false; 2 * m];
    let mut ans: i64 = 0;
    for i in 0..2 * m {
        if visited[i] {
            continue;
        }
        let mut x_count = 0;
        let mut y_count = 0;
        let mut bfs = VecDeque::new();
        bfs.push_back(i);
        visited[i] = true;
        while let Some(now) = bfs.pop_front() {
            if now < m {
                x_count += 1;
            } else {
                y_count += 1;
            }
            for next in g[now].iter() {
                if visited[next.to] {
                    continue;
                }
                visited[next.to] = true;
                bfs.push_back(next.to);
            }
        }
        ans += x_count * y_count;
    }
