    }
    let mut to = vec![vec![]; 2 * N];
    for (x, y) in xy {
        to[x].push(N + y);
        to[N + y].push(x);
    }
    let mut visit = vec![false; 2 * N];
    let mut ans = 0;
    for i in 0..N {
        if visit[i] {
            continue;
        }
        let (x, y) = dfs(i, &to, &mut visit);
