fn dfs(v: usize, to: &Vec<Vec<usize>>, visit: &mut Vec<bool>) -> (usize, usize) {
    let mut x = 0;
    let mut y = 0;
    if v / N == 0 {
        x += 1;
    } else {
        y += 1;
    }
    visit[v] = true;
    for &u in to[v].iter() {
        if visit[u] {
            continue;
        }
        let (dx, dy) = dfs(u, to, visit);
        x += dx;
        y += dy;
    }
    (x, y)
}

