#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct Point {
    y: u32,
    x: u32,
}

fn main() {
    let mut input_str = String::new();
    std::io::stdin().read_to_string(&mut input_str).unwrap();

    let input_parts = input_str.split_whitespace().collect::<Vec<_>>();
    let mut input_parts_it = input_parts.iter().cloned();

    let n: usize = input_parts_it.next().unwrap().parse().unwrap();

    let mut points: Vec<_> = (0..n)
        .map(|_| Point {
            x: input_parts_it.next().unwrap().parse().unwrap(),
            y: input_parts_it.next().unwrap().parse().unwrap(),
        })
        .collect();

    let mut x_set = vec![Vec::new(); 100001];
    for p in points.iter() {
        x_set[p.x as usize].push(*p);
    }

    let mut point_set: HashSet<_> = points.iter().cloned().collect();
    points.sort();

    let mut count = 0;

    for (i1, pt1) in points.iter().enumerate() {
        let x1 = pt1.x;
        let y1 = pt1.y;

        for pt2 in x_set[x1 as usize].iter() {
            if pt2.y == y1 {
                continue;
            }

            for pt3 in points[i1 + 1..].iter() {
                if pt3.y != y1 {
                    break;
                }

                let new_pt = Point { x: pt3.x, y: pt2.y };
                if point_set.insert(new_pt) {
                    count += 1;
                }
            }

            for pt3 in points[0..i1].iter().rev() {
                if pt3.y != y1 {
                    break;
                }

                let new_pt = Point { x: pt3.x, y: pt2.y };
                if point_set.insert(new_pt) {
                    count += 1;
                }
            }
        }
    }

    println!("{}", count);
}

