    let mut ys2 = vec![BTreeSet::new(); 100000];
    for (i, &(x, y)) in ps.iter().enumerate() {
        let ri = uf.root(i);
        let (rx, ry) = ps[ri];
        xs2[rx].insert(y);
        ys2[ry].insert(x);
    }
    let mut count = 0;
    for (i, &(x, y)) in ps.iter().enumerate() {
        if uf.root(i) == i {
            // eprintln!("{:?}", xs2[x]);
            // eprintln!("{:?}", ys2[x]);
            count += xs2[x].len() * ys2[y].len();
        }
    }
    // eprintln!("count = {}", count);
    count -= n;
    writeln!(buf, "{}", count);
    buf
}

