use std::cell::RefCell;
use std::rc::Rc;

struct UnionFind {
    par: Rc<RefCell<Vec<usize>>>,
}

impl UnionFind {
    fn new(n: usize) -> Self {
        let uf = UnionFind {
            par: Rc::new(RefCell::new(vec![0; n])),
        };
        for i in 0..n {
            uf.par.borrow_mut()[i] = i;
        }
        uf
    }

    fn root(&self, x: usize) -> usize {
        let t = self.par.borrow()[x];
        if t == x {
            x
        } else {
            self.par.borrow_mut()[x] = self.root(t);
            self.par.borrow()[x]
        }
    }

    fn same(&self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }

    fn unite(&self, mut x: usize, mut y: usize) {
        x = self.root(x);
        y = self.root(y);
        if x == y {
            return;
        }

        self.par.borrow_mut()[x] = y;
    }
}

fn solve(xys: &[(usize, usize)]) -> usize {
    let n = xys.len();
    const MAX: usize = 20000;

    let uf = UnionFind::new(MAX * 2 + 1);

    let mut mx = [0; MAX * 2 + 1];
    let mut my = [0; MAX * 2 + 1];

    for &(x, y) in xys.iter() {
        uf.unite(x, y + MAX);
    }

    for i in 1..MAX {
        mx[uf.root(i)] += 1;
        my[uf.root(i + MAX)] += 1;
    }

    let mut ans = 0;

    for i in 1..(MAX * 2 + 1) {
        ans += mx[i] * my[i];
    }

    ans - n
}

