fn solve() {
    let n = get!(usize);
    let xy = get!(usize, usize; n);

    if n < 3 {
        println!("0");
        return;
    }

    let xmax = 100_001;
    let mut nodes = vec![Vec::new(); 2*xmax];
    for &(x,y) in &xy {
        nodes[x].push(xmax+y);
        nodes[xmax+y].push(x);
    }

    let mut queue = VecDeque::new();
    let mut visited = vec![false; 2*xmax];
    let mut sum = 0usize;
    let mut in_count = n;
    for &(x,_) in &xy {
        if visited[x] {
            continue;
        }
        queue.push_back(x);
        visited[x] = true;
        let mut ncount = 0;
        while let Some(node) = queue.pop_front() {
            ncount += 1;
            for &next in &nodes[node] {
                if visited[next] {
                    continue;
                }
                visited[next] = true;
                queue.push_back(next);
            }
        }
        if ncount <= 2 {
            in_count -= 1;
            continue;
        }
        sum += (ncount-ncount/2)*(ncount/2);
    }
    println!("{}", sum-in_count);
}

use std::io::*;

mod disjoint_set {
    pub struct DisjointSet {
        parent: Vec<usize>,
        size: Vec<usize>,
    }
    impl DisjointSet {
        pub fn new(n: usize) -> DisjointSet {
            DisjointSet {
                parent: (0..n).collect(),
                size: vec![1; n],
            }
        }
        pub fn root(&mut self, x: usize) -> usize {
            if x == self.parent[x] {
                x
            } else {
                let tmp = self.parent[x];
                self.parent[x] = self.root(tmp);
                self.parent[x]
            }
        }
        pub fn merge(&mut self, x: usize, y: usize) {
            let x = self.root(x);
            let y = self.root(y);
            if x == y {
                return;
            }
            if self.size[x] > self.size[y] {
                self.size[x] += self.size[y];
                self.parent[y] = x;
            } else {
                self.size[y] += self.size[x];
                self.parent[x] = y;
            }
        }
    }
}

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let a: Vec<(usize, usize)> = (0..n)
        .map(|_| {
            (
                itr.next().unwrap().parse().unwrap(),
                itr.next().unwrap().parse().unwrap(),
            )
        })
        .collect();

    let mut ds = disjoint_set::DisjointSet::new(200001);

    let mut root_seen = vec![false; 200001];
    let mut xseen = vec![false; 100001];
    let mut yseen = vec![false; 100001];
    let mut xsize = vec![0; 200001];
    let mut ysize = vec![0; 200001];

    for i in 0..n {
        ds.merge(a[i].0, a[i].1 + 100000);
    }

    // rootのxsize, ysizeを計算
    for i in 0..n {
        if !xseen[a[i].0] {
            xsize[ds.root(a[i].0)] += 1;
            xseen[a[i].0] = true;
        }
        if !yseen[a[i].1] {
            ysize[ds.root(a[i].1)] += 1;
            yseen[a[i].1] = true;
        }
    }

    let mut ans = 0;
    for i in 0..n {
        let root = ds.root(a[i].0);
        if !root_seen[root] {
            ans += xsize[root] * ysize[root];
            root_seen[root] = true;
        }
    }
    println!("{}", ans - n);
}

