const N: usize = 100000;

fn main() {
	let mut s = String::new();
	use std::io::Read;
	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let mut edges = vec![vec![]; 2 * N];
	for _ in 0..n {
		let x = s.next().unwrap().parse::<usize>().unwrap() - 1;
		let y = s.next().unwrap().parse::<usize>().unwrap() - 1 + N;
		edges[x].push(y);
		edges[y].push(x);
	}
	let mut visit = vec![false; 2 * N];
	let mut ans = 0;
	for i in 0..N {
		if visit[i] || edges[i].len() == 0 {
			continue;
		}
		let mut q = vec![i];
		let mut cnt = [0; 2];
		while let Some(v) = q.pop() {
			if visit[v] {
				continue;
			}
			visit[v] = true;
			cnt[v / N] += 1;
			for &to in edges[v].iter() {
				if !visit[to] {
					q.push(to);
				}
			}
		}
		ans += cnt[0] * cnt[1];
	}
	ans -= n;
	println!("{}", ans);
}

