        xys.insert(x, ys);
      },
      Some(ys) => {
        ys.insert(y);
      },
    }
    let o = yxs.get_mut(&y);
    match o {
      None => {
        let mut xs = BTreeSet::new();
        xs.insert(x);
        yxs.insert(y, xs);
      },
      Some(xs) => {
        xs.insert(x);
      }
    }
  }
  let mut visited: BTreeSet<(usize, usize)> = BTreeSet::new();
  for (x, ys) in &xys {
    for y in ys {
      dfs(&xys, &yxs, &mut visited, *x, *y);
    }
  }
