fn dfs(edges: &Vec<Vec<usize>>, cur: usize, par:usize, root:usize, g: &mut Vec<usize>) {
    g[cur] = root;
    for &node in edges[cur].iter() {
        if node != par {
            dfs(edges, node, cur, root, g);
        }
    }
}


fn main() {
    input!{
      n: usize,
      xys: [(usize, usize); n],
    }
    use std::collections::HashMap;
    let mut xs: Vec<_> = xys.iter().map(|v|v.0).collect();
    xs.sort();
    xs.dedup();
    let xs: HashMap<_, _> = xs.into_iter().enumerate().map(|(i, v)| (v, i)).collect();

    let mut ys: Vec<_> = xys.iter().map(|v|v.1).collect();
    ys.sort();
    ys.dedup();
    let ys: HashMap<_, _> = ys.into_iter().enumerate().map(|(i, v)| (v, i)).collect();

    let xn = xs.len();
    let yn = ys.len();
    let m = xn+yn;
    let mut edges = vec![vec![]; m];
    for &(x, y) in xys.iter() {
         let a = xs[&x];
         let b = ys[&y] + xn;
         edges[a].push(b);
         edges[b].push(a);
    }

    let mut grp = vec![m; m];
    for i in 0..m {
        if grp[i] == m {
            dfs(&edges, i, m, i, &mut grp);
        }
    }
    let mut grp2: Vec<_> = grp.iter().cloned().collect();
    grp2.sort();
    grp2.dedup();


    let mut g_nodes = vec![vec![]; grp2.len()];
    for &(x, y) in xys.iter() {
         let a = xs[&x];
         let g = grp2.binary_search(&grp[a]).unwrap();
         g_nodes[g].push((x, y));
    }
    // debug!(g_nodes);

    let mut ans = 0u64;
    for nodes in g_nodes {
        let mut xs: Vec<_> = nodes.iter().map(|v|v.0).collect();
        xs.sort();
        xs.dedup();
        let mut ys: Vec<_> = nodes.iter().map(|v|v.1).collect();
        ys.sort();
        ys.dedup();
        ans += xs.len() as u64 * ys.len() as u64;
    }
    println!("{}", ans-n as u64);
}

use std::io::{self, BufRead};

use std::collections::{BTreeMap, BTreeSet};

fn dfs(xys: &BTreeMap<usize, BTreeSet<usize>>, yxs: &BTreeMap<usize, BTreeSet<usize>>, visited: &mut BTreeSet<(usize, usize)>, x: usize, y: usize) {
  visited.insert((x, y));
  if !yxs.contains_key(&y) {
    return;
  }
  for z in yxs.get(&y).unwrap() {
    if x == *z {
      continue;
    }
    if !xys.contains_key(&x) {
      continue;
    }
    for w in xys.get(&x).unwrap() {
      if y == *w {
        continue;
      }
      if visited.contains(&(*z, *w)) {
        continue;
      }
      dfs(xys, yxs, visited, *z, *w);
    }
  }
}

fn main() {
  let stdin = io::stdin();
  let mut lines = stdin.lock().lines();
  let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
  let mut xys: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
  let mut yxs: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
  for _ in 0..n {
    let xs: Vec<usize> = lines.next().unwrap().unwrap().split(' ').map(|x| x.parse().unwrap()).collect();
    let (x, y) = (xs[0], xs[1]);
    if !xys.contains_key(&x) {
      xys.insert(x, BTreeSet::new());
    }
    if let Some(ys) = xys.get_mut(&x) {
      ys.insert(y);
    }
    if !yxs.contains_key(&y) {
      yxs.insert(y, BTreeSet::new());
    }
    if let Some(xs) = yxs.get_mut(&y) {
      xs.insert(x);
    }
  }
  let mut visited: BTreeSet<(usize, usize)> = BTreeSet::new();
  for (x, ys) in &xys {
    for y in ys {
      dfs(&xys, &yxs, &mut visited, *x, *y);
    }
  }
  println!("{}", visited.len() - n);
}

