use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        ps: [(usize1, usize1); n],
    }
    let mut xs = vec![vec![]; 100000];
    let mut ys = vec![vec![]; 100000];
    for (i, &(x, y)) in ps.iter().enumerate() {
        xs[x].push((i, x, y));
        ys[y].push((i, x, y));
    }
    for i in 0..100000 {
        xs[i].sort_by(|&x, &y| x.2.cmp(&y.2));
        ys[i].sort_by(|&x, &y| x.1.cmp(&y.1));
    }
    let mut checked: BTreeSet<(usize, usize)> = BTreeSet::new();
    let mut count = 0;
    for (i, &(x, y)) in ps.iter().enumerate() {
        if checked.get(&(xs[x][0].2, ys[y][0].1)).is_none() {
            count += xs[x].len() * ys[y].len();
        }
        checked.insert((xs[x][0].2, ys[y][0].1));
    }
    // eprintln!("count = {}", count);
    count -= n;
    writeln!(buf, "{}", count);
    buf
}

