pub struct UnionFindRank {
    parent: Vec<usize>,
    rank: Vec<usize>,
}
impl UnionFindRank {
#[allow(dead_code)]
    pub fn new(n: usize) -> Self {
        let mut parent = vec![0; n];
        for i in 0..n {
            parent[i] = i;
        }
        UnionFindRank {
            parent: parent,
            rank: vec![0; n],
        }
    }
#[allow(dead_code)]
    pub fn root(&mut self, a: usize) -> usize {
        if self.parent[a] == a {
            a
        } else {
            let tmp = self.parent[a];
            self.parent[a] = self.root(tmp);
            self.parent[a]
        }
    }
#[allow(dead_code)]
    pub fn unite(&mut self, a: usize, b: usize) {
        let a = self.root(a);
        let b = self.root(b);
        if a == b {
            return;
        }
        if self.rank[a] > self.rank[b] {
            self.parent[b] = a;
        } else {
            self.parent[a] = b;
            if self.rank[a] == self.rank[b] {
                self.rank[b] += 1;
            }
        }
    }
#[allow(dead_code)]
    pub fn is_same(&mut self, a: usize, b: usize) -> bool {
        self.root(a) == self.root(b)
    }
}

fn solve() {
    let n = get!(usize);
    let xy = get!(usize, usize; n);

    if n < 3 {
        println!("0");
        return;
    }

    let xmax = 100_001;
    let mut tree = UnionFindRank::new(1000_000);
    let mut map = BTreeMap::new();
    for &(x,y) in &xy {
        tree.unite(x, y+xmax);
        let entry = map.entry(tree.root(x)).or_insert((BTreeSet::new(), BTreeSet::new()));
        entry.0.insert(x);
        entry.1.insert(y);
    }

    let mut sum = 0;
    for (_, (x,y)) in map {
        let x = x.len();
        let y = y.len();
        if x >= 2 && y >= 2 {
            sum += x * y;
        }
    }

    println!("{}", sum-n);
}

