    for &(a, b) in &p {
        let xp = uf.root(a);
        let yp = uf.root(b);
        let mut hp = x.entry(xp).or_insert(HashSet::new());
        hp.insert(a);
        let mut hp = y.entry(yp).or_insert(HashSet::new());
        hp.insert(b);
    }

    mydbg!(x, y);
    for (k, v) in &x {
        if let Some(v2) = y.get(k) {
            ans += v.len() * v2.len();
        }
    }

    echo!(ans.saturating_sub(N));
}

