use std::io::prelude::*;

fn input<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let n: usize = input();
    let xy: Vec<(i32, i32)> = (0..n).map(|_| (input(), input())).collect();
    const V: usize = 100005;

    let mut e = vec![vec![vec![]; V]; 2];
    for (x, y) in xy {
        let (x, y) = (x as usize - 1, y as usize - 1);
        e[0][x].push(y);
        e[1][y].push(x);
    }

    let mut used = vec![vec![false; V]; 2];
    let mut ans = 0i64;
    for i in 0..V {
        if !used[0][i] {
            let mut cnt = vec![0, 0];
            dfs(i, 0, &e, &mut used, &mut cnt);
            ans += cnt[0] * cnt[1];
        }
        if !used[1][i] {
            let mut cnt = vec![0, 0];
            dfs(i, 0, &e, &mut used, &mut cnt);
            ans += cnt[0] * cnt[1];
        }
    }

    println!("{}", ans - n as i64);
}

fn dfs(
    cur: usize,
    xy: usize,
    e: &Vec<Vec<Vec<usize>>>,
    used: &mut Vec<Vec<bool>>,
    cnt: &mut Vec<i64>,
) {
    if used[xy][cur] {
        return;
    }

    used[xy][cur] = true;
    cnt[xy] += 1;
    for &next in &e[xy][cur] {
        let xy = 1 - xy;
        if !used[xy][next] {
            dfs(next, xy, e, used, cnt);
        }
    }
}

