struct Solver {
    n: usize,
    k: usize,
    ys_of_x: Vec<Vec<usize>>,
    xs_of_y: Vec<Vec<usize>>,
    c_of_x: Vec<usize>,
    c_of_y: Vec<usize>,
}

impl Solver {
    fn new(n: usize, k: usize) -> Solver {
        Solver {
            n: n,
            k: k,
            ys_of_x: vec![Vec::new(); n],
            xs_of_y: vec![Vec::new(); n],
            c_of_x: vec![0; n],
            c_of_y: vec![0; n],
        }
    }
    fn add_point(&mut self, x: usize, y: usize) {
        self.ys_of_x[x].push(y);
        self.xs_of_y[y].push(x);
    }
    fn solve(&mut self) {
        let mut m = 0;
        for x in 0..self.n {
            if self.c_of_x[x] == 0 && !self.ys_of_x[x].is_empty() {
                m += 1;
                self.dfs_x(x, m);
            }
        }
        let mut nx_of_c: Vec<usize> = vec![0; m + 1];
        let mut ny_of_c: Vec<usize> = vec![0; m + 1];
        for x in 0..self.n {
            nx_of_c[self.c_of_x[x]] += 1;
        }
        for y in 0..self.n {
            ny_of_c[self.c_of_y[y]] += 1;
        }
        let mut ans = 0;
        for c in 1..m + 1 {
            ans += nx_of_c[c] * ny_of_c[c];
        }
        ans -= self.k;
        println!("{}", ans);
    }
    fn dfs_x(&mut self, x: usize, c: usize) {
        if self.c_of_x[x] != 0 {
            return;
        }
        self.c_of_x[x] = c;
        for i in 0..self.ys_of_x[x].len() {
            let y = self.ys_of_x[x][i];
            self.dfs_y(y, c);
        }
    }
    fn dfs_y(&mut self, y: usize, c: usize) {
        if self.c_of_y[y] != 0 {
            return;
        }
        self.c_of_y[y] = c;
        for i in 0..self.xs_of_y[y].len() {
            let x = self.xs_of_y[y][i];
            self.dfs_x(x, c);
        }
    }
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
