    let mut ok = false;
    let mut x_seen = vec![false; 100000+1];
    let mut y_seen = vec![false; 100000+1];
    for &(x, y) in xys.iter() {
        if x_seen[x as usize] || y_seen[y as usize] {
            ok = true;
            break;
        }
        x_seen[x as usize] = true;
        y_seen[y as usize] = true;
    }

    if !ok {
        return println!("{}", 0);
    }


    let mut xs: Vec<_> = xys.iter().map(|v| v.0).collect();
    let mut ys: Vec<_> = xys.iter().map(|v| v.1).collect();
    xs.sort();
    xs.dedup();
    ys.sort();
    ys.dedup();
    let mut ans = xs.len() as u64 * ys.len() as u64;
    println!("{}", ans-n);
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

