fn make_compress_dict(xs: &Vec<usize>) -> HashMap<usize, usize> {
    let mut x_compress_dict = HashMap::new();
    for &x in xs.iter() {
        if !x_compress_dict.contains_key(&x) {
            let next = x_compress_dict.len();
            x_compress_dict.insert(x, next);
        }
    }
    x_compress_dict
}

fn main() {
    let n = read::<usize>();

    let mut points = vec![];
    for _ in 0..n {
        let v = read_vec::<usize>();
        let (x, y) = (v[0], v[1]);
        points.push((x, y));
    }
    points.sort();

    let mut xs = points.iter().map(|x| x.0).collect::<Vec<_>>();
    let mut ys = points.iter().map(|x| x.1).collect::<Vec<_>>();
    let x_compress_dict = make_compress_dict(&xs);
    let y_compress_dict = make_compress_dict(&ys);

    let length = x_compress_dict.len() + y_compress_dict.len();
    let mut edges = vec![vec![]; length];
    for &(x, y) in points.iter() {
        edges[x_compress_dict[&x]].push(x_compress_dict.len() + y_compress_dict[&y]);
        edges[x_compress_dict.len() + y_compress_dict[&y]].push(x_compress_dict[&x]);
    }

    let mut checked = vec![false; length];
    let mut ans = 0;
    for &(x, y) in points.iter() {
        let x = x_compress_dict[&x];
        if checked[x] {
            continue;
        }
        let (ret, x_size, y_size) = dfs(x, x_compress_dict.len(), &edges, &mut checked);
        ans += x_size * y_size - ret / 2;
    }
    println!("{}", ans);
}

fn dfs(
    current_idx: usize,
    x_length: usize,
    edges: &Vec<Vec<usize>>,
    checked: &mut Vec<bool>,
) -> (i64, i64, i64) {
    checked[current_idx] = true;
    let mut ret = 0i64;
    let mut x_size = 0i64;
    let mut y_size = 0i64;
    if current_idx < x_length {
        x_size = 1;
    } else {
        y_size = 1;
    }
    ret += edges[current_idx].len() as i64;
    for &to in edges[current_idx].iter() {
        if checked[to] {
            continue;
        }
        let result = dfs(to, x_length, edges, checked);
        ret += result.0;
        x_size += result.1;
        y_size += result.2;
    }
    (ret, x_size, y_size)
}

