fn main() {
    let mut sc = Scanner::new();
    let m: usize = sc.cin();
    const N: usize = 100002;
    let mut xy = vec![vec![]; N];
    let mut yx = vec![vec![]; N];
    for _ in 0..m {
        let x: usize = sc.cin();
        let y: usize = sc.cin();
        xy[x].push(y);
        yx[y].push(x);
    }
    let mut used = vec![false; N];
    let mut used_y = vec![false; N];
    let mut ans = 0;
    for i in 0..N {
        if used[i] { continue }
        let mut x_count = 0;
        let mut y_count = 0;
        let mut e_count = 0;
        let mut stack = vec![(true, i)];
        while let Some((b, u)) = stack.pop() {
            if b {
                used[u] = true;
                x_count += 1;
                for &v in xy[u].iter() {
                    if used_y[v] { continue }
                    stack.push((false, v));
                    e_count += 1;
                }
            } else {
                used_y[u] = true;
                y_count += 1;
                for &v in yx[u].iter() {
                    if used[v] { continue }
                    stack.push((true, v));
                    e_count += 1;
                }
            }
        }
        ans += x_count * y_count - e_count;
    }
    put!(ans);
}

